INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation)
VALUES
  ('42', 'luk', 'Lukas', 18, 12, 'aku berpuasa dua kali seminggu, aku memberikan sepersepuluh dari segala penghasilanku.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 13, 'Tetapi pemungut cukai itu berdiri jauh-jauh, bahkan ia tidak berani menengadah ke langit, melainkan ia memukul diri dan berkata: Ya Allah, kasihanilah aku orang berdosa ini.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 14, 'Aku berkata kepadamu: Orang ini pulang ke rumahnya sebagai orang yang dibenarkan Allah dan orang lain itu tidak. Sebab barangsiapa meninggikan diri, ia akan direndahkan dan barangsiapa merendahkan diri, ia akan ditinggikan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 15, 'Maka datanglah orang-orang membawa anak-anaknya yang kecil kepada Yesus, supaya Ia menjamah mereka. Melihat itu murid-murid-Nya memarahi orang-orang itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 16, 'Tetapi Yesus memanggil mereka dan berkata: "Biarkanlah anak-anak itu datang kepada-Ku, dan jangan kamu menghalang-halangi mereka, sebab orang-orang yang seperti itulah yang empunya Kerajaan Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 17, 'Aku berkata kepadamu: Sesungguhnya barangsiapa tidak menyambut Kerajaan Allah seperti seorang anak kecil, ia tidak akan masuk ke dalamnya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 18, 'Ada seorang pemimpin bertanya kepada Yesus, katanya: "Guru yang baik, apa yang harus aku perbuat untuk memperoleh hidup yang kekal?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 19, 'Jawab Yesus: "Mengapa kaukatakan Aku baik? Tak seorangpun yang baik selain dari pada Allah saja.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 20, 'Engkau tentu mengetahui segala perintah Allah: Jangan berzinah, jangan membunuh, jangan mencuri, jangan mengucapkan saksi dusta, hormatilah ayahmu dan ibumu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 21, 'Kata orang itu: "Semuanya itu telah kuturuti sejak masa mudaku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 22, 'Mendengar itu Yesus berkata kepadanya: "Masih tinggal satu hal lagi yang harus kaulakukan: juallah segala yang kaumiliki dan bagi-bagikanlah itu kepada orang-orang miskin, maka engkau akan beroleh harta di sorga, kemudian datanglah ke mari dan ikutlah Aku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 23, 'Ketika orang itu mendengar perkataan itu, ia menjadi amat sedih, sebab ia sangat kaya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 24, 'Lalu Yesus memandang dia dan berkata: "Alangkah sukarnya orang yang beruang masuk ke dalam Kerajaan Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 25, 'Sebab lebih mudah seekor unta masuk melalui lobang jarum dari pada seorang kaya masuk ke dalam Kerajaan Allah."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 26, 'Dan mereka yang mendengar itu berkata: "Jika demikian, siapakah yang dapat diselamatkan?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 27, 'Kata Yesus: "Apa yang tidak mungkin bagi manusia, mungkin bagi Allah."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 28, 'Petrus berkata: "Kami ini telah meninggalkan segala kepunyaan kami dan mengikut Engkau."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 29, 'Kata Yesus kepada mereka: "Aku berkata kepadamu, sesungguhnya setiap orang yang karena Kerajaan Allah meninggalkan rumahnya, isterinya atau saudaranya, orang tuanya atau anak-anaknya,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 30, 'akan menerima kembali lipat ganda pada masa ini juga, dan pada zaman yang akan datang ia akan menerima hidup yang kekal."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 31, 'Yesus memanggil kedua belas murid-Nya, lalu berkata kepada mereka: "Sekarang kita pergi ke Yerusalem dan segala sesuatu yang ditulis oleh para nabi mengenai Anak Manusia akan digenapi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 32, 'Sebab Ia akan diserahkan kepada bangsa-bangsa yang tidak mengenal Allah, diolok-olokkan, dihina dan diludahi,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 33, 'dan mereka menyesah dan membunuh Dia, dan pada hari ketiga Ia akan bangkit."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 34, 'Akan tetapi mereka sama sekali tidak mengerti semuanya itu; arti perkataan itu tersembunyi bagi mereka dan mereka tidak tahu apa yang dimaksudkan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 35, 'Waktu Yesus hampir tiba di Yerikho, ada seorang buta yang duduk di pinggir jalan dan mengemis.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 36, 'Waktu orang itu mendengar orang banyak lewat, ia bertanya: "Apa itu?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 37, 'Kata orang kepadanya: "Yesus orang Nazaret lewat."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 38, 'Lalu ia berseru: "Yesus, Anak Daud, kasihanilah aku!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 39, 'Maka mereka, yang berjalan di depan, menegor dia supaya ia diam. Namun semakin keras ia berseru: "Anak Daud, kasihanilah aku!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 40, 'Lalu Yesus berhenti dan menyuruh membawa orang itu kepada-Nya. Dan ketika ia telah berada di dekat-Nya, Yesus bertanya kepadanya:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 41, '"Apa yang kaukehendaki supaya Aku perbuat bagimu?" Jawab orang itu: "Tuhan, supaya aku dapat melihat!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 42, 'Lalu kata Yesus kepadanya: "Melihatlah engkau, imanmu telah menyelamatkan engkau!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 18, 43, 'Dan seketika itu juga melihatlah ia, lalu mengikuti Dia sambil memuliakan Allah. Seluruh rakyat melihat hal itu dan memuji-muji Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 1, 'Yesus masuk ke kota Yerikho dan berjalan terus melintasi kota itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 2, 'Di situ ada seorang bernama Zakheus, kepala pemungut cukai, dan ia seorang yang kaya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 3, 'Ia berusaha untuk melihat orang apakah Yesus itu, tetapi ia tidak berhasil karena orang banyak, sebab badannya pendek.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 4, 'Maka berlarilah ia mendahului orang banyak, lalu memanjat pohon ara untuk melihat Yesus, yang akan lewat di situ.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 5, 'Ketika Yesus sampai ke tempat itu, Ia melihat ke atas dan berkata: "Zakheus, segeralah turun, sebab hari ini Aku harus menumpang di rumahmu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 6, 'Lalu Zakheus segera turun dan menerima Yesus dengan sukacita.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 7, 'Tetapi semua orang yang melihat hal itu bersungut-sungut, katanya: "Ia menumpang di rumah orang berdosa."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 8, 'Tetapi Zakheus berdiri dan berkata kepada Tuhan: "Tuhan, setengah dari milikku akan kuberikan kepada orang miskin dan sekiranya ada sesuatu yang kuperas dari seseorang akan kukembalikan empat kali lipat."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 9, 'Kata Yesus kepadanya: "Hari ini telah terjadi keselamatan kepada rumah ini, karena orang inipun anak Abraham.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 10, 'Sebab Anak Manusia datang untuk mencari dan menyelamatkan yang hilang."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 11, 'Untuk mereka yang mendengarkan Dia di situ, Yesus melanjutkan perkataan-Nya dengan suatu perumpamaan, sebab Ia sudah dekat Yerusalem dan mereka menyangka, bahwa Kerajaan Allah akan segera kelihatan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 12, 'Maka Ia berkata: "Ada seorang bangsawan berangkat ke sebuah negeri yang jauh untuk dinobatkan menjadi raja di situ dan setelah itu baru kembali.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 13, 'Ia memanggil sepuluh orang hambanya dan memberikan sepuluh mina kepada mereka, katanya: Pakailah ini untuk berdagang sampai aku datang kembali.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 14, 'Akan tetapi orang-orang sebangsanya membenci dia, lalu mengirimkan utusan menyusul dia untuk mengatakan: Kami tidak mau orang ini menjadi raja atas kami.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 15, 'Dan terjadilah, ketika ia kembali, setelah ia dinobatkan menjadi raja, ia menyuruh memanggil hamba-hambanya, yang telah diberinya uang itu, untuk mengetahui berapa hasil dagang mereka masing-masing.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 16, 'Orang yang pertama datang dan berkata: Tuan, mina tuan yang satu itu telah menghasilkan sepuluh mina.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 17, 'Katanya kepada orang itu: Baik sekali perbuatanmu itu, hai hamba yang baik; engkau telah setia dalam perkara kecil, karena itu terimalah kekuasaan atas sepuluh kota.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 18, 'Datanglah yang kedua dan berkata: Tuan, mina tuan telah menghasilkan lima mina.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 19, 'Katanya kepada orang itu: Dan engkau, kuasailah lima kota.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 20, 'Dan hamba yang ketiga datang dan berkata: Tuan, inilah mina tuan, aku telah menyimpannya dalam sapu tangan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 21, 'Sebab aku takut akan tuan, karena tuan adalah manusia yang keras; tuan mengambil apa yang tidak pernah tuan taruh dan tuan menuai apa yang tidak tuan tabur.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 22, 'Katanya kepada orang itu: Hai hamba yang jahat, aku akan menghakimi engkau menurut perkataanmu sendiri. Engkau sudah tahu bahwa aku adalah orang yang keras, yang mengambil apa yang tidak pernah aku taruh dan menuai apa yang tidak aku tabur.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 23, 'Jika demikian, mengapa uangku itu tidak kauberikan kepada orang yang menjalankan uang? Maka sekembaliku aku dapat mengambilnya serta dengan bunganya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 24, 'Lalu katanya kepada orang-orang yang berdiri di situ: Ambillah mina yang satu itu dari padanya dan berikanlah kepada orang yang mempunyai sepuluh mina itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 25, 'Kata mereka kepadanya: Tuan, ia sudah mempunyai sepuluh mina.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 26, 'Jawabnya: Aku berkata kepadamu: Setiap orang yang mempunyai, kepadanya akan diberi, tetapi siapa yang tidak mempunyai, dari padanya akan diambil, juga apa yang ada padanya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 27, 'Akan tetapi semua seteruku ini, yang tidak suka aku menjadi rajanya, bawalah mereka ke mari dan bunuhlah mereka di depan mataku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 28, 'Dan setelah mengatakan semuanya itu Yesus mendahului mereka dan meneruskan perjalanan-Nya ke Yerusalem.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 29, 'Ketika Ia telah dekat Betfage dan Betania, yang terletak di gunung yang bernama Bukit Zaitun, Yesus menyuruh dua orang murid-Nya', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 30, 'dengan pesan: "Pergilah ke kampung yang di depanmu itu: Pada waktu kamu masuk di situ, kamu akan mendapati seekor keledai muda tertambat, yang belum pernah ditunggangi orang. Lepaskanlah keledai itu dan bawalah ke mari.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 31, 'Dan jika ada orang bertanya kepadamu: Mengapa kamu melepaskannya? jawablah begini: Tuhan memerlukannya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 32, 'Lalu pergilah mereka yang disuruh itu, dan mereka mendapati segala sesuatu seperti yang telah dikatakan Yesus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 33, 'Ketika mereka melepaskan keledai itu, berkatalah orang yang empunya keledai itu: "Mengapa kamu melepaskan keledai itu?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 34, 'Kata mereka: "Tuhan memerlukannya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 35, 'Mereka membawa keledai itu kepada Yesus, lalu mengalasinya dengan pakaian mereka dan menolong Yesus naik ke atasnya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 36, 'Dan sementara Yesus mengendarai keledai itu mereka menghamparkan pakaiannya di jalan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 37, 'Ketika Ia dekat Yerusalem, di tempat jalan menurun dari Bukit Zaitun, mulailah semua murid yang mengiringi Dia bergembira dan memuji Allah dengan suara nyaring oleh karena segala mujizat yang telah mereka lihat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 38, 'Kata mereka: "Diberkatilah Dia yang datang sebagai Raja dalam nama Tuhan, damai sejahtera di sorga dan kemuliaan di tempat yang mahatinggi!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 39, 'Beberapa orang Farisi yang turut dengan orang banyak itu berkata kepada Yesus: "Guru, tegorlah murid-murid-Mu itu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 40, 'Jawab-Nya: "Aku berkata kepadamu: Jika mereka ini diam, maka batu ini akan berteriak."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 41, 'Dan ketika Yesus telah dekat dan melihat kota itu, Ia menangisinya,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 42, 'kata-Nya: "Wahai, betapa baiknya jika pada hari ini juga engkau mengerti apa yang perlu untuk damai sejahteramu! Tetapi sekarang hal itu tersembunyi bagi matamu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 43, 'Sebab akan datang harinya, bahwa musuhmu akan mengelilingi engkau dengan kubu, lalu mengepung engkau dan menghimpit engkau dari segala jurusan,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 44, 'dan mereka akan membinasakan engkau beserta dengan pendudukmu dan pada tembokmu mereka tidak akan membiarkan satu batupun tinggal terletak di atas batu yang lain, karena engkau tidak mengetahui saat, bilamana Allah melawat engkau."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 45, 'Lalu Yesus masuk ke Bait Allah dan mulailah Ia mengusir semua pedagang di situ,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 46, 'kata-Nya kepada mereka: "Ada tertulis: Rumah-Ku adalah rumah doa. Tetapi kamu menjadikannya sarang penyamun."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 47, 'Tiap-tiap hari Ia mengajar di dalam Bait Allah. Imam-imam kepala dan ahli-ahli Taurat serta orang-orang terkemuka dari bangsa Israel berusaha untuk membinasakan Dia,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 19, 48, 'tetapi mereka tidak tahu, bagaimana harus melakukannya, sebab seluruh rakyat terpikat kepada-Nya dan ingin mendengarkan Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 1, 'Pada suatu hari ketika Yesus mengajar orang banyak di Bait Allah dan memberitakan Injil, datanglah imam-imam kepala dan ahli-ahli Taurat serta tua-tua ke situ,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 2, 'dan mereka berkata kepada Yesus: "Katakanlah kepada kami dengan kuasa manakah Engkau melakukan hal-hal itu, dan siapa yang memberikan kuasa itu kepada-Mu!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 3, 'Jawab Yesus kepada mereka: "Aku juga akan mengajukan suatu pertanyaan kepada kamu. Katakanlah kepada-Ku:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 4, 'Baptisan Yohanes itu, dari sorga atau dari manusia?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 5, 'Mereka mempertimbangkannya di antara mereka, dan berkata: "Jikalau kita katakan: Dari sorga, Ia akan berkata: Mengapakah kamu tidak percaya kepadanya?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 6, 'Tetapi jikalau kita katakan: Dari manusia, seluruh rakyat akan melempari kita dengan batu, sebab mereka yakin, bahwa Yohanes adalah seorang nabi."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 7, 'Lalu mereka menjawab, bahwa mereka tidak tahu dari mana baptisan itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 8, 'Maka kata Yesus kepada mereka: "Jika demikian, Aku juga tidak mengatakan kepadamu dengan kuasa manakah Aku melakukan hal-hal itu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 9, 'Lalu Yesus mengatakan perumpamaan ini kepada orang banyak: "Seorang membuka kebun anggur; kemudian ia menyewakannya kepada penggarap-penggarap lalu berangkat ke negeri lain untuk waktu yang agak lama.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 10, 'Dan ketika sudah tiba musimnya, ia menyuruh seorang hamba kepada penggarap-penggarap itu, supaya mereka menyerahkan sebagian dari hasil kebun anggur itu kepadanya. Tetapi penggarap-penggarap itu memukul hamba itu dan menyuruhnya pulang dengan tangan hampa.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 11, 'Sesudah itu ia menyuruh seorang hamba yang lain, tetapi hamba itu juga dipukul dan dipermalukan oleh mereka, lalu disuruh pulang dengan tangan hampa.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 12, 'Selanjutnya ia menyuruh hamba yang ketiga, tetapi orang itu juga dilukai oleh mereka, lalu dilemparkan ke luar kebun itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 13, 'Maka kata tuan kebun anggur itu: Apakah yang harus kuperbuat? Aku akan menyuruh anakku yang kekasih; tentu ia mereka segani.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 14, 'Tetapi ketika penggarap-penggarap itu melihat anaknya itu, mereka berunding, katanya: Ia adalah ahli waris, mari kita bunuh dia, supaya warisan ini menjadi milik kita.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 15, 'Lalu mereka melemparkan dia ke luar kebun anggur itu dan membunuhnya. Sekarang apa yang akan dilakukan oleh tuan kebun anggur itu dengan mereka?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 16, 'Ia akan datang dan membinasakan penggarap-penggarap itu, dan mempercayakan kebun anggur itu kepada orang-orang lain." Mendengar itu mereka berkata: "Sekali-kali jangan!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 17, 'Tetapi Yesus memandang mereka dan berkata: "Jika demikian apakah arti nas ini: Batu yang dibuang oleh tukang-tukang bangunan telah menjadi batu penjuru?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 18, 'Barangsiapa jatuh ke atas batu itu, ia akan hancur, dan barangsiapa ditimpa batu itu, ia akan remuk."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 19, 'Lalu ahli-ahli Taurat dan imam-imam kepala berusaha menangkap Dia pada saat itu juga, sebab mereka tahu, bahwa merekalah yang dimaksudkan-Nya dengan perumpamaan itu, tetapi mereka takut kepada orang banyak.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 20, 'Ahli-ahli Taurat dan imam-imam kepala mengamat-amati Yesus. Mereka menyuruh kepada-Nya mata-mata yang berlaku seolah-olah orang jujur, supaya mereka dapat menjerat-Nya dengan suatu pertanyaan dan menyerahkan-Nya kepada wewenang dan kuasa wali negeri.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 21, 'Orang-orang itu mengajukan pertanyaan ini kepada-Nya: "Guru, kami tahu, bahwa segala perkataan dan pengajaran-Mu benar dan Engkau tidak mencari muka, melainkan dengan jujur mengajar jalan Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 22, 'Apakah kami diperbolehkan membayar pajak kepada Kaisar atau tidak?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 23, 'Tetapi Yesus mengetahui maksud mereka yang licik itu, lalu berkata kepada mereka:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 24, '"Tunjukkanlah kepada-Ku suatu dinar; gambar dan tulisan siapakah ada padanya?" Jawab mereka: "Gambar dan tulisan Kaisar."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 25, 'Lalu kata Yesus kepada mereka: "Kalau begitu berikanlah kepada Kaisar apa yang wajib kamu berikan kepada Kaisar dan kepada Allah apa yang wajib kamu berikan kepada Allah!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 26, 'Dan mereka tidak dapat menjerat Dia dalam perkataan-Nya di depan orang banyak. Mereka heran akan jawab-Nya itu dan mereka diam.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 27, 'Maka datanglah kepada Yesus beberapa orang Saduki, yang tidak mengakui adanya kebangkitan. Mereka bertanya kepada-Nya:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 28, '"Guru, Musa menuliskan perintah ini untuk kita: Jika seorang, yang mempunyai saudara laki-laki, mati sedang isterinya masih ada, tetapi ia tidak meninggalkan anak, saudaranya harus kawin dengan isterinya itu dan membangkitkan keturunan bagi saudaranya itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 29, 'Adalah tujuh orang bersaudara. Yang pertama kawin dengan seorang perempuan lalu mati dengan tidak meninggalkan anak.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 30, 'Lalu perempuan itu dikawini oleh yang kedua,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 31, 'dan oleh yang ketiga dan demikianlah berturut-turut oleh ketujuh saudara itu, mereka semuanya mati dengan tidak meninggalkan anak.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 32, 'Akhirnya perempuan itupun mati.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 33, 'Bagaimana sekarang dengan perempuan itu, siapakah di antara orang-orang itu yang menjadi suaminya pada hari kebangkitan? Sebab ketujuhnya telah beristerikan dia."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 34, 'Jawab Yesus kepada mereka: "Orang-orang dunia ini kawin dan dikawinkan,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 35, 'tetapi mereka yang dianggap layak untuk mendapat bagian dalam dunia yang lain itu dan dalam kebangkitan dari antara orang mati, tidak kawin dan tidak dikawinkan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 36, 'Sebab mereka tidak dapat mati lagi; mereka sama seperti malaikat-malaikat dan mereka adalah anak-anak Allah, karena mereka telah dibangkitkan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 37, 'Tentang bangkitnya orang-orang mati, Musa telah memberitahukannya dalam nas tentang semak duri, di mana Tuhan disebut Allah Abraham, Allah Ishak dan Allah Yakub.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 38, 'Ia bukan Allah orang mati, melainkan Allah orang hidup, sebab di hadapan Dia semua orang hidup."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 39, 'Mendengar itu beberapa ahli Taurat berkata: "Guru, jawab-Mu itu tepat sekali."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 40, 'Sebab mereka tidak berani lagi menanyakan apa-apa kepada Yesus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 41, 'Tetapi Yesus berkata kepada mereka: "Bagaimana orang dapat mengatakan, bahwa Mesias adalah Anak Daud?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 42, 'Sebab Daud sendiri berkata dalam kitab Mazmur: Tuhan telah berfirman kepada Tuanku: duduklah di sebelah kanan-Ku,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 43, 'sampai Kubuat musuh-musuh-Mu menjadi tumpuan kaki-Mu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 44, 'Jadi Daud menyebut Dia Tuannya, bagaimana mungkin Ia anaknya pula?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 45, 'Ketika semua orang banyak mendengarkan, Yesus berkata kepada murid-murid-Nya:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 46, '"Waspadalah terhadap ahli-ahli Taurat yang suka berjalan-jalan memakai jubah panjang dan suka menerima penghormatan di pasar, yang suka duduk di tempat terdepan di rumah ibadat dan di tempat terhormat dalam perjamuan,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 20, 47, 'yang menelan rumah janda-janda dan yang mengelabui mata orang dengan doa yang panjang-panjang. Mereka itu pasti akan menerima hukuman yang lebih berat."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 1, 'Ketika Yesus mengangkat muka-Nya, Ia melihat orang-orang kaya memasukkan persembahan mereka ke dalam peti persembahan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 2, 'Ia melihat juga seorang janda miskin memasukkan dua peser ke dalam peti itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 3, 'Lalu Ia berkata: "Aku berkata kepadamu, sesungguhnya janda miskin ini memberi lebih banyak dari pada semua orang itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 4, 'Sebab mereka semua memberi persembahannya dari kelimpahannya, tetapi janda ini memberi dari kekurangannya, bahkan ia memberi seluruh nafkahnya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 5, 'Ketika beberapa orang berbicara tentang Bait Allah dan mengagumi bangunan itu yang dihiasi dengan batu yang indah-indah dan dengan berbagai-bagai barang persembahan, berkatalah Yesus:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 6, '"Apa yang kamu lihat di situ?akan datang harinya di mana tidak ada satu batupun akan dibiarkan terletak di atas batu yang lain; semuanya akan diruntuhkan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 7, 'Dan murid-murid bertanya kepada Yesus, katanya: "Guru, bilamanakah itu akan terjadi? Dan apakah tandanya, kalau itu akan terjadi?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 8, 'Jawab-Nya: "Waspadalah, supaya kamu jangan disesatkan. Sebab banyak orang akan datang dengan memakai nama-Ku dan berkata: Akulah Dia, dan: Saatnya sudah dekat. Janganlah kamu mengikuti mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 9, 'Dan apabila kamu mendengar tentang peperangan dan pemberontakan, janganlah kamu terkejut. Sebab semuanya itu harus terjadi dahulu, tetapi itu tidak berarti kesudahannya akan datang segera."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 10, 'Ia berkata kepada mereka: "Bangsa akan bangkit melawan bangsa dan kerajaan melawan kerajaan,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 11, 'dan akan terjadi gempa bumi yang dahsyat dan di berbagai tempat akan ada penyakit sampar dan kelaparan, dan akan terjadi juga hal-hal yang mengejutkan dan tanda-tanda yang dahsyat dari langit.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 12, 'Tetapi sebelum semuanya itu kamu akan ditangkap dan dianiaya; kamu akan diserahkan ke rumah-rumah ibadat dan penjara-penjara, dan kamu akan dihadapkan kepada raja-raja dan penguasa-penguasa oleh karena nama-Ku.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 13, 'Hal itu akan menjadi kesempatan bagimu untuk bersaksi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 14, 'Sebab itu tetapkanlah di dalam hatimu, supaya kamu jangan memikirkan lebih dahulu pembelaanmu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 15, 'Sebab Aku sendiri akan memberikan kepadamu kata-kata hikmat, sehingga kamu tidak dapat ditentang atau dibantah lawan-lawanmu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 16, 'Dan kamu akan diserahkan juga oleh orang tuamu, saudara-saudaramu, kaum keluargamu dan sahabat-sahabatmu dan beberapa orang di antara kamu akan dibunuh', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 17, 'dan kamu akan dibenci semua orang oleh karena nama-Ku.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 18, 'Tetapi tidak sehelaipun dari rambut kepalamu akan hilang.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 19, 'Kalau kamu tetap bertahan, kamu akan memperoleh hidupmu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 20, '"Apabila kamu melihat Yerusalem dikepung oleh tentara-tentara, ketahuilah, bahwa keruntuhannya sudah dekat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 21, 'Pada waktu itu orang-orang yang berada di Yudea harus melarikan diri ke pegunungan, dan orang-orang yang berada di dalam kota harus mengungsi, dan orang-orang yang berada di pedusunan jangan masuk lagi ke dalam kota,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 22, 'sebab itulah masa pembalasan di mana akan genap semua yang ada tertulis.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 23, 'Celakalah ibu-ibu yang sedang hamil atau yang menyusukan bayi pada masa itu! Sebab akan datang kesesakan yang dahsyat atas seluruh negeri dan murka atas bangsa ini,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 24, 'dan mereka akan tewas oleh mata pedang dan dibawa sebagai tawanan ke segala bangsa, dan Yerusalem akan diinjak-injak oleh bangsa-bangsa yang tidak mengenal Allah, sampai genaplah zaman bangsa-bangsa itu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 25, '"Dan akan ada tanda-tanda pada matahari dan bulan dan bintang-bintang, dan di bumi bangsa-bangsa akan takut dan bingung menghadapi deru dan gelora laut.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 26, 'Orang akan mati ketakutan karena kecemasan berhubung dengan segala apa yang menimpa bumi ini, sebab kuasa-kuasa langit akan goncang.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 27, 'Pada waktu itu orang akan melihat Anak Manusia datang dalam awan dengan segala kekuasaan dan kemuliaan-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 28, 'Apabila semuanya itu mulai terjadi, bangkitlah dan angkatlah mukamu, sebab penyelamatanmu sudah dekat."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 29, 'Lalu Yesus mengatakan perumpamaan ini kepada mereka: "Perhatikanlah pohon ara atau pohon apa saja.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 30, 'Apabila kamu melihat pohon-pohon itu sudah bertunas, kamu tahu dengan sendirinya bahwa musim panas sudah dekat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 31, 'Demikian juga, jika kamu melihat hal-hal itu terjadi, ketahuilah, bahwa Kerajaan Allah sudah dekat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 32, 'Aku berkata kepadamu: Sesungguhnya angkatan ini tidak akan berlalu, sebelum semuanya terjadi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 33, 'Langit dan bumi akan berlalu, tetapi perkataan-Ku tidak akan berlalu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 34, '"Jagalah dirimu, supaya hatimu jangan sarat oleh pesta pora dan kemabukan serta kepentingan-kepentingan duniawi dan supaya hari Tuhan jangan dengan tiba-tiba jatuh ke atas dirimu seperti suatu jerat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 35, 'Sebab ia akan menimpa semua penduduk bumi ini.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 36, 'Berjaga-jagalah senantiasa sambil berdoa, supaya kamu beroleh kekuatan untuk luput dari semua yang akan terjadi itu, dan supaya kamu tahan berdiri di hadapan Anak Manusia."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 37, 'Pada siang hari Yesus mengajar di Bait Allah dan pada malam hari Ia keluar dan bermalam di gunung yang bernama Bukit Zaitun.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 21, 38, 'Dan pagi-pagi semua orang banyak datang kepada-Nya di dalam Bait Allah untuk mendengarkan Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 1, 'Hari raya Roti Tidak Beragi, yang disebut Paskah, sudah dekat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 2, 'Imam-imam kepala dan ahli-ahli Taurat mencari jalan, bagaimana mereka dapat membunuh Yesus, sebab mereka takut kepada orang banyak.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 3, 'Maka masuklah Iblis ke dalam Yudas, yang bernama Iskariot, seorang dari kedua belas murid itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 4, 'Lalu pergilah Yudas kepada imam-imam kepala dan kepala-kepala pengawal Bait Allah dan berunding dengan mereka, bagaimana ia dapat menyerahkan Yesus kepada mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 5, 'Mereka sangat gembira dan bermupakat untuk memberikan sejumlah uang kepadanya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 6, 'Ia menyetujuinya, dan mulai dari waktu itu ia mencari kesempatan yang baik untuk menyerahkan Yesus kepada mereka tanpa setahu orang banyak.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 7, 'Maka tibalah hari raya Roti Tidak Beragi, yaitu hari di mana orang harus menyembelih domba Paskah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 8, 'Lalu Yesus menyuruh Petrus dan Yohanes, kata-Nya: "Pergilah, persiapkanlah perjamuan Paskah bagi kita supaya kita makan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 9, 'Kata mereka kepada-Nya: "Di manakah Engkau kehendaki kami mempersiapkannya?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 10, 'Jawab-Nya: "Apabila kamu masuk ke dalam kota, kamu akan bertemu dengan seorang yang membawa kendi berisi air. Ikutilah dia ke dalam rumah yang dimasukinya,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 11, 'dan katakanlah kepada tuan rumah itu: Guru bertanya kepadamu: di manakah ruangan tempat Aku bersama-sama dengan murid-murid-Ku akan makan Paskah?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 12, 'Lalu orang itu akan menunjukkan kepadamu sebuah ruangan atas yang besar yang sudah lengkap, di situlah kamu harus mempersiapkannya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 13, 'Maka berangkatlah mereka dan mereka mendapati semua seperti yang dikatakan Yesus kepada mereka. Lalu mereka mempersiapkan Paskah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 14, 'Ketika tiba saatnya, Yesus duduk makan bersama-sama dengan rasul-rasul-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 15, 'Kata-Nya kepada mereka: "Aku sangat rindu makan Paskah ini bersama-sama dengan kamu, sebelum Aku menderita.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 16, 'Sebab Aku berkata kepadamu: Aku tidak akan memakannya lagi sampai ia beroleh kegenapannya dalam Kerajaan Allah."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 17, 'Kemudian Ia mengambil sebuah cawan, mengucap syukur, lalu berkata: "Ambillah ini dan bagikanlah di antara kamu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 18, 'Sebab Aku berkata kepada kamu: mulai dari sekarang ini Aku tidak akan minum lagi hasil pokok anggur sampai Kerajaan Allah telah datang."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 19, 'Lalu Ia mengambil roti, mengucap syukur, memecah-mecahkannya dan memberikannya kepada mereka, kata-Nya: "Inilah tubuh-Ku yang diserahkan bagi kamu; perbuatlah ini menjadi peringatan akan Aku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 20, 'Demikian juga dibuat-Nya dengan cawan sesudah makan; Ia berkata: "Cawan ini adalah perjanjian baru oleh darah-Ku, yang ditumpahkan bagi kamu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 21, 'Tetapi, lihat, tangan orang yang menyerahkan Aku, ada bersama dengan Aku di meja ini.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 22, 'Sebab Anak Manusia memang akan pergi seperti yang telah ditetapkan, akan tetapi, celakalah orang yang olehnya Ia diserahkan!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 23, 'Lalu mulailah mereka mempersoalkan, siapa di antara mereka yang akan berbuat demikian.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 24, 'Terjadilah juga pertengkaran di antara murid-murid Yesus, siapakah yang dapat dianggap terbesar di antara mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 25, 'Yesus berkata kepada mereka: "Raja-raja bangsa-bangsa memerintah rakyat mereka dan orang-orang yang menjalankan kuasa atas mereka disebut pelindung-pelindung.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 26, 'Tetapi kamu tidaklah demikian, melainkan yang terbesar di antara kamu hendaklah menjadi sebagai yang paling muda dan pemimpin sebagai pelayan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 27, 'Sebab siapakah yang lebih besar: yang duduk makan, atau yang melayani? Bukankah dia yang duduk makan? Tetapi Aku ada di tengah-tengah kamu sebagai pelayan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 28, 'Kamulah yang tetap tinggal bersama-sama dengan Aku dalam segala pencobaan yang Aku alami.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 29, 'Dan Aku menentukan hak-hak Kerajaan bagi kamu, sama seperti Bapa-Ku menentukannya bagi-Ku,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 30, 'bahwa kamu akan makan dan minum semeja dengan Aku di dalam Kerajaan-Ku dan kamu akan duduk di atas takhta untuk menghakimi kedua belas suku Israel.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 31, 'Simon, Simon, lihat, Iblis telah menuntut untuk menampi kamu seperti gandum,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 32, 'tetapi Aku telah berdoa untuk engkau, supaya imanmu jangan gugur. Dan engkau, jikalau engkau sudah insaf, kuatkanlah saudara-saudaramu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 33, 'Jawab Petrus: "Tuhan, aku bersedia masuk penjara dan mati bersama-sama dengan Engkau!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 34, 'Tetapi Yesus berkata: "Aku berkata kepadamu, Petrus, hari ini ayam tidak akan berkokok, sebelum engkau tiga kali menyangkal, bahwa engkau mengenal Aku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 35, 'Lalu Ia berkata kepada mereka: "Ketika Aku mengutus kamu dengan tiada membawa pundi-pundi, bekal dan kasut, adakah kamu kekurangan apa-apa?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 36, 'Jawab mereka: "Suatupun tidak." Kata-Nya kepada mereka: "Tetapi sekarang ini, siapa yang mempunyai pundi-pundi, hendaklah ia membawanya, demikian juga yang mempunyai bekal; dan siapa yang tidak mempunyainya hendaklah ia menjual jubahnya dan membeli pedang.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 37, 'Sebab Aku berkata kepada kamu, bahwa nas Kitab Suci ini harus digenapi pada-Ku: Ia akan terhitung di antara pemberontak-pemberontak. Sebab apa yang tertulis tentang Aku sedang digenapi."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 38, 'Kata mereka: "Tuhan, ini dua pedang." Jawab-Nya: "Sudah cukup."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 39, 'Lalu pergilah Yesus ke luar kota dan sebagaimana biasa Ia menuju Bukit Zaitun. Murid-murid-Nya juga mengikuti Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 40, 'Setelah tiba di tempat itu Ia berkata kepada mereka: "Berdoalah supaya kamu jangan jatuh ke dalam pencobaan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 41, 'Kemudian Ia menjauhkan diri dari mereka kira-kira sepelempar batu jaraknya, lalu Ia berlutut dan berdoa, kata-Nya:', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 42, '"Ya Bapa-Ku, jikalau Engkau mau, ambillah cawan ini dari pada-Ku; tetapi bukanlah kehendak-Ku, melainkan kehendak-Mulah yang terjadi."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 43, 'Maka seorang malaikat dari langit menampakkan diri kepada-Nya untuk memberi kekuatan kepada-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 44, 'Ia sangat ketakutan dan makin bersungguh-sungguh berdoa. Peluh-Nya menjadi seperti titik-titik darah yang bertetesan ke tanah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 45, 'Lalu Ia bangkit dari doa-Nya dan kembali kepada murid-murid-Nya, tetapi Ia mendapati mereka sedang tidur karena dukacita.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 46, 'Kata-Nya kepada mereka: "Mengapa kamu tidur? Bangunlah dan berdoalah, supaya kamu jangan jatuh ke dalam pencobaan."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 47, 'Waktu Yesus masih berbicara datanglah serombongan orang, sedang murid-Nya yang bernama Yudas, seorang dari kedua belas murid itu, berjalan di depan mereka. Yudas mendekati Yesus untuk mencium-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 48, 'Maka kata Yesus kepadanya: "Hai Yudas, engkau menyerahkan Anak Manusia dengan ciuman?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 49, 'Ketika mereka, yang bersama-sama dengan Yesus, melihat apa yang akan terjadi, berkatalah mereka: "Tuhan, mestikah kami menyerang mereka dengan pedang?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 50, 'Dan seorang dari mereka menyerang hamba Imam Besar sehingga putus telinga kanannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 51, 'Tetapi Yesus berkata: "Sudahlah itu." Lalu Ia menjamah telinga orang itu dan menyembuhkannya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 52, 'Maka Yesus berkata kepada imam-imam kepala dan kepala-kepala pengawal Bait Allah serta tua-tua yang datang untuk menangkap Dia, kata-Nya: "Sangkamu Aku ini penyamun, maka kamu datang lengkap dengan pedang dan pentung?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 53, 'Padahal tiap-tiap hari Aku ada di tengah-tengah kamu di dalam Bait Allah, dan kamu tidak menangkap Aku. Tetapi inilah saat kamu, dan inilah kuasa kegelapan itu."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 54, 'Lalu Yesus ditangkap dan dibawa dari tempat itu. Ia digiring ke rumah Imam Besar. Dan Petrus mengikut dari jauh.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 55, 'Di tengah-tengah halaman rumah itu orang memasang api dan mereka duduk mengelilinginya. Petrus juga duduk di tengah-tengah mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 56, 'Seorang hamba perempuan melihat dia duduk dekat api; ia mengamat-amatinya lalu berkata: "Juga orang ini bersama-sama dengan Dia."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 57, 'Tetapi Petrus menyangkal, katanya: "Bukan, aku tidak kenal Dia!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 58, 'Tidak berapa lama kemudian seorang lain melihat dia lalu berkata: "Engkau juga seorang dari mereka!" Tetapi Petrus berkata: "Bukan, aku tidak!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 59, 'Dan kira-kira sejam kemudian seorang lain berkata dengan tegas: "Sungguh, orang ini juga bersama-sama dengan Dia, sebab ia juga orang Galilea."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 22, 60, 'Tetapi Petrus berkata: "Bukan, aku tidak tahu apa yang engkau katakan." Seketika itu juga, sementara ia berkata, berkokoklah ayam.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 1, 'Lalu bangkitlah seluruh sidang itu dan Yesus dibawa menghadap Pilatus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 2, 'Di situ mereka mulai menuduh Dia, katanya: "Telah kedapatan oleh kami, bahwa orang ini menyesatkan bangsa kami, dan melarang membayar pajak kepada Kaisar, dan tentang diri-Nya Ia mengatakan, bahwa Ia adalah Kristus, yaitu Raja."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 3, 'Pilatus bertanya kepada-Nya: "Engkaukah raja orang Yahudi?" Jawab Yesus: "Engkau sendiri mengatakannya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 4, 'Kata Pilatus kepada imam-imam kepala dan seluruh orang banyak itu: "Aku tidak mendapati kesalahan apapun pada orang ini."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 5, 'Tetapi mereka makin kuat mendesak, katanya: "Ia menghasut rakyat dengan ajaran-Nya di seluruh Yudea, Ia mulai di Galilea dan sudah sampai ke sini."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 6, 'Ketika Pilatus mendengar itu ia bertanya, apakah orang itu seorang Galilea.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 7, 'Dan ketika ia tahu, bahwa Yesus seorang dari wilayah Herodes, ia mengirim Dia menghadap Herodes, yang pada waktu itu ada juga di Yerusalem.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 8, 'Ketika Herodes melihat Yesus, ia sangat girang. Sebab sudah lama ia ingin melihat-Nya, karena ia sering mendengar tentang Dia, lagipula ia mengharapkan melihat bagaimana Yesus mengadakan suatu tanda.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 9, 'Ia mengajukan banyak pertanyaan kepada Yesus, tetapi Yesus tidak memberi jawaban apapun.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 10, 'Sementara itu imam-imam kepala dan ahli-ahli Taurat maju ke depan dan melontarkan tuduhan-tuduhan yang berat terhadap Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 11, 'Maka mulailah Herodes dan pasukannya menista dan mengolok-olokkan Dia, ia mengenakan jubah kebesaran kepada-Nya lalu mengirim Dia kembali kepada Pilatus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 12, 'Dan pada hari itu juga bersahabatlah Herodes dan Pilatus; sebelum itu mereka bermusuhan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 13, 'Lalu Pilatus mengumpulkan imam-imam kepala dan pemimpin-pemimpin serta rakyat,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 14, 'dan berkata kepada mereka: "Kamu telah membawa orang ini kepadaku sebagai seorang yang menyesatkan rakyat. Kamu lihat sendiri bahwa aku telah memeriksa-Nya, dan dari kesalahan-kesalahan yang kamu tuduhkan kepada-Nya tidak ada yang kudapati pada-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 15, 'Dan Herodes juga tidak, sebab ia mengirimkan Dia kembali kepada kami. Sesungguhnya tidak ada suatu apapun yang dilakukan-Nya yang setimpal dengan hukuman mati.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 16, 'Jadi aku akan menghajar Dia, lalu melepaskan-Nya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 17, '(Sebab ia wajib melepaskan seorang bagi mereka pada hari raya itu.)', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 18, 'Tetapi mereka berteriak bersama-sama: "Enyahkanlah Dia, lepaskanlah Barabas bagi kami!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 19, 'Barabas ini dimasukkan ke dalam penjara berhubung dengan suatu pemberontakan yang telah terjadi di dalam kota dan karena pembunuhan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 20, 'Sekali lagi Pilatus berbicara dengan suara keras kepada mereka, karena ia ingin melepaskan Yesus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 21, 'Tetapi mereka berteriak membalasnya, katanya: "Salibkanlah Dia! Salibkanlah Dia!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 22, 'Kata Pilatus untuk ketiga kalinya kepada mereka: "Kejahatan apa yang sebenarnya telah dilakukan orang ini? Tidak ada suatu kesalahanpun yang kudapati pada-Nya, yang setimpal dengan hukuman mati. Jadi aku akan menghajar Dia, lalu melepaskan-Nya."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 23, 'Tetapi dengan berteriak mereka mendesak dan menuntut, supaya Ia disalibkan, dan akhirnya mereka menang dengan teriak mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 24, 'Lalu Pilatus memutuskan, supaya tuntutan mereka dikabulkan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 25, 'Dan ia melepaskan orang yang dimasukkan ke dalam penjara karena pemberontakan dan pembunuhan itu sesuai dengan tuntutan mereka, tetapi Yesus diserahkannya kepada mereka untuk diperlakukan semau-maunya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 26, 'Ketika mereka membawa Yesus, mereka menahan seorang yang bernama Simon dari Kirene, yang baru datang dari luar kota, lalu diletakkan salib itu di atas bahunya, supaya dipikulnya sambil mengikuti Yesus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 27, 'Sejumlah besar orang mengikuti Dia; di antaranya banyak perempuan yang menangisi dan meratapi Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 28, 'Yesus berpaling kepada mereka dan berkata: "Hai puteri-puteri Yerusalem, janganlah kamu menangisi Aku, melainkan tangisilah dirimu sendiri dan anak-anakmu!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 29, 'Sebab lihat, akan tiba masanya orang berkata: Berbahagialah perempuan mandul dan yang rahimnya tidak pernah melahirkan, dan yang susunya tidak pernah menyusui.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 30, 'Maka orang akan mulai berkata kepada gunung-gunung: Runtuhlah menimpa kami! dan kepada bukit-bukit: Timbunilah kami!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 31, 'Sebab jikalau orang berbuat demikian dengan kayu hidup, apakah yang akan terjadi dengan kayu kering?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 32, 'Dan ada juga digiring dua orang lain, yaitu dua penjahat untuk dihukum mati bersama-sama dengan Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 33, 'Ketika mereka sampai di tempat yang bernama Tengkorak, mereka menyalibkan Yesus di situ dan juga kedua orang penjahat itu, yang seorang di sebelah kanan-Nya dan yang lain di sebelah kiri-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 34, 'Yesus berkata: "Ya Bapa, ampunilah mereka, sebab mereka tidak tahu apa yang mereka perbuat." Dan mereka membuang undi untuk membagi pakaian-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 35, 'Orang banyak berdiri di situ dan melihat semuanya. Pemimpin-pemimpin mengejek Dia, katanya: "Orang lain Ia selamatkan, biarlah sekarang Ia menyelamatkan diri-Nya sendiri, jika Ia adalah Mesias, orang yang dipilih Allah."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 36, 'Juga prajurit-prajurit mengolok-olokkan Dia; mereka mengunjukkan anggur asam kepada-Nya', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 37, 'dan berkata: "Jika Engkau adalah raja orang Yahudi, selamatkanlah diri-Mu!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 38, 'Ada juga tulisan di atas kepala-Nya: "Inilah raja orang Yahudi".', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 39, 'Seorang dari penjahat yang di gantung itu menghujat Dia, katanya: "Bukankah Engkau adalah Kristus? Selamatkanlah diri-Mu dan kami!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 40, 'Tetapi yang seorang menegor dia, katanya: "Tidakkah engkau takut, juga tidak kepada Allah, sedang engkau menerima hukuman yang sama?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 41, 'Kita memang selayaknya dihukum, sebab kita menerima balasan yang setimpal dengan perbuatan kita, tetapi orang ini tidak berbuat sesuatu yang salah."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 42, 'Lalu ia berkata: "Yesus, ingatlah akan aku, apabila Engkau datang sebagai Raja."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 43, 'Kata Yesus kepadanya: "Aku berkata kepadamu, sesungguhnya hari ini juga engkau akan ada bersama-sama dengan Aku di dalam Firdaus."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 44, 'Ketika itu hari sudah kira-kira jam dua belas, lalu kegelapan meliputi seluruh daerah itu sampai jam tiga,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 45, 'sebab matahari tidak bersinar. Dan tabir Bait Suci terbelah dua.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 46, 'Lalu Yesus berseru dengan suara nyaring: "Ya Bapa, ke dalam tangan-Mu Kuserahkan nyawa-Ku." Dan sesudah berkata demikian Ia menyerahkan nyawa-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 47, 'Ketika kepala pasukan melihat apa yang terjadi, ia memuliakan Allah, katanya: "Sungguh, orang ini adalah orang benar!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 48, 'Dan sesudah seluruh orang banyak, yang datang berkerumun di situ untuk tontonan itu, melihat apa yang terjadi itu, pulanglah mereka sambil memukul-mukul diri.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 49, 'Semua orang yang mengenal Yesus dari dekat, termasuk perempuan-perempuan yang mengikuti Dia dari Galilea, berdiri jauh-jauh dan melihat semuanya itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 50, 'Adalah seorang yang bernama Yusuf. Ia anggota Majelis Besar, dan seorang yang baik lagi benar.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 51, 'Ia tidak setuju dengan putusan dan tindakan Majelis itu. Ia berasal dari Arimatea, sebuah kota Yahudi dan ia menanti-nantikan Kerajaan Allah.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 52, 'Ia pergi menghadap Pilatus dan meminta mayat Yesus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 53, 'Dan sesudah ia menurunkan mayat itu, ia mengapaninya dengan kain lenan, lalu membaringkannya di dalam kubur yang digali di dalam bukit batu, di mana belum pernah dibaringkan mayat.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 54, 'Hari itu adalah hari persiapan dan sabat hampir mulai.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 55, 'Dan perempuan-perempuan yang datang bersama-sama dengan Yesus dari Galilea, ikut serta dan mereka melihat kubur itu dan bagaimana mayat-Nya dibaringkan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 23, 56, 'Dan setelah pulang, mereka menyediakan rempah-rempah dan minyak mur. (23-56b) Dan pada hari Sabat mereka beristirahat menurut hukum Taurat,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 1, 'tetapi pagi-pagi benar pada hari pertama minggu itu mereka pergi ke kubur membawa rempah-rempah yang telah disediakan mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 2, 'Mereka mendapati batu sudah terguling dari kubur itu,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 3, 'dan setelah masuk mereka tidak menemukan mayat Tuhan Yesus.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 4, 'Sementara mereka berdiri termangu-mangu karena hal itu, tiba-tiba ada dua orang berdiri dekat mereka memakai pakaian yang berkilau-kilauan.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 5, 'Mereka sangat ketakutan dan menundukkan kepala, tetapi kedua orang itu berkata kepada mereka: "Mengapa kamu mencari Dia yang hidup, di antara orang mati?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 6, 'Ia tidak ada di sini, Ia telah bangkit. Ingatlah apa yang dikatakan-Nya kepada kamu, ketika Ia masih di Galilea,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 7, 'yaitu bahwa Anak Manusia harus diserahkan ke tangan orang-orang berdosa dan disalibkan, dan akan bangkit pada hari yang ketiga."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 8, 'Maka teringatlah mereka akan perkataan Yesus itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 9, 'Dan setelah mereka kembali dari kubur, mereka menceriterakan semuanya itu kepada kesebelas murid dan kepada semua saudara yang lain.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 10, 'Perempuan-perempuan itu ialah Maria dari Magdala, dan Yohana, dan Maria ibu Yakobus. Dan perempuan-perempuan lain juga yang bersama-sama dengan mereka memberitahukannya kepada rasul-rasul.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 11, 'Tetapi bagi mereka perkataan-perkataan itu seakan-akan omong kosong dan mereka tidak percaya kepada perempuan-perempuan itu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 12, 'Sungguhpun demikian Petrus bangun, lalu cepat-cepat pergi ke kubur itu. Ketika ia menjenguk ke dalam, ia melihat hanya kain kapan saja. Lalu ia pergi, dan ia bertanya dalam hatinya apa yang kiranya telah terjadi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 13, 'Pada hari itu juga dua orang dari murid-murid Yesus pergi ke sebuah kampung bernama Emaus, yang terletak kira-kira tujuh mil jauhnya dari Yerusalem,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 14, 'dan mereka bercakap-cakap tentang segala sesuatu yang telah terjadi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 15, 'Ketika mereka sedang bercakap-cakap dan bertukar pikiran, datanglah Yesus sendiri mendekati mereka, lalu berjalan bersama-sama dengan mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 16, 'Tetapi ada sesuatu yang menghalangi mata mereka, sehingga mereka tidak dapat mengenal Dia.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 17, 'Yesus berkata kepada mereka: "Apakah yang kamu percakapkan sementara kamu berjalan?" Maka berhentilah mereka dengan muka muram.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 18, 'Seorang dari mereka, namanya Kleopas, menjawab-Nya: "Adakah Engkau satu-satunya orang asing di Yerusalem, yang tidak tahu apa yang terjadi di situ pada hari-hari belakangan ini?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 19, 'Kata-Nya kepada mereka: "Apakah itu?" Jawab mereka: "Apa yang terjadi dengan Yesus orang Nazaret. Dia adalah seorang nabi, yang berkuasa dalam pekerjaan dan perkataan di hadapan Allah dan di depan seluruh bangsa kami.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 20, 'Tetapi imam-imam kepala dan pemimpin-pemimpin kami telah menyerahkan Dia untuk dihukum mati dan mereka telah menyalibkan-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 21, 'Padahal kami dahulu mengharapkan, bahwa Dialah yang datang untuk membebaskan bangsa Israel. Tetapi sementara itu telah lewat tiga hari, sejak semuanya itu terjadi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 22, 'Tetapi beberapa perempuan dari kalangan kami telah mengejutkan kami: Pagi-pagi buta mereka telah pergi ke kubur,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 23, 'dan tidak menemukan mayat-Nya. Lalu mereka datang dengan berita, bahwa telah kelihatan kepada mereka malaikat-malaikat, yang mengatakan, bahwa Ia hidup.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 24, 'Dan beberapa teman kami telah pergi ke kubur itu dan mendapati, bahwa memang benar yang dikatakan perempuan-perempuan itu, tetapi Dia tidak mereka lihat."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 25, 'Lalu Ia berkata kepada mereka: "Hai kamu orang bodoh, betapa lambannya hatimu, sehingga kamu tidak percaya segala sesuatu, yang telah dikatakan para nabi!', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 26, 'Bukankah Mesias harus menderita semuanya itu untuk masuk ke dalam kemuliaan-Nya?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 27, 'Lalu Ia menjelaskan kepada mereka apa yang tertulis tentang Dia dalam seluruh Kitab Suci, mulai dari kitab-kitab Musa dan segala kitab nabi-nabi.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 28, 'Mereka mendekati kampung yang mereka tuju, lalu Ia berbuat seolah-olah hendak meneruskan perjalanan-Nya.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 29, 'Tetapi mereka sangat mendesak-Nya, katanya: "Tinggallah bersama-sama dengan kami, sebab hari telah menjelang malam dan matahari hampir terbenam." Lalu masuklah Ia untuk tinggal bersama-sama dengan mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 30, 'Waktu Ia duduk makan dengan mereka, Ia mengambil roti, mengucap berkat, lalu memecah-mecahkannya dan memberikannya kepada mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 31, 'Ketika itu terbukalah mata mereka dan merekapun mengenal Dia, tetapi Ia lenyap dari tengah-tengah mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 32, 'Kata mereka seorang kepada yang lain: "Bukankah hati kita berkobar-kobar, ketika Ia berbicara dengan kita di tengah jalan dan ketika Ia menerangkan Kitab Suci kepada kita?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 33, 'Lalu bangunlah mereka dan terus kembali ke Yerusalem. Di situ mereka mendapati kesebelas murid itu. Mereka sedang berkumpul bersama-sama dengan teman-teman mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 34, 'Kata mereka itu: "Sesungguhnya Tuhan telah bangkit dan telah menampakkan diri kepada Simon."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 35, 'Lalu kedua orang itupun menceriterakan apa yang terjadi di tengah jalan dan bagaimana mereka mengenal Dia pada waktu Ia memecah-mecahkan roti.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 36, 'Dan sementara mereka bercakap-cakap tentang hal-hal itu, Yesus tiba-tiba berdiri di tengah-tengah mereka dan berkata kepada mereka: "Damai sejahtera bagi kamu!"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 37, 'Mereka terkejut dan takut dan menyangka bahwa mereka melihat hantu.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 38, 'Akan tetapi Ia berkata kepada mereka: "Mengapa kamu terkejut dan apa sebabnya timbul keragu-raguan di dalam hati kamu?', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 39, 'Lihatlah tangan-Ku dan kaki-Ku: Aku sendirilah ini; rabalah Aku dan lihatlah, karena hantu tidak ada daging dan tulangnya, seperti yang kamu lihat ada pada-Ku."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 40, 'Sambil berkata demikian, Ia memperlihatkan tangan dan kaki-Nya kepada mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 41, 'Dan ketika mereka belum percaya karena girangnya dan masih heran, berkatalah Ia kepada mereka: "Adakah padamu makanan di sini?"', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 42, 'Lalu mereka memberikan kepada-Nya sepotong ikan goreng.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 43, 'Ia mengambilnya dan memakannya di depan mata mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 44, 'Ia berkata kepada mereka: "Inilah perkataan-Ku, yang telah Kukatakan kepadamu ketika Aku masih bersama-sama dengan kamu, yakni bahwa harus digenapi semua yang ada tertulis tentang Aku dalam kitab Taurat Musa dan kitab nabi-nabi dan kitab Mazmur."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 45, 'Lalu Ia membuka pikiran mereka, sehingga mereka mengerti Kitab Suci.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 46, 'Kata-Nya kepada mereka: "Ada tertulis demikian: Mesias harus menderita dan bangkit dari antara orang mati pada hari yang ketiga,', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 47, 'dan lagi: dalam nama-Nya berita tentang pertobatan dan pengampunan dosa harus disampaikan kepada segala bangsa, mulai dari Yerusalem.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 48, 'Kamu adalah saksi dari semuanya ini.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 49, 'Dan Aku akan mengirim kepadamu apa yang dijanjikan Bapa-Ku. Tetapi kamu harus tinggal di dalam kota ini sampai kamu diperlengkapi dengan kekuasaan dari tempat tinggi."', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 50, 'Lalu Yesus membawa mereka ke luar kota sampai dekat Betania. Di situ Ia mengangkat tangan-Nya dan memberkati mereka.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 51, 'Dan ketika Ia sedang memberkati mereka, Ia berpisah dari mereka dan terangkat ke sorga.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 52, 'Mereka sujud menyembah kepada-Nya, lalu mereka pulang ke Yerusalem dengan sangat bersukacita.', 'id', 'TB'),
  ('42', 'luk', 'Lukas', 24, 53, 'Mereka senantiasa berada di dalam Bait Allah dan memuliakan Allah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 1, 'Pada mulanya adalah Firman; Firman itu bersama-sama dengan Allah dan Firman itu adalah Allah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 2, 'Ia pada mulanya bersama-sama dengan Allah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 3, 'Segala sesuatu dijadikan oleh Dia dan tanpa Dia tidak ada suatupun yang telah jadi dari segala yang telah dijadikan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 4, 'Dalam Dia ada hidup dan hidup itu adalah terang manusia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 5, 'Terang itu bercahaya di dalam kegelapan dan kegelapan itu tidak menguasainya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 6, 'Datanglah seorang yang diutus Allah, namanya Yohanes;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 7, 'ia datang sebagai saksi untuk memberi kesaksian tentang terang itu, supaya oleh dia semua orang menjadi percaya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 8, 'Ia bukan terang itu, tetapi ia harus memberi kesaksian tentang terang itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 9, 'Terang yang sesungguhnya, yang menerangi setiap orang, sedang datang ke dalam dunia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 10, 'Ia telah ada di dalam dunia dan dunia dijadikan oleh-Nya, tetapi dunia tidak mengenal-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 11, 'Ia datang kepada milik kepunyaan-Nya, tetapi orang-orang kepunyaan-Nya itu tidak menerima-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 12, 'Tetapi semua orang yang menerima-Nya diberi-Nya kuasa supaya menjadi anak-anak Allah, yaitu mereka yang percaya dalam nama-Nya;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 13, 'orang-orang yang diperanakkan bukan dari darah atau dari daging, bukan pula secara jasmani oleh keinginan seorang laki-laki, melainkan dari Allah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 14, 'Firman itu telah menjadi manusia, dan diam di antara kita, dan kita telah melihat kemuliaan-Nya, yaitu kemuliaan yang diberikan kepada-Nya sebagai Anak Tunggal Bapa, penuh kasih karunia dan kebenaran.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 15, 'Yohanes memberi kesaksian tentang Dia dan berseru, katanya: "Inilah Dia, yang kumaksudkan ketika aku berkata: Kemudian dari padaku akan datang Dia yang telah mendahului aku, sebab Dia telah ada sebelum aku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 16, 'Karena dari kepenuhan-Nya kita semua telah menerima kasih karunia demi kasih karunia;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 17, 'sebab hukum Taurat diberikan oleh Musa, tetapi kasih karunia dan kebenaran datang oleh Yesus Kristus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 18, 'Tidak seorangpun yang pernah melihat Allah; tetapi Anak Tunggal Allah, yang ada di pangkuan Bapa, Dialah yang menyatakan-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 19, 'Dan inilah kesaksian Yohanes ketika orang Yahudi dari Yerusalem mengutus beberapa imam dan orang-orang Lewi kepadanya untuk menanyakan dia: "Siapakah engkau?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 20, 'Ia mengaku dan tidak berdusta, katanya: "Aku bukan Mesias."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 21, 'Lalu mereka bertanya kepadanya: "Kalau begitu, siapakah engkau? Elia?" Dan ia menjawab: "Bukan!" "Engkaukah nabi yang akan datang?" Dan ia menjawab: "Bukan!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 22, 'Maka kata mereka kepadanya: "Siapakah engkau? Sebab kami harus memberi jawab kepada mereka yang mengutus kami. Apakah katamu tentang dirimu sendiri?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 23, 'Jawabnya: "Akulah suara orang yang berseru-seru di padang gurun: Luruskanlah jalan Tuhan! seperti yang telah dikatakan nabi Yesaya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 24, 'Dan di antara orang-orang yang diutus itu ada beberapa orang Farisi.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 25, 'Mereka bertanya kepadanya, katanya: "Mengapakah engkau membaptis, jikalau engkau bukan Mesias, bukan Elia, dan bukan nabi yang akan datang?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 26, 'Yohanes menjawab mereka, katanya: "Aku membaptis dengan air; tetapi di tengah-tengah kamu berdiri Dia yang tidak kamu kenal,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 27, 'yaitu Dia, yang datang kemudian dari padaku. Membuka tali kasut-Nyapun aku tidak layak."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 28, 'Hal itu terjadi di Betania yang di seberang sungai Yordan, di mana Yohanes membaptis.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 29, 'Pada keesokan harinya Yohanes melihat Yesus datang kepadanya dan ia berkata: "Lihatlah Anak domba Allah, yang menghapus dosa dunia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 30, 'Dialah yang kumaksud ketika kukatakan: Kemudian dari padaku akan datang seorang, yang telah mendahului aku, sebab Dia telah ada sebelum aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 31, 'Dan aku sendiripun mula-mula tidak mengenal Dia, tetapi untuk itulah aku datang dan membaptis dengan air, supaya Ia dinyatakan kepada Israel."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 32, 'Dan Yohanes memberi kesaksian, katanya: "Aku telah melihat Roh turun dari langit seperti merpati, dan Ia tinggal di atas-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 33, 'Dan akupun tidak mengenal-Nya, tetapi Dia, yang mengutus aku untuk membaptis dengan air, telah berfirman kepadaku: Jikalau engkau melihat Roh itu turun ke atas seseorang dan tinggal di atas-Nya, Dialah itu yang akan membaptis dengan Roh Kudus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 34, 'Dan aku telah melihat-Nya dan memberi kesaksian: Ia inilah Anak Allah."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 35, 'Pada keesokan harinya Yohanes berdiri di situ pula dengan dua orang muridnya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 36, 'Dan ketika ia melihat Yesus lewat, ia berkata: "Lihatlah Anak domba Allah!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 37, 'Kedua murid itu mendengar apa yang dikatakannya itu, lalu mereka pergi mengikut Yesus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 38, 'Tetapi Yesus menoleh ke belakang. Ia melihat, bahwa mereka mengikut Dia lalu berkata kepada mereka: "Apakah yang kamu cari?" Kata mereka kepada-Nya: "Rabi (artinya: Guru), di manakah Engkau tinggal?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 39, 'Ia berkata kepada mereka: "Marilah dan kamu akan melihatnya." Merekapun datang dan melihat di mana Ia tinggal, dan hari itu mereka tinggal bersama-sama dengan Dia; waktu itu kira-kira pukul empat.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 40, 'Salah seorang dari keduanya yang mendengar perkataan Yohanes lalu mengikut Yesus adalah Andreas, saudara Simon Petrus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 41, 'Andreas mula-mula bertemu dengan Simon, saudaranya, dan ia berkata kepadanya: "Kami telah menemukan Mesias (artinya: Kristus)."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 42, 'Ia membawanya kepada Yesus. Yesus memandang dia dan berkata: "Engkau Simon, anak Yohanes, engkau akan dinamakan Kefas (artinya: Petrus)."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 43, 'Pada keesokan harinya Yesus memutuskan untuk berangkat ke Galilea. Ia bertemu dengan Filipus, dan berkata kepadanya: "Ikutlah Aku!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 44, 'Filipus itu berasal dari Betsaida, kota Andreas dan Petrus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 45, 'Filipus bertemu dengan Natanael dan berkata kepadanya: "Kami telah menemukan Dia, yang disebut oleh Musa dalam kitab Taurat dan oleh para nabi, yaitu Yesus, anak Yusuf dari Nazaret."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 46, 'Kata Natanael kepadanya: "Mungkinkah sesuatu yang baik datang dari Nazaret?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 47, 'Kata Filipus kepadanya: "Mari dan lihatlah!" Yesus melihat Natanael datang kepada-Nya, lalu berkata tentang dia: "Lihat, inilah seorang Israel sejati, tidak ada kepalsuan di dalamnya!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 48, 'Kata Natanael kepada-Nya: "Bagaimana Engkau mengenal aku?" Jawab Yesus kepadanya: "Sebelum Filipus memanggil engkau, Aku telah melihat engkau di bawah pohon ara."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 49, 'Kata Natanael kepada-Nya: "Rabi, Engkau Anak Allah, Engkau Raja orang Israel!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 50, 'Yesus menjawab, kata-Nya: "Karena Aku berkata kepadamu: Aku melihat engkau di bawah pohon ara, maka engkau percaya? Engkau akan melihat hal-hal yang lebih besar dari pada itu."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 1, 51, 'Lalu kata Yesus kepadanya: "Aku berkata kepadamu, sesungguhnya engkau akan melihat langit terbuka dan malaikat-malaikat Allah turun naik kepada Anak Manusia."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 1, 'Pada hari ketiga ada perkawinan di Kana yang di Galilea, dan ibu Yesus ada di situ;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 2, 'Yesus dan murid-murid-Nya diundang juga ke perkawinan itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 3, 'Ketika mereka kekurangan anggur, ibu Yesus berkata kepada-Nya: "Mereka kehabisan anggur."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 4, 'Kata Yesus kepadanya: "Mau apakah engkau dari pada-Ku, ibu? Saat-Ku belum tiba."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 5, 'Tetapi ibu Yesus berkata kepada pelayan-pelayan: "Apa yang dikatakan kepadamu, buatlah itu!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 6, 'Di situ ada enam tempayan yang disediakan untuk pembasuhan menurut adat orang Yahudi, masing-masing isinya dua tiga buyung.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 7, 'Yesus berkata kepada pelayan-pelayan itu: "Isilah tempayan-tempayan itu penuh dengan air." Dan merekapun mengisinya sampai penuh.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 8, 'Lalu kata Yesus kepada mereka: "Sekarang cedoklah dan bawalah kepada pemimpin pesta." Lalu merekapun membawanya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 9, 'Setelah pemimpin pesta itu mengecap air, yang telah menjadi anggur itu?dan ia tidak tahu dari mana datangnya, tetapi pelayan-pelayan, yang mencedok air itu, mengetahuinya?ia memanggil mempelai laki-laki,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 10, 'dan berkata kepadanya: "Setiap orang menghidangkan anggur yang baik dahulu dan sesudah orang puas minum, barulah yang kurang baik; akan tetapi engkau menyimpan anggur yang baik sampai sekarang."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 11, 'Hal itu dibuat Yesus di Kana yang di Galilea, sebagai yang pertama dari tanda-tanda-Nya dan dengan itu Ia telah menyatakan kemuliaan-Nya, dan murid-murid-Nya percaya kepada-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 12, 'Sesudah itu Yesus pergi ke Kapernaum, bersama-sama dengan ibu-Nya dan saudara-saudara-Nya dan murid-murid-Nya, dan mereka tinggal di situ hanya beberapa hari saja.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 13, 'Ketika hari raya Paskah orang Yahudi sudah dekat, Yesus berangkat ke Yerusalem.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 14, 'Dalam Bait Suci didapati-Nya pedagang-pedagang lembu, kambing domba dan merpati, dan penukar-penukar uang duduk di situ.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 15, 'Ia membuat cambuk dari tali lalu mengusir mereka semua dari Bait Suci dengan semua kambing domba dan lembu mereka; uang penukar-penukar dihamburkan-Nya ke tanah dan meja-meja mereka dibalikkan-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 16, 'Kepada pedagang-pedagang merpati Ia berkata: "Ambil semuanya ini dari sini, jangan kamu membuat rumah Bapa-Ku menjadi tempat berjualan."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 17, 'Maka teringatlah murid-murid-Nya, bahwa ada tertulis: "Cinta untuk rumah-Mu menghanguskan Aku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 18, 'Orang-orang Yahudi menantang Yesus, katanya: "Tanda apakah dapat Engkau tunjukkan kepada kami, bahwa Engkau berhak bertindak demikian?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 19, 'Jawab Yesus kepada mereka: "Rombak Bait Allah ini, dan dalam tiga hari Aku akan mendirikannya kembali."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 20, 'Lalu kata orang Yahudi kepada-Nya: "Empat puluh enam tahun orang mendirikan Bait Allah ini dan Engkau dapat membangunnya dalam tiga hari?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 21, 'Tetapi yang dimaksudkan-Nya dengan Bait Allah ialah tubuh-Nya sendiri.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 22, 'Kemudian, sesudah Ia bangkit dari antara orang mati, barulah teringat oleh murid-murid-Nya bahwa hal itu telah dikatakan-Nya, dan merekapun percayalah akan Kitab Suci dan akan perkataan yang telah diucapkan Yesus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 23, 'Dan sementara Ia di Yerusalem selama hari raya Paskah, banyak orang percaya dalam nama-Nya, karena mereka telah melihat tanda-tanda yang diadakan-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 24, 'Tetapi Yesus sendiri tidak mempercayakan diri-Nya kepada mereka, karena Ia mengenal mereka semua,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 2, 25, 'dan karena tidak perlu seorangpun memberi kesaksian kepada-Nya tentang manusia, sebab Ia tahu apa yang ada di dalam hati manusia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 1, 'Adalah seorang Farisi yang bernama Nikodemus, seorang pemimpin agama Yahudi.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 2, 'Ia datang pada waktu malam kepada Yesus dan berkata: "Rabi, kami tahu, bahwa Engkau datang sebagai guru yang diutus Allah; sebab tidak ada seorangpun yang dapat mengadakan tanda-tanda yang Engkau adakan itu, jika Allah tidak menyertainya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 3, 'Yesus menjawab, kata-Nya: "Aku berkata kepadamu, sesungguhnya jika seorang tidak dilahirkan kembali, ia tidak dapat melihat Kerajaan Allah."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 4, 'Kata Nikodemus kepada-Nya: "Bagaimanakah mungkin seorang dilahirkan, kalau ia sudah tua? Dapatkah ia masuk kembali ke dalam rahim ibunya dan dilahirkan lagi?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 5, 'Jawab Yesus: "Aku berkata kepadamu, sesungguhnya jika seorang tidak dilahirkan dari air dan Roh, ia tidak dapat masuk ke dalam Kerajaan Allah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 6, 'Apa yang dilahirkan dari daging, adalah daging, dan apa yang dilahirkan dari Roh, adalah roh.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 7, 'Janganlah engkau heran, karena Aku berkata kepadamu: Kamu harus dilahirkan kembali.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 8, 'Angin bertiup ke mana ia mau, dan engkau mendengar bunyinya, tetapi engkau tidak tahu dari mana ia datang atau ke mana ia pergi. Demikianlah halnya dengan tiap-tiap orang yang lahir dari Roh."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 9, 'Nikodemus menjawab, katanya: "Bagaimanakah mungkin hal itu terjadi?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 10, 'Jawab Yesus: "Engkau adalah pengajar Israel, dan engkau tidak mengerti hal-hal itu?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 11, 'Aku berkata kepadamu, sesungguhnya kami berkata-kata tentang apa yang kami ketahui dan kami bersaksi tentang apa yang kami lihat, tetapi kamu tidak menerima kesaksian kami.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 12, 'Kamu tidak percaya, waktu Aku berkata-kata dengan kamu tentang hal-hal duniawi, bagaimana kamu akan percaya, kalau Aku berkata-kata dengan kamu tentang hal-hal sorgawi?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 13, 'Tidak ada seorangpun yang telah naik ke sorga, selain dari pada Dia yang telah turun dari sorga, yaitu Anak Manusia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 14, 'Dan sama seperti Musa meninggikan ular di padang gurun, demikian juga Anak Manusia harus ditinggikan,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 15, 'supaya setiap orang yang percaya kepada-Nya beroleh hidup yang kekal.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 16, 'Karena begitu besar kasih Allah akan dunia ini, sehingga Ia telah mengaruniakan Anak-Nya yang tunggal, supaya setiap orang yang percaya kepada-Nya tidak binasa, melainkan beroleh hidup yang kekal.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 17, 'Sebab Allah mengutus Anak-Nya ke dalam dunia bukan untuk menghakimi dunia, melainkan untuk menyelamatkannya oleh Dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 18, 'Barangsiapa percaya kepada-Nya, ia tidak akan dihukum; barangsiapa tidak percaya, ia telah berada di bawah hukuman, sebab ia tidak percaya dalam nama Anak Tunggal Allah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 19, 'Dan inilah hukuman itu: Terang telah datang ke dalam dunia, tetapi manusia lebih menyukai kegelapan dari pada terang, sebab perbuatan-perbuatan mereka jahat.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 20, 'Sebab barangsiapa berbuat jahat, membenci terang dan tidak datang kepada terang itu, supaya perbuatan-perbuatannya yang jahat itu tidak nampak;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 21, 'tetapi barangsiapa melakukan yang benar, ia datang kepada terang, supaya menjadi nyata, bahwa perbuatan-perbuatannya dilakukan dalam Allah."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 22, 'Sesudah itu Yesus pergi dengan murid-murid-Nya ke tanah Yudea dan Ia diam di sana bersama-sama mereka dan membaptis.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 23, 'Akan tetapi Yohanespun membaptis juga di Ainon, dekat Salim, sebab di situ banyak air, dan orang-orang datang ke situ untuk dibaptis,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 24, 'sebab pada waktu itu Yohanes belum dimasukkan ke dalam penjara.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 25, 'Maka timbullah perselisihan di antara murid-murid Yohanes dengan seorang Yahudi tentang penyucian.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 26, 'Lalu mereka datang kepada Yohanes dan berkata kepadanya: "Rabi, orang yang bersama dengan engkau di seberang sungai Yordan dan yang tentang Dia engkau telah memberi kesaksian, Dia membaptis juga dan semua orang pergi kepada-Nya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 27, 'Jawab Yohanes: "Tidak ada seorangpun yang dapat mengambil sesuatu bagi dirinya, kalau tidak dikaruniakan kepadanya dari sorga.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 28, 'Kamu sendiri dapat memberi kesaksian, bahwa aku telah berkata: Aku bukan Mesias, tetapi aku diutus untuk mendahului-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 29, 'Yang empunya mempelai perempuan, ialah mempelai laki-laki; tetapi sahabat mempelai laki-laki, yang berdiri dekat dia dan yang mendengarkannya, sangat bersukacita mendengar suara mempelai laki-laki itu. Itulah sukacitaku, dan sekarang sukacitaku itu penuh.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 30, 'Ia harus makin besar, tetapi aku harus makin kecil.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 31, 'Siapa yang datang dari atas adalah di atas semuanya; siapa yang berasal dari bumi, termasuk pada bumi dan berkata-kata dalam bahasa bumi. Siapa yang datang dari sorga adalah di atas semuanya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 32, 'Ia memberi kesaksian tentang apa yang dilihat-Nya dan yang didengar-Nya, tetapi tak seorangpun yang menerima kesaksian-Nya itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 33, 'Siapa yang menerima kesaksian-Nya itu, ia mengaku, bahwa Allah adalah benar.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 34, 'Sebab siapa yang diutus Allah, Dialah yang menyampaikan firman Allah, karena Allah mengaruniakan Roh-Nya dengan tidak terbatas.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 35, 'Bapa mengasihi Anak dan telah menyerahkan segala sesuatu kepada-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 3, 36, 'Barangsiapa percaya kepada Anak, ia beroleh hidup yang kekal, tetapi barangsiapa tidak taat kepada Anak, ia tidak akan melihat hidup, melainkan murka Allah tetap ada di atasnya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 1, 'Ketika Tuhan Yesus mengetahui, bahwa orang-orang Farisi telah mendengar, bahwa Ia memperoleh dan membaptis murid lebih banyak dari pada Yohanes', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 2, 'meskipun Yesus sendiri tidak membaptis, melainkan murid-murid-Nya,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 3, 'Iapun meninggalkan Yudea dan kembali lagi ke Galilea.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 4, 'Ia harus melintasi daerah Samaria.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 5, 'Maka sampailah Ia ke sebuah kota di Samaria, yang bernama Sikhar dekat tanah yang diberikan Yakub dahulu kepada anaknya, Yusuf.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 6, 'Di situ terdapat sumur Yakub. Yesus sangat letih oleh perjalanan, karena itu Ia duduk di pinggir sumur itu. Hari kira-kira pukul dua belas.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 7, 'Maka datanglah seorang perempuan Samaria hendak menimba air. Kata Yesus kepadanya: "Berilah Aku minum."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 8, 'Sebab murid-murid-Nya telah pergi ke kota membeli makanan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 9, 'Maka kata perempuan Samaria itu kepada-Nya: "Masakan Engkau, seorang Yahudi, minta minum kepadaku, seorang Samaria?" (Sebab orang Yahudi tidak bergaul dengan orang Samaria.)', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 10, 'Jawab Yesus kepadanya: "Jikalau engkau tahu tentang karunia Allah dan siapakah Dia yang berkata kepadamu: Berilah Aku minum! niscaya engkau telah meminta kepada-Nya dan Ia telah memberikan kepadamu air hidup."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 11, 'Kata perempuan itu kepada-Nya: "Tuhan, Engkau tidak punya timba dan sumur ini amat dalam; dari manakah Engkau memperoleh air hidup itu?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 12, 'Adakah Engkau lebih besar dari pada bapa kami Yakub, yang memberikan sumur ini kepada kami dan yang telah minum sendiri dari dalamnya, ia serta anak-anaknya dan ternaknya?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 13, 'Jawab Yesus kepadanya: "Barangsiapa minum air ini, ia akan haus lagi,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 14, 'tetapi barangsiapa minum air yang akan Kuberikan kepadanya, ia tidak akan haus untuk selama-lamanya. Sebaliknya air yang akan Kuberikan kepadanya, akan menjadi mata air di dalam dirinya, yang terus-menerus memancar sampai kepada hidup yang kekal."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 15, 'Kata perempuan itu kepada-Nya: "Tuhan, berikanlah aku air itu, supaya aku tidak haus dan tidak usah datang lagi ke sini untuk menimba air."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 16, 'Kata Yesus kepadanya: "Pergilah, panggillah suamimu dan datang ke sini."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 17, 'Kata perempuan itu: "Aku tidak mempunyai suami." Kata Yesus kepadanya: "Tepat katamu, bahwa engkau tidak mempunyai suami,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 18, 'sebab engkau sudah mempunyai lima suami dan yang ada sekarang padamu, bukanlah suamimu. Dalam hal ini engkau berkata benar."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 19, 'Kata perempuan itu kepada-Nya: "Tuhan, nyata sekarang padaku, bahwa Engkau seorang nabi.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 20, 'Nenek moyang kami menyembah di atas gunung ini, tetapi kamu katakan, bahwa Yerusalemlah tempat orang menyembah."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 21, 'Kata Yesus kepadanya: "Percayalah kepada-Ku, hai perempuan, saatnya akan tiba, bahwa kamu akan menyembah Bapa bukan di gunung ini dan bukan juga di Yerusalem.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 22, 'Kamu menyembah apa yang tidak kamu kenal, kami menyembah apa yang kami kenal, sebab keselamatan datang dari bangsa Yahudi.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 23, 'Tetapi saatnya akan datang dan sudah tiba sekarang, bahwa penyembah-penyembah benar akan menyembah Bapa dalam roh dan kebenaran; sebab Bapa menghendaki penyembah-penyembah demikian.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 24, 'Allah itu Roh dan barangsiapa menyembah Dia, harus menyembah-Nya dalam roh dan kebenaran."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 25, 'Jawab perempuan itu kepada-Nya: "Aku tahu, bahwa Mesias akan datang, yang disebut juga Kristus; apabila Ia datang, Ia akan memberitakan segala sesuatu kepada kami."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 26, 'Kata Yesus kepadanya: "Akulah Dia, yang sedang berkata-kata dengan engkau."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 27, 'Pada waktu itu datanglah murid-murid-Nya dan mereka heran, bahwa Ia sedang bercakap-cakap dengan seorang perempuan. Tetapi tidak seorangpun yang berkata: "Apa yang Engkau kehendaki? Atau: Apa yang Engkau percakapkan dengan dia?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 28, 'Maka perempuan itu meninggalkan tempayannya di situ lalu pergi ke kota dan berkata kepada orang-orang yang di situ:', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 29, '"Mari, lihat! Di sana ada seorang yang mengatakan kepadaku segala sesuatu yang telah kuperbuat. Mungkinkah Dia Kristus itu?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 30, 'Maka merekapun pergi ke luar kota lalu datang kepada Yesus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 31, 'Sementara itu murid-murid-Nya mengajak Dia, katanya: "Rabi, makanlah."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 32, 'Akan tetapi Ia berkata kepada mereka: "Pada-Ku ada makanan yang tidak kamu kenal."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 33, 'Maka murid-murid itu berkata seorang kepada yang lain: "Adakah orang yang telah membawa sesuatu kepada-Nya untuk dimakan?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 34, 'Kata Yesus kepada mereka: "Makanan-Ku ialah melakukan kehendak Dia yang mengutus Aku dan menyelesaikan pekerjaan-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 35, 'Bukankah kamu mengatakan: Empat bulan lagi tibalah musim menuai? Tetapi Aku berkata kepadamu: Lihatlah sekelilingmu dan pandanglah ladang-ladang yang sudah menguning dan matang untuk dituai.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 36, 'Sekarang juga penuai telah menerima upahnya dan ia mengumpulkan buah untuk hidup yang kekal, sehingga penabur dan penuai sama-sama bersukacita.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 37, 'Sebab dalam hal ini benarlah peribahasa: Yang seorang menabur dan yang lain menuai.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 38, 'Aku mengutus kamu untuk menuai apa yang tidak kamu usahakan; orang-orang lain berusaha dan kamu datang memetik hasil usaha mereka."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 39, 'Dan banyak orang Samaria dari kota itu telah menjadi percaya kepada-Nya karena perkataan perempuan itu, yang bersaksi: "Ia mengatakan kepadaku segala sesuatu yang telah kuperbuat."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 40, 'Ketika orang-orang Samaria itu sampai kepada Yesus, mereka meminta kepada-Nya, supaya Ia tinggal pada mereka; dan Iapun tinggal di situ dua hari lamanya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 41, 'Dan lebih banyak lagi orang yang menjadi percaya karena perkataan-Nya,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 42, 'dan mereka berkata kepada perempuan itu: "Kami percaya, tetapi bukan lagi karena apa yang kaukatakan, sebab kami sendiri telah mendengar Dia dan kami tahu, bahwa Dialah benar-benar Juruselamat dunia."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 43, 'Dan setelah dua hari itu Yesus berangkat dari sana ke Galilea,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 44, 'sebab Yesus sendiri telah bersaksi, bahwa seorang nabi tidak dihormati di negerinya sendiri.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 45, 'Maka setelah ia tiba di Galilea, orang-orang Galileapun menyambut Dia, karena mereka telah melihat segala sesuatu yang dikerjakan-Nya di Yerusalem pada pesta itu, sebab mereka sendiripun turut ke pesta itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 46, 'Maka Yesus kembali lagi ke Kana di Galilea, di mana Ia membuat air menjadi anggur. Dan di Kapernaum ada seorang pegawai istana, anaknya sedang sakit.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 47, 'Ketika ia mendengar, bahwa Yesus telah datang dari Yudea ke Galilea, pergilah ia kepada-Nya lalu meminta, supaya Ia datang dan menyembuhkan anaknya, sebab anaknya itu hampir mati.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 48, 'Maka kata Yesus kepadanya: "Jika kamu tidak melihat tanda dan mujizat, kamu tidak percaya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 49, 'Pegawai istana itu berkata kepada-Nya: "Tuhan, datanglah sebelum anakku mati."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 50, 'Kata Yesus kepadanya: "Pergilah, anakmu hidup!" Orang itu percaya akan perkataan yang dikatakan Yesus kepadanya, lalu pergi.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 51, 'Ketika ia masih di tengah jalan hamba-hambanya telah datang kepadanya dengan kabar, bahwa anaknya hidup.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 52, 'Ia bertanya kepada mereka pukul berapa anak itu mulai sembuh. Jawab mereka: "Kemarin siang pukul satu demamnya hilang."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 53, 'Maka teringatlah ayah itu, bahwa pada saat itulah Yesus berkata kepadanya: "Anakmu hidup." Lalu iapun percaya, ia dan seluruh keluarganya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 4, 54, 'Dan itulah tanda kedua yang dibuat Yesus ketika Ia pulang dari Yudea ke Galilea.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 1, 'Sesudah itu ada hari raya orang Yahudi, dan Yesus berangkat ke Yerusalem.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 2, 'Di Yerusalem dekat Pintu Gerbang Domba ada sebuah kolam, yang dalam bahasa Ibrani disebut Betesda; ada lima serambinya', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 3, 'dan di serambi-serambi itu berbaring sejumlah besar orang sakit: orang-orang buta, orang-orang timpang dan orang-orang lumpuh, yang menantikan goncangan air kolam itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 4, 'Sebab sewaktu-waktu turun malaikat Tuhan ke kolam itu dan menggoncangkan air itu; barangsiapa yang terdahulu masuk ke dalamnya sesudah goncangan air itu, menjadi sembuh, apapun juga penyakitnya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 5, 'Di situ ada seorang yang sudah tiga puluh delapan tahun lamanya sakit.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 6, 'Ketika Yesus melihat orang itu berbaring di situ dan karena Ia tahu, bahwa ia telah lama dalam keadaan itu, berkatalah Ia kepadanya: "Maukah engkau sembuh?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 7, 'Jawab orang sakit itu kepada-Nya: "Tuhan, tidak ada orang yang menurunkan aku ke dalam kolam itu apabila airnya mulai goncang, dan sementara aku menuju ke kolam itu, orang lain sudah turun mendahului aku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 8, 'Kata Yesus kepadanya: "Bangunlah, angkatlah tilammu dan berjalanlah."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 9, 'Dan pada saat itu juga sembuhlah orang itu lalu ia mengangkat tilamnya dan berjalan. Tetapi hari itu hari Sabat.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 10, 'Karena itu orang-orang Yahudi berkata kepada orang yang baru sembuh itu: "Hari ini hari Sabat dan tidak boleh engkau memikul tilammu."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 11, 'Akan tetapi ia menjawab mereka: "Orang yang telah menyembuhkan aku, dia yang mengatakan kepadaku: Angkatlah tilammu dan berjalanlah."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 12, 'Mereka bertanya kepadanya: "Siapakah orang itu yang berkata kepadamu: Angkatlah tilammu dan berjalanlah?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 13, 'Tetapi orang yang baru sembuh itu tidak tahu siapa orang itu, sebab Yesus telah menghilang ke tengah-tengah orang banyak di tempat itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 14, 'Kemudian Yesus bertemu dengan dia dalam Bait Allah lalu berkata kepadanya: "Engkau telah sembuh; jangan berbuat dosa lagi, supaya padamu jangan terjadi yang lebih buruk."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 15, 'Orang itu keluar, lalu menceriterakan kepada orang-orang Yahudi, bahwa Yesuslah yang telah menyembuhkan dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 16, 'Dan karena itu orang-orang Yahudi berusaha menganiaya Yesus, karena Ia melakukan hal-hal itu pada hari Sabat.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 17, 'Tetapi Ia berkata kepada mereka: "Bapa-Ku bekerja sampai sekarang, maka Akupun bekerja juga."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 18, 'Sebab itu orang-orang Yahudi lebih berusaha lagi untuk membunuh-Nya, bukan saja karena Ia meniadakan hari Sabat, tetapi juga karena Ia mengatakan bahwa Allah adalah Bapa-Nya sendiri dan dengan demikian menyamakan diri-Nya dengan Allah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 19, 'Maka Yesus menjawab mereka, kata-Nya: "Aku berkata kepadamu, sesungguhnya Anak tidak dapat mengerjakan sesuatu dari diri-Nya sendiri, jikalau tidak Ia melihat Bapa mengerjakannya; sebab apa yang dikerjakan Bapa, itu juga yang dikerjakan Anak.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 20, 'Sebab Bapa mengasihi Anak dan Ia menunjukkan kepada-Nya segala sesuatu yang dikerjakan-Nya sendiri, bahkan Ia akan menunjukkan kepada-Nya pekerjaan-pekerjaan yang lebih besar lagi dari pada pekerjaan-pekerjaan itu, sehingga kamu menjadi heran.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 21, 'Sebab sama seperti Bapa membangkitkan orang-orang mati dan menghidupkannya, demikian juga Anak menghidupkan barangsiapa yang dikehendaki-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 22, 'Bapa tidak menghakimi siapapun, melainkan telah menyerahkan penghakiman itu seluruhnya kepada Anak,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 23, 'supaya semua orang menghormati Anak sama seperti mereka menghormati Bapa. Barangsiapa tidak menghormati Anak, ia juga tidak menghormati Bapa, yang mengutus Dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 24, 'Aku berkata kepadamu: Sesungguhnya barangsiapa mendengar perkataan-Ku dan percaya kepada Dia yang mengutus Aku, ia mempunyai hidup yang kekal dan tidak turut dihukum, sebab ia sudah pindah dari dalam maut ke dalam hidup.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 25, 'Aku berkata kepadamu: Sesungguhnya saatnya akan tiba dan sudah tiba, bahwa orang-orang mati akan mendengar suara Anak Allah, dan mereka yang mendengarnya, akan hidup.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 26, 'Sebab sama seperti Bapa mempunyai hidup dalam diri-Nya sendiri, demikian juga diberikan-Nya Anak mempunyai hidup dalam diri-Nya sendiri.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 27, 'Dan Ia telah memberikan kuasa kepada-Nya untuk menghakimi, karena Ia adalah Anak Manusia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 28, 'Janganlah kamu heran akan hal itu, sebab saatnya akan tiba, bahwa semua orang yang di dalam kuburan akan mendengar suara-Nya,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 29, 'dan mereka yang telah berbuat baik akan keluar dan bangkit untuk hidup yang kekal, tetapi mereka yang telah berbuat jahat akan bangkit untuk dihukum.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 30, 'Aku tidak dapat berbuat apa-apa dari diri-Ku sendiri; Aku menghakimi sesuai dengan apa yang Aku dengar, dan penghakiman-Ku adil, sebab Aku tidak menuruti kehendak-Ku sendiri, melainkan kehendak Dia yang mengutus Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 31, 'Kalau Aku bersaksi tentang diri-Ku sendiri, maka kesaksian-Ku itu tidak benar;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 32, 'ada yang lain yang bersaksi tentang Aku dan Aku tahu, bahwa kesaksian yang diberikan-Nya tentang Aku adalah benar.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 33, 'Kamu telah mengirim utusan kepada Yohanes dan ia telah bersaksi tentang kebenaran;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 34, 'tetapi Aku tidak memerlukan kesaksian dari manusia, namun Aku mengatakan hal ini, supaya kamu diselamatkan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 35, 'Ia adalah pelita yang menyala dan yang bercahaya dan kamu hanya mau menikmati seketika saja cahayanya itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 36, 'Tetapi Aku mempunyai suatu kesaksian yang lebih penting dari pada kesaksian Yohanes, yaitu segala pekerjaan yang diserahkan Bapa kepada-Ku, supaya Aku melaksanakannya. Pekerjaan itu juga yang Kukerjakan sekarang, dan itulah yang memberi kesaksian tentang Aku, bahwa Bapa yang mengutus Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 37, 'Bapa yang mengutus Aku, Dialah yang bersaksi tentang Aku. Kamu tidak pernah mendengar suara-Nya, rupa-Nyapun tidak pernah kamu lihat,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 38, 'dan firman-Nya tidak menetap di dalam dirimu, sebab kamu tidak percaya kepada Dia yang diutus-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 39, 'Kamu menyelidiki Kitab-kitab Suci, sebab kamu menyangka bahwa oleh-Nya kamu mempunyai hidup yang kekal, tetapi walaupun Kitab-kitab Suci itu memberi kesaksian tentang Aku,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 40, 'namun kamu tidak mau datang kepada-Ku untuk memperoleh hidup itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 41, 'Aku tidak memerlukan hormat dari manusia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 42, 'Tetapi tentang kamu, memang Aku tahu bahwa di dalam hatimu kamu tidak mempunyai kasih akan Allah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 43, 'Aku datang dalam nama Bapa-Ku dan kamu tidak menerima Aku; jikalau orang lain datang atas namanya sendiri, kamu akan menerima dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 44, 'Bagaimanakah kamu dapat percaya, kamu yang menerima hormat seorang dari yang lain dan yang tidak mencari hormat yang datang dari Allah yang Esa?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 45, 'Jangan kamu menyangka, bahwa Aku akan mendakwa kamu di hadapan Bapa; yang mendakwa kamu adalah Musa, yaitu Musa, yang kepadanya kamu menaruh pengharapanmu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 46, 'Sebab jikalau kamu percaya kepada Musa, tentu kamu akan percaya juga kepada-Ku, sebab ia telah menulis tentang Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 5, 47, 'Tetapi jikalau kamu tidak percaya akan apa yang ditulisnya, bagaimanakah kamu akan percaya akan apa yang Kukatakan?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 1, 'Sesudah itu Yesus berangkat ke seberang danau Galilea, yaitu danau Tiberias.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 2, 'Orang banyak berbondong-bondong mengikuti Dia, karena mereka melihat mujizat-mujizat penyembuhan, yang diadakan-Nya terhadap orang-orang sakit.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 3, 'Dan Yesus naik ke atas gunung dan duduk di situ dengan murid-murid-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 4, 'Dan Paskah, hari raya orang Yahudi, sudah dekat.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 5, 'Ketika Yesus memandang sekeliling-Nya dan melihat, bahwa orang banyak berbondong-bondong datang kepada-Nya, berkatalah Ia kepada Filipus: "Di manakah kita akan membeli roti, supaya mereka ini dapat makan?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 6, 'Hal itu dikatakan-Nya untuk mencobai dia, sebab Ia sendiri tahu, apa yang hendak dilakukan-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 7, 'Jawab Filipus kepada-Nya: "Roti seharga dua ratus dinar tidak akan cukup untuk mereka ini, sekalipun masing-masing mendapat sepotong kecil saja."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 8, 'Seorang dari murid-murid-Nya, yaitu Andreas, saudara Simon Petrus, berkata kepada-Nya:', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 9, '"Di sini ada seorang anak, yang mempunyai lima roti jelai dan dua ikan; tetapi apakah artinya itu untuk orang sebanyak ini?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 10, 'Kata Yesus: "Suruhlah orang-orang itu duduk." Adapun di tempat itu banyak rumput. Maka duduklah orang-orang itu, kira-kira lima ribu laki-laki banyaknya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 11, 'Lalu Yesus mengambil roti itu, mengucap syukur dan membagi-bagikannya kepada mereka yang duduk di situ, demikian juga dibuat-Nya dengan ikan-ikan itu, sebanyak yang mereka kehendaki.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 12, 'Dan setelah mereka kenyang Ia berkata kepada murid-murid-Nya: "Kumpulkanlah potongan-potongan yang lebih supaya tidak ada yang terbuang."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 13, 'Maka merekapun mengumpulkannya, dan mengisi dua belas bakul penuh dengan potongan-potongan dari kelima roti jelai yang lebih setelah orang makan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 14, 'Ketika orang-orang itu melihat mujizat yang telah diadakan-Nya, mereka berkata: "Dia ini adalah benar-benar nabi yang akan datang ke dalam dunia."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 15, 'Karena Yesus tahu, bahwa mereka hendak datang dan hendak membawa Dia dengan paksa untuk menjadikan Dia raja, Ia menyingkir pula ke gunung, seorang diri.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 16, 'Dan ketika hari sudah mulai malam, murid-murid Yesus pergi ke danau, lalu naik ke perahu', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 17, 'dan menyeberang ke Kapernaum. Ketika hari sudah gelap Yesus belum juga datang mendapatkan mereka,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 18, 'sedang laut bergelora karena angin kencang.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 19, 'Sesudah mereka mendayung kira-kira dua tiga mil jauhnya, mereka melihat Yesus berjalan di atas air mendekati perahu itu. Maka ketakutanlah mereka.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 20, 'Tetapi Ia berkata kepada mereka: "Aku ini, jangan takut!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 21, 'Mereka mau menaikkan Dia ke dalam perahu, dan seketika juga perahu itu sampai ke pantai yang mereka tujui.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 22, 'Pada keesokan harinya orang banyak, yang masih tinggal di seberang, melihat bahwa di situ tidak ada perahu selain dari pada yang satu tadi dan bahwa Yesus tidak turut naik ke perahu itu bersama-sama dengan murid-murid-Nya, dan bahwa murid-murid-Nya saja yang berangkat.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 23, 'Tetapi sementara itu beberapa perahu lain datang dari Tiberias dekat ke tempat mereka makan roti, sesudah Tuhan mengucapkan syukur atasnya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 24, 'Ketika orang banyak melihat, bahwa Yesus tidak ada di situ dan murid-murid-Nya juga tidak, mereka naik ke perahu-perahu itu lalu berangkat ke Kapernaum untuk mencari Yesus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 25, 'Ketika orang banyak menemukan Yesus di seberang laut itu, mereka berkata kepada-Nya: "Rabi, bilamana Engkau tiba di sini?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 26, 'Yesus menjawab mereka: "Aku berkata kepadamu, sesungguhnya kamu mencari Aku, bukan karena kamu telah melihat tanda-tanda, melainkan karena kamu telah makan roti itu dan kamu kenyang.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 27, 'Bekerjalah, bukan untuk makanan yang akan dapat binasa, melainkan untuk makanan yang bertahan sampai kepada hidup yang kekal, yang akan diberikan Anak Manusia kepadamu; sebab Dialah yang disahkan oleh Bapa, Allah, dengan meterai-Nya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 28, 'Lalu kata mereka kepada-Nya: "Apakah yang harus kami perbuat, supaya kami mengerjakan pekerjaan yang dikehendaki Allah?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 29, 'Jawab Yesus kepada mereka: "Inilah pekerjaan yang dikehendaki Allah, yaitu hendaklah kamu percaya kepada Dia yang telah diutus Allah."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 30, 'Maka kata mereka kepada-Nya: "Tanda apakah yang Engkau perbuat, supaya dapat kami melihatnya dan percaya kepada-Mu? Pekerjaan apakah yang Engkau lakukan?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 31, 'Nenek moyang kami telah makan manna di padang gurun, seperti ada tertulis: Mereka diberi-Nya makan roti dari sorga."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 32, 'Maka kata Yesus kepada mereka: "Aku berkata kepadamu, sesungguhnya bukan Musa yang memberikan kamu roti dari sorga, melainkan Bapa-Ku yang memberikan kamu roti yang benar dari sorga.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 33, 'Karena roti yang dari Allah ialah roti yang turun dari sorga dan yang memberi hidup kepada dunia."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 34, 'Maka kata mereka kepada-Nya: "Tuhan, berikanlah kami roti itu senantiasa."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 35, 'Kata Yesus kepada mereka: "Akulah roti hidup; barangsiapa datang kepada-Ku, ia tidak akan lapar lagi, dan barangsiapa percaya kepada-Ku, ia tidak akan haus lagi.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 36, 'Tetapi Aku telah berkata kepadamu: Sungguhpun kamu telah melihat Aku, kamu tidak percaya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 37, 'Semua yang diberikan Bapa kepada-Ku akan datang kepada-Ku, dan barangsiapa datang kepada-Ku, ia tidak akan Kubuang.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 38, 'Sebab Aku telah turun dari sorga bukan untuk melakukan kehendak-Ku, tetapi untuk melakukan kehendak Dia yang telah mengutus Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 39, 'Dan Inilah kehendak Dia yang telah mengutus Aku, yaitu supaya dari semua yang telah diberikan-Nya kepada-Ku jangan ada yang hilang, tetapi supaya Kubangkitkan pada akhir zaman.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 40, 'Sebab inilah kehendak Bapa-Ku, yaitu supaya setiap orang, yang melihat Anak dan yang percaya kepada-Nya beroleh hidup yang kekal, dan supaya Aku membangkitkannya pada akhir zaman."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 41, 'Maka bersungut-sungutlah orang Yahudi tentang Dia, karena Ia telah mengatakan: "Akulah roti yang telah turun dari sorga."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 42, 'Kata mereka: "Bukankah Ia ini Yesus, anak Yusuf, yang ibu bapanya kita kenal? Bagaimana Ia dapat berkata: Aku telah turun dari sorga?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 43, 'Jawab Yesus kepada mereka: "Jangan kamu bersungut-sungut.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 44, 'Tidak ada seorangpun yang dapat datang kepada-Ku, jikalau ia tidak ditarik oleh Bapa yang mengutus Aku, dan ia akan Kubangkitkan pada akhir zaman.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 45, 'Ada tertulis dalam kitab nabi-nabi: Dan mereka semua akan diajar oleh Allah. Dan setiap orang, yang telah mendengar dan menerima pengajaran dari Bapa, datang kepada-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 46, 'Hal itu tidak berarti, bahwa ada orang yang telah melihat Bapa. Hanya Dia yang datang dari Allah, Dialah yang telah melihat Bapa.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 47, 'Aku berkata kepadamu: Sesungguhnya barangsiapa percaya, ia mempunyai hidup yang kekal.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 48, 'Akulah roti hidup.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 49, 'Nenek moyangmu telah makan manna di padang gurun dan mereka telah mati.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 50, 'Inilah roti yang turun dari sorga: Barangsiapa makan dari padanya, ia tidak akan mati.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 51, 'Akulah roti hidup yang telah turun dari sorga. Jikalau seorang makan dari roti ini, ia akan hidup selama-lamanya, dan roti yang Kuberikan itu ialah daging-Ku, yang akan Kuberikan untuk hidup dunia."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 52, 'Orang-orang Yahudi bertengkar antara sesama mereka dan berkata: "Bagaimana Ia ini dapat memberikan daging-Nya kepada kita untuk dimakan."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 53, 'Maka kata Yesus kepada mereka: "Aku berkata kepadamu, sesungguhnya jikalau kamu tidak makan daging Anak Manusia dan minum darah-Nya, kamu tidak mempunyai hidup di dalam dirimu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 54, 'Barangsiapa makan daging-Ku dan minum darah-Ku, ia mempunyai hidup yang kekal dan Aku akan membangkitkan dia pada akhir zaman.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 55, 'Sebab daging-Ku adalah benar-benar makanan dan darah-Ku adalah benar-benar minuman.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 56, 'Barangsiapa makan daging-Ku dan minum darah-Ku, ia tinggal di dalam Aku dan Aku di dalam dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 57, 'Sama seperti Bapa yang hidup mengutus Aku dan Aku hidup oleh Bapa, demikian juga barangsiapa yang memakan Aku, akan hidup oleh Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 58, 'Inilah roti yang telah turun dari sorga, bukan roti seperti yang dimakan nenek moyangmu dan mereka telah mati. Barangsiapa makan roti ini, ia akan hidup selama-lamanya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 59, 'Semuanya ini dikatakan Yesus di Kapernaum ketika Ia mengajar di rumah ibadat.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 6, 60, 'Sesudah mendengar semuanya itu banyak dari murid-murid Yesus yang berkata: "Perkataan ini keras, siapakah yang sanggup mendengarkannya?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 1, 'Sesudah itu Yesus berjalan keliling Galilea, sebab Ia tidak mau tetap tinggal di Yudea, karena di sana orang-orang Yahudi berusaha untuk membunuh-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 2, 'Ketika itu sudah dekat hari raya orang Yahudi, yaitu hari raya Pondok Daun.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 3, 'Maka kata saudara-saudara Yesus kepada-Nya: "Berangkatlah dari sini dan pergi ke Yudea, supaya murid-murid-Mu juga melihat perbuatan-perbuatan yang Engkau lakukan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 4, 'Sebab tidak seorangpun berbuat sesuatu di tempat tersembunyi, jika ia mau diakui di muka umum. Jikalau Engkau berbuat hal-hal yang demikian, tampakkanlah diri-Mu kepada dunia."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 5, 'Sebab saudara-saudara-Nya sendiripun tidak percaya kepada-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 6, 'Maka jawab Yesus kepada mereka: "Waktu-Ku belum tiba, tetapi bagi kamu selalu ada waktu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 7, 'Dunia tidak dapat membenci kamu, tetapi ia membenci Aku, sebab Aku bersaksi tentang dia, bahwa pekerjaan-pekerjaannya jahat.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 8, 'Pergilah kamu ke pesta itu. Aku belum pergi ke situ, karena waktu-Ku belum genap."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 9, 'Demikianlah kata-Nya kepada mereka, dan Iapun tinggal di Galilea.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 10, 'Tetapi sesudah saudara-saudara Yesus berangkat ke pesta itu, Iapun pergi juga ke situ, tidak terang-terangan tetapi diam-diam.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 11, 'Orang-orang Yahudi mencari Dia di pesta itu dan berkata: "Di manakah Ia?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 12, 'Dan banyak terdengar bisikan di antara orang banyak tentang Dia. Ada yang berkata: "Ia orang baik." Ada pula yang berkata: "Tidak, Ia menyesatkan rakyat."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 13, 'Tetapi tidak seorangpun yang berani berkata terang-terangan tentang Dia karena takut terhadap orang-orang Yahudi.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 14, 'Waktu pesta itu sedang berlangsung, Yesus masuk ke Bait Allah lalu mengajar di situ.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 15, 'Maka heranlah orang-orang Yahudi dan berkata: "Bagaimanakah orang ini mempunyai pengetahuan demikian tanpa belajar!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 16, 'Jawab Yesus kepada mereka: "Ajaran-Ku tidak berasal dari diri-Ku sendiri, tetapi dari Dia yang telah mengutus Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 17, 'Barangsiapa mau melakukan kehendak-Nya, ia akan tahu entah ajaran-Ku ini berasal dari Allah, entah Aku berkata-kata dari diri-Ku sendiri.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 18, 'Barangsiapa berkata-kata dari dirinya sendiri, ia mencari hormat bagi dirinya sendiri, tetapi barangsiapa mencari hormat bagi Dia yang mengutusnya, ia benar dan tidak ada ketidakbenaran padanya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 19, 'Bukankah Musa yang telah memberikan hukum Taurat kepadamu? Namun tidak seorangpun di antara kamu yang melakukan hukum Taurat itu. Mengapa kamu berusaha membunuh Aku?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 20, 'Orang banyak itu menjawab: "Engkau kerasukan setan; siapakah yang berusaha membunuh Engkau?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 21, 'Jawab Yesus kepada mereka: "Hanya satu perbuatan yang Kulakukan dan kamu semua telah heran.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 22, 'Jadi: Musa menetapkan supaya kamu bersunat?sebenarnya sunat itu tidak berasal dari Musa, tetapi dari nenek moyang kita?dan kamu menyunat orang pada hari Sabat!', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 23, 'Jikalau seorang menerima sunat pada hari Sabat, supaya jangan melanggar hukum Musa, mengapa kamu marah kepada-Ku, karena Aku menyembuhkan seluruh tubuh seorang manusia pada hari Sabat.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 24, 'Janganlah menghakimi menurut apa yang nampak, tetapi hakimilah dengan adil."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 25, 'Beberapa orang Yerusalem berkata: "Bukankah Dia ini yang mereka mau bunuh?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 26, 'Dan lihatlah, Ia berbicara dengan leluasa dan mereka tidak mengatakan apa-apa kepada-Nya. Mungkinkah pemimpin kita benar-benar sudah tahu, bahwa Ia adalah Kristus?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 27, 'Tetapi tentang orang ini kita tahu dari mana asal-Nya, tetapi bilamana Kristus datang, tidak ada seorangpun yang tahu dari mana asal-Nya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 28, 'Waktu Yesus mengajar di Bait Allah, Ia berseru: "Memang Aku kamu kenal dan kamu tahu dari mana asal-Ku; namun Aku datang bukan atas kehendak-Ku sendiri, tetapi Aku diutus oleh Dia yang benar yang tidak kamu kenal.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 29, 'Aku kenal Dia, sebab Aku datang dari Dia dan Dialah yang mengutus Aku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 30, 'Mereka berusaha menangkap Dia, tetapi tidak ada seorangpun yang menyentuh Dia, sebab saat-Nya belum tiba.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 31, 'Tetapi di antara orang banyak itu ada banyak yang percaya kepada-Nya dan mereka berkata: "Apabila Kristus datang, mungkinkah Ia akan mengadakan lebih banyak mujizat dari pada yang telah diadakan oleh Dia ini?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 32, 'Orang-orang Farisi mendengar orang banyak membisikkan hal-hal itu mengenai Dia, dan karena itu imam-imam kepala dan orang-orang Farisi menyuruh penjaga-penjaga Bait Allah untuk menangkap-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 33, 'Maka kata Yesus: "Tinggal sedikit waktu saja Aku ada bersama kamu dan sesudah itu Aku akan pergi kepada Dia yang telah mengutus Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 34, 'Kamu akan mencari Aku, tetapi tidak akan bertemu dengan Aku, sebab kamu tidak dapat datang ke tempat di mana Aku berada."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 35, 'Orang-orang Yahudi itu berkata seorang kepada yang lain: "Ke manakah Ia akan pergi, sehingga kita tidak dapat bertemu dengan Dia? Adakah maksud-Nya untuk pergi kepada mereka yang tinggal di perantauan, di antara orang Yunani, untuk mengajar orang Yunani?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 36, 'Apakah maksud perkataan yang diucapkan-Nya ini: Kamu akan mencari Aku, tetapi kamu tidak akan bertemu dengan Aku, dan: Kamu tidak dapat datang ke tempat di mana Aku berada?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 37, 'Dan pada hari terakhir, yaitu pada puncak perayaan itu, Yesus berdiri dan berseru: "Barangsiapa haus, baiklah ia datang kepada-Ku dan minum!', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 38, 'Barangsiapa percaya kepada-Ku, seperti yang dikatakan oleh Kitab Suci: Dari dalam hatinya akan mengalir aliran-aliran air hidup."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 39, 'Yang dimaksudkan-Nya ialah Roh yang akan diterima oleh mereka yang percaya kepada-Nya; sebab Roh itu belum datang, karena Yesus belum dimuliakan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 40, 'Beberapa orang di antara orang banyak, yang mendengarkan perkataan-perkata itu, berkata: "Dia ini benar-benar nabi yang akan datang."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 41, 'Yang lain berkata: "Ia ini Mesias." Tetapi yang lain lagi berkata: "Bukan, Mesias tidak datang dari Galilea!', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 42, 'Karena Kitab Suci mengatakan, bahwa Mesias berasal dari keturunan Daud dan dari kampung Betlehem, tempat Daud dahulu tinggal."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 43, 'Maka timbullah pertentangan di antara orang banyak karena Dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 44, 'Beberapa orang di antara mereka mau menangkap Dia, tetapi tidak ada seorangpun yang berani menyentuh-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 45, 'Maka penjaga-penjaga itu pergi kepada imam-imam kepala dan orang-orang Farisi, yang berkata kepada mereka: "Mengapa kamu tidak membawa-Nya?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 46, 'Jawab penjaga-penjaga itu: "Belum pernah seorang manusia berkata seperti orang itu!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 47, 'Jawab orang-orang Farisi itu kepada mereka: "Adakah kamu juga disesatkan?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 48, 'Adakah seorang di antara pemimpin-pemimpin yang percaya kepada-Nya, atau seorang di antara orang-orang Farisi?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 49, 'Tetapi orang banyak ini yang tidak mengenal hukum Taurat, terkutuklah mereka!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 50, 'Nikodemus, seorang dari mereka, yang dahulu telah datang kepada-Nya, berkata kepada mereka:', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 51, '"Apakah hukum Taurat kita menghukum seseorang, sebelum ia didengar dan sebelum orang mengetahui apa yang telah dibuat-Nya?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 52, 'Jawab mereka: "Apakah engkau juga orang Galilea? Selidikilah Kitab Suci dan engkau akan tahu bahwa tidak ada nabi yang datang dari Galilea."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 7, 53, 'Lalu mereka pulang, masing-masing ke rumahnya,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 1, 'tetapi Yesus pergi ke bukit Zaitun.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 2, 'Pagi-pagi benar Ia berada lagi di Bait Allah, dan seluruh rakyat datang kepada-Nya. Ia duduk dan mengajar mereka.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 3, 'Maka ahli-ahli Taurat dan orang-orang Farisi membawa kepada-Nya seorang perempuan yang kedapatan berbuat zinah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 4, 'Mereka menempatkan perempuan itu di tengah-tengah lalu berkata kepada Yesus: "Rabi, perempuan ini tertangkap basah ketika ia sedang berbuat zinah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 5, 'Musa dalam hukum Taurat memerintahkan kita untuk melempari perempuan-perempuan yang demikian. Apakah pendapat-Mu tentang hal itu?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 6, 'Mereka mengatakan hal itu untuk mencobai Dia, supaya mereka memperoleh sesuatu untuk menyalahkan-Nya. Tetapi Yesus membungkuk lalu menulis dengan jari-Nya di tanah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 7, 'Dan ketika mereka terus-menerus bertanya kepada-Nya, Iapun bangkit berdiri lalu berkata kepada mereka: "Barangsiapa di antara kamu tidak berdosa, hendaklah ia yang pertama melemparkan batu kepada perempuan itu."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 8, 'Lalu Ia membungkuk pula dan menulis di tanah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 9, 'Tetapi setelah mereka mendengar perkataan itu, pergilah mereka seorang demi seorang, mulai dari yang tertua. Akhirnya tinggallah Yesus seorang diri dengan perempuan itu yang tetap di tempatnya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 10, 'Lalu Yesus bangkit berdiri dan berkata kepadanya: "Hai perempuan, di manakah mereka? Tidak adakah seorang yang menghukum engkau?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 11, 'Jawabnya: "Tidak ada, Tuhan." Lalu kata Yesus: "Akupun tidak menghukum engkau. Pergilah, dan jangan berbuat dosa lagi mulai dari sekarang."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 12, 'Maka Yesus berkata pula kepada orang banyak, kata-Nya: "Akulah terang dunia; barangsiapa mengikut Aku, ia tidak akan berjalan dalam kegelapan, melainkan ia akan mempunyai terang hidup."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 13, 'Kata orang-orang Farisi kepada-Nya: "Engkau bersaksi tentang diri-Mu, kesaksian-Mu tidak benar."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 14, 'Jawab Yesus kepada mereka, kata-Nya: "Biarpun Aku bersaksi tentang diri-Ku sendiri, namun kesaksian-Ku itu benar, sebab Aku tahu, dari mana Aku datang dan ke mana Aku pergi. Tetapi kamu tidak tahu, dari mana Aku datang dan ke mana Aku pergi.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 15, 'Kamu menghakimi menurut ukuran manusia, Aku tidak menghakimi seorangpun,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 16, 'dan jikalau Aku menghakimi, maka penghakiman-Ku itu benar, sebab Aku tidak seorang diri, tetapi Aku bersama dengan Dia yang mengutus Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 17, 'Dan dalam kitab Tauratmu ada tertulis, bahwa kesaksian dua orang adalah sah;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 18, 'Akulah yang bersaksi tentang diri-Ku sendiri, dan juga Bapa, yang mengutus Aku, bersaksi tentang Aku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 19, 'Maka kata mereka kepada-Nya: "Di manakah Bapa-Mu?" Jawab Yesus: "Baik Aku, maupun Bapa-Ku tidak kamu kenal. Jikalau sekiranya kamu mengenal Aku, kamu mengenal juga Bapa-Ku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 20, 'Kata-kata itu dikatakan Yesus dekat perbendaharaan, waktu Ia mengajar di dalam Bait Allah. Dan tidak seorangpun yang menangkap Dia, karena saat-Nya belum tiba.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 21, 'Maka Yesus berkata pula kepada orang banyak: "Aku akan pergi dan kamu akan mencari Aku tetapi kamu akan mati dalam dosamu. Ke tempat Aku pergi, tidak mungkin kamu datang."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 22, 'Maka kata orang-orang Yahudi itu: "Apakah Ia mau bunuh diri dan karena itu dikatakan-Nya: Ke tempat Aku pergi, tidak mungkin kamu datang?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 23, 'Lalu Ia berkata kepada mereka: "Kamu berasal dari bawah, Aku dari atas; kamu dari dunia ini, Aku bukan dari dunia ini.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 24, 'Karena itu tadi Aku berkata kepadamu, bahwa kamu akan mati dalam dosamu; sebab jikalau kamu tidak percaya, bahwa Akulah Dia, kamu akan mati dalam dosamu."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 25, 'Maka kata mereka kepada-Nya: "Siapakah Engkau?" Jawab Yesus kepada mereka: "Apakah gunanya lagi Aku berbicara dengan kamu?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 26, 'Banyak yang harus Kukatakan dan Kuhakimi tentang kamu; akan tetapi Dia, yang mengutus Aku, adalah benar, dan apa yang Kudengar dari pada-Nya, itu yang Kukatakan kepada dunia."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 27, 'Mereka tidak mengerti, bahwa Ia berbicara kepada mereka tentang Bapa.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 28, 'Maka kata Yesus: "Apabila kamu telah meninggikan Anak Manusia, barulah kamu tahu, bahwa Akulah Dia, dan bahwa Aku tidak berbuat apa-apa dari diri-Ku sendiri, tetapi Aku berbicara tentang hal-hal, sebagaimana diajarkan Bapa kepada-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 29, 'Dan Ia, yang telah mengutus Aku, Ia menyertai Aku. Ia tidak membiarkan Aku sendiri, sebab Aku senantiasa berbuat apa yang berkenan kepada-Nya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 30, 'Setelah Yesus mengatakan semuanya itu, banyak orang percaya kepada-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 31, 'Maka kata-Nya kepada orang-orang Yahudi yang percaya kepada-Nya: "Jikalau kamu tetap dalam firman-Ku, kamu benar-benar adalah murid-Ku', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 32, 'dan kamu akan mengetahui kebenaran, dan kebenaran itu akan memerdekakan kamu."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 33, 'Jawab mereka: "Kami adalah keturunan Abraham dan tidak pernah menjadi hamba siapapun. Bagaimana Engkau dapat berkata: Kamu akan merdeka?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 34, 'Kata Yesus kepada mereka: "Aku berkata kepadamu, sesungguhnya setiap orang yang berbuat dosa, adalah hamba dosa.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 35, 'Dan hamba tidak tetap tinggal dalam rumah, tetapi anak tetap tinggal dalam rumah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 36, 'Jadi apabila Anak itu memerdekakan kamu, kamupun benar-benar merdeka."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 37, '"Aku tahu, bahwa kamu adalah keturunan Abraham, tetapi kamu berusaha untuk membunuh Aku karena firman-Ku tidak beroleh tempat di dalam kamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 38, 'Apa yang Kulihat pada Bapa, itulah yang Kukatakan, dan demikian juga kamu perbuat tentang apa yang kamu dengar dari bapamu."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 39, 'Jawab mereka kepada-Nya: "Bapa kami ialah Abraham." Kata Yesus kepada mereka: "Jikalau sekiranya kamu anak-anak Abraham, tentulah kamu mengerjakan pekerjaan yang dikerjakan oleh Abraham.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 40, 'Tetapi yang kamu kerjakan ialah berusaha membunuh Aku; Aku, seorang yang mengatakan kebenaran kepadamu, yaitu kebenaran yang Kudengar dari Allah; pekerjaan yang demikian tidak dikerjakan oleh Abraham.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 41, 'Kamu mengerjakan pekerjaan bapamu sendiri." Jawab mereka: "Kami tidak dilahirkan dari zinah. Bapa kami satu, yaitu Allah."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 42, 'Kata Yesus kepada mereka: "Jikalau Allah adalah Bapamu, kamu akan mengasihi Aku, sebab Aku keluar dan datang dari Allah. Dan Aku datang bukan atas kehendak-Ku sendiri, melainkan Dialah yang mengutus Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 43, 'Apakah sebabnya kamu tidak mengerti bahasa-Ku? Sebab kamu tidak dapat menangkap firman-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 44, 'Iblislah yang menjadi bapamu dan kamu ingin melakukan keinginan-keinginan bapamu. Ia adalah pembunuh manusia sejak semula dan tidak hidup dalam kebenaran, sebab di dalam dia tidak ada kebenaran. Apabila ia berkata dusta, ia berkata atas kehendaknya sendiri, sebab ia adalah pendusta dan bapa segala dusta.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 45, 'Tetapi karena Aku mengatakan kebenaran kepadamu, kamu tidak percaya kepada-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 46, 'Siapakah di antaramu yang membuktikan bahwa Aku berbuat dosa? Apabila Aku mengatakan kebenaran, mengapakah kamu tidak percaya kepada-Ku?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 47, 'Barangsiapa berasal dari Allah, ia mendengarkan firman Allah; itulah sebabnya kamu tidak mendengarkannya, karena kamu tidak berasal dari Allah."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 48, 'Orang-orang Yahudi menjawab Yesus: "Bukankah benar kalau kami katakan bahwa Engkau orang Samaria dan kerasukan setan?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 49, 'Jawab Yesus: "Aku tidak kerasukan setan, tetapi Aku menghormati Bapa-Ku dan kamu tidak menghormati Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 50, 'Tetapi Aku tidak mencari hormat bagi-Ku: ada Satu yang mencarinya dan Dia juga yang menghakimi.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 51, 'Aku berkata kepadamu: Sesungguhnya barangsiapa menuruti firman-Ku, ia tidak akan mengalami maut sampai selama-lamanya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 52, 'Kata orang-orang Yahudi kepada-Nya: "Sekarang kami tahu, bahwa Engkau kerasukan setan. Sebab Abraham telah mati dan demikian juga nabi-nabi, namun Engkau berkata: Barangsiapa menuruti firman-Ku, ia tidak akan mengalami maut sampai selama-lamanya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 53, 'Adakah Engkau lebih besar dari pada bapa kita Abraham, yang telah mati! Nabi-nabipun telah mati; dengan siapakah Engkau samakan diri-Mu?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 54, 'Jawab Yesus: "Jikalau Aku memuliakan diri-Ku sendiri, maka kemuliaan-Ku itu sedikitpun tidak ada artinya. Bapa-Kulah yang memuliakan Aku, tentang siapa kamu berkata: Dia adalah Allah kami,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 55, 'padahal kamu tidak mengenal Dia, tetapi Aku mengenal Dia. Dan jika Aku berkata: Aku tidak mengenal Dia, maka Aku adalah pendusta, sama seperti kamu, tetapi Aku mengenal Dia dan Aku menuruti firman-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 56, 'Abraham bapamu bersukacita bahwa ia akan melihat hari-Ku dan ia telah melihatnya dan ia bersukacita."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 57, 'Maka kata orang-orang Yahudi itu kepada-Nya: "Umur-Mu belum sampai lima puluh tahun dan Engkau telah melihat Abraham?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 58, 'Kata Yesus kepada mereka: "Aku berkata kepadamu, sesungguhnya sebelum Abraham jadi, Aku telah ada."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 8, 59, 'Lalu mereka mengambil batu untuk melempari Dia; tetapi Yesus menghilang dan meninggalkan Bait Allah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 1, 'Waktu Yesus sedang lewat, Ia melihat seorang yang buta sejak lahirnya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 2, 'Murid-murid-Nya bertanya kepada-Nya: "Rabi, siapakah yang berbuat dosa, orang ini sendiri atau orang tuanya, sehingga ia dilahirkan buta?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 3, 'Jawab Yesus: "Bukan dia dan bukan juga orang tuanya, tetapi karena pekerjaan-pekerjaan Allah harus dinyatakan di dalam dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 4, 'Kita harus mengerjakan pekerjaan Dia yang mengutus Aku, selama masih siang; akan datang malam, di mana tidak ada seorangpun yang dapat bekerja.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 5, 'Selama Aku di dalam dunia, Akulah terang dunia."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 6, 'Setelah Ia mengatakan semuanya itu, Ia meludah ke tanah, dan mengaduk ludahnya itu dengan tanah, lalu mengoleskannya pada mata orang buta tadi', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 7, 'dan berkata kepadanya: "Pergilah, basuhlah dirimu dalam kolam Siloam." Siloam artinya: "Yang diutus." Maka pergilah orang itu, ia membasuh dirinya lalu kembali dengan matanya sudah melek.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 8, 'Tetapi tetangga-tetangganya dan mereka, yang dahulu mengenalnya sebagai pengemis, berkata: "Bukankah dia ini, yang selalu mengemis?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 9, 'Ada yang berkata: "Benar, dialah ini." Ada pula yang berkata: "Bukan, tetapi ia serupa dengan dia." Orang itu sendiri berkata: "Benar, akulah itu."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 10, 'Kata mereka kepadanya: "Bagaimana matamu menjadi melek?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 11, 'Jawabnya: "Orang yang disebut Yesus itu mengaduk tanah, mengoleskannya pada mataku dan berkata kepadaku: Pergilah ke Siloam dan basuhlah dirimu. Lalu aku pergi dan setelah aku membasuh diriku, aku dapat melihat."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 12, 'Lalu mereka berkata kepadanya: "Di manakah Dia?" Jawabnya: "Aku tidak tahu."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 13, 'Lalu mereka membawa orang yang tadinya buta itu kepada orang-orang Farisi.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 14, 'Adapun hari waktu Yesus mengaduk tanah dan memelekkan mata orang itu, adalah hari Sabat.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 15, 'Karena itu orang-orang Farisipun bertanya kepadanya, bagaimana matanya menjadi melek. Jawabnya: "Ia mengoleskan adukan tanah pada mataku, lalu aku membasuh diriku, dan sekarang aku dapat melihat."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 16, 'Maka kata sebagian orang-orang Farisi itu: "Orang ini tidak datang dari Allah, sebab Ia tidak memelihara hari Sabat." Sebagian pula berkata: "Bagaimanakah seorang berdosa dapat membuat mujizat yang demikian?" Maka timbullah pertentangan di antara mereka.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 17, 'Lalu kata mereka pula kepada orang buta itu: "Dan engkau, apakah katamu tentang Dia, karena Ia telah memelekkan matamu?" Jawabnya: "Ia adalah seorang nabi."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 18, 'Tetapi orang-orang Yahudi itu tidak percaya, bahwa tadinya ia buta dan baru dapat melihat lagi, sampai mereka memanggil orang tuanya', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 19, 'dan bertanya kepada mereka: "Inikah anakmu, yang kamu katakan bahwa ia lahir buta? Kalau begitu bagaimanakah ia sekarang dapat melihat?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 20, 'Jawab orang tua itu: "Yang kami tahu ialah, bahwa dia ini anak kami dan bahwa ia lahir buta,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 21, 'tetapi bagaimana ia sekarang dapat melihat, kami tidak tahu, dan siapa yang memelekkan matanya, kami tidak tahu juga. Tanyakanlah kepadanya sendiri, ia sudah dewasa, ia dapat berkata-kata untuk dirinya sendiri."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 22, 'Orang tuanya berkata demikian, karena mereka takut kepada orang-orang Yahudi, sebab orang-orang Yahudi itu telah sepakat bahwa setiap orang yang mengaku Dia sebagai Mesias, akan dikucilkan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 23, 'Itulah sebabnya maka orang tuanya berkata: "Ia telah dewasa, tanyakanlah kepadanya sendiri."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 24, 'Lalu mereka memanggil sekali lagi orang yang tadinya buta itu dan berkata kepadanya: "Katakanlah kebenaran di hadapan Allah; kami tahu bahwa orang itu orang berdosa."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 25, 'Jawabnya: "Apakah orang itu orang berdosa, aku tidak tahu; tetapi satu hal aku tahu, yaitu bahwa aku tadinya buta, dan sekarang dapat melihat."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 26, 'Kata mereka kepadanya: "Apakah yang diperbuat-Nya padamu? Bagaimana Ia memelekkan matamu?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 27, 'Jawabnya: "Telah kukatakan kepadamu, dan kamu tidak mendengarkannya; mengapa kamu hendak mendengarkannya lagi? Barangkali kamu mau menjadi murid-Nya juga?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 28, 'Sambil mengejek mereka berkata kepadanya: "Engkau murid orang itu tetapi kami murid-murid Musa.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 29, 'Kami tahu, bahwa Allah telah berfirman kepada Musa, tetapi tentang Dia itu kami tidak tahu dari mana Ia datang."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 30, 'Jawab orang itu kepada mereka: "Aneh juga bahwa kamu tidak tahu dari mana Ia datang, sedangkan Ia telah memelekkan mataku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 31, 'Kita tahu, bahwa Allah tidak mendengarkan orang-orang berdosa, melainkan orang-orang yang saleh dan yang melakukan kehendak-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 32, 'Dari dahulu sampai sekarang tidak pernah terdengar, bahwa ada orang yang memelekkan mata orang yang lahir buta.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 33, 'Jikalau orang itu tidak datang dari Allah, Ia tidak dapat berbuat apa-apa."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 34, 'Jawab mereka: "Engkau ini lahir sama sekali dalam dosa dan engkau hendak mengajar kami?" Lalu mereka mengusir dia ke luar.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 35, 'Yesus mendengar bahwa ia telah diusir ke luar oleh mereka. Kemudian Ia bertemu dengan dia dan berkata: "Percayakah engkau kepada Anak Manusia?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 36, 'Jawabnya: "Siapakah Dia, Tuhan? Supaya aku percaya kepada-Nya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 37, 'Kata Yesus kepadanya: "Engkau bukan saja melihat Dia; tetapi Dia yang sedang berkata-kata dengan engkau, Dialah itu!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 38, 'Katanya: "Aku percaya, Tuhan!" Lalu ia sujud menyembah-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 39, 'Kata Yesus: "Aku datang ke dalam dunia untuk menghakimi, supaya barangsiapa yang tidak melihat, dapat melihat, dan supaya barangsiapa yang dapat melihat, menjadi buta."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 40, 'Kata-kata itu didengar oleh beberapa orang Farisi yang berada di situ dan mereka berkata kepada-Nya: "Apakah itu berarti bahwa kami juga buta?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 9, 41, 'Jawab Yesus kepada mereka: "Sekiranya kamu buta, kamu tidak berdosa, tetapi karena kamu berkata: Kami melihat, maka tetaplah dosamu."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 1, '"Aku berkata kepadamu: Sesungguhnya siapa yang masuk ke dalam kandang domba dengan tidak melalui pintu, tetapi dengan memanjat tembok, ia adalah seorang pencuri dan seorang perampok;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 2, 'tetapi siapa yang masuk melalui pintu, ia adalah gembala domba.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 3, 'Untuk dia penjaga membuka pintu dan domba-domba mendengarkan suaranya dan ia memanggil domba-dombanya masing-masing menurut namanya dan menuntunnya ke luar.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 4, 'Jika semua dombanya telah dibawanya ke luar, ia berjalan di depan mereka dan domba-domba itu mengikuti dia, karena mereka mengenal suaranya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 5, 'Tetapi seorang asing pasti tidak mereka ikuti, malah mereka lari dari padanya, karena suara orang-orang asing tidak mereka kenal."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 6, 'Itulah yang dikatakan Yesus dalam perumpamaan kepada mereka, tetapi mereka tidak mengerti apa maksudnya Ia berkata demikian kepada mereka.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 7, 'Maka kata Yesus sekali lagi: "Aku berkata kepadamu, sesungguhnya Akulah pintu ke domba-domba itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 8, 'Semua orang yang datang sebelum Aku, adalah pencuri dan perampok, dan domba-domba itu tidak mendengarkan mereka.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 9, 'Akulah pintu; barangsiapa masuk melalui Aku, ia akan selamat dan ia akan masuk dan keluar dan menemukan padang rumput.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 10, 'Pencuri datang hanya untuk mencuri dan membunuh dan membinasakan; Aku datang, supaya mereka mempunyai hidup, dan mempunyainya dalam segala kelimpahan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 11, 'Akulah gembala yang baik. Gembala yang baik memberikan nyawanya bagi domba-dombanya;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 12, 'sedangkan seorang upahan yang bukan gembala, dan yang bukan pemilik domba-domba itu sendiri, ketika melihat serigala datang, meninggalkan domba-domba itu lalu lari, sehingga serigala itu menerkam dan mencerai-beraikan domba-domba itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 13, 'Ia lari karena ia seorang upahan dan tidak memperhatikan domba-domba itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 14, 'Akulah gembala yang baik dan Aku mengenal domba-domba-Ku dan domba-domba-Ku mengenal Aku', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 15, 'sama seperti Bapa mengenal Aku dan Aku mengenal Bapa, dan Aku memberikan nyawa-Ku bagi domba-domba-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 16, 'Ada lagi pada-Ku domba-domba lain, yang bukan dari kandang ini; domba-domba itu harus Kutuntun juga dan mereka akan mendengarkan suara-Ku dan mereka akan menjadi satu kawanan dengan satu gembala.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 17, 'Bapa mengasihi Aku, oleh karena Aku memberikan nyawa-Ku untuk menerimanya kembali.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 18, 'Tidak seorangpun mengambilnya dari pada-Ku, melainkan Aku memberikannya menurut kehendak-Ku sendiri. Aku berkuasa memberikannya dan berkuasa mengambilnya kembali. Inilah tugas yang Kuterima dari Bapa-Ku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 19, 'Maka timbullah pula pertentangan di antara orang-orang Yahudi karena perkataan itu. Banyak di antara mereka berkata:', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 20, '"Ia kerasukan setan dan gila; mengapa kamu mendengarkan Dia?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 21, 'Yang lain berkata: "Itu bukan perkataan orang yang kerasukan setan; dapatkah setan memelekkan mata orang-orang buta?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 22, 'Tidak lama kemudian tibalah hari raya Pentahbisan Bait Allah di Yerusalem; ketika itu musim dingin.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 23, 'Dan Yesus berjalan-jalan di Bait Allah, di serambi Salomo.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 24, 'Maka orang-orang Yahudi mengelilingi Dia dan berkata kepada-Nya: "Berapa lama lagi Engkau membiarkan kami hidup dalam kebimbangan? Jikalau Engkau Mesias, katakanlah terus terang kepada kami."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 25, 'Yesus menjawab mereka: "Aku telah mengatakannya kepada kamu, tetapi kamu tidak percaya; pekerjaan-pekerjaan yang Kulakukan dalam nama Bapa-Ku, itulah yang memberikan kesaksian tentang Aku,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 26, 'tetapi kamu tidak percaya, karena kamu tidak termasuk domba-domba-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 27, 'Domba-domba-Ku mendengarkan suara-Ku dan Aku mengenal mereka dan mereka mengikut Aku,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 28, 'dan Aku memberikan hidup yang kekal kepada mereka dan mereka pasti tidak akan binasa sampai selama-lamanya dan seorangpun tidak akan merebut mereka dari tangan-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 29, 'Bapa-Ku, yang memberikan mereka kepada-Ku, lebih besar dari pada siapapun, dan seorangpun tidak dapat merebut mereka dari tangan Bapa.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 30, 'Aku dan Bapa adalah satu."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 31, 'Sekali lagi orang-orang Yahudi mengambil batu untuk melempari Yesus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 32, 'Kata Yesus kepada mereka: "Banyak pekerjaan baik yang berasal dari Bapa-Ku yang Kuperlihatkan kepadamu; pekerjaan manakah di antaranya yang menyebabkan kamu mau melempari Aku?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 33, 'Jawab orang-orang Yahudi itu: "Bukan karena suatu pekerjaan baik maka kami mau melempari Engkau, melainkan karena Engkau menghujat Allah dan karena Engkau, sekalipun hanya seorang manusia saja, menyamakan diri-Mu dengan Allah."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 34, 'Kata Yesus kepada mereka: "Tidakkah ada tertulis dalam kitab Taurat kamu: Aku telah berfirman: Kamu adalah allah?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 35, 'Jikalau mereka, kepada siapa firman itu disampaikan, disebut allah?sedang Kitab Suci tidak dapat dibatalkan?,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 36, 'masihkah kamu berkata kepada Dia yang dikuduskan oleh Bapa dan yang telah diutus-Nya ke dalam dunia: Engkau menghujat Allah! Karena Aku telah berkata: Aku Anak Allah?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 37, 'Jikalau Aku tidak melakukan pekerjaan-pekerjaan Bapa-Ku, janganlah percaya kepada-Ku,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 38, 'tetapi jikalau Aku melakukannya dan kamu tidak mau percaya kepada-Ku, percayalah akan pekerjaan-pekerjaan itu, supaya kamu boleh mengetahui dan mengerti, bahwa Bapa di dalam Aku dan Aku di dalam Bapa."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 39, 'Sekali lagi mereka mencoba menangkap Dia, tetapi Ia luput dari tangan mereka.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 40, 'Kemudian Yesus pergi lagi ke seberang Yordan, ke tempat Yohanes membaptis dahulu, lalu Ia tinggal di situ.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 41, 'Dan banyak orang datang kepada-Nya dan berkata: "Yohanes memang tidak membuat satu tandapun, tetapi semua yang pernah dikatakan Yohanes tentang orang ini adalah benar."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 10, 42, 'Dan banyak orang di situ percaya kepada-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 1, 'Ada seorang yang sedang sakit, namanya Lazarus. Ia tinggal di Betania, kampung Maria dan adiknya Marta.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 2, 'Maria ialah perempuan yang pernah meminyaki kaki Tuhan dengan minyak mur dan menyekanya dengan rambutnya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 3, 'Dan Lazarus yang sakit itu adalah saudaranya. Kedua perempuan itu mengirim kabar kepada Yesus: "Tuhan, dia yang Engkau kasihi, sakit."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 4, 'Ketika Yesus mendengar kabar itu, Ia berkata: "Penyakit itu tidak akan membawa kematian, tetapi akan menyatakan kemuliaan Allah, sebab oleh penyakit itu Anak Allah akan dimuliakan."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 5, 'Yesus memang mengasihi Marta dan kakaknya dan Lazarus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 6, 'Namun setelah didengar-Nya, bahwa Lazarus sakit, Ia sengaja tinggal dua hari lagi di tempat, di mana Ia berada;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 7, 'tetapi sesudah itu Ia berkata kepada murid-murid-Nya: "Mari kita kembali lagi ke Yudea."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 8, 'Murid-murid itu berkata kepada-Nya: "Rabi, baru-baru ini orang-orang Yahudi mencoba melempari Engkau, masih maukah Engkau kembali ke sana?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 9, 'Jawab Yesus: "Bukankah ada dua belas jam dalam satu hari? Siapa yang berjalan pada siang hari, kakinya tidak terantuk, karena ia melihat terang dunia ini.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 10, 'Tetapi jikalau seorang berjalan pada malam hari, kakinya terantuk, karena terang tidak ada di dalam dirinya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 11, 'Demikianlah perkataan-Nya, dan sesudah itu Ia berkata kepada mereka: "Lazarus, saudara kita, telah tertidur, tetapi Aku pergi ke sana untuk membangunkan dia dari tidurnya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 12, 'Maka kata murid-murid itu kepada-Nya: "Tuhan, jikalau ia tertidur, ia akan sembuh."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 13, 'Tetapi maksud Yesus ialah tertidur dalam arti mati, sedangkan sangka mereka Yesus berkata tentang tertidur dalam arti biasa.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 14, 'Karena itu Yesus berkata dengan terus terang: "Lazarus sudah mati;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 15, 'tetapi syukurlah Aku tidak hadir pada waktu itu, sebab demikian lebih baik bagimu, supaya kamu dapat belajar percaya. Marilah kita pergi sekarang kepadanya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 16, 'Lalu Tomas, yang disebut Didimus, berkata kepada teman-temannya, yaitu murid-murid yang lain: "Marilah kita pergi juga untuk mati bersama-sama dengan Dia."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 17, 'Maka ketika Yesus tiba, didapati-Nya Lazarus telah empat hari berbaring di dalam kubur.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 18, 'Betania terletak dekat Yerusalem, kira-kira dua mil jauhnya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 19, 'Di situ banyak orang Yahudi telah datang kepada Marta dan Maria untuk menghibur mereka berhubung dengan kematian saudaranya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 20, 'Ketika Marta mendengar, bahwa Yesus datang, ia pergi mendapatkan-Nya. Tetapi Maria tinggal di rumah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 21, 'Maka kata Marta kepada Yesus: "Tuhan, sekiranya Engkau ada di sini, saudaraku pasti tidak mati.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 22, 'Tetapi sekarangpun aku tahu, bahwa Allah akan memberikan kepada-Mu segala sesuatu yang Engkau minta kepada-Nya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 23, 'Kata Yesus kepada Marta: "Saudaramu akan bangkit."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 24, 'Kata Marta kepada-Nya: "Aku tahu bahwa ia akan bangkit pada waktu orang-orang bangkit pada akhir zaman."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 25, 'Jawab Yesus: "Akulah kebangkitan dan hidup; barangsiapa percaya kepada-Ku, ia akan hidup walaupun ia sudah mati,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 26, 'dan setiap orang yang hidup dan yang percaya kepada-Ku, tidak akan mati selama-lamanya. Percayakah engkau akan hal ini?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 27, 'Jawab Marta: "Ya, Tuhan, aku percaya, bahwa Engkaulah Mesias, Anak Allah, Dia yang akan datang ke dalam dunia."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 28, 'Dan sesudah berkata demikian ia pergi memanggil saudaranya Maria dan berbisik kepadanya: "Guru ada di sana dan Ia memanggil engkau."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 29, 'Mendengar itu Maria segera bangkit lalu pergi mendapatkan Yesus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 30, 'Tetapi waktu itu Yesus belum sampai ke dalam kampung itu. Ia masih berada di tempat Marta menjumpai Dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 31, 'Ketika orang-orang Yahudi yang bersama-sama dengan Maria di rumah itu untuk menghiburnya, melihat bahwa Maria segera bangkit dan pergi ke luar, mereka mengikutinya, karena mereka menyangka bahwa ia pergi ke kubur untuk meratap di situ.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 32, 'Setibanya Maria di tempat Yesus berada dan melihat Dia, tersungkurlah ia di depan kaki-Nya dan berkata kepada-Nya: "Tuhan, sekiranya Engkau ada di sini, saudaraku pasti tidak mati."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 33, 'Ketika Yesus melihat Maria menangis dan juga orang-orang Yahudi yang datang bersama-sama dia, maka masygullah hati-Nya. Ia sangat terharu dan berkata:', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 34, '"Di manakah dia kamu baringkan?" Jawab mereka: "Tuhan, marilah dan lihatlah!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 35, 'Maka menangislah Yesus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 36, 'Kata orang-orang Yahudi: "Lihatlah, betapa kasih-Nya kepadanya!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 37, 'Tetapi beberapa orang di antaranya berkata: "Ia yang memelekkan mata orang buta, tidak sanggupkah Ia bertindak, sehingga orang ini tidak mati?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 38, 'Maka masygullah pula hati Yesus, lalu Ia pergi ke kubur itu. Kubur itu adalah sebuah gua yang ditutup dengan batu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 39, 'Kata Yesus: "Angkat batu itu!" Marta, saudara orang yang meninggal itu, berkata kepada-Nya: "Tuhan, ia sudah berbau, sebab sudah empat hari ia mati."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 40, 'Jawab Yesus: "Bukankah sudah Kukatakan kepadamu: Jikalau engkau percaya engkau akan melihat kemuliaan Allah?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 41, 'Maka mereka mengangkat batu itu. Lalu Yesus menengadah ke atas dan berkata: "Bapa, Aku mengucap syukur kepada-Mu, karena Engkau telah mendengarkan Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 42, 'Aku tahu, bahwa Engkau selalu mendengarkan Aku, tetapi oleh karena orang banyak yang berdiri di sini mengelilingi Aku, Aku mengatakannya, supaya mereka percaya, bahwa Engkaulah yang telah mengutus Aku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 43, 'Dan sesudah berkata demikian, berserulah Ia dengan suara keras: "Lazarus, marilah ke luar!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 44, 'Orang yang telah mati itu datang ke luar, kaki dan tangannya masih terikat dengan kain kapan dan mukanya tertutup dengan kain peluh. Kata Yesus kepada mereka: "Bukalah kain-kain itu dan biarkan ia pergi."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 45, 'Banyak di antara orang-orang Yahudi yang datang melawat Maria dan yang menyaksikan sendiri apa yang telah dibuat Yesus, percaya kepada-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 46, 'Tetapi ada yang pergi kepada orang-orang Farisi dan menceriterakan kepada mereka, apa yang telah dibuat Yesus itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 47, 'Lalu imam-imam kepala dan orang-orang Farisi memanggil Mahkamah Agama untuk berkumpul dan mereka berkata: "Apakah yang harus kita buat? Sebab orang itu membuat banyak mujizat.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 48, 'Apabila kita biarkan Dia, maka semua orang akan percaya kepada-Nya dan orang-orang Roma akan datang dan akan merampas tempat suci kita serta bangsa kita."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 49, 'Tetapi seorang di antara mereka, yaitu Kayafas, Imam Besar pada tahun itu, berkata kepada mereka: "Kamu tidak tahu apa-apa,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 50, 'dan kamu tidak insaf, bahwa lebih berguna bagimu, jika satu orang mati untuk bangsa kita dari pada seluruh bangsa kita ini binasa."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 51, 'Hal itu dikatakannya bukan dari dirinya sendiri, tetapi sebagai Imam Besar pada tahun itu ia bernubuat, bahwa Yesus akan mati untuk bangsa itu,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 52, 'dan bukan untuk bangsa itu saja, tetapi juga untuk mengumpulkan dan mempersatukan anak-anak Allah yang tercerai-berai.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 53, 'Mulai dari hari itu mereka sepakat untuk membunuh Dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 54, 'Karena itu Yesus tidak tampil lagi di muka umum di antara orang-orang Yahudi, Ia berangkat dari situ ke daerah dekat padang gurun, ke sebuah kota yang bernama Efraim, dan di situ Ia tinggal bersama-sama murid-murid-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 55, 'Pada waktu itu hari raya Paskah orang Yahudi sudah dekat dan banyak orang dari negeri itu berangkat ke Yerusalem untuk menyucikan diri sebelum Paskah itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 56, 'Mereka mencari Yesus dan sambil berdiri di dalam Bait Allah, mereka berkata seorang kepada yang lain: "Bagaimana pendapatmu? Akan datang jugakah Ia ke pesta?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 11, 57, 'Sementara itu imam-imam kepala dan orang-orang Farisi telah memberikan perintah supaya setiap orang yang tahu di mana Dia berada memberitahukannya, agar mereka dapat menangkap Dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 1, 'Enam hari sebelum Paskah Yesus datang ke Betania, tempat tinggal Lazarus yang dibangkitkan Yesus dari antara orang mati.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 2, 'Di situ diadakan perjamuan untuk Dia dan Marta melayani, sedang salah seorang yang turut makan dengan Yesus adalah Lazarus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 3, 'Maka Maria mengambil setengah kati minyak narwastu murni yang mahal harganya, lalu meminyaki kaki Yesus dan menyekanya dengan rambutnya; dan bau minyak semerbak di seluruh rumah itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 4, 'Tetapi Yudas Iskariot, seorang dari murid-murid Yesus, yang akan segera menyerahkan Dia, berkata:', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 5, '"Mengapa minyak narwastu ini tidak dijual tiga ratus dinar dan uangnya diberikan kepada orang-orang miskin?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 6, 'Hal itu dikatakannya bukan karena ia memperhatikan nasib orang-orang miskin, melainkan karena ia adalah seorang pencuri; ia sering mengambil uang yang disimpan dalam kas yang dipegangnya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 7, 'Maka kata Yesus: "Biarkanlah dia melakukan hal ini mengingat hari penguburan-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 8, 'Karena orang-orang miskin selalu ada pada kamu, tetapi Aku tidak akan selalu ada pada kamu."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 9, 'Sejumlah besar orang Yahudi mendengar, bahwa Yesus ada di sana dan mereka datang bukan hanya karena Yesus, melainkan juga untuk melihat Lazarus, yang telah dibangkitkan-Nya dari antara orang mati.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 10, 'Lalu imam-imam kepala bermupakat untuk membunuh Lazarus juga,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 11, 'sebab karena dia banyak orang Yahudi meninggalkan mereka dan percaya kepada Yesus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 12, 'Keesokan harinya ketika orang banyak yang datang merayakan pesta mendengar, bahwa Yesus sedang di tengah jalan menuju Yerusalem,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 13, 'mereka mengambil daun-daun palem, dan pergi menyongsong Dia sambil berseru-seru: "Hosana! Diberkatilah Dia yang datang dalam nama Tuhan, Raja Israel!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 14, 'Yesus menemukan seekor keledai muda lalu Ia naik ke atasnya, seperti ada tertulis:', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 15, '"Jangan takut, hai puteri Sion, lihatlah, Rajamu datang, duduk di atas seekor anak keledai."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 16, 'Mula-mula murid-murid Yesus tidak mengerti akan hal itu, tetapi sesudah Yesus dimuliakan, teringatlah mereka, bahwa nas itu mengenai Dia, dan bahwa mereka telah melakukannya juga untuk Dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 17, 'Orang banyak yang bersama-sama dengan Dia ketika Ia memanggil Lazarus keluar dari kubur dan membangkitkannya dari antara orang mati, memberi kesaksian tentang Dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 18, 'Sebab itu orang banyak itu pergi menyongsong Dia, karena mereka mendengar, bahwa Ia yang membuat mujizat itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 19, 'Maka kata orang-orang Farisi seorang kepada yang lain: "Kamu lihat sendiri, bahwa kamu sama sekali tidak berhasil, lihatlah, seluruh dunia datang mengikuti Dia."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 20, 'Di antara mereka yang berangkat untuk beribadah pada hari raya itu, terdapat beberapa orang Yunani.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 21, 'Orang-orang itu pergi kepada Filipus, yang berasal dari Betsaida di Galilea, lalu berkata kepadanya: "Tuan, kami ingin bertemu dengan Yesus."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 22, 'Filipus pergi memberitahukannya kepada Andreas; Andreas dan Filipus menyampaikannya pula kepada Yesus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 23, 'Tetapi Yesus menjawab mereka, kata-Nya: "Telah tiba saatnya Anak Manusia dimuliakan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 24, 'Aku berkata kepadamu: Sesungguhnya jikalau biji gandum tidak jatuh ke dalam tanah dan mati, ia tetap satu biji saja; tetapi jika ia mati, ia akan menghasilkan banyak buah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 25, 'Barangsiapa mencintai nyawanya, ia akan kehilangan nyawanya, tetapi barangsiapa tidak mencintai nyawanya di dunia ini, ia akan memeliharanya untuk hidup yang kekal.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 26, 'Barangsiapa melayani Aku, ia harus mengikut Aku dan di mana Aku berada, di situpun pelayan-Ku akan berada. Barangsiapa melayani Aku, ia akan dihormati Bapa.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 27, 'Sekarang jiwa-Ku terharu dan apakah yang akan Kukatakan? Bapa, selamatkanlah Aku dari saat ini? Tidak, sebab untuk itulah Aku datang ke dalam saat ini.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 28, 'Bapa, muliakanlah nama-Mu!" Maka terdengarlah suara dari sorga: "Aku telah memuliakan-Nya, dan Aku akan memuliakan-Nya lagi!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 29, 'Orang banyak yang berdiri di situ dan mendengarkannya berkata, bahwa itu bunyi guntur. Ada pula yang berkata: "Seorang malaikat telah berbicara dengan Dia."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 30, 'Jawab Yesus: "Suara itu telah terdengar bukan oleh karena Aku, melainkan oleh karena kamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 31, 'Sekarang berlangsung penghakiman atas dunia ini: sekarang juga penguasa dunia ini akan dilemparkan ke luar;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 32, 'dan Aku, apabila Aku ditinggikan dari bumi, Aku akan menarik semua orang datang kepada-Ku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 33, 'Ini dikatakan-Nya untuk menyatakan bagaimana caranya Ia akan mati.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 34, 'Lalu jawab orang banyak itu: "Kami telah mendengar dari hukum Taurat, bahwa Mesias tetap hidup selama-lamanya; bagaimana mungkin Engkau mengatakan, bahwa Anak Manusia harus ditinggikan? Siapakah Anak Manusia itu?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 35, 'Kata Yesus kepada mereka: "Hanya sedikit waktu lagi terang ada di antara kamu. Selama terang itu ada padamu, percayalah kepadanya, supaya kegelapan jangan menguasai kamu; barangsiapa berjalan dalam kegelapan, ia tidak tahu ke mana ia pergi.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 36, 'Percayalah kepada terang itu, selama terang itu ada padamu, supaya kamu menjadi anak-anak terang." Sesudah berkata demikian, Yesus pergi bersembunyi dari antara mereka.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 37, 'Dan meskipun Yesus mengadakan begitu banyak mujizat di depan mata mereka, namun mereka tidak percaya kepada-Nya,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 38, 'supaya genaplah firman yang disampaikan oleh nabi Yesaya: "Tuhan, siapakah yang percaya kepada pemberitaan kami? Dan kepada siapakah tangan kekuasaan Tuhan dinyatakan?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 39, 'Karena itu mereka tidak dapat percaya, sebab Yesaya telah berkata juga:', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 40, '"Ia telah membutakan mata dan mendegilkan hati mereka, supaya mereka jangan melihat dengan mata, dan menanggap dengan hati, lalu berbalik, sehingga Aku menyembuhkan mereka."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 41, 'Hal ini dikatakan oleh Yesaya, karena ia telah melihat kemuliaan-Nya dan telah berkata-kata tentang Dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 42, 'Namun banyak juga di antara pemimpin yang percaya kepada-Nya, tetapi oleh karena orang-orang Farisi mereka tidak mengakuinya berterus terang, supaya mereka jangan dikucilkan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 43, 'Sebab mereka lebih suka akan kehormatan manusia dari pada kehormatan Allah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 44, 'Tetapi Yesus berseru kata-Nya: "Barangsiapa percaya kepada-Ku, ia bukan percaya kepada-Ku, tetapi kepada Dia, yang telah mengutus Aku;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 45, 'dan barangsiapa melihat Aku, ia melihat Dia, yang telah mengutus Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 46, 'Aku telah datang ke dalam dunia sebagai terang, supaya setiap orang yang percaya kepada-Ku, jangan tinggal di dalam kegelapan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 47, 'Dan jikalau seorang mendengar perkataan-Ku, tetapi tidak melakukannya, Aku tidak menjadi hakimnya, sebab Aku datang bukan untuk menghakimi dunia, melainkan untuk menyelamatkannya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 48, 'Barangsiapa menolak Aku, dan tidak menerima perkataan-Ku, ia sudah ada hakimnya, yaitu firman yang telah Kukatakan, itulah yang akan menjadi hakimnya pada akhir zaman.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 49, 'Sebab Aku berkata-kata bukan dari diri-Ku sendiri, tetapi Bapa, yang mengutus Aku, Dialah yang memerintahkan Aku untuk mengatakan apa yang harus Aku katakan dan Aku sampaikan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 12, 50, 'Dan Aku tahu, bahwa perintah-Nya itu adalah hidup yang kekal. Jadi apa yang Aku katakan, Aku menyampaikannya sebagaimana yang difirmankan oleh Bapa kepada-Ku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 1, 'Sementara itu sebelum hari raya Paskah mulai, Yesus telah tahu, bahwa saat-Nya sudah tiba untuk beralih dari dunia ini kepada Bapa. Sama seperti Ia senantiasa mengasihi murid-murid-Nya demikianlah sekarang Ia mengasihi mereka sampai kepada kesudahannya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 2, 'Mereka sedang makan bersama, dan Iblis telah membisikkan rencana dalam hati Yudas Iskariot, anak Simon, untuk mengkhianati Dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 3, 'Yesus tahu, bahwa Bapa-Nya telah menyerahkan segala sesuatu kepada-Nya dan bahwa Ia datang dari Allah dan kembali kepada Allah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 4, 'Lalu bangunlah Yesus dan menanggalkan jubah-Nya. Ia mengambil sehelai kain lenan dan mengikatkannya pada pinggang-Nya,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 5, 'kemudian Ia menuangkan air ke dalam sebuah basi, dan mulai membasuh kaki murid-murid-Nya lalu menyekanya dengan kain yang terikat pada pinggang-Nya itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 6, 'Maka sampailah Ia kepada Simon Petrus. Kata Petrus kepada-Nya: "Tuhan, Engkau hendak membasuh kakiku?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 7, 'Jawab Yesus kepadanya: "Apa yang Kuperbuat, engkau tidak tahu sekarang, tetapi engkau akan mengertinya kelak."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 8, 'Kata Petrus kepada-Nya: "Engkau tidak akan membasuh kakiku sampai selama-lamanya." Jawab Yesus: "Jikalau Aku tidak membasuh engkau, engkau tidak mendapat bagian dalam Aku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 9, 'Kata Simon Petrus kepada-Nya: "Tuhan, jangan hanya kakiku saja, tetapi juga tangan dan kepalaku!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 10, 'Kata Yesus kepadanya: "Barangsiapa telah mandi, ia tidak usah membasuh diri lagi selain membasuh kakinya, karena ia sudah bersih seluruhnya. Juga kamu sudah bersih, hanya tidak semua."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 11, 'Sebab Ia tahu, siapa yang akan menyerahkan Dia. Karena itu Ia berkata: "Tidak semua kamu bersih."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 12, 'Sesudah Ia membasuh kaki mereka, Ia mengenakan pakaian-Nya dan kembali ke tempat-Nya. Lalu Ia berkata kepada mereka: "Mengertikah kamu apa yang telah Kuperbuat kepadamu?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 13, 'Kamu menyebut Aku Guru dan Tuhan, dan katamu itu tepat, sebab memang Akulah Guru dan Tuhan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 14, 'Jadi jikalau Aku membasuh kakimu, Aku yang adalah Tuhan dan Gurumu, maka kamupun wajib saling membasuh kakimu;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 15, 'sebab Aku telah memberikan suatu teladan kepada kamu, supaya kamu juga berbuat sama seperti yang telah Kuperbuat kepadamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 16, 'Aku berkata kepadamu: Sesungguhnya seorang hamba tidaklah lebih tinggi dari pada tuannya, ataupun seorang utusan dari pada dia yang mengutusnya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 17, 'Jikalau kamu tahu semua ini, maka berbahagialah kamu, jika kamu melakukannya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 18, 'Bukan tentang kamu semua Aku berkata. Aku tahu, siapa yang telah Kupilih. Tetapi haruslah genap nas ini: Orang yang makan roti-Ku, telah mengangkat tumitnya terhadap Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 19, 'Aku mengatakannya kepadamu sekarang juga sebelum hal itu terjadi, supaya jika hal itu terjadi, kamu percaya, bahwa Akulah Dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 20, 'Aku berkata kepadamu: Sesungguhnya barangsiapa menerima orang yang Kuutus, ia menerima Aku, dan barangsiapa menerima Aku, ia menerima Dia yang mengutus Aku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 21, 'Setelah Yesus berkata demikian Ia sangat terharu, lalu bersaksi: "Aku berkata kepadamu, sesungguhnya seorang di antara kamu akan menyerahkan Aku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 22, 'Murid-murid itu memandang seorang kepada yang lain, mereka ragu-ragu siapa yang dimaksudkan-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 23, 'Seorang di antara murid Yesus, yaitu murid yang dikasihi-Nya, bersandar dekat kepada-Nya, di sebelah kanan-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 24, 'Kepada murid itu Simon Petrus memberi isyarat dan berkata: "Tanyalah siapa yang dimaksudkan-Nya!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 25, 'Murid yang duduk dekat Yesus itu berpaling dan berkata kepada-Nya: "Tuhan, siapakah itu?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 26, 'Jawab Yesus: "Dialah itu, yang kepadanya Aku akan memberikan roti, sesudah Aku mencelupkannya." Sesudah berkata demikian Ia mengambil roti, mencelupkannya dan memberikannya kepada Yudas, anak Simon Iskariot.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 27, 'Dan sesudah Yudas menerima roti itu, ia kerasukan Iblis. Maka Yesus berkata kepadanya: "Apa yang hendak kauperbuat, perbuatlah dengan segera."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 28, 'Tetapi tidak ada seorangpun dari antara mereka yang duduk makan itu mengerti, apa maksud Yesus mengatakan itu kepada Yudas.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 29, 'Karena Yudas memegang kas ada yang menyangka, bahwa Yesus menyuruh dia membeli apa-apa yang perlu untuk perayaan itu, atau memberi apa-apa kepada orang miskin.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 30, 'Yudas menerima roti itu lalu segera pergi. Pada waktu itu hari sudah malam.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 31, 'Sesudah Yudas pergi, berkatalah Yesus: "Sekarang Anak Manusia dipermuliakan dan Allah dipermuliakan di dalam Dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 32, 'Jikalau Allah dipermuliakan di dalam Dia, Allah akan mempermuliakan Dia juga di dalam diri-Nya, dan akan mempermuliakan Dia dengan segera.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 33, 'Hai anak-anak-Ku, hanya seketika saja lagi Aku ada bersama kamu. Kamu akan mencari Aku, dan seperti yang telah Kukatakan kepada orang-orang Yahudi: Ke tempat Aku pergi, tidak mungkin kamu datang, demikian pula Aku mengatakannya sekarang juga kepada kamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 34, 'Aku memberikan perintah baru kepada kamu, yaitu supaya kamu saling mengasihi; sama seperti Aku telah mengasihi kamu demikian pula kamu harus saling mengasihi.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 35, 'Dengan demikian semua orang akan tahu, bahwa kamu adalah murid-murid-Ku, yaitu jikalau kamu saling mengasihi."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 36, 'Simon Petrus berkata kepada Yesus: "Tuhan, ke manakah Engkau pergi?" Jawab Yesus: "Ke tempat Aku pergi, engkau tidak dapat mengikuti Aku sekarang, tetapi kelak engkau akan mengikuti Aku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 37, 'Kata Petrus kepada-Nya: "Tuhan, mengapa aku tidak dapat mengikuti Engkau sekarang? Aku akan memberikan nyawaku bagi-Mu!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 13, 38, 'Jawab Yesus: "Nyawamu akan kauberikan bagi-Ku? Sesungguhnya Aku berkata kepadamu: Sebelum ayam berkokok, engkau telah menyangkal Aku tiga kali."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 1, '"Janganlah gelisah hatimu; percayalah kepada Allah, percayalah juga kepada-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 2, 'Di rumah Bapa-Ku banyak tempat tinggal. Jika tidak demikian, tentu Aku mengatakannya kepadamu. Sebab Aku pergi ke situ untuk menyediakan tempat bagimu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 3, 'Dan apabila Aku telah pergi ke situ dan telah menyediakan tempat bagimu, Aku akan datang kembali dan membawa kamu ke tempat-Ku, supaya di tempat di mana Aku berada, kamupun berada.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 4, 'Dan ke mana Aku pergi, kamu tahu jalan ke situ."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 5, 'Kata Tomas kepada-Nya: "Tuhan, kami tidak tahu ke mana Engkau pergi; jadi bagaimana kami tahu jalan ke situ?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 6, 'Kata Yesus kepadanya: "Akulah jalan dan kebenaran dan hidup. Tidak ada seorangpun yang datang kepada Bapa, kalau tidak melalui Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 7, 'Sekiranya kamu mengenal Aku, pasti kamu juga mengenal Bapa-Ku. Sekarang ini kamu mengenal Dia dan kamu telah melihat Dia."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 8, 'Kata Filipus kepada-Nya: "Tuhan, tunjukkanlah Bapa itu kepada kami, itu sudah cukup bagi kami."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 9, 'Kata Yesus kepadanya: "Telah sekian lama Aku bersama-sama kamu, Filipus, namun engkau tidak mengenal Aku? Barangsiapa telah melihat Aku, ia telah melihat Bapa; bagaimana engkau berkata: Tunjukkanlah Bapa itu kepada kami.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 10, 'Tidak percayakah engkau, bahwa Aku di dalam Bapa dan Bapa di dalam Aku? Apa yang Aku katakan kepadamu, tidak Aku katakan dari diri-Ku sendiri, tetapi Bapa, yang diam di dalam Aku, Dialah yang melakukan pekerjaan-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 11, 'Percayalah kepada-Ku, bahwa Aku di dalam Bapa dan Bapa di dalam Aku; atau setidak-tidaknya, percayalah karena pekerjaan-pekerjaan itu sendiri.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 12, 'Aku berkata kepadamu: Sesungguhnya barangsiapa percaya kepada-Ku, ia akan melakukan juga pekerjaan-pekerjaan yang Aku lakukan, bahkan pekerjaan-pekerjaan yang lebih besar dari pada itu. Sebab Aku pergi kepada Bapa;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 13, 'dan apa juga yang kamu minta dalam nama-Ku, Aku akan melakukannya, supaya Bapa dipermuliakan di dalam Anak.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 14, 'Jika kamu meminta sesuatu kepada-Ku dalam nama-Ku, Aku akan melakukannya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 15, '"Jikalau kamu mengasihi Aku, kamu akan menuruti segala perintah-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 16, 'Aku akan minta kepada Bapa, dan Ia akan memberikan kepadamu seorang Penolong yang lain, supaya Ia menyertai kamu selama-lamanya,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 17, 'yaitu Roh Kebenaran. Dunia tidak dapat menerima Dia, sebab dunia tidak melihat Dia dan tidak mengenal Dia. Tetapi kamu mengenal Dia, sebab Ia menyertai kamu dan akan diam di dalam kamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 18, 'Aku tidak akan meninggalkan kamu sebagai yatim piatu. Aku datang kembali kepadamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 19, 'Tinggal sesaat lagi dan dunia tidak akan melihat Aku lagi, tetapi kamu melihat Aku, sebab Aku hidup dan kamupun akan hidup.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 20, 'Pada waktu itulah kamu akan tahu, bahwa Aku di dalam Bapa-Ku dan kamu di dalam Aku dan Aku di dalam kamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 21, 'Barangsiapa memegang perintah-Ku dan melakukannya, dialah yang mengasihi Aku. Dan barangsiapa mengasihi Aku, ia akan dikasihi oleh Bapa-Ku dan Akupun akan mengasihi dia dan akan menyatakan diri-Ku kepadanya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 22, 'Yudas, yang bukan Iskariot, berkata kepada-Nya: "Tuhan, apakah sebabnya maka Engkau hendak menyatakan diri-Mu kepada kami, dan bukan kepada dunia?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 23, 'Jawab Yesus: "Jika seorang mengasihi Aku, ia akan menuruti firman-Ku dan Bapa-Ku akan mengasihi dia dan Kami akan datang kepadanya dan diam bersama-sama dengan dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 24, 'Barangsiapa tidak mengasihi Aku, ia tidak menuruti firman-Ku; dan firman yang kamu dengar itu bukanlah dari pada-Ku, melainkan dari Bapa yang mengutus Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 25, 'Semuanya itu Kukatakan kepadamu, selagi Aku berada bersama-sama dengan kamu;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 26, 'tetapi Penghibur, yaitu Roh Kudus, yang akan diutus oleh Bapa dalam nama-Ku, Dialah yang akan mengajarkan segala sesuatu kepadamu dan akan mengingatkan kamu akan semua yang telah Kukatakan kepadamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 27, 'Damai sejahtera Kutinggalkan bagimu. Damai sejahtera-Ku Kuberikan kepadamu, dan apa yang Kuberikan tidak seperti yang diberikan oleh dunia kepadamu. Janganlah gelisah dan gentar hatimu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 28, 'Kamu telah mendengar, bahwa Aku telah berkata kepadamu: Aku pergi, tetapi Aku datang kembali kepadamu. Sekiranya kamu mengasihi Aku, kamu tentu akan bersukacita karena Aku pergi kepada Bapa-Ku, sebab Bapa lebih besar dari pada Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 29, 'Dan sekarang juga Aku mengatakannya kepadamu sebelum hal itu terjadi, supaya kamu percaya, apabila hal itu terjadi.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 30, 'Tidak banyak lagi Aku berkata-kata dengan kamu, sebab penguasa dunia ini datang dan ia tidak berkuasa sedikitpun atas diri-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 14, 31, 'Tetapi supaya dunia tahu, bahwa Aku mengasihi Bapa dan bahwa Aku melakukan segala sesuatu seperti yang diperintahkan Bapa kepada-Ku, bangunlah, marilah kita pergi dari sini."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 1, '"Akulah pokok anggur yang benar dan Bapa-Kulah pengusahanya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 2, 'Setiap ranting pada-Ku yang tidak berbuah, dipotong-Nya dan setiap ranting yang berbuah, dibersihkan-Nya, supaya ia lebih banyak berbuah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 3, 'Kamu memang sudah bersih karena firman yang telah Kukatakan kepadamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 4, 'Tinggallah di dalam Aku dan Aku di dalam kamu. Sama seperti ranting tidak dapat berbuah dari dirinya sendiri, kalau ia tidak tinggal pada pokok anggur, demikian juga kamu tidak berbuah, jikalau kamu tidak tinggal di dalam Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 5, 'Akulah pokok anggur dan kamulah ranting-rantingnya. Barangsiapa tinggal di dalam Aku dan Aku di dalam dia, ia berbuah banyak, sebab di luar Aku kamu tidak dapat berbuat apa-apa.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 6, 'Barangsiapa tidak tinggal di dalam Aku, ia dibuang ke luar seperti ranting dan menjadi kering, kemudian dikumpulkan orang dan dicampakkan ke dalam api lalu dibakar.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 7, 'Jikalau kamu tinggal di dalam Aku dan firman-Ku tinggal di dalam kamu, mintalah apa saja yang kamu kehendaki, dan kamu akan menerimanya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 8, 'Dalam hal inilah Bapa-Ku dipermuliakan, yaitu jika kamu berbuah banyak dan dengan demikian kamu adalah murid-murid-Ku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 9, '"Seperti Bapa telah mengasihi Aku, demikianlah juga Aku telah mengasihi kamu; tinggallah di dalam kasih-Ku itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 10, 'Jikalau kamu menuruti perintah-Ku, kamu akan tinggal di dalam kasih-Ku, seperti Aku menuruti perintah Bapa-Ku dan tinggal di dalam kasih-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 11, 'Semuanya itu Kukatakan kepadamu, supaya sukacita-Ku ada di dalam kamu dan sukacitamu menjadi penuh.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 12, 'Inilah perintah-Ku, yaitu supaya kamu saling mengasihi, seperti Aku telah mengasihi kamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 13, 'Tidak ada kasih yang lebih besar dari pada kasih seorang yang memberikan nyawanya untuk sahabat-sahabatnya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 14, 'Kamu adalah sahabat-Ku, jikalau kamu berbuat apa yang Kuperintahkan kepadamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 15, 'Aku tidak menyebut kamu lagi hamba, sebab hamba tidak tahu, apa yang diperbuat oleh tuannya, tetapi Aku menyebut kamu sahabat, karena Aku telah memberitahukan kepada kamu segala sesuatu yang telah Kudengar dari Bapa-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 16, 'Bukan kamu yang memilih Aku, tetapi Akulah yang memilih kamu. Dan Aku telah menetapkan kamu, supaya kamu pergi dan menghasilkan buah dan buahmu itu tetap, supaya apa yang kamu minta kepada Bapa dalam nama-Ku, diberikan-Nya kepadamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 17, 'Inilah perintah-Ku kepadamu: Kasihilah seorang akan yang lain."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 18, '"Jikalau dunia membenci kamu, ingatlah bahwa ia telah lebih dahulu membenci Aku dari pada kamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 19, 'Sekiranya kamu dari dunia, tentulah dunia mengasihi kamu sebagai miliknya. Tetapi karena kamu bukan dari dunia, melainkan Aku telah memilih kamu dari dunia, sebab itulah dunia membenci kamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 20, 'Ingatlah apa yang telah Kukatakan kepadamu: Seorang hamba tidaklah lebih tinggi dari pada tuannya. Jikalau mereka telah menganiaya Aku, mereka juga akan menganiaya kamu; jikalau mereka telah menuruti firman-Ku, mereka juga akan menuruti perkataanmu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 21, 'Tetapi semuanya itu akan mereka lakukan terhadap kamu karena nama-Ku, sebab mereka tidak mengenal Dia, yang telah mengutus Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 22, 'Sekiranya Aku tidak datang dan tidak berkata-kata kepada mereka, mereka tentu tidak berdosa. Tetapi sekarang mereka tidak mempunyai dalih bagi dosa mereka!', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 23, 'Barangsiapa membenci Aku, ia membenci juga Bapa-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 24, 'Sekiranya Aku tidak melakukan pekerjaan di tengah-tengah mereka seperti yang tidak pernah dilakukan orang lain, mereka tentu tidak berdosa. Tetapi sekarang walaupun mereka telah melihat semuanya itu, namun mereka membenci baik Aku maupun Bapa-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 25, 'Tetapi firman yang ada tertulis dalam kitab Taurat mereka harus digenapi: Mereka membenci Aku tanpa alasan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 26, 'Jikalau Penghibur yang akan Kuutus dari Bapa datang, yaitu Roh Kebenaran yang keluar dari Bapa, Ia akan bersaksi tentang Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 15, 27, 'Tetapi kamu juga harus bersaksi, karena kamu dari semula bersama-sama dengan Aku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 1, '"Semuanya ini Kukatakan kepadamu, supaya kamu jangan kecewa dan menolak Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 2, 'Kamu akan dikucilkan, bahkan akan datang saatnya bahwa setiap orang yang membunuh kamu akan menyangka bahwa ia berbuat bakti bagi Allah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 3, 'Mereka akan berbuat demikian, karena mereka tidak mengenal baik Bapa maupun Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 4, 'Tetapi semuanya ini Kukatakan kepadamu, supaya apabila datang saatnya kamu ingat, bahwa Aku telah mengatakannya kepadamu." (16-4b) "Hal ini tidak Kukatakan kepadamu dari semula, karena selama ini Aku masih bersama-sama dengan kamu,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 5, 'tetapi sekarang Aku pergi kepada Dia yang telah mengutus Aku, dan tiada seorangpun di antara kamu yang bertanya kepada-Ku: Ke mana Engkau pergi?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 6, 'Tetapi karena Aku mengatakan hal itu kepadamu, sebab itu hatimu berdukacita.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 7, 'Namun benar yang Kukatakan ini kepadamu: Adalah lebih berguna bagi kamu, jika Aku pergi. Sebab jikalau Aku tidak pergi, Penghibur itu tidak akan datang kepadamu, tetapi jikalau Aku pergi, Aku akan mengutus Dia kepadamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 8, 'Dan kalau Ia datang, Ia akan menginsafkan dunia akan dosa, kebenaran dan penghakiman;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 9, 'akan dosa, karena mereka tetap tidak percaya kepada-Ku;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 10, 'akan kebenaran, karena Aku pergi kepada Bapa dan kamu tidak melihat Aku lagi;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 11, 'akan penghakiman, karena penguasa dunia ini telah dihukum.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 12, 'Masih banyak hal yang harus Kukatakan kepadamu, tetapi sekarang kamu belum dapat menanggungnya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 13, 'Tetapi apabila Ia datang, yaitu Roh Kebenaran, Ia akan memimpin kamu ke dalam seluruh kebenaran; sebab Ia tidak akan berkata-kata dari diri-Nya sendiri, tetapi segala sesuatu yang didengar-Nya itulah yang akan dikatakan-Nya dan Ia akan memberitakan kepadamu hal-hal yang akan datang.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 14, 'Ia akan memuliakan Aku, sebab Ia akan memberitakan kepadamu apa yang diterimanya dari pada-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 15, 'Segala sesuatu yang Bapa punya, adalah Aku punya; sebab itu Aku berkata: Ia akan memberitakan kepadamu apa yang diterimanya dari pada-Ku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 16, '"Tinggal sesaat saja dan kamu tidak melihat Aku lagi dan tinggal sesaat saja pula dan kamu akan melihat Aku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 17, 'Mendengar itu beberapa dari murid-Nya berkata seorang kepada yang lain: "Apakah artinya Ia berkata kepada kita: Tinggal sesaat saja dan kamu tidak melihat Aku dan tinggal sesaat saja pula dan kamu akan melihat Aku? Dan: Aku pergi kepada Bapa?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 18, 'Maka kata mereka: "Apakah artinya Ia berkata: Tinggal sesaat saja? Kita tidak tahu apa maksud-Nya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 19, 'Yesus tahu, bahwa mereka hendak menanyakan sesuatu kepada-Nya, lalu Ia berkata kepada mereka: "Adakah kamu membicarakan seorang dengan yang lain apa yang Kukatakan tadi, yaitu: Tinggal sesaat saja dan kamu tidak melihat Aku dan tinggal sesaat saja pula dan kamu akan melihat Aku?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 20, 'Aku berkata kepadamu: Sesungguhnya kamu akan menangis dan meratap, tetapi dunia akan bergembira; kamu akan berdukacita, tetapi dukacitamu akan berubah menjadi sukacita.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 21, 'Seorang perempuan berdukacita pada saat ia melahirkan, tetapi sesudah ia melahirkan anaknya, ia tidak ingat lagi akan penderitaannya, karena kegembiraan bahwa seorang manusia telah dilahirkan ke dunia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 22, 'Demikian juga kamu sekarang diliputi dukacita, tetapi Aku akan melihat kamu lagi dan hatimu akan bergembira dan tidak ada seorangpun yang dapat merampas kegembiraanmu itu dari padamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 23, 'Dan pada hari itu kamu tidak akan menanyakan apa-apa kepada-Ku. Aku berkata kepadamu: Sesungguhnya segala sesuatu yang kamu minta kepada Bapa, akan diberikan-Nya kepadamu dalam nama-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 24, 'Sampai sekarang kamu belum meminta sesuatupun dalam nama-Ku. Mintalah maka kamu akan menerima, supaya penuhlah sukacitamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 25, 'Semuanya ini Kukatakan kepadamu dengan kiasan. Akan tiba saatnya Aku tidak lagi berkata-kata kepadamu dengan kiasan, tetapi terus terang memberitakan Bapa kepadamu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 26, 'Pada hari itu kamu akan berdoa dalam nama-Ku. Dan tidak Aku katakan kepadamu, bahwa Aku meminta bagimu kepada Bapa,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 27, 'sebab Bapa sendiri mengasihi kamu, karena kamu telah mengasihi Aku dan percaya, bahwa Aku datang dari Allah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 28, 'Aku datang dari Bapa dan Aku datang ke dalam dunia; Aku meninggalkan dunia pula dan pergi kepada Bapa."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 29, 'Kata murid-murid-Nya: "Lihat, sekarang Engkau terus terang berkata-kata dan Engkau tidak memakai kiasan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 30, 'Sekarang kami tahu, bahwa Engkau mengetahui segala sesuatu dan tidak perlu orang bertanya kepada-Mu. Karena itu kami percaya, bahwa Engkau datang dari Allah."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 31, 'Jawab Yesus kepada mereka: "Percayakah kamu sekarang?', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 32, 'Lihat, saatnya datang, bahkan sudah datang, bahwa kamu diceraiberaikan masing-masing ke tempatnya sendiri dan kamu meninggalkan Aku seorang diri. Namun Aku tidak seorang diri, sebab Bapa menyertai Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 16, 33, 'Semuanya itu Kukatakan kepadamu, supaya kamu beroleh damai sejahtera dalam Aku. Dalam dunia kamu menderita penganiayaan, tetapi kuatkanlah hatimu, Aku telah mengalahkan dunia."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 1, 'Demikianlah kata Yesus. Lalu Ia menengadah ke langit dan berkata: "Bapa, telah tiba saatnya; permuliakanlah Anak-Mu, supaya Anak-Mu mempermuliakan Engkau.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 2, 'Sama seperti Engkau telah memberikan kepada-Nya kuasa atas segala yang hidup, demikian pula Ia akan memberikan hidup yang kekal kepada semua yang telah Engkau berikan kepada-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 3, 'Inilah hidup yang kekal itu, yaitu bahwa mereka mengenal Engkau, satu-satunya Allah yang benar, dan mengenal Yesus Kristus yang telah Engkau utus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 4, 'Aku telah mempermuliakan Engkau di bumi dengan jalan menyelesaikan pekerjaan yang Engkau berikan kepada-Ku untuk melakukannya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 5, 'Oleh sebab itu, ya Bapa, permuliakanlah Aku pada-Mu sendiri dengan kemuliaan yang Kumiliki di hadirat-Mu sebelum dunia ada.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 6, 'Aku telah menyatakan nama-Mu kepada semua orang, yang Engkau berikan kepada-Ku dari dunia. Mereka itu milik-Mu dan Engkau telah memberikan mereka kepada-Ku dan mereka telah menuruti firman-Mu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 7, 'Sekarang mereka tahu, bahwa semua yang Engkau berikan kepada-Ku itu berasal dari pada-Mu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 8, 'Sebab segala firman yang Engkau sampaikan kepada-Ku telah Kusampaikan kepada mereka dan mereka telah menerimanya. Mereka tahu benar-benar, bahwa Aku datang dari pada-Mu, dan mereka percaya, bahwa Engkaulah yang telah mengutus Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 9, 'Aku berdoa untuk mereka. Bukan untuk dunia Aku berdoa, tetapi untuk mereka, yang telah Engkau berikan kepada-Ku, sebab mereka adalah milik-Mu', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 10, 'dan segala milik-Ku adalah milik-Mu dan milik-Mu adalah milik-Ku, dan Aku telah dipermuliakan di dalam mereka.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 11, 'Dan Aku tidak ada lagi di dalam dunia, tetapi mereka masih ada di dalam dunia, dan Aku datang kepada-Mu. Ya Bapa yang kudus, peliharalah mereka dalam nama-Mu, yaitu nama-Mu yang telah Engkau berikan kepada-Ku, supaya mereka menjadi satu sama seperti Kita.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 12, 'Selama Aku bersama mereka, Aku memelihara mereka dalam nama-Mu, yaitu nama-Mu yang telah Engkau berikan kepada-Ku; Aku telah menjaga mereka dan tidak ada seorangpun dari mereka yang binasa selain dari pada dia yang telah ditentukan untuk binasa, supaya genaplah yang tertulis dalam Kitab Suci.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 13, 'Tetapi sekarang, Aku datang kepada-Mu dan Aku mengatakan semuanya ini sementara Aku masih ada di dalam dunia, supaya penuhlah sukacita-Ku di dalam diri mereka.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 14, 'Aku telah memberikan firman-Mu kepada mereka dan dunia membenci mereka, karena mereka bukan dari dunia, sama seperti Aku bukan dari dunia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 15, 'Aku tidak meminta, supaya Engkau mengambil mereka dari dunia, tetapi supaya Engkau melindungi mereka dari pada yang jahat.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 16, 'Mereka bukan dari dunia, sama seperti Aku bukan dari dunia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 17, 'Kuduskanlah mereka dalam kebenaran; firman-Mu adalah kebenaran.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 18, 'Sama seperti Engkau telah mengutus Aku ke dalam dunia, demikian pula Aku telah mengutus mereka ke dalam dunia;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 19, 'dan Aku menguduskan diri-Ku bagi mereka, supaya merekapun dikuduskan dalam kebenaran.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 20, 'Dan bukan untuk mereka ini saja Aku berdoa, tetapi juga untuk orang-orang, yang percaya kepada-Ku oleh pemberitaan mereka;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 21, 'supaya mereka semua menjadi satu, sama seperti Engkau, ya Bapa, di dalam Aku dan Aku di dalam Engkau, agar mereka juga di dalam Kita, supaya dunia percaya, bahwa Engkaulah yang telah mengutus Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 22, 'Dan Aku telah memberikan kepada mereka kemuliaan, yang Engkau berikan kepada-Ku, supaya mereka menjadi satu, sama seperti Kita adalah satu:', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 23, 'Aku di dalam mereka dan Engkau di dalam Aku supaya mereka sempurna menjadi satu, agar dunia tahu, bahwa Engkau yang telah mengutus Aku dan bahwa Engkau mengasihi mereka, sama seperti Engkau mengasihi Aku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 24, 'Ya Bapa, Aku mau supaya, di manapun Aku berada, mereka juga berada bersama-sama dengan Aku, mereka yang telah Engkau berikan kepada-Ku, agar mereka memandang kemuliaan-Ku yang telah Engkau berikan kepada-Ku, sebab Engkau telah mengasihi Aku sebelum dunia dijadikan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 25, 'Ya Bapa yang adil, memang dunia tidak mengenal Engkau, tetapi Aku mengenal Engkau, dan mereka ini tahu, bahwa Engkaulah yang telah mengutus Aku;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 17, 26, 'dan Aku telah memberitahukan nama-Mu kepada mereka dan Aku akan memberitahukannya, supaya kasih yang Engkau berikan kepada-Ku ada di dalam mereka dan Aku di dalam mereka."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 1, 'Setelah Yesus mengatakan semuanya itu keluarlah Ia dari situ bersama-sama dengan murid-murid-Nya dan mereka pergi ke seberang sungai Kidron. Di situ ada suatu taman dan Ia masuk ke taman itu bersama-sama dengan murid-murid-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 2, 'Yudas, yang mengkhianati Yesus, tahu juga tempat itu, karena Yesus sering berkumpul di situ dengan murid-murid-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 3, 'Maka datanglah Yudas juga ke situ dengan sepasukan prajurit dan penjaga-penjaga Bait Allah yang disuruh oleh imam-imam kepala dan orang-orang Farisi lengkap dengan lentera, suluh dan senjata.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 4, 'Maka Yesus, yang tahu semua yang akan menimpa diri-Nya, maju ke depan dan berkata kepada mereka: "Siapakah yang kamu cari?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 5, 'Jawab mereka: "Yesus dari Nazaret." Kata-Nya kepada mereka: "Akulah Dia." Yudas yang mengkhianati Dia berdiri juga di situ bersama-sama mereka.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 6, 'Ketika Ia berkata kepada mereka: "Akulah Dia," mundurlah mereka dan jatuh ke tanah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 7, 'Maka Ia bertanya pula: "Siapakah yang kamu cari?" Kata mereka: "Yesus dari Nazaret."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 8, 'Jawab Yesus: "Telah Kukatakan kepadamu, Akulah Dia. Jika Aku yang kamu cari, biarkanlah mereka ini pergi."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 9, 'Demikian hendaknya supaya genaplah firman yang telah dikatakan-Nya: "Dari mereka yang Engkau serahkan kepada-Ku, tidak seorangpun yang Kubiarkan binasa."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 10, 'Lalu Simon Petrus, yang membawa pedang, menghunus pedang itu, menetakkannya kepada hamba Imam Besar dan memutuskan telinga kanannya. Nama hamba itu Malkhus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 11, 'Kata Yesus kepada Petrus: "Sarungkan pedangmu itu; bukankah Aku harus minum cawan yang diberikan Bapa kepada-Ku?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 12, 'Maka pasukan prajurit serta perwiranya dan penjaga-penjaga yang disuruh orang Yahudi itu menangkap Yesus dan membelenggu Dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 13, 'Lalu mereka membawa-Nya mula-mula kepada Hanas, karena Hanas adalah mertua Kayafas, yang pada tahun itu menjadi Imam Besar;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 14, 'dan Kayafaslah yang telah menasihatkan orang-orang Yahudi: "Adalah lebih berguna jika satu orang mati untuk seluruh bangsa."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 15, 'Simon Petrus dan seorang murid lain mengikuti Yesus. Murid itu mengenal Imam Besar dan ia masuk bersama-sama dengan Yesus ke halaman istana Imam Besar,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 16, 'tetapi Petrus tinggal di luar dekat pintu. Maka murid lain tadi, yang mengenal Imam Besar, kembali ke luar, bercakap-cakap dengan perempuan penjaga pintu lalu membawa Petrus masuk.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 17, 'Maka kata hamba perempuan penjaga pintu kepada Petrus: "Bukankah engkau juga murid orang itu?" Jawab Petrus: "Bukan!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 18, 'Sementara itu hamba-hamba dan penjaga-penjaga Bait Allah telah memasang api arang, sebab hawa dingin waktu itu, dan mereka berdiri berdiang di situ. Juga Petrus berdiri berdiang bersama-sama dengan mereka.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 19, 'Maka mulailah Imam Besar menanyai Yesus tentang murid-murid-Nya dan tentang ajaran-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 20, 'Jawab Yesus kepadanya: "Aku berbicara terus terang kepada dunia: Aku selalu mengajar di rumah-rumah ibadat dan di Bait Allah, tempat semua orang Yahudi berkumpul; Aku tidak pernah berbicara sembunyi-sembunyi.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 21, 'Mengapakah engkau menanyai Aku? Tanyailah mereka, yang telah mendengar apa yang Kukatakan kepada mereka; sungguh, mereka tahu apa yang telah Kukatakan."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 22, 'Ketika Ia mengatakan hal itu, seorang penjaga yang berdiri di situ, menampar muka-Nya sambil berkata: "Begitukah jawab-Mu kepada Imam Besar?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 23, 'Jawab Yesus kepadanya: "Jikalau kata-Ku itu salah, tunjukkanlah salahnya, tetapi jikalau kata-Ku itu benar, mengapakah engkau menampar Aku?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 24, 'Maka Hanas mengirim Dia terbelenggu kepada Kayafas, Imam Besar itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 25, 'Simon Petrus masih berdiri berdiang. Kata orang-orang di situ kepadanya: "Bukankah engkau juga seorang murid-Nya?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 26, 'Ia menyangkalnya, katanya: "Bukan." Kata seorang hamba Imam Besar, seorang keluarga dari hamba yang telinganya dipotong Petrus: "Bukankah engkau kulihat di taman itu bersama-sama dengan Dia?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 27, 'Maka Petrus menyangkalnya pula dan ketika itu berkokoklah ayam.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 28, 'Maka mereka membawa Yesus dari Kayafas ke gedung pengadilan. Ketika itu hari masih pagi. Mereka sendiri tidak masuk ke gedung pengadilan itu, supaya jangan menajiskan diri, sebab mereka hendak makan Paskah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 29, 'Sebab itu Pilatus keluar mendapatkan mereka dan berkata: "Apakah tuduhan kamu terhadap orang ini?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 30, 'Jawab mereka kepadanya: "Jikalau Ia bukan seorang penjahat, kami tidak menyerahkan-Nya kepadamu!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 31, 'Kata Pilatus kepada mereka: "Ambillah Dia dan hakimilah Dia menurut hukum Tauratmu." Kata orang-orang Yahudi itu: "Kami tidak diperbolehkan membunuh seseorang."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 32, 'Demikian hendaknya supaya genaplah firman Yesus, yang dikatakan-Nya untuk menyatakan bagaimana caranya Ia akan mati.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 33, 'Maka kembalilah Pilatus ke dalam gedung pengadilan, lalu memanggil Yesus dan bertanya kepada-Nya: "Engkau inikah raja orang Yahudi?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 34, 'Jawab Yesus: "Apakah engkau katakan hal itu dari hatimu sendiri, atau adakah orang lain yang mengatakannya kepadamu tentang Aku?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 35, 'Kata Pilatus: "Apakah aku seorang Yahudi? Bangsa-Mu sendiri dan imam-imam kepala yang telah menyerahkan Engkau kepadaku; apakah yang telah Engkau perbuat?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 36, 'Jawab Yesus: "Kerajaan-Ku bukan dari dunia ini; jika Kerajaan-Ku dari dunia ini, pasti hamba-hamba-Ku telah melawan, supaya Aku jangan diserahkan kepada orang Yahudi, akan tetapi Kerajaan-Ku bukan dari sini."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 37, 'Maka kata Pilatus kepada-Nya: "Jadi Engkau adalah raja?" Jawab Yesus: "Engkau mengatakan, bahwa Aku adalah raja. Untuk itulah Aku lahir dan untuk itulah Aku datang ke dalam dunia ini, supaya Aku memberi kesaksian tentang kebenaran; setiap orang yang berasal dari kebenaran mendengarkan suara-Ku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 38, 'Kata Pilatus kepada-Nya: "Apakah kebenaran itu?" (18-38b) Sesudah mengatakan demikian, keluarlah Pilatus lagi mendapatkan orang-orang Yahudi dan berkata kepada mereka: "Aku tidak mendapati kesalahan apapun pada-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 39, 'Tetapi pada kamu ada kebiasaan, bahwa pada Paskah aku membebaskan seorang bagimu. Maukah kamu, supaya aku membebaskan raja orang Yahudi bagimu?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 18, 40, 'Mereka berteriak pula: "Jangan Dia, melainkan Barabas!" Barabas adalah seorang penyamun.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 1, 'Lalu Pilatus mengambil Yesus dan menyuruh orang menyesah Dia.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 2, 'Prajurit-prajurit menganyam sebuah mahkota duri dan menaruhnya di atas kepala-Nya. Mereka memakaikan Dia jubah ungu,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 3, 'dan sambil maju ke depan mereka berkata: "Salam, hai raja orang Yahudi!" Lalu mereka menampar muka-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 4, 'Pilatus keluar lagi dan berkata kepada mereka: "Lihatlah, aku membawa Dia ke luar kepada kamu, supaya kamu tahu, bahwa aku tidak mendapati kesalahan apapun pada-Nya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 5, 'Lalu Yesus keluar, bermahkota duri dan berjubah ungu. Maka kata Pilatus kepada mereka: "Lihatlah manusia itu!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 6, 'Ketika imam-imam kepala dan penjaga-penjaga itu melihat Dia, berteriaklah mereka: "Salibkan Dia, salibkan Dia!" Kata Pilatus kepada mereka: "Ambil Dia dan salibkan Dia; sebab aku tidak mendapati kesalahan apapun pada-Nya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 7, 'Jawab orang-orang Yahudi itu kepadanya: "Kami mempunyai hukum dan menurut hukum itu Ia harus mati, sebab Ia menganggap diri-Nya sebagai Anak Allah."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 8, 'Ketika Pilatus mendengar perkataan itu bertambah takutlah ia,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 9, 'lalu ia masuk pula ke dalam gedung pengadilan dan berkata kepada Yesus: "Dari manakah asal-Mu?" Tetapi Yesus tidak memberi jawab kepadanya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 10, 'Maka kata Pilatus kepada-Nya: "Tidakkah Engkau mau bicara dengan aku? Tidakkah Engkau tahu, bahwa aku berkuasa untuk membebaskan Engkau, dan berkuasa juga untuk menyalibkan Engkau?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 11, 'Yesus menjawab: "Engkau tidak mempunyai kuasa apapun terhadap Aku, jikalau kuasa itu tidak diberikan kepadamu dari atas. Sebab itu: dia, yang menyerahkan Aku kepadamu, lebih besar dosanya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 12, 'Sejak itu Pilatus berusaha untuk membebaskan Dia, tetapi orang-orang Yahudi berteriak: "Jikalau engkau membebaskan Dia, engkau bukanlah sahabat Kaisar. Setiap orang yang menganggap dirinya sebagai raja, ia melawan Kaisar."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 13, 'Ketika Pilatus mendengar perkataan itu, ia menyuruh membawa Yesus ke luar, dan ia duduk di kursi pengadilan, di tempat yang bernama Litostrotos, dalam bahasa Ibrani Gabata.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 14, 'Hari itu ialah hari persiapan Paskah, kira-kira jam dua belas. Kata Pilatus kepada orang-orang Yahudi itu: "Inilah rajamu!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 15, 'Maka berteriaklah mereka: "Enyahkan Dia! Enyahkan Dia! Salibkan Dia!" Kata Pilatus kepada mereka: "Haruskah aku menyalibkan rajamu?" Jawab imam-imam kepala: "Kami tidak mempunyai raja selain dari pada Kaisar!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 16, 'Akhirnya Pilatus menyerahkan Yesus kepada mereka untuk disalibkan. (19-16b) Mereka menerima Yesus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 17, 'Sambil memikul salib-Nya Ia pergi ke luar ke tempat yang bernama Tempat Tengkorak, dalam bahasa Ibrani: Golgota.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 18, 'Dan di situ Ia disalibkan mereka dan bersama-sama dengan Dia disalibkan juga dua orang lain, sebelah-menyebelah, Yesus di tengah-tengah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 19, 'Dan Pilatus menyuruh memasang juga tulisan di atas kayu salib itu, bunyinya: "Yesus, orang Nazaret, Raja orang Yahudi."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 20, 'Banyak orang Yahudi yang membaca tulisan itu, sebab tempat di mana Yesus disalibkan letaknya dekat kota dan kata-kata itu tertulis dalam bahasa Ibrani, bahasa Latin dan bahasa Yunani.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 21, 'Maka kata imam-imam kepala orang Yahudi kepada Pilatus: "Jangan engkau menulis: Raja orang Yahudi, tetapi bahwa Ia mengatakan: Aku adalah Raja orang Yahudi."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 22, 'Jawab Pilatus: "Apa yang kutulis, tetap tertulis."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 23, 'Sesudah prajurit-prajurit itu menyalibkan Yesus, mereka mengambil pakaian-Nya lalu membaginya menjadi empat bagian untuk tiap-tiap prajurit satu bagian?dan jubah-Nya juga mereka ambil. Jubah itu tidak berjahit, dari atas ke bawah hanya satu tenunan saja.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 24, 'Karena itu mereka berkata seorang kepada yang lain: "Janganlah kita membaginya menjadi beberapa potong, tetapi baiklah kita membuang undi untuk menentukan siapa yang mendapatnya." Demikianlah hendaknya supaya genaplah yang ada tertulis dalam Kitab Suci: "Mereka membagi-bagi pakaian-Ku di antara mereka dan mereka membuang undi atas jubah-Ku." Hal itu telah dilakukan prajurit-prajurit itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 25, 'Dan dekat salib Yesus berdiri ibu-Nya dan saudara ibu-Nya, Maria, isteri Klopas dan Maria Magdalena.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 26, 'Ketika Yesus melihat ibu-Nya dan murid yang dikasihi-Nya di sampingnya, berkatalah Ia kepada ibu-Nya: "Ibu, inilah, anakmu!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 27, 'Kemudian kata-Nya kepada murid-murid-Nya: "Inilah ibumu!" Dan sejak saat itu murid itu menerima dia di dalam rumahnya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 28, 'Sesudah itu, karena Yesus tahu, bahwa segala sesuatu telah selesai, berkatalah Ia?supaya genaplah yang ada tertulis dalam Kitab Suci?:"Aku haus!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 29, 'Di situ ada suatu bekas penuh anggur asam. Maka mereka mencucukkan bunga karang, yang telah dicelupkan dalam anggur asam, pada sebatang hisop lalu mengunjukkannya ke mulut Yesus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 30, 'Sesudah Yesus meminum anggur asam itu, berkatalah Ia: "Sudah selesai." Lalu Ia menundukkan kepala-Nya dan menyerahkan nyawa-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 31, 'Karena hari itu hari persiapan dan supaya pada hari Sabat mayat-mayat itu tidak tinggal tergantung pada kayu salib?sebab Sabat itu adalah hari yang besar?maka datanglah orang-orang Yahudi kepada Pilatus dan meminta kepadanya supaya kaki orang-orang itu dipatahkan dan mayat-mayatnya diturunkan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 32, 'Maka datanglah prajurit-prajurit lalu mematahkan kaki orang yang pertama dan kaki orang yang lain yang disalibkan bersama-sama dengan Yesus;', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 33, 'tetapi ketika mereka sampai kepada Yesus dan melihat bahwa Ia telah mati, mereka tidak mematahkan kaki-Nya,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 34, 'tetapi seorang dari antara prajurit itu menikam lambung-Nya dengan tombak, dan segera mengalir keluar darah dan air.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 35, 'Dan orang yang melihat hal itu sendiri yang memberikan kesaksian ini dan kesaksiannya benar, dan ia tahu, bahwa ia mengatakan kebenaran, supaya kamu juga percaya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 36, 'Sebab hal itu terjadi, supaya genaplah yang tertulis dalam Kitab Suci: "Tidak ada tulang-Nya yang akan dipatahkan."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 37, 'Dan ada pula nas yang mengatakan: "Mereka akan memandang kepada Dia yang telah mereka tikam."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 38, 'Sesudah itu Yusuf dari Arimatea?ia murid Yesus, tetapi sembunyi-sembunyi karena takut kepada orang-orang Yahudi?meminta kepada Pilatus, supaya ia diperbolehkan menurunkan mayat Yesus. Dan Pilatus meluluskan permintaannya itu. Lalu datanglah ia dan menurunkan mayat itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 39, 'Juga Nikodemus datang ke situ. Dialah yang mula-mula datang waktu malam kepada Yesus. Ia membawa campuran minyak mur dengan minyak gaharu, kira-kira lima puluh kati beratnya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 40, 'Mereka mengambil mayat Yesus, mengapaninya dengan kain lenan dan membubuhinya dengan rempah-rempah menurut adat orang Yahudi bila menguburkan mayat.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 41, 'Dekat tempat di mana Yesus disalibkan ada suatu taman dan dalam taman itu ada suatu kubur baru yang di dalamnya belum pernah dimakamkan seseorang.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 19, 42, 'Karena hari itu hari persiapan orang Yahudi, sedang kubur itu tidak jauh letaknya, maka mereka meletakkan mayat Yesus ke situ.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 1, 'Pada hari pertama minggu itu, pagi-pagi benar ketika hari masih gelap, pergilah Maria Magdalena ke kubur itu dan ia melihat bahwa batu telah diambil dari kubur.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 2, 'Ia berlari-lari mendapatkan Simon Petrus dan murid yang lain yang dikasihi Yesus, dan berkata kepada mereka: "Tuhan telah diambil orang dari kuburnya dan kami tidak tahu di mana Ia diletakkan."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 3, 'Maka berangkatlah Petrus dan murid yang lain itu ke kubur.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 4, 'Keduanya berlari bersama-sama, tetapi murid yang lain itu berlari lebih cepat dari pada Petrus sehingga lebih dahulu sampai di kubur.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 5, 'Ia menjenguk ke dalam, dan melihat kain kapan terletak di tanah; akan tetapi ia tidak masuk ke dalam.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 6, 'Maka datanglah Simon Petrus juga menyusul dia dan masuk ke dalam kubur itu. Ia melihat kain kapan terletak di tanah,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 7, 'sedang kain peluh yang tadinya ada di kepala Yesus tidak terletak dekat kain kapan itu, tetapi agak di samping di tempat yang lain dan sudah tergulung.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 8, 'Maka masuklah juga murid yang lain, yang lebih dahulu sampai di kubur itu dan ia melihatnya dan percaya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 9, 'Sebab selama itu mereka belum mengerti isi Kitab Suci yang mengatakan, bahwa Ia harus bangkit dari antara orang mati.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 10, 'Lalu pulanglah kedua murid itu ke rumah.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 11, 'Tetapi Maria berdiri dekat kubur itu dan menangis. Sambil menangis ia menjenguk ke dalam kubur itu,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 12, 'dan tampaklah olehnya dua orang malaikat berpakaian putih, yang seorang duduk di sebelah kepala dan yang lain di sebelah kaki di tempat mayat Yesus terbaring.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 13, 'Kata malaikat-malaikat itu kepadanya: "Ibu, mengapa engkau menangis?" Jawab Maria kepada mereka: "Tuhanku telah diambil orang dan aku tidak tahu di mana Ia diletakkan."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 14, 'Sesudah berkata demikian ia menoleh ke belakang dan melihat Yesus berdiri di situ, tetapi ia tidak tahu, bahwa itu adalah Yesus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 15, 'Kata Yesus kepadanya: "Ibu, mengapa engkau menangis? Siapakah yang engkau cari?" Maria menyangka orang itu adalah penunggu taman, lalu berkata kepada-Nya: "Tuan, jikalau tuan yang mengambil Dia, katakanlah kepadaku, di mana tuan meletakkan Dia, supaya aku dapat mengambil-Nya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 16, 'Kata Yesus kepadanya: "Maria!" Maria berpaling dan berkata kepada-Nya dalam bahasa Ibrani: "Rabuni!", artinya Guru.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 17, 'Kata Yesus kepadanya: "Janganlah engkau memegang Aku, sebab Aku belum pergi kepada Bapa, tetapi pergilah kepada saudara-saudara-Ku dan katakanlah kepada mereka, bahwa sekarang Aku akan pergi kepada Bapa-Ku dan Bapamu, kepada Allah-Ku dan Allahmu."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 18, 'Maria Magdalena pergi dan berkata kepada murid-murid: "Aku telah melihat Tuhan!" dan juga bahwa Dia yang mengatakan hal-hal itu kepadanya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 19, 'Ketika hari sudah malam pada hari pertama minggu itu berkumpullah murid-murid Yesus di suatu tempat dengan pintu-pintu yang terkunci karena mereka takut kepada orang-orang Yahudi. Pada waktu itu datanglah Yesus dan berdiri di tengah-tengah mereka dan berkata: "Damai sejahtera bagi kamu!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 20, 'Dan sesudah berkata demikian, Ia menunjukkan tangan-Nya dan lambung-Nya kepada mereka. Murid-murid itu bersukacita ketika mereka melihat Tuhan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 21, 'Maka kata Yesus sekali lagi: "Damai sejahtera bagi kamu! Sama seperti Bapa mengutus Aku, demikian juga sekarang Aku mengutus kamu."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 22, 'Dan sesudah berkata demikian, Ia mengembusi mereka dan berkata: "Terimalah Roh Kudus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 23, 'Jikalau kamu mengampuni dosa orang, dosanya diampuni, dan jikalau kamu menyatakan dosa orang tetap ada, dosanya tetap ada."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 24, 'Tetapi Tomas, seorang dari kedua belas murid itu, yang disebut Didimus, tidak ada bersama-sama mereka, ketika Yesus datang ke situ.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 25, 'Maka kata murid-murid yang lain itu kepadanya: "Kami telah melihat Tuhan!" Tetapi Tomas berkata kepada mereka: "Sebelum aku melihat bekas paku pada tangan-Nya dan sebelum aku mencucukkan jariku ke dalam bekas paku itu dan mencucukkan tanganku ke dalam lambung-Nya, sekali-kali aku tidak akan percaya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 26, 'Delapan hari kemudian murid-murid Yesus berada kembali dalam rumah itu dan Tomas bersama-sama dengan mereka. Sementara pintu-pintu terkunci, Yesus datang dan Ia berdiri di tengah-tengah mereka dan berkata: "Damai sejahtera bagi kamu!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 27, 'Kemudian Ia berkata kepada Tomas: "Taruhlah jarimu di sini dan lihatlah tangan-Ku, ulurkanlah tanganmu dan cucukkan ke dalam lambung-Ku dan jangan engkau tidak percaya lagi, melainkan percayalah."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 28, 'Tomas menjawab Dia: "Ya Tuhanku dan Allahku!"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 29, 'Kata Yesus kepadanya: "Karena engkau telah melihat Aku, maka engkau percaya. Berbahagialah mereka yang tidak melihat, namun percaya."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 30, 'Memang masih banyak tanda lain yang dibuat Yesus di depan mata murid-murid-Nya, yang tidak tercatat dalam kitab ini,', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 20, 31, 'tetapi semua yang tercantum di sini telah dicatat, supaya kamu percaya, bahwa Yesuslah Mesias, Anak Allah, dan supaya kamu oleh imanmu memperoleh hidup dalam nama-Nya.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 1, 'Kemudian Yesus menampakkan diri lagi kepada murid-murid-Nya di pantai danau Tiberias dan Ia menampakkan diri sebagai berikut.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 2, 'Di pantai itu berkumpul Simon Petrus, Tomas yang disebut Didimus, Natanael dari Kana yang di Galilea, anak-anak Zebedeus dan dua orang murid-Nya yang lain.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 3, 'Kata Simon Petrus kepada mereka: "Aku pergi menangkap ikan." Kata mereka kepadanya: "Kami pergi juga dengan engkau." Mereka berangkat lalu naik ke perahu, tetapi malam itu mereka tidak menangkap apa-apa.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 4, 'Ketika hari mulai siang, Yesus berdiri di pantai; akan tetapi murid-murid itu tidak tahu, bahwa itu adalah Yesus.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 5, 'Kata Yesus kepada mereka: "Hai anak-anak, adakah kamu mempunyai lauk-pauk?" Jawab mereka: "Tidak ada."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 6, 'Maka kata Yesus kepada mereka: "Tebarkanlah jalamu di sebelah kanan perahu, maka akan kamu peroleh." Lalu mereka menebarkannya dan mereka tidak dapat menariknya lagi karena banyaknya ikan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 7, 'Maka murid yang dikasihi Yesus itu berkata kepada Petrus: "Itu Tuhan." Ketika Petrus mendengar, bahwa itu adalah Tuhan, maka ia mengenakan pakaiannya, sebab ia tidak berpakaian, lalu terjun ke dalam danau.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 8, 'Murid-murid yang lain datang dengan perahu karena mereka tidak jauh dari darat, hanya kira-kira dua ratus hasta saja dan mereka menghela jala yang penuh ikan itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 9, 'Ketika mereka tiba di darat, mereka melihat api arang dan di atasnya ikan dan roti.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 10, 'Kata Yesus kepada mereka: "Bawalah beberapa ikan, yang baru kamu tangkap itu."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 11, 'Simon Petrus naik ke perahu lalu menghela jala itu ke darat, penuh ikan-ikan besar: seratus lima puluh tiga ekor banyaknya, dan sungguhpun sebanyak itu, jala itu tidak koyak.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 12, 'Kata Yesus kepada mereka: "Marilah dan sarapanlah." Tidak ada di antara murid-murid itu yang berani bertanya kepada-Nya: "Siapakah Engkau?" Sebab mereka tahu, bahwa Ia adalah Tuhan.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 13, 'Yesus maju ke depan, mengambil roti dan memberikannya kepada mereka, demikian juga ikan itu.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 14, 'Itulah ketiga kalinya Yesus menampakkan diri kepada murid-murid-Nya sesudah Ia bangkit dari antara orang mati.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 15, 'Sesudah sarapan Yesus berkata kepada Simon Petrus: "Simon, anak Yohanes, apakah engkau mengasihi Aku lebih dari pada mereka ini?" Jawab Petrus kepada-Nya: "Benar Tuhan, Engkau tahu, bahwa aku mengasihi Engkau." Kata Yesus kepadanya: "Gembalakanlah domba-domba-Ku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 16, 'Kata Yesus pula kepadanya untuk kedua kalinya: "Simon, anak Yohanes, apakah engkau mengasihi Aku?" Jawab Petrus kepada-Nya: "Benar Tuhan, Engkau tahu, bahwa aku mengasihi Engkau." Kata Yesus kepadanya: "Gembalakanlah domba-domba-Ku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 17, 'Kata Yesus kepadanya untuk ketiga kalinya: "Simon, anak Yohanes, apakah engkau mengasihi Aku?" Maka sedih hati Petrus karena Yesus berkata untuk ketiga kalinya: "Apakah engkau mengasihi Aku?" Dan ia berkata kepada-Nya: "Tuhan, Engkau tahu segala sesuatu, Engkau tahu, bahwa aku mengasihi Engkau." Kata Yesus kepadanya: "Gembalakanlah domba-domba-Ku.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 18, 'Aku berkata kepadamu: Sesungguhnya ketika engkau masih muda engkau mengikat pinggangmu sendiri dan engkau berjalan ke mana saja kaukehendaki, tetapi jika engkau sudah menjadi tua, engkau akan mengulurkan tanganmu dan orang lain akan mengikat engkau dan membawa engkau ke tempat yang tidak kaukehendaki."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 19, 'Dan hal ini dikatakan-Nya untuk menyatakan bagaimana Petrus akan mati dan memuliakan Allah. Sesudah mengatakan demikian Ia berkata kepada Petrus: "Ikutlah Aku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 20, 'Ketika Petrus berpaling, ia melihat bahwa murid yang dikasihi Yesus sedang mengikuti mereka, yaitu murid yang pada waktu mereka sedang makan bersama duduk dekat Yesus dan yang berkata: "Tuhan, siapakah dia yang akan menyerahkan Engkau?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 21, 'Ketika Petrus melihat murid itu, ia berkata kepada Yesus: "Tuhan, apakah yang akan terjadi dengan dia ini?"', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 22, 'Jawab Yesus: "Jikalau Aku menghendaki, supaya ia tinggal hidup sampai Aku datang, itu bukan urusanmu. Tetapi engkau: ikutlah Aku."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 23, 'Maka tersebarlah kabar di antara saudara-saudara itu, bahwa murid itu tidak akan mati. Tetapi Yesus tidak mengatakan kepada Petrus, bahwa murid itu tidak akan mati, melainkan: "Jikalau Aku menghendaki supaya ia tinggal hidup sampai Aku datang, itu bukan urusanmu."', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 24, 'Dialah murid, yang memberi kesaksian tentang semuanya ini dan yang telah menuliskannya dan kita tahu, bahwa kesaksiannya itu benar.', 'id', 'TB'),
  ('43', 'yoh', 'Yohanes', 21, 25, 'Masih banyak hal-hal lain lagi yang diperbuat oleh Yesus, tetapi jikalau semuanya itu harus dituliskan satu per satu, maka agaknya dunia ini tidak dapat memuat semua kitab yang harus ditulis itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 1, 'Hai Teofilus, dalam bukuku yang pertama aku menulis tentang segala sesuatu yang dikerjakan dan diajarkan Yesus,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 2, 'sampai pada hari Ia terangkat. Sebelum itu Ia telah memberi perintah-Nya oleh Roh Kudus kepada rasul-rasul yang dipilih-Nya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 3, 'Kepada mereka Ia menunjukkan diri-Nya setelah penderitaan-Nya selesai, dan dengan banyak tanda Ia membuktikan, bahwa Ia hidup. Sebab selama empat puluh hari Ia berulang-ulang menampakkan diri dan berbicara kepada mereka tentang Kerajaan Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 4, 'Pada suatu hari ketika Ia makan bersama-sama dengan mereka, Ia melarang mereka meninggalkan Yerusalem, dan menyuruh mereka tinggal di situ menantikan janji Bapa, yang?demikian kata-Nya?"telah kamu dengar dari pada-Ku.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 5, 'Sebab Yohanes membaptis dengan air, tetapi tidak lama lagi kamu akan dibaptis dengan Roh Kudus."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 6, 'Maka bertanyalah mereka yang berkumpul di situ: "Tuhan, maukah Engkau pada masa ini memulihkan kerajaan bagi Israel?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 7, 'Jawab-Nya: "Engkau tidak perlu mengetahui masa dan waktu, yang ditetapkan Bapa sendiri menurut kuasa-Nya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 8, 'Tetapi kamu akan menerima kuasa, kalau Roh Kudus turun ke atas kamu, dan kamu akan menjadi saksi-Ku di Yerusalem dan di seluruh Yudea dan Samaria dan sampai ke ujung bumi."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 9, 'Sesudah Ia mengatakan demikian, terangkatlah Ia disaksikan oleh mereka, dan awan menutup-Nya dari pandangan mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 10, 'Ketika mereka sedang menatap ke langit waktu Ia naik itu, tiba-tiba berdirilah dua orang yang berpakaian putih dekat mereka,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 11, 'dan berkata kepada mereka: "Hai orang-orang Galilea, mengapakah kamu berdiri melihat ke langit? Yesus ini, yang terangkat ke sorga meninggalkan kamu, akan datang kembali dengan cara yang sama seperti kamu melihat Dia naik ke sorga."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 12, 'Maka kembalilah rasul-rasul itu ke Yerusalem dari bukit yang disebut Bukit Zaitun, yang hanya seperjalanan Sabat jauhnya dari Yerusalem.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 13, 'Setelah mereka tiba di kota, naiklah mereka ke ruang atas, tempat mereka menumpang. Mereka itu ialah Petrus dan Yohanes, Yakobus dan Andreas, Filipus dan Tomas, Bartolomeus dan Matius, Yakobus bin Alfeus, dan Simon orang Zelot dan Yudas bin Yakobus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 14, 'Mereka semua bertekun dengan sehati dalam doa bersama-sama, dengan beberapa perempuan serta Maria, ibu Yesus, dan dengan saudara-saudara Yesus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 15, 'Pada hari-hari itu berdirilah Petrus di tengah-tengah saudara-saudara yang sedang berkumpul itu, kira-kira seratus dua puluh orang banyaknya, lalu berkata:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 16, '"Hai saudara-saudara, haruslah genap nas Kitab Suci, yang disampaikan Roh Kudus dengan perantaraan Daud tentang Yudas, pemimpin orang-orang yang menangkap Yesus itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 17, 'Dahulu ia termasuk bilangan kami dan mengambil bagian di dalam pelayanan ini."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 18, '?Yudas ini telah membeli sebidang tanah dengan upah kejahatannya, lalu ia jatuh tertelungkup, dan perutnya terbelah sehingga semua isi perutnya tertumpah ke luar.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 19, 'Hal itu diketahui oleh semua penduduk Yerusalem, sehingga tanah itu mereka sebut dalam bahasa mereka sendiri "Hakal-Dama", artinya Tanah Darah?.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 20, '"Sebab ada tertulis dalam kitab Mazmur: Biarlah perkemahannya menjadi sunyi, dan biarlah tidak ada penghuni di dalamnya: dan: Biarlah jabatannya diambil orang lain.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 21, 'Jadi harus ditambahkan kepada kami seorang dari mereka yang senantiasa datang berkumpul dengan kami selama Tuhan Yesus bersama-sama dengan kami,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 22, 'yaitu mulai dari baptisan Yohanes sampai hari Yesus terangkat ke sorga meninggalkan kami, untuk menjadi saksi dengan kami tentang kebangkitan-Nya."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 23, 'Lalu mereka mengusulkan dua orang: Yusuf yang disebut Barsabas dan yang juga bernama Yustus, dan Matias.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 24, 'Mereka semua berdoa dan berkata: "Ya Tuhan, Engkaulah yang mengenal hati semua orang, tunjukkanlah kiranya siapa yang Engkau pilih dari kedua orang ini,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 25, 'untuk menerima jabatan pelayanan, yaitu kerasulan yang ditinggalkan Yudas yang telah jatuh ke tempat yang wajar baginya."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 1, 26, 'Lalu mereka membuang undi bagi kedua orang itu dan yang kena undi adalah Matias dan dengan demikian ia ditambahkan kepada bilangan kesebelas rasul itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 1, 'Ketika tiba hari Pentakosta, semua orang percaya berkumpul di satu tempat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 2, 'Tiba-tiba turunlah dari langit suatu bunyi seperti tiupan angin keras yang memenuhi seluruh rumah, di mana mereka duduk;', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 3, 'dan tampaklah kepada mereka lidah-lidah seperti nyala api yang bertebaran dan hinggap pada mereka masing-masing.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 4, 'Maka penuhlah mereka dengan Roh Kudus, lalu mereka mulai berkata-kata dalam bahasa-bahasa lain, seperti yang diberikan oleh Roh itu kepada mereka untuk mengatakannya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 5, 'Waktu itu di Yerusalem diam orang-orang Yahudi yang saleh dari segala bangsa di bawah kolong langit.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 6, 'Ketika turun bunyi itu, berkerumunlah orang banyak. Mereka bingung karena mereka masing-masing mendengar rasul-rasul itu berkata-kata dalam bahasa mereka sendiri.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 7, 'Mereka semua tercengang-cengang dan heran, lalu berkata: "Bukankah mereka semua yang berkata-kata itu orang Galilea?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 8, 'Bagaimana mungkin kita masing-masing mendengar mereka berkata-kata dalam bahasa kita sendiri, yaitu bahasa yang kita pakai di negeri asal kita:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 9, 'kita orang Partia, Media, Elam, penduduk Mesopotamia, Yudea dan Kapadokia, Pontus dan Asia,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 10, 'Frigia dan Pamfilia, Mesir dan daerah-daerah Libia yang berdekatan dengan Kirene, pendatang-pendatang dari Roma,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 11, 'baik orang Yahudi maupun penganut agama Yahudi, orang Kreta dan orang Arab, kita mendengar mereka berkata-kata dalam bahasa kita sendiri tentang perbuatan-perbuatan besar yang dilakukan Allah."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 12, 'Mereka semuanya tercengang-cengang dan sangat termangu-mangu sambil berkata seorang kepada yang lain: "Apakah artinya ini?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 13, 'Tetapi orang lain menyindir: "Mereka sedang mabuk oleh anggur manis."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 14, 'Maka bangkitlah Petrus berdiri dengan kesebelas rasul itu, dan dengan suara nyaring ia berkata kepada mereka: "Hai kamu orang Yahudi dan kamu semua yang tinggal di Yerusalem, ketahuilah dan camkanlah perkataanku ini.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 15, 'Orang-orang ini tidak mabuk seperti yang kamu sangka, karena hari baru pukul sembilan,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 16, 'tetapi itulah yang difirmankan Allah dengan perantaraan nabi Yoel:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 17, 'Akan terjadi pada hari-hari terakhir?demikianlah firman Allah?bahwa Aku akan mencurahkan Roh-Ku ke atas semua manusia; maka anak-anakmu laki-laki dan perempuan akan bernubuat, dan teruna-terunamu akan mendapat penglihatan-penglihatan, dan orang-orangmu yang tua akan mendapat mimpi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 18, 'Juga ke atas hamba-hamba-Ku laki-laki dan perempuan akan Kucurahkan Roh-Ku pada hari-hari itu dan mereka akan bernubuat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 19, 'Dan Aku akan mengadakan mujizat-mujizat di atas, di langit dan tanda-tanda di bawah, di bumi: darah dan api dan gumpalan-gumpalan asap.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 20, 'Matahari akan berubah menjadi gelap gulita dan bulan menjadi darah sebelum datangnya hari Tuhan, hari yang besar dan mulia itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 21, 'Dan barangsiapa yang berseru kepada nama Tuhan akan diselamatkan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 22, 'Hai orang-orang Israel, dengarlah perkataan ini: Yang aku maksudkan, ialah Yesus dari Nazaret, seorang yang telah ditentukan Allah dan yang dinyatakan kepadamu dengan kekuatan-kekuatan dan mujizat-mujizat dan tanda-tanda yang dilakukan oleh Allah dengan perantaraan Dia di tengah-tengah kamu, seperti yang kamu tahu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 23, 'Dia yang diserahkan Allah menurut maksud dan rencana-Nya, telah kamu salibkan dan kamu bunuh oleh tangan bangsa-bangsa durhaka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 24, 'Tetapi Allah membangkitkan Dia dengan melepaskan Dia dari sengsara maut, karena tidak mungkin Ia tetap berada dalam kuasa maut itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 25, 'Sebab Daud berkata tentang Dia: Aku senantiasa memandang kepada Tuhan, karena Ia berdiri di sebelah kananku, aku tidak goyah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 26, 'Sebab itu hatiku bersukacita dan jiwaku bersorak-sorak, bahkan tubuhku akan diam dengan tenteram,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 27, 'sebab Engkau tidak menyerahkan aku kepada dunia orang mati, dan tidak membiarkan Orang Kudus-Mu melihat kebinasaan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 28, 'Engkau memberitahukan kepadaku jalan kehidupan; Engkau akan melimpahi aku dengan sukacita di hadapan-Mu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 29, 'Saudara-saudara, aku boleh berkata-kata dengan terus terang kepadamu tentang Daud, bapa bangsa kita. Ia telah mati dan dikubur, dan kuburannya masih ada pada kita sampai hari ini.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 30, 'Tetapi ia adalah seorang nabi dan ia tahu, bahwa Allah telah berjanji kepadanya dengan mengangkat sumpah, bahwa Ia akan mendudukkan seorang dari keturunan Daud sendiri di atas takhtanya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 31, 'Karena itu ia telah melihat ke depan dan telah berbicara tentang kebangkitan Mesias, ketika ia mengatakan, bahwa Dia tidak ditinggalkan di dalam dunia orang mati, dan bahwa daging-Nya tidak mengalami kebinasaan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 32, 'Yesus inilah yang dibangkitkan Allah, dan tentang hal itu kami semua adalah saksi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 33, 'Dan sesudah Ia ditinggikan oleh tangan kanan Allah dan menerima Roh Kudus yang dijanjikan itu, maka dicurahkan-Nya apa yang kamu lihat dan dengar di sini.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 34, 'Sebab bukan Daud yang naik ke sorga, malahan Daud sendiri berkata: Tuhan telah berfirman kepada Tuanku:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 35, 'Duduklah di sebelah kanan-Ku, sampai Kubuat musuh-musuh-Mu menjadi tumpuan kaki-Mu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 36, 'Jadi seluruh kaum Israel harus tahu dengan pasti, bahwa Allah telah membuat Yesus, yang kamu salibkan itu, menjadi Tuhan dan Kristus."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 37, 'Ketika mereka mendengar hal itu hati mereka sangat terharu, lalu mereka bertanya kepada Petrus dan rasul-rasul yang lain: "Apakah yang harus kami perbuat, saudara-saudara?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 38, 'Jawab Petrus kepada mereka: "Bertobatlah dan hendaklah kamu masing-masing memberi dirimu dibaptis dalam nama Yesus Kristus untuk pengampunan dosamu, maka kamu akan menerima karunia Roh Kudus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 39, 'Sebab bagi kamulah janji itu dan bagi anak-anakmu dan bagi orang yang masih jauh, yaitu sebanyak yang akan dipanggil oleh Tuhan Allah kita."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 40, 'Dan dengan banyak perkataan lain lagi ia memberi suatu kesaksian yang sungguh-sungguh dan ia mengecam dan menasihati mereka, katanya: "Berilah dirimu diselamatkan dari angkatan yang jahat ini."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 41, 'Orang-orang yang menerima perkataannya itu memberi diri dibaptis dan pada hari itu jumlah mereka bertambah kira-kira tiga ribu jiwa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 42, 'Mereka bertekun dalam pengajaran rasul-rasul dan dalam persekutuan. Dan mereka selalu berkumpul untuk memecahkan roti dan berdoa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 43, 'Maka ketakutanlah mereka semua, sedang rasul-rasul itu mengadakan banyak mujizat dan tanda.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 44, 'Dan semua orang yang telah menjadi percaya tetap bersatu, dan segala kepunyaan mereka adalah kepunyaan bersama,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 45, 'dan selalu ada dari mereka yang menjual harta miliknya, lalu membagi-bagikannya kepada semua orang sesuai dengan keperluan masing-masing.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 46, 'Dengan bertekun dan dengan sehati mereka berkumpul tiap-tiap hari dalam Bait Allah. Mereka memecahkan roti di rumah masing-masing secara bergilir dan makan bersama-sama dengan gembira dan dengan tulus hati,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 2, 47, 'sambil memuji Allah. Dan mereka disukai semua orang. Dan tiap-tiap hari Tuhan menambah jumlah mereka dengan orang yang diselamatkan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 1, 'Pada suatu hari menjelang waktu sembahyang, yaitu pukul tiga petang, naiklah Petrus dan Yohanes ke Bait Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 2, 'Di situ ada seorang laki-laki, yang lumpuh sejak lahirnya sehingga ia harus diusung. Tiap-tiap hari orang itu diletakkan dekat pintu gerbang Bait Allah, yang bernama Gerbang Indah, untuk meminta sedekah kepada orang yang masuk ke dalam Bait Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 3, 'Ketika orang itu melihat, bahwa Petrus dan Yohanes hendak masuk ke Bait Allah, ia meminta sedekah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 4, 'Mereka menatap dia dan Petrus berkata: "Lihatlah kepada kami."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 5, 'Lalu orang itu menatap mereka dengan harapan akan mendapat sesuatu dari mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 6, 'Tetapi Petrus berkata: "Emas dan perak tidak ada padaku, tetapi apa yang kupunyai, kuberikan kepadamu: Demi nama Yesus Kristus, orang Nazaret itu, berjalanlah!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 7, 'Lalu ia memegang tangan kanan orang itu dan membantu dia berdiri. Seketika itu juga kuatlah kaki dan mata kaki orang itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 8, 'Ia melonjak berdiri lalu berjalan kian ke mari dan mengikuti mereka ke dalam Bait Allah, berjalan dan melompat-lompat serta memuji Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 9, 'Seluruh rakyat itu melihat dia berjalan sambil memuji Allah,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 10, 'lalu mereka mengenal dia sebagai orang yang biasanya duduk meminta sedekah di Gerbang Indah Bait Allah, sehingga mereka takjub dan tercengang tentang apa yang telah terjadi padanya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 11, 'Karena orang itu tetap mengikuti Petrus dan Yohanes, maka seluruh orang banyak yang sangat keheranan itu datang mengerumuni mereka di serambi yang disebut Serambi Salomo.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 12, 'Petrus melihat orang banyak itu lalu berkata: "Hai orang Israel, mengapa kamu heran tentang kejadian itu dan mengapa kamu menatap kami seolah-olah kami membuat orang ini berjalan karena kuasa atau kesalehan kami sendiri?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 13, 'Allah Abraham, Ishak dan Yakub, Allah nenek moyang kita telah memuliakan Hamba-Nya, yaitu Yesus yang kamu serahkan dan tolak di depan Pilatus, walaupun Pilatus berpendapat, bahwa Ia harus dilepaskan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 14, 'Tetapi kamu telah menolak Yang Kudus dan Benar, serta menghendaki seorang pembunuh sebagai hadiahmu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 15, 'Demikianlah Ia, Pemimpin kepada hidup, telah kamu bunuh, tetapi Allah telah membangkitkan Dia dari antara orang mati; dan tentang hal itu kami adalah saksi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 16, 'Dan karena kepercayaan dalam Nama Yesus, maka Nama itu telah menguatkan orang yang kamu lihat dan kamu kenal ini; dan kepercayaan itu telah memberi kesembuhan kepada orang ini di depan kamu semua.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 17, 'Hai saudara-saudara, aku tahu bahwa kamu telah berbuat demikian karena ketidaktahuan, sama seperti semua pemimpin kamu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 18, 'Tetapi dengan jalan demikian Allah telah menggenapi apa yang telah difirmankan-Nya dahulu dengan perantaraan nabi-nabi-Nya, yaitu bahwa Mesias yang diutus-Nya harus menderita.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 19, 'Karena itu sadarlah dan bertobatlah, supaya dosamu dihapuskan,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 20, 'agar Tuhan mendatangkan waktu kelegaan, dan mengutus Yesus, yang dari semula diuntukkan bagimu sebagai Kristus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 21, 'Kristus itu harus tinggal di sorga sampai waktu pemulihan segala sesuatu, seperti yang difirmankan Allah dengan perantaraan nabi-nabi-Nya yang kudus di zaman dahulu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 22, 'Bukankah telah dikatakan Musa: Tuhan Allah akan membangkitkan bagimu seorang nabi dari antara saudara-saudaramu, sama seperti aku: Dengarkanlah dia dalam segala sesuatu yang akan dikatakannya kepadamu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 23, 'Dan akan terjadi, bahwa semua orang yang tidak mendengarkan nabi itu, akan dibasmi dari umat kita.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 24, 'Dan semua nabi yang pernah berbicara, mulai dari Samuel, dan sesudah dia, telah bernubuat tentang zaman ini.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 25, 'Kamulah yang mewarisi nubuat-nubuat itu dan mendapat bagian dalam perjanjian yang telah diadakan Allah dengan nenek moyang kita, ketika Ia berfirman kepada Abraham: Oleh keturunanmu semua bangsa di muka bumi akan diberkati.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 3, 26, 'Dan bagi kamulah pertama-tama Allah membangkitkan Hamba-Nya dan mengutus-Nya kepada kamu, supaya Ia memberkati kamu dengan memimpin kamu masing-masing kembali dari segala kejahatanmu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 1, 'Ketika Petrus dan Yohanes sedang berbicara kepada orang banyak, mereka tiba-tiba didatangi imam-imam dan kepala pengawal Bait Allah serta orang-orang Saduki.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 2, 'Orang-orang itu sangat marah karena mereka mengajar orang banyak dan memberitakan, bahwa dalam Yesus ada kebangkitan dari antara orang mati.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 3, 'Mereka ditangkap dan diserahkan ke dalam tahanan sampai keesokan harinya, karena hari telah malam.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 4, 'Tetapi di antara orang yang mendengar ajaran itu banyak yang menjadi percaya, sehingga jumlah mereka menjadi kira-kira lima ribu orang laki-laki.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 5, 'Pada keesokan harinya pemimpin-pemimpin Yahudi serta tua-tua dan ahli-ahli Taurat mengadakan sidang di Yerusalem', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 6, 'dengan Imam Besar Hanas dan Kayafas, Yohanes dan Aleksander dan semua orang lain yang termasuk keturunan Imam Besar.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 7, 'Lalu Petrus dan Yohanes dihadapkan kepada sidang itu dan mulai diperiksa dengan pertanyaan ini: "Dengan kuasa manakah atau dalam nama siapakah kamu bertindak demikian itu?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 8, 'Maka jawab Petrus, penuh dengan Roh Kudus: "Hai pemimpin-pemimpin umat dan tua-tua,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 9, 'jika kami sekarang harus diperiksa karena suatu kebajikan kepada seorang sakit dan harus menerangkan dengan kuasa manakah orang itu disembuhkan,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 10, 'maka ketahuilah oleh kamu sekalian dan oleh seluruh umat Israel, bahwa dalam nama Yesus Kristus, orang Nazaret, yang telah kamu salibkan, tetapi yang telah dibangkitkan Allah dari antara orang mati?bahwa oleh karena Yesus itulah orang ini berdiri dengan sehat sekarang di depan kamu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 11, 'Yesus adalah batu yang dibuang oleh tukang-tukang bangunan?yaitu kamu sendiri?,namun ia telah menjadi batu penjuru.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 12, 'Dan keselamatan tidak ada di dalam siapapun juga selain di dalam Dia, sebab di bawah kolong langit ini tidak ada nama lain yang diberikan kepada manusia yang olehnya kita dapat diselamatkan."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 13, 'Ketika sidang itu melihat keberanian Petrus dan Yohanes dan mengetahui, bahwa keduanya orang biasa yang tidak terpelajar, heranlah mereka; dan mereka mengenal keduanya sebagai pengikut Yesus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 14, 'Tetapi karena mereka melihat orang yang disembuhkan itu berdiri di samping kedua rasul itu, mereka tidak dapat mengatakan apa-apa untuk membantahnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 15, 'Dan setelah mereka menyuruh rasul-rasul itu meninggalkan ruang sidang, berundinglah mereka,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 16, 'dan berkata: "Tindakan apakah yang harus kita ambil terhadap orang-orang ini? Sebab telah nyata kepada semua penduduk Yerusalem, bahwa mereka telah mengadakan suatu mujizat yang menyolok dan kita tidak dapat menyangkalnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 17, 'Tetapi supaya hal itu jangan makin luas tersiar di antara orang banyak, baiklah kita mengancam dan melarang mereka, supaya mereka jangan berbicara lagi dengan siapapun dalam nama itu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 18, 'Dan setelah keduanya disuruh masuk, mereka diperintahkan, supaya sama sekali jangan berbicara atau mengajar lagi dalam nama Yesus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 19, 'Tetapi Petrus dan Yohanes menjawab mereka: "Silakan kamu putuskan sendiri manakah yang benar di hadapan Allah: taat kepada kamu atau taat kepada Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 20, 'Sebab tidak mungkin bagi kami untuk tidak berkata-kata tentang apa yang telah kami lihat dan yang telah kami dengar."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 21, 'Mereka semakin keras mengancam rasul-rasul itu, tetapi akhirnya melepaskan mereka juga, sebab sidang tidak melihat jalan untuk menghukum mereka karena takut akan orang banyak yang memuliakan nama Allah berhubung dengan apa yang telah terjadi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 22, 'Sebab orang yang disembuhkan oleh mujizat itu sudah lebih dari empat puluh tahun umurnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 23, 'Sesudah dilepaskan pergilah Petrus dan Yohanes kepada teman-teman mereka, lalu mereka menceriterakan segala sesuatu yang dikatakan imam-imam kepala dan tua-tua kepada mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 24, 'Ketika teman-teman mereka mendengar hal itu, berserulah mereka bersama-sama kepada Allah, katanya: "Ya Tuhan, Engkaulah yang menjadikan langit dan bumi, laut dan segala isinya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 25, 'Dan oleh Roh Kudus dengan perantaraan hamba-Mu Daud, bapa kami, Engkau telah berfirman: Mengapa rusuh bangsa-bangsa, mengapa suku-suku bangsa mereka-reka perkara yang sia-sia?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 26, 'Raja-raja dunia bersiap-siap dan para pembesar berkumpul untuk melawan Tuhan dan Yang Diurapi-Nya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 27, 'Sebab sesungguhnya telah berkumpul di dalam kota ini Herodes dan Pontius Pilatus beserta bangsa-bangsa dan suku-suku bangsa Israel melawan Yesus, Hamba-Mu yang kudus, yang Engkau urapi,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 28, 'untuk melaksanakan segala sesuatu yang telah Engkau tentukan dari semula oleh kuasa dan kehendak-Mu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 29, 'Dan sekarang, ya Tuhan, lihatlah bagaimana mereka mengancam kami dan berikanlah kepada hamba-hamba-Mu keberanian untuk memberitakan firman-Mu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 30, 'Ulurkanlah tangan-Mu untuk menyembuhkan orang, dan adakanlah tanda-tanda dan mujizat-mujizat oleh nama Yesus, Hamba-Mu yang kudus."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 31, 'Dan ketika mereka sedang berdoa, goyanglah tempat mereka berkumpul itu dan mereka semua penuh dengan Roh Kudus, lalu mereka memberitakan firman Allah dengan berani.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 32, 'Adapun kumpulan orang yang telah percaya itu, mereka sehati dan sejiwa, dan tidak seorangpun yang berkata, bahwa sesuatu dari kepunyaannya adalah miliknya sendiri, tetapi segala sesuatu adalah kepunyaan mereka bersama.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 33, 'Dan dengan kuasa yang besar rasul-rasul memberi kesaksian tentang kebangkitan Tuhan Yesus dan mereka semua hidup dalam kasih karunia yang melimpah-limpah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 34, 'Sebab tidak ada seorangpun yang berkekurangan di antara mereka; karena semua orang yang mempunyai tanah atau rumah, menjual kepunyaannya itu, dan hasil penjualan itu mereka bawa', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 35, 'dan mereka letakkan di depan kaki rasul-rasul; lalu dibagi-bagikan kepada setiap orang sesuai dengan keperluannya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 36, 'Demikian pula dengan Yusuf, yang oleh rasul-rasul disebut Barnabas, artinya anak penghiburan, seorang Lewi dari Siprus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 4, 37, 'Ia menjual ladang, miliknya, lalu membawa uangnya itu dan meletakkannya di depan kaki rasul-rasul.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 1, 'Ada seorang lain yang bernama Ananias. Ia beserta isterinya Safira menjual sebidang tanah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 2, 'Dengan setahu isterinya ia menahan sebagian dari hasil penjualan itu dan sebagian lain dibawa dan diletakkannya di depan kaki rasul-rasul.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 3, 'Tetapi Petrus berkata: "Ananias, mengapa hatimu dikuasai Iblis, sehingga engkau mendustai Roh Kudus dan menahan sebagian dari hasil penjualan tanah itu?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 4, 'Selama tanah itu tidak dijual, bukankah itu tetap kepunyaanmu, dan setelah dijual, bukankah hasilnya itu tetap dalam kuasamu? Mengapa engkau merencanakan perbuatan itu dalam hatimu? Engkau bukan mendustai manusia, tetapi mendustai Allah."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 5, 'Ketika mendengar perkataan itu rebahlah Ananias dan putuslah nyawanya. Maka sangatlah ketakutan semua orang yang mendengar hal itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 6, 'Lalu datanglah beberapa orang muda; mereka mengapani mayat itu, mengusungnya ke luar dan pergi menguburnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 7, 'Kira-kira tiga jam kemudian masuklah isteri Ananias, tetapi ia tidak tahu apa yang telah terjadi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 8, 'Kata Petrus kepadanya: "Katakanlah kepadaku, dengan harga sekiankah tanah itu kamu jual?" Jawab perempuan itu: "Betul sekian."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 9, 'Kata Petrus: "Mengapa kamu berdua bersepakat untuk mencobai Roh Tuhan? Lihatlah, orang-orang yang baru mengubur suamimu berdiri di depan pintu dan mereka akan mengusung engkau juga ke luar."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 10, 'Lalu rebahlah perempuan itu seketika itu juga di depan kaki Petrus dan putuslah nyawanya. Ketika orang-orang muda itu masuk, mereka mendapati dia sudah mati, lalu mereka mengusungnya ke luar dan menguburnya di samping suaminya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 11, 'Maka sangat ketakutanlah seluruh jemaat dan semua orang yang mendengar hal itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 12, 'Dan oleh rasul-rasul diadakan banyak tanda dan mujizat di antara orang banyak. Semua orang percaya selalu berkumpul di Serambi Salomo dalam persekutuan yang erat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 13, 'Orang-orang lain tidak ada yang berani menggabungkan diri kepada mereka. Namun mereka sangat dihormati orang banyak.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 14, 'Dan makin lama makin bertambahlah jumlah orang yang percaya kepada Tuhan, baik laki-laki maupun perempuan,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 15, 'bahkan mereka membawa orang-orang sakit ke luar, ke jalan raya, dan membaringkannya di atas balai-balai dan tilam, supaya, apabila Petrus lewat, setidak-tidaknya bayangannya mengenai salah seorang dari mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 16, 'Dan juga orang banyak dari kota-kota di sekitar Yerusalem datang berduyun-duyun serta membawa orang-orang yang sakit dan orang-orang yang diganggu roh jahat. Dan mereka semua disembuhkan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 17, 'Akhirnya mulailah Imam Besar dan pengikut-pengikutnya, yaitu orang-orang dari mazhab Saduki, bertindak sebab mereka sangat iri hati.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 18, 'Mereka menangkap rasul-rasul itu, lalu memasukkan mereka ke dalam penjara kota.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 19, 'Tetapi waktu malam seorang malaikat Tuhan membuka pintu-pintu penjara itu dan membawa mereka ke luar, katanya:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 20, '"Pergilah, berdirilah di Bait Allah dan beritakanlah seluruh firman hidup itu kepada orang banyak."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 21, 'Mereka mentaati pesan itu, dan menjelang pagi masuklah mereka ke dalam Bait Allah, lalu mulai mengajar di situ. Sementara itu Imam Besar dan pengikut-pengikutnya menyuruh Mahkamah Agama berkumpul, yaitu seluruh majelis tua-tua bangsa Israel, dan mereka menyuruh mengambil rasul-rasul itu dari penjara.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 22, 'Tetapi ketika pejabat-pejabat datang ke penjara, mereka tidak menemukan rasul-rasul itu di situ. Lalu mereka kembali dan memberitahukan,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 23, 'katanya: "Kami mendapati penjara terkunci dengan sangat rapihnya dan semua pengawal ada di tempatnya di muka pintu, tetapi setelah kami membukanya, tidak seorangpun yang kami temukan di dalamnya."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 24, 'Ketika kepala pengawal Bait Allah dan imam-imam kepala mendengar laporan itu, mereka cemas dan bertanya apa yang telah terjadi dengan rasul-rasul itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 25, 'Tetapi datanglah seorang mendapatkan mereka dengan kabar: "Lihat, orang-orang yang telah kamu masukkan ke dalam penjara, ada di dalam Bait Allah dan mereka mengajar orang banyak."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 26, 'Maka pergilah kepala pengawal serta orang-orangnya ke Bait Allah, lalu mengambil kedua rasul itu, tetapi tidak dengan kekerasan, karena mereka takut, kalau-kalau orang banyak melempari mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 27, 'Mereka membawa keduanya dan menghadapkan mereka kepada Mahkamah Agama. Imam Besar mulai menanyai mereka,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 28, 'katanya: "Dengan keras kami melarang kamu mengajar dalam Nama itu. Namun ternyata, kamu telah memenuhi Yerusalem dengan ajaranmu dan kamu hendak menanggungkan darah Orang itu kepada kami."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 29, 'Tetapi Petrus dan rasul-rasul itu menjawab, katanya: "Kita harus lebih taat kepada Allah dari pada kepada manusia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 30, 'Allah nenek moyang kita telah membangkitkan Yesus, yang kamu gantungkan pada kayu salib dan kamu bunuh.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 31, 'Dialah yang telah ditinggikan oleh Allah sendiri dengan tangan kanan-Nya menjadi Pemimpin dan Juruselamat, supaya Israel dapat bertobat dan menerima pengampunan dosa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 32, 'Dan kami adalah saksi dari segala sesuatu itu, kami dan Roh Kudus, yang dikaruniakan Allah kepada semua orang yang mentaati Dia."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 33, 'Mendengar perkataan itu sangatlah tertusuk hati mereka dan mereka bermaksud membunuh rasul-rasul itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 34, 'Tetapi seorang Farisi dalam Mahkamah Agama itu, yang bernama Gamaliel, seorang ahli Taurat yang sangat dihormati seluruh orang banyak, bangkit dan meminta, supaya orang-orang itu disuruh keluar sebentar.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 35, 'Sesudah itu ia berkata kepada sidang: "Hai orang-orang Israel, pertimbangkanlah baik-baik, apa yang hendak kamu perbuat terhadap orang-orang ini!', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 36, 'Sebab dahulu telah muncul si Teudas, yang mengaku dirinya seorang istimewa dan ia mempunyai kira-kira empat ratus orang pengikut; tetapi ia dibunuh dan cerai-berailah seluruh pengikutnya dan lenyap.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 37, 'Sesudah dia, pada waktu pendaftaran penduduk, muncullah si Yudas, seorang Galilea. Ia menyeret banyak orang dalam pemberontakannya, tetapi ia juga tewas dan cerai-berailah seluruh pengikutnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 38, 'Karena itu aku berkata kepadamu: Janganlah bertindak terhadap orang-orang ini. Biarkanlah mereka, sebab jika maksud dan perbuatan mereka berasal dari manusia, tentu akan lenyap,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 39, 'tetapi kalau berasal dari Allah, kamu tidak akan dapat melenyapkan orang-orang ini; mungkin ternyata juga nanti, bahwa kamu melawan Allah." Nasihat itu diterima.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 40, 'Mereka memanggil rasul-rasul itu, lalu menyesah mereka dan melarang mereka mengajar dalam nama Yesus. Sesudah itu mereka dilepaskan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 41, 'Rasul-rasul itu meninggalkan sidang Mahkamah Agama dengan gembira, karena mereka telah dianggap layak menderita penghinaan oleh karena Nama Yesus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 5, 42, 'Dan setiap hari mereka melanjutkan pengajaran mereka di Bait Allah dan di rumah-rumah orang dan memberitakan Injil tentang Yesus yang adalah Mesias.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 6, 1, 'Pada masa itu, ketika jumlah murid makin bertambah, timbullah sungut-sungut di antara orang-orang Yahudi yang berbahasa Yunani terhadap orang-orang Ibrani, karena pembagian kepada janda-janda mereka diabaikan dalam pelayanan sehari-hari.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 6, 2, 'Berhubung dengan itu kedua belas rasul itu memanggil semua murid berkumpul dan berkata: "Kami tidak merasa puas, karena kami melalaikan Firman Allah untuk melayani meja.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 6, 3, 'Karena itu, saudara-saudara, pilihlah tujuh orang dari antaramu, yang terkenal baik, dan yang penuh Roh dan hikmat, supaya kami mengangkat mereka untuk tugas itu,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 6, 4, 'dan supaya kami sendiri dapat memusatkan pikiran dalam doa dan pelayanan Firman."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 6, 5, 'Usul itu diterima baik oleh seluruh jemaat, lalu mereka memilih Stefanus, seorang yang penuh iman dan Roh Kudus, dan Filipus, Prokhorus, Nikanor, Timon, Parmenas dan Nikolaus, seorang penganut agama Yahudi dari Antiokhia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 6, 6, 'Mereka itu dihadapkan kepada rasul-rasul, lalu rasul-rasul itupun berdoa dan meletakkan tangan di atas mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 6, 7, 'Firman Allah makin tersebar, dan jumlah murid di Yerusalem makin bertambah banyak; juga sejumlah besar imam menyerahkan diri dan percaya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 6, 8, 'Dan Stefanus, yang penuh dengan karunia dan kuasa, mengadakan mujizat-mujizat dan tanda-tanda di antara orang banyak.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 6, 9, 'Tetapi tampillah beberapa orang dari jemaat Yahudi yang disebut jemaat orang Libertini?anggota-anggota jemaat itu adalah orang-orang dari Kirene dan dari Aleksandria?bersama dengan beberapa orang Yahudi dari Kilikia dan dari Asia. Orang-orang itu bersoal jawab dengan Stefanus,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 6, 10, 'tetapi mereka tidak sanggup melawan hikmatnya dan Roh yang mendorong dia berbicara.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 6, 11, 'Lalu mereka menghasut beberapa orang untuk mengatakan: "Kami telah mendengar dia mengucapkan kata-kata hujat terhadap Musa dan Allah."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 6, 12, 'Dengan jalan demikian mereka mengadakan suatu gerakan di antara orang banyak serta tua-tua dan ahli-ahli Taurat; mereka menyergap Stefanus, menyeretnya dan membawanya ke hadapan Mahkamah Agama.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 6, 13, 'Lalu mereka memajukan saksi-saksi palsu yang berkata: "Orang ini terus-menerus mengucapkan perkataan yang menghina tempat kudus ini dan hukum Taurat,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 6, 14, 'sebab kami telah mendengar dia mengatakan, bahwa Yesus, orang Nazaret itu, akan merubuhkan tempat ini dan mengubah adat istiadat yang diwariskan oleh Musa kepada kita."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 6, 15, 'Semua orang yang duduk dalam sidang Mahkamah Agama itu menatap Stefanus, lalu mereka melihat muka Stefanus sama seperti muka seorang malaikat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 1, 'Kata Imam Besar: "Benarkah demikian?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 2, 'Jawab Stefanus: "Hai saudara-saudara dan bapa-bapa, dengarkanlah! Allah yang Mahamulia telah menampakkan diri-Nya kepada bapa leluhur kita Abraham, ketika ia masih di Mesopotamia, sebelum ia menetap di Haran,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 3, 'dan berfirman kepadanya: Keluarlah dari negerimu dan dari sanak saudaramu dan pergilah ke negeri yang akan Kutunjukkan kepadamu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 4, 'Maka keluarlah ia dari negeri orang Kasdim, lalu menetap di Haran. Dan setelah ayahnya meninggal, Allah menyuruh dia pindah dari situ ke tanah ini, tempat kamu diam sekarang;', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 5, 'dan di situ Allah tidak memberikan milik pusaka kepadanya, bahkan setapak tanahpun tidak, tetapi Ia berjanji akan memberikan tanah itu kepadanya menjadi kepunyaannya dan kepunyaan keturunannya, walaupun pada waktu itu ia tidak mempunyai anak.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 6, 'Beginilah firman Allah, yaitu bahwa keturunannya akan menjadi pendatang di negeri asing dan bahwa mereka akan diperbudak dan dianiaya empat ratus tahun lamanya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 7, 'Tetapi bangsa yang akan memperbudak mereka itu akan Kuhukum, firman Allah, dan sesudah itu mereka akan keluar dari situ dan beribadah kepada-Ku di tempat ini.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 8, 'Lalu Allah memberikan kepadanya perjanjian sunat; dan demikianlah Abraham memperanakkan Ishak, lalu menyunatkannya pada hari yang kedelapan; dan Ishak memperanakkan Yakub, dan Yakub memperanakkan kedua belas bapa leluhur kita.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 9, 'Karena iri hati, bapa-bapa leluhur kita menjual Yusuf ke tanah Mesir, tetapi Allah menyertai dia,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 10, 'dan melepaskannya dari segala penindasan serta menganugerahkan kepadanya kasih karunia dan hikmat, ketika ia menghadap Firaun, raja Mesir. Firaun mengangkatnya menjadi kuasa atas tanah Mesir dan atas seluruh istananya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 11, 'Maka datanglah bahaya kelaparan menimpa seluruh tanah Mesir dan tanah Kanaan serta penderitaan yang besar, sehingga nenek moyang kita tidak mendapat makanan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 12, 'Tetapi ketika Yakub mendengar, bahwa di tanah Mesir ada gandum, ia menyuruh nenek moyang kita ke sana. Itulah kunjungan mereka yang pertama;', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 13, 'pada kunjungan mereka yang kedua Yusuf memperkenalkan dirinya kepada saudara-saudaranya, lalu ketahuanlah asal-usul Yusuf kepada Firaun.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 14, 'Kemudian Yusuf menyuruh menjemput Yakub, ayahnya, dan semua sanak saudaranya, tujuh puluh lima jiwa banyaknya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 15, 'Lalu pergilah Yakub ke tanah Mesir. Di situ ia meninggal, ia dan nenek moyang kita;', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 16, 'mayat mereka dipindahkan ke Sikhem dan diletakkan di dalam kuburan yang telah dibeli Abraham dengan sejumlah uang perak dari anak-anak Hemor di Sikhem.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 17, 'Tetapi makin dekat genapnya janji yang diberikan Allah kepada Abraham, makin bertambah banyaklah bangsa itu di Mesir,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 18, 'sampai bangkit seorang raja lain memerintah tanah Mesir, seorang yang tidak mengenal Yusuf.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 19, 'Raja itu mempergunakan tipu daya terhadap bangsa kita dan menganiaya nenek moyang kita serta menyuruh membuang bayi mereka, supaya bangsa kita itu jangan berkembang.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 20, 'Pada waktu itulah Musa lahir dan ia elok di mata Allah. Tiga bulan lamanya ia diasuh di rumah ayahnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 21, 'Lalu ia dibuang, tetapi puteri Firaun memungutnya dan menyuruh mengasuhnya seperti anaknya sendiri.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 22, 'Dan Musa dididik dalam segala hikmat orang Mesir, dan ia berkuasa dalam perkataan dan perbuatannya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 23, 'Pada waktu ia berumur empat puluh tahun, timbullah keinginan dalam hatinya untuk mengunjungi saudara-saudaranya, yaitu orang-orang Israel.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 24, 'Ketika itu ia melihat seorang dianiaya oleh seorang Mesir, lalu ia menolong dan membela orang itu dengan membunuh orang Mesir itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 25, 'Pada sangkanya saudara-saudaranya akan mengerti, bahwa Allah memakai dia untuk menyelamatkan mereka, tetapi mereka tidak mengerti.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 26, 'Pada keesokan harinya ia muncul pula ketika dua orang Israel sedang berkelahi, lalu ia berusaha mendamaikan mereka, katanya: Saudara-saudara! Bukankah kamu ini bersaudara? Mengapakah kamu saling menganiaya?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 27, 'Tetapi orang yang berbuat salah kepada temannya itu menolak Musa dan berkata: Siapakah yang mengangkat engkau menjadi pemimpin dan hakim atas kami?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 28, 'Apakah engkau bermaksud membunuh aku, sama seperti kemarin engkau membunuh orang Mesir itu?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 29, 'Mendengar perkataan itu, larilah Musa dan hidup sebagai pendatang di tanah Midian. Di situ ia memperanakkan dua orang anak laki-laki.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 30, 'Dan sesudah empat puluh tahun tampaklah kepadanya seorang malaikat di padang gurun gunung Sinai di dalam nyala api yang keluar dari semak duri.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 31, 'Musa heran tentang penglihatan itu, dan ketika ia pergi ke situ untuk melihatnya dari dekat, datanglah suara Tuhan kepadanya:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 32, 'Akulah Allah nenek moyangmu, Allah Abraham, Ishak dan Yakub. Maka gemetarlah Musa, dan ia tidak berani lagi melihatnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 33, 'Lalu firman Allah kepadanya: Tanggalkanlah kasutmu dari kakimu, sebab tempat, di mana engkau berdiri itu, adalah tanah yang kudus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 34, 'Aku telah memperhatikan dengan sungguh kesengsaraan umat-Ku di tanah Mesir dan Aku telah mendengar keluh kesah mereka, dan Aku telah turun untuk melepaskan mereka; karena itu marilah, engkau akan Kuutus ke tanah Mesir.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 35, 'Musa ini, yang telah mereka tolak, dengan mengatakan: Siapakah yang mengangkat engkau menjadi pemimpin dan hakim? ?Musa ini juga telah diutus oleh Allah sebagai pemimpin dan penyelamat oleh malaikat, yang telah menampakkan diri kepadanya di semak duri itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 36, 'Dialah yang membawa mereka keluar dengan mengadakan mujizat-mujizat dan tanda-tanda di tanah Mesir, di Laut Merah dan di padang gurun, empat puluh tahun lamanya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 37, 'Musa ini pulalah yang berkata kepada orang Israel: Seorang nabi seperti aku ini akan dibangkitkan Allah bagimu dari antara saudara-saudaramu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 38, 'Musa inilah yang menjadi pengantara dalam sidang jemaah di padang gurun di antara malaikat yang berfirman kepadanya di gunung Sinai dan nenek moyang kita; dan dialah yang menerima firman-firman yang hidup untuk menyampaikannya kepada kamu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 39, 'Tetapi nenek moyang kita tidak mau taat kepadanya, malahan mereka menolaknya. Dalam hati mereka ingin kembali ke tanah Mesir.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 40, 'Kepada Harun mereka berkata: Buatlah untuk kami beberapa allah yang akan berjalan di depan kami, sebab Musa ini yang telah memimpin kami keluar dari tanah Mesir?kami tidak tahu apa yang telah terjadi dengan dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 41, 'Lalu pada waktu itu mereka membuat sebuah anak lembu dan mempersembahkan persembahan kepada berhala itu dan mereka bersukacita tentang apa yang dibuat sendiri oleh mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 42, 'Maka berpalinglah Allah dari mereka dan membiarkan mereka beribadah kepada bala tentara langit, seperti yang tertulis dalam kitab nabi-nabi: Apakah kamu mempersembahkan kepada-Ku korban sembelihan dan persembahan selama empat puluh tahun di padang gurun itu, hai kaum Israel?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 43, 'Tidak pernah, malahan kamu mengusung kemah Molokh dan bintang dewa Refan, patung-patung yang kamu buat itu untuk disembah. Maka Aku akan membawa kamu ke dalam pembuangan, sampai di seberang sana Babel.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 44, 'Kemah Kesaksian ada pada nenek moyang kita di padang gurun, seperti yang diperintahkan Allah kepada Musa untuk membuatnya menurut contoh yang telah dilihatnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 45, 'Kemah itu yang diterima nenek moyang kita dan yang dengan pimpinan Yosua dibawa masuk ke tanah ini, yaitu waktu tanah ini direbut dari bangsa-bangsa lain yang dihalau Allah dari depan nenek moyang kita; demikianlah sampai kepada zaman Daud.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 46, 'Daud telah mendapat kasih karunia di hadapan Allah dan ia memohon, supaya ia diperkenankan untuk mendirikan suatu tempat kediaman bagi Allah Yakub.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 47, 'Tetapi Salomolah yang mendirikan sebuah rumah untuk Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 48, 'Tetapi Yang Mahatinggi tidak diam di dalam apa yang dibuat oleh tangan manusia, seperti yang dikatakan oleh nabi:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 49, 'Langit adalah takhta-Ku, dan bumi adalah tumpuan kaki-Ku. Rumah apakah yang akan kamu dirikan bagi-Ku, demikian firman Tuhan, tempat apakah yang akan menjadi perhentian-Ku?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 50, 'Bukankah tangan-Ku sendiri yang membuat semuanya ini?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 51, 'Hai orang-orang yang keras kepala dan yang tidak bersunat hati dan telinga, kamu selalu menentang Roh Kudus, sama seperti nenek moyangmu, demikian juga kamu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 52, 'Siapakah dari nabi-nabi yang tidak dianiaya oleh nenek moyangmu? Bahkan mereka membunuh orang-orang yang lebih dahulu memberitakan tentang kedatangan Orang Benar, yang sekarang telah kamu khianati dan kamu bunuh.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 53, 'Kamu telah menerima hukum Taurat yang disampaikan oleh malaikat-malaikat, akan tetapi kamu tidak menurutinya."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 54, 'Ketika anggota-anggota Mahkamah Agama itu mendengar semuanya itu, sangat tertusuk hati mereka. Maka mereka menyambutnya dengan gertakan gigi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 55, 'Tetapi Stefanus, yang penuh dengan Roh Kudus, menatap ke langit, lalu melihat kemuliaan Allah dan Yesus berdiri di sebelah kanan Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 56, 'Lalu katanya: "Sungguh, aku melihat langit terbuka dan Anak Manusia berdiri di sebelah kanan Allah."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 57, 'Maka berteriak-teriaklah mereka dan sambil menutup telinga serentak menyerbu dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 58, 'Mereka menyeret dia ke luar kota, lalu melemparinya. Dan saksi-saksi meletakkan jubah mereka di depan kaki seorang muda yang bernama Saulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 59, 'Sedang mereka melemparinya Stefanus berdoa, katanya: "Ya Tuhan Yesus, terimalah rohku."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 7, 60, 'Sambil berlutut ia berseru dengan suara nyaring: "Tuhan, janganlah tanggungkan dosa ini kepada mereka!" Dan dengan perkataan itu meninggallah ia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 1, 'Saulus juga setuju, bahwa Stefanus mati dibunuh. (8-1b) Pada waktu itu mulailah penganiayaan yang hebat terhadap jemaat di Yerusalem. Mereka semua, kecuali rasul-rasul, tersebar ke seluruh daerah Yudea dan Samaria.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 2, 'Orang-orang saleh menguburkan mayat Stefanus serta meratapinya dengan sangat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 3, 'Tetapi Saulus berusaha membinasakan jemaat itu dan ia memasuki rumah demi rumah dan menyeret laki-laki dan perempuan ke luar dan menyerahkan mereka untuk dimasukkan ke dalam penjara.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 4, 'Mereka yang tersebar itu menjelajah seluruh negeri itu sambil memberitakan Injil.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 5, 'Dan Filipus pergi ke suatu kota di Samaria dan memberitakan Mesias kepada orang-orang di situ.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 6, 'Ketika orang banyak itu mendengar pemberitaan Filipus dan melihat tanda-tanda yang diadakannya, mereka semua dengan bulat hati menerima apa yang diberitakannya itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 7, 'Sebab dari banyak orang yang kerasukan roh jahat keluarlah roh-roh itu sambil berseru dengan suara keras, dan banyak juga orang lumpuh dan orang timpang yang disembuhkan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 8, 'Maka sangatlah besar sukacita dalam kota itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 9, 'Seorang yang bernama Simon telah sejak dahulu melakukan sihir di kota itu dan mentakjubkan rakyat Samaria, serta berlagak seolah-olah ia seorang yang sangat penting.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 10, 'Semua orang, besar kecil, mengikuti dia dan berkata: "Orang ini adalah kuasa Allah yang terkenal sebagai Kuasa Besar."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 11, 'Dan mereka mengikutinya, karena sudah lama ia mentakjubkan mereka oleh perbuatan sihirnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 12, 'Tetapi sekarang mereka percaya kepada Filipus yang memberitakan Injil tentang Kerajaan Allah dan tentang nama Yesus Kristus, dan mereka memberi diri mereka dibaptis, baik laki-laki maupun perempuan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 13, 'Simon sendiri juga menjadi percaya, dan sesudah dibaptis, ia senantiasa bersama-sama dengan Filipus, dan takjub ketika ia melihat tanda-tanda dan mujizat-mujizat besar yang terjadi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 14, 'Ketika rasul-rasul di Yerusalem mendengar, bahwa tanah Samaria telah menerima firman Allah, mereka mengutus Petrus dan Yohanes ke situ.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 15, 'Setibanya di situ kedua rasul itu berdoa, supaya orang-orang Samaria itu beroleh Roh Kudus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 16, 'Sebab Roh Kudus belum turun di atas seorangpun di antara mereka, karena mereka hanya dibaptis dalam nama Tuhan Yesus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 17, 'Kemudian keduanya menumpangkan tangan di atas mereka, lalu mereka menerima Roh Kudus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 18, 'Ketika Simon melihat, bahwa pemberian Roh Kudus terjadi oleh karena rasul-rasul itu menumpangkan tangannya, ia menawarkan uang kepada mereka,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 19, 'serta berkata: "Berikanlah juga kepadaku kuasa itu, supaya jika aku menumpangkan tanganku di atas seseorang, ia boleh menerima Roh Kudus."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 20, 'Tetapi Petrus berkata kepadanya: "Binasalah kiranya uangmu itu bersama dengan engkau, karena engkau menyangka, bahwa engkau dapat membeli karunia Allah dengan uang.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 21, 'Tidak ada bagian atau hakmu dalam perkara ini, sebab hatimu tidak lurus di hadapan Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 22, 'Jadi bertobatlah dari kejahatanmu ini dan berdoalah kepada Tuhan, supaya Ia mengampuni niat hatimu ini;', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 23, 'sebab kulihat, bahwa hatimu telah seperti empedu yang pahit dan terjerat dalam kejahatan."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 24, 'Jawab Simon: "Hendaklah kamu berdoa untuk aku kepada Tuhan, supaya kepadaku jangan kiranya terjadi segala apa yang telah kamu katakan itu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 25, 'Setelah keduanya bersaksi dan memberitakan firman Tuhan, kembalilah mereka ke Yerusalem dan dalam perjalanannya itu mereka memberitakan Injil dalam banyak kampung di Samaria.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 26, 'Kemudian berkatalah seorang malaikat Tuhan kepada Filipus, katanya: "Bangunlah dan berangkatlah ke sebelah selatan, menurut jalan yang turun dari Yerusalem ke Gaza." Jalan itu jalan yang sunyi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 27, 'Lalu berangkatlah Filipus. Adalah seorang Etiopia, seorang sida-sida, pembesar dan kepala perbendaharaan Sri Kandake, ratu negeri Etiopia, yang pergi ke Yerusalem untuk beribadah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 28, 'Sekarang orang itu sedang dalam perjalanan pulang dan duduk dalam keretanya sambil membaca kitab nabi Yesaya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 29, 'Lalu kata Roh kepada Filipus: "Pergilah ke situ dan dekatilah kereta itu!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 30, 'Filipus segera ke situ dan mendengar sida-sida itu sedang membaca kitab nabi Yesaya. Kata Filipus: "Mengertikah tuan apa yang tuan baca itu?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 31, 'Jawabnya: "Bagaimanakah aku dapat mengerti, kalau tidak ada yang membimbing aku?" Lalu ia meminta Filipus naik dan duduk di sampingnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 32, 'Nas yang dibacanya itu berbunyi seperti berikut: Seperti seekor domba Ia dibawa ke pembantaian; dan seperti anak domba yang kelu di depan orang yang menggunting bulunya, demikianlah Ia tidak membuka mulut-Nya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 33, 'Dalam kehinaan-Nya berlangsunglah hukuman-Nya; siapakah yang akan menceriterakan asal-usul-Nya? Sebab nyawa-Nya diambil dari bumi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 34, 'Maka kata sida-sida itu kepada Filipus: "Aku bertanya kepadamu, tentang siapakah nabi berkata demikian? Tentang dirinya sendiri atau tentang orang lain?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 35, 'Maka mulailah Filipus berbicara dan bertolak dari nas itu ia memberitakan Injil Yesus kepadanya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 36, 'Mereka melanjutkan perjalanan mereka, dan tiba di suatu tempat yang ada air. Lalu kata sida-sida itu: "Lihat, di situ ada air; apakah halangannya, jika aku dibaptis?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 37, '(Sahut Filipus: "Jika tuan percaya dengan segenap hati, boleh." Jawabnya: "Aku percaya, bahwa Yesus Kristus adalah Anak Allah.")', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 38, 'Lalu orang Etiopia itu menyuruh menghentikan kereta itu, dan keduanya turun ke dalam air, baik Filipus maupun sida-sida itu, dan Filipus membaptis dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 39, 'Dan setelah mereka keluar dari air, Roh Tuhan tiba-tiba melarikan Filipus dan sida-sida itu tidak melihatnya lagi. Ia meneruskan perjalanannya dengan sukacita.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 8, 40, 'Tetapi ternyata Filipus ada di Asdod. Ia berjalan melalui daerah itu dan memberitakan Injil di semua kota sampai ia tiba di Kaisarea.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 1, 'Sementara itu berkobar-kobar hati Saulus untuk mengancam dan membunuh murid-murid Tuhan. Ia menghadap Imam Besar,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 2, 'dan meminta surat kuasa dari padanya untuk dibawa kepada majelis-majelis Yahudi di Damsyik, supaya, jika ia menemukan laki-laki atau perempuan yang mengikuti Jalan Tuhan, ia menangkap mereka dan membawa mereka ke Yerusalem.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 3, 'Dalam perjalanannya ke Damsyik, ketika ia sudah dekat kota itu, tiba-tiba cahaya memancar dari langit mengelilingi dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 4, 'Ia rebah ke tanah dan kedengaranlah olehnya suatu suara yang berkata kepadanya: "Saulus, Saulus, mengapakah engkau menganiaya Aku?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 5, 'Jawab Saulus: "Siapakah Engkau, Tuhan?" Kata-Nya: "Akulah Yesus yang kauaniaya itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 6, 'Tetapi bangunlah dan pergilah ke dalam kota, di sana akan dikatakan kepadamu, apa yang harus kauperbuat."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 7, 'Maka termangu-mangulah teman-temannya seperjalanan, karena mereka memang mendengar suara itu, tetapi tidak melihat seorang jugapun.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 8, 'Saulus bangun dan berdiri, lalu membuka matanya, tetapi ia tidak dapat melihat apa-apa; mereka harus menuntun dia masuk ke Damsyik.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 9, 'Tiga hari lamanya ia tidak dapat melihat dan tiga hari lamanya ia tidak makan dan minum.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 10, 'Di Damsyik ada seorang murid Tuhan bernama Ananias. Firman Tuhan kepadanya dalam suatu penglihatan: "Ananias!" Jawabnya: "Ini aku, Tuhan!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 11, 'Firman Tuhan: "Mari, pergilah ke jalan yang bernama Jalan Lurus, dan carilah di rumah Yudas seorang dari Tarsus yang bernama Saulus. Ia sekarang berdoa,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 12, 'dan dalam suatu penglihatan ia melihat, bahwa seorang yang bernama Ananias masuk ke dalam dan menumpangkan tangannya ke atasnya, supaya ia dapat melihat lagi."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 13, 'Jawab Ananias: "Tuhan, dari banyak orang telah kudengar tentang orang itu, betapa banyaknya kejahatan yang dilakukannya terhadap orang-orang kudus-Mu di Yerusalem.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 14, 'Dan ia datang ke mari dengan kuasa penuh dari imam-imam kepala untuk menangkap semua orang yang memanggil nama-Mu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 15, 'Tetapi firman Tuhan kepadanya: "Pergilah, sebab orang ini adalah alat pilihan bagi-Ku untuk memberitakan nama-Ku kepada bangsa-bangsa lain serta raja-raja dan orang-orang Israel.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 16, 'Aku sendiri akan menunjukkan kepadanya, betapa banyak penderitaan yang harus ia tanggung oleh karena nama-Ku."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 17, 'Lalu pergilah Ananias ke situ dan masuk ke rumah itu. Ia menumpangkan tangannya ke atas Saulus, katanya: "Saulus, saudaraku, Tuhan Yesus, yang telah menampakkan diri kepadamu di jalan yang engkau lalui, telah menyuruh aku kepadamu, supaya engkau dapat melihat lagi dan penuh dengan Roh Kudus."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 18, 'Dan seketika itu juga seolah-olah selaput gugur dari matanya, sehingga ia dapat melihat lagi. Ia bangun lalu dibaptis.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 19, 'Dan setelah ia makan, pulihlah kekuatannya. (9-19b) Saulus tinggal beberapa hari bersama-sama dengan murid-murid di Damsyik.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 20, 'Ketika itu juga ia memberitakan Yesus di rumah-rumah ibadat, dan mengatakan bahwa Yesus adalah Anak Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 21, 'Semua orang yang mendengar hal itu heran dan berkata: "Bukankah dia ini yang di Yerusalem mau membinasakan barangsiapa yang memanggil nama Yesus ini? Dan bukankah ia datang ke sini dengan maksud untuk menangkap dan membawa mereka ke hadapan imam-imam kepala?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 22, 'Akan tetapi Saulus semakin besar pengaruhnya dan ia membingungkan orang-orang Yahudi yang tinggal di Damsyik, karena ia membuktikan, bahwa Yesus adalah Mesias.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 23, 'Beberapa hari kemudian orang Yahudi merundingkan suatu rencana untuk membunuh Saulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 24, 'Tetapi maksud jahat itu diketahui oleh Saulus. Siang malam orang-orang Yahudi mengawal semua pintu gerbang kota, supaya dapat membunuh dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 25, 'Sungguhpun demikian pada suatu malam murid-muridnya mengambilnya dan menurunkannya dari atas tembok kota dalam sebuah keranjang.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 26, 'Setibanya di Yerusalem Saulus mencoba menggabungkan diri kepada murid-murid, tetapi semuanya takut kepadanya, karena mereka tidak dapat percaya, bahwa ia juga seorang murid.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 27, 'Tetapi Barnabas menerima dia dan membawanya kepada rasul-rasul dan menceriterakan kepada mereka, bagaimana Saulus melihat Tuhan di tengah jalan dan bahwa Tuhan berbicara dengan dia dan bagaimana keberaniannya mengajar di Damsyik dalam nama Yesus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 28, 'Dan Saulus tetap bersama-sama dengan mereka di Yerusalem, dan dengan keberanian mengajar dalam nama Tuhan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 29, 'Ia juga berbicara dan bersoal jawab dengan orang-orang Yahudi yang berbahasa Yunani, tetapi mereka itu berusaha membunuh dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 30, 'Akan tetapi setelah hal itu diketahui oleh saudara-saudara anggota jemaat, mereka membawa dia ke Kaisarea dan dari situ membantu dia ke Tarsus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 31, 'Selama beberapa waktu jemaat di seluruh Yudea, Galilea dan Samaria berada dalam keadaan damai. Jemaat itu dibangun dan hidup dalam takut akan Tuhan. Jumlahnya makin bertambah besar oleh pertolongan dan penghiburan Roh Kudus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 32, 'Pada waktu itu Petrus berjalan keliling, mengadakan kunjungan ke mana-mana. Dalam perjalanan itu ia singgah juga kepada orang-orang kudus yang di Lida.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 33, 'Di situ didapatinya seorang bernama Eneas, yang telah delapan tahun terbaring di tempat tidur karena lumpuh.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 34, 'Kata Petrus kepadanya: "Eneas, Yesus Kristus menyembuhkan engkau; bangunlah dan bereskanlah tempat tidurmu!" Seketika itu juga bangunlah orang itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 35, 'Semua penduduk Lida dan Saron melihat dia, lalu mereka berbalik kepada Tuhan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 36, 'Di Yope ada seorang murid perempuan bernama Tabita?dalam bahasa Yunani Dorkas. Perempuan itu banyak sekali berbuat baik dan memberi sedekah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 37, 'Tetapi pada waktu itu ia sakit lalu meninggal. Dan setelah dimandikan, mayatnya dibaringkan di ruang atas.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 38, 'Lida dekat dengan Yope. Ketika murid-murid mendengar, bahwa Petrus ada di Lida, mereka menyuruh dua orang kepadanya dengan permintaan: "Segeralah datang ke tempat kami."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 39, 'Maka berkemaslah Petrus dan berangkat bersama-sama dengan mereka. Setelah sampai di sana, ia dibawa ke ruang atas dan semua janda datang berdiri dekatnya dan sambil menangis mereka menunjukkan kepadanya semua baju dan pakaian, yang dibuat Dorkas waktu ia masih hidup.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 40, 'Tetapi Petrus menyuruh mereka semua keluar, lalu ia berlutut dan berdoa. Kemudian ia berpaling ke mayat itu dan berkata: "Tabita, bangkitlah!" Lalu Tabita membuka matanya dan ketika melihat Petrus, ia bangun lalu duduk.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 41, 'Petrus memegang tangannya dan membantu dia berdiri. Kemudian ia memanggil orang-orang kudus beserta janda-janda, lalu menunjukkan kepada mereka, bahwa perempuan itu hidup.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 42, 'Peristiwa itu tersiar di seluruh Yope dan banyak orang menjadi percaya kepada Tuhan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 9, 43, 'Kemudian dari pada itu Petrus tinggal beberapa hari di Yope, di rumah seorang yang bernama Simon, seorang penyamak kulit.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 1, 'Di Kaisarea ada seorang yang bernama Kornelius, seorang perwira pasukan yang disebut pasukan Italia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 2, 'Ia saleh, ia serta seisi rumahnya takut akan Allah dan ia memberi banyak sedekah kepada umat Yahudi dan senantiasa berdoa kepada Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 3, 'Dalam suatu penglihatan, kira-kira jam tiga petang, jelas tampak kepadanya seorang malaikat Allah masuk ke rumahnya dan berkata kepadanya: "Kornelius!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 4, 'Ia menatap malaikat itu dan dengan takut ia berkata: "Ada apa, Tuhan?" Jawab malaikat itu: "Semua doamu dan sedekahmu telah naik ke hadirat Allah dan Allah mengingat engkau.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 5, 'Dan sekarang, suruhlah beberapa orang ke Yope untuk menjemput seorang yang bernama Simon dan yang disebut Petrus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 6, 'Ia menumpang di rumah seorang penyamak kulit yang bernama Simon, yang tinggal di tepi laut."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 7, 'Setelah malaikat yang berbicara kepadanya itu meninggalkan dia, dipanggilnya dua orang hambanya beserta seorang prajurit yang saleh dari orang-orang yang selalu bersama-sama dengan dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 8, 'Dan sesudah ia menjelaskan segala sesuatu kepada mereka, ia menyuruh mereka ke Yope.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 9, 'Keesokan harinya ketika ketiga orang itu berada dalam perjalanan dan sudah dekat kota Yope, kira-kira pukul dua belas tengah hari, naiklah Petrus ke atas rumah untuk berdoa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 10, 'Ia merasa lapar dan ingin makan, tetapi sementara makanan disediakan, tiba-tiba rohnya diliputi kuasa ilahi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 11, 'Tampak olehnya langit terbuka dan turunlah suatu benda berbentuk kain lebar yang bergantung pada keempat sudutnya, yang diturunkan ke tanah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 12, 'Di dalamnya terdapat pelbagai jenis binatang berkaki empat, binatang menjalar dan burung.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 13, 'Kedengaranlah olehnya suatu suara yang berkata: "Bangunlah, hai Petrus, sembelihlah dan makanlah!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 14, 'Tetapi Petrus menjawab: "Tidak, Tuhan, tidak, sebab aku belum pernah makan sesuatu yang haram dan yang tidak tahir."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 15, 'Kedengaran pula untuk kedua kalinya suara yang berkata kepadanya: "Apa yang dinyatakan halal oleh Allah, tidak boleh engkau nyatakan haram."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 16, 'Hal ini terjadi sampai tiga kali dan segera sesudah itu terangkatlah benda itu ke langit.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 17, 'Petrus bertanya-tanya di dalam hatinya, apa kiranya arti penglihatan yang telah dilihatnya itu. Sementara itu telah sampai di muka pintu orang-orang yang disuruh oleh Kornelius dan yang berusaha mengetahui di mana rumah Petrus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 18, 'Mereka memanggil seorang dan bertanya, apakah Simon yang disebut Petrus ada menumpang di rumah itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 19, 'Dan ketika Petrus sedang berpikir tentang penglihatan itu, berkatalah Roh: "Ada tiga orang mencari engkau.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 20, 'Bangunlah, turunlah ke bawah dan berangkatlah bersama-sama dengan mereka, jangan bimbang, sebab Aku yang menyuruh mereka ke mari."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 21, 'Lalu turunlah Petrus ke bawah dan berkata kepada orang-orang itu: "Akulah yang kamu cari; apakah maksud kedatangan kamu?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 22, 'Jawab mereka: "Kornelius, seorang perwira yang tulus hati dan takut akan Allah, dan yang terkenal baik di antara seluruh bangsa Yahudi, telah menerima penyataan Allah dengan perantaraan seorang malaikat kudus, supaya ia mengundang engkau ke rumahnya dan mendengar apa yang akan kaukatakan."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 23, 'Ia mempersilakan mereka untuk bermalam di situ. Keesokan harinya ia bangun dan berangkat bersama-sama dengan mereka, dan beberapa saudara dari Yope menyertai dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 24, 'Dan pada hari berikutnya sampailah mereka di Kaisarea. Kornelius sedang menantikan mereka dan ia telah memanggil sanak saudaranya dan sahabat-sahabatnya berkumpul.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 25, 'Ketika Petrus masuk, datanglah Kornelius menyambutnya, dan sambil tersungkur di depan kakinya, ia menyembah Petrus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 26, 'Tetapi Petrus menegakkan dia, katanya: "Bangunlah, aku hanya manusia saja."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 27, 'Dan sambil bercakap-cakap dengan dia, ia masuk dan mendapati banyak orang sedang berkumpul.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 28, 'Ia berkata kepada mereka: "Kamu tahu, betapa kerasnya larangan bagi seorang Yahudi untuk bergaul dengan orang-orang yang bukan Yahudi atau masuk ke rumah mereka. Tetapi Allah telah menunjukkan kepadaku, bahwa aku tidak boleh menyebut orang najis atau tidak tahir.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 29, 'Itulah sebabnya aku tidak berkeberatan ketika aku dipanggil, lalu datang ke mari. Sekarang aku ingin tahu, apa sebabnya kamu memanggil aku."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 30, 'Jawab Kornelius: "Empat hari yang lalu kira-kira pada waktu yang sama seperti sekarang, yaitu jam tiga petang, aku sedang berdoa di rumah. Tiba-tiba ada seorang berdiri di depanku, pakaiannya berkilau-kilauan', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 31, 'dan ia berkata: Kornelius, doamu telah didengarkan Allah dan sedekahmu telah diingatkan di hadapan-Nya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 32, 'Suruhlah orang ke Yope untuk menjemput Simon yang disebut Petrus; ia sedang menumpang di rumah Simon, seorang penyamak kulit, yang tinggal di tepi laut.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 33, 'Karena itu segera kusuruh orang kepadamu, dan dengan senang hati engkau telah datang. Sekarang kami semua sudah hadir di sini di hadapan Allah untuk mendengarkan apa yang ditugaskan Allah kepadamu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 34, 'Lalu mulailah Petrus berbicara, katanya: "Sesungguhnya aku telah mengerti, bahwa Allah tidak membedakan orang.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 35, 'Setiap orang dari bangsa manapun yang takut akan Dia dan yang mengamalkan kebenaran berkenan kepada-Nya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 36, 'Itulah firman yang Ia suruh sampaikan kepada orang-orang Israel, yaitu firman yang memberitakan damai sejahtera oleh Yesus Kristus, yang adalah Tuhan dari semua orang.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 37, 'Kamu tahu tentang segala sesuatu yang terjadi di seluruh tanah Yudea, mulai dari Galilea, sesudah baptisan yang diberitakan oleh Yohanes,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 38, 'yaitu tentang Yesus dari Nazaret: bagaimana Allah mengurapi Dia dengan Roh Kudus dan kuat kuasa, Dia, yang berjalan berkeliling sambil berbuat baik dan menyembuhkan semua orang yang dikuasai Iblis, sebab Allah menyertai Dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 39, 'Dan kami adalah saksi dari segala sesuatu yang diperbuat-Nya di tanah Yudea maupun di Yerusalem; dan mereka telah membunuh Dia dan menggantung Dia pada kayu salib.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 40, 'Yesus itu telah dibangkitkan Allah pada hari yang ketiga, dan Allah berkenan, bahwa Ia menampakkan diri,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 41, 'bukan kepada seluruh bangsa, tetapi kepada saksi-saksi, yang sebelumnya telah ditunjuk oleh Allah, yaitu kepada kami yang telah makan dan minum bersama-sama dengan Dia, setelah Ia bangkit dari antara orang mati.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 42, 'Dan Ia telah menugaskan kami memberitakan kepada seluruh bangsa dan bersaksi, bahwa Dialah yang ditentukan Allah menjadi Hakim atas orang-orang hidup dan orang-orang mati.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 43, 'Tentang Dialah semua nabi bersaksi, bahwa barangsiapa percaya kepada-Nya, ia akan mendapat pengampunan dosa oleh karena nama-Nya."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 44, 'Ketika Petrus sedang berkata demikian, turunlah Roh Kudus ke atas semua orang yang mendengarkan pemberitaan itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 45, 'Dan semua orang percaya dari golongan bersunat yang menyertai Petrus, tercengang-cengang, karena melihat, bahwa karunia Roh Kudus dicurahkan ke atas bangsa-bangsa lain juga,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 46, 'sebab mereka mendengar orang-orang itu berkata-kata dalam bahasa roh dan memuliakan Allah. Lalu kata Petrus:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 47, '"Bolehkah orang mencegah untuk membaptis orang-orang ini dengan air, sedangkan mereka telah menerima Roh Kudus sama seperti kita?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 10, 48, 'Lalu ia menyuruh mereka dibaptis dalam nama Yesus Kristus. Kemudian mereka meminta Petrus, supaya ia tinggal beberapa hari lagi bersama-sama dengan mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 1, 'Rasul-rasul dan saudara-saudara di Yudea mendengar, bahwa bangsa-bangsa lain juga menerima firman Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 2, 'Ketika Petrus tiba di Yerusalem, orang-orang dari golongan yang bersunat berselisih pendapat dengan dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 3, 'Kata mereka: "Engkau telah masuk ke rumah orang-orang yang tidak bersunat dan makan bersama-sama dengan mereka."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 4, 'Tetapi Petrus menjelaskan segala sesuatu berturut-turut, katanya:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 5, '"Aku sedang berdoa di kota Yope, tiba-tiba rohku diliputi kuasa ilahi dan aku melihat suatu penglihatan: suatu benda berbentuk kain lebar yang bergantung pada keempat sudutnya diturunkan dari langit sampai di depanku.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 6, 'Aku menatapnya dan di dalamnya aku lihat segala jenis binatang berkaki empat dan binatang liar dan binatang menjalar dan burung-burung.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 7, 'Lalu aku mendengar suara berkata kepadaku: Bangunlah, hai Petrus, sembelihlah dan makanlah!', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 8, 'Tetapi aku berkata: Tidak, Tuhan, tidak, sebab belum pernah sesuatu yang haram dan yang tidak tahir masuk ke dalam mulutku.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 9, 'Akan tetapi untuk kedua kalinya suara dari sorga berkata kepadaku: Apa yang dinyatakan halal oleh Allah, tidak boleh engkau nyatakan haram!', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 10, 'Hal itu terjadi sampai tiga kali, lalu semuanya ditarik kembali ke langit.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 11, 'Dan seketika itu juga tiga orang berdiri di depan rumah, di mana kami menumpang; mereka diutus kepadaku dari Kaisarea.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 12, 'Lalu kata Roh kepadaku: Pergi bersama mereka dengan tidak bimbang! Dan keenam saudara ini menyertai aku. Kami masuk ke dalam rumah orang itu,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 13, 'dan ia menceriterakan kepada kami, bagaimana ia melihat seorang malaikat berdiri di dalam rumahnya dan berkata kepadanya: Suruhlah orang ke Yope untuk menjemput Simon yang disebut Petrus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 14, 'Ia akan menyampaikan suatu berita kepada kamu, yang akan mendatangkan keselamatan bagimu dan bagi seluruh isi rumahmu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 15, 'Dan ketika aku mulai berbicara, turunlah Roh Kudus ke atas mereka, sama seperti dahulu ke atas kita.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 16, 'Maka teringatlah aku akan perkataan Tuhan: Yohanes membaptis dengan air, tetapi kamu akan dibaptis dengan Roh Kudus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 17, 'Jadi jika Allah memberikan karunia-Nya kepada mereka sama seperti kepada kita pada waktu kita mulai percaya kepada Yesus Kristus, bagaimanakah mungkin aku mencegah Dia?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 18, 'Ketika mereka mendengar hal itu, mereka menjadi tenang, lalu memuliakan Allah, katanya: "Jadi kepada bangsa-bangsa lain juga Allah mengaruniakan pertobatan yang memimpin kepada hidup."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 19, 'Sementara itu banyak saudara-saudara telah tersebar karena penganiayaan yang timbul sesudah Stefanus dihukum mati. Mereka tersebar sampai ke Fenisia, Siprus dan Antiokhia; namun mereka memberitakan Injil kepada orang Yahudi saja.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 20, 'Akan tetapi di antara mereka ada beberapa orang Siprus dan orang Kirene yang tiba di Antiokhia dan berkata-kata juga kepada orang-orang Yunani dan memberitakan Injil, bahwa Yesus adalah Tuhan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 21, 'Dan tangan Tuhan menyertai mereka dan sejumlah besar orang menjadi percaya dan berbalik kepada Tuhan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 22, 'Maka sampailah kabar tentang mereka itu kepada jemaat di Yerusalem, lalu jemaat itu mengutus Barnabas ke Antiokhia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 23, 'Setelah Barnabas datang dan melihat kasih karunia Allah, bersukacitalah ia. Ia menasihati mereka, supaya mereka semua tetap setia kepada Tuhan,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 24, 'karena Barnabas adalah orang baik, penuh dengan Roh Kudus dan iman. Sejumlah orang dibawa kepada Tuhan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 25, 'Lalu pergilah Barnabas ke Tarsus untuk mencari Saulus; dan setelah bertemu dengan dia, ia membawanya ke Antiokhia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 26, 'Mereka tinggal bersama-sama dengan jemaat itu satu tahun lamanya, sambil mengajar banyak orang. Di Antiokhialah murid-murid itu untuk pertama kalinya disebut Kristen.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 27, 'Pada waktu itu datanglah beberapa nabi dari Yerusalem ke Antiokhia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 28, 'Seorang dari mereka yang bernama Agabus bangkit dan oleh kuasa Roh ia mengatakan, bahwa seluruh dunia akan ditimpa bahaya kelaparan yang besar. Hal itu terjadi juga pada zaman Klaudius.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 29, 'Lalu murid-murid memutuskan untuk mengumpulkan suatu sumbangan, sesuai dengan kemampuan mereka masing-masing dan mengirimkannya kepada saudara-saudara yang diam di Yudea.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 11, 30, 'Hal itu mereka lakukan juga dan mereka mengirimkannya kepada penatua-penatua dengan perantaraan Barnabas dan Saulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 1, 'Kira-kira pada waktu itu raja Herodes mulai bertindak dengan keras terhadap beberapa orang dari jemaat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 2, 'Ia menyuruh membunuh Yakobus, saudara Yohanes, dengan pedang.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 3, 'Ketika ia melihat, bahwa hal itu menyenangkan hati orang Yahudi, ia melanjutkan perbuatannya itu dan menyuruh menahan Petrus. Waktu itu hari raya Roti Tidak Beragi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 4, 'Setelah Petrus ditangkap, Herodes menyuruh memenjarakannya di bawah penjagaan empat regu, masing-masing terdiri dari empat prajurit. Maksudnya ialah, supaya sehabis Paskah ia menghadapkannya ke depan orang banyak.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 5, 'Demikianlah Petrus ditahan di dalam penjara. Tetapi jemaat dengan tekun mendoakannya kepada Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 6, 'Pada malam sebelum Herodes hendak menghadapkannya kepada orang banyak, Petrus tidur di antara dua orang prajurit, terbelenggu dengan dua rantai. Selain itu prajurit-prajurit pengawal sedang berkawal di muka pintu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 7, 'Tiba-tiba berdirilah seorang malaikat Tuhan dekat Petrus dan cahaya bersinar dalam ruang itu. Malaikat itu menepuk Petrus untuk membangunkannya, katanya: "Bangunlah segera!" Maka gugurlah rantai itu dari tangan Petrus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 8, 'Lalu kata malaikat itu kepadanya: "Ikatlah pinggangmu dan kenakanlah sepatumu!" Iapun berbuat demikian. Lalu malaikat itu berkata kepadanya: "Kenakanlah jubahmu dan ikutlah aku!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 9, 'Lalu ia mengikuti malaikat itu ke luar dan ia tidak tahu, bahwa apa yang dilakukan malaikat itu sungguh-sungguh terjadi, sangkanya ia melihat suatu penglihatan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 10, 'Setelah mereka melalui tempat kawal pertama dan tempat kawal kedua, sampailah mereka ke pintu gerbang besi yang menuju ke kota. Pintu itu terbuka dengan sendirinya bagi mereka. Sesudah tiba di luar, mereka berjalan sampai ke ujung jalan, dan tiba-tiba malaikat itu meninggalkan dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 11, 'Dan setelah sadar akan dirinya, Petrus berkata: "Sekarang tahulah aku benar-benar bahwa Tuhan telah menyuruh malaikat-Nya dan menyelamatkan aku dari tangan Herodes dan dari segala sesuatu yang diharapkan orang Yahudi."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 12, 'Dan setelah berpikir sebentar, pergilah ia ke rumah Maria, ibu Yohanes yang disebut juga Markus. Di situ banyak orang berkumpul dan berdoa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 13, 'Dan ketika ia mengetuk pintu gerbang, datanglah seorang hamba perempuan bernama Rode untuk mengetahui siapa yang mengetuk itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 14, 'Ia terus mengenal suara Petrus, tetapi karena girangnya ia tidak membuka pintu gerbang itu dan segera masuk ke dalam untuk memberitahukan, bahwa Petrus ada di depan pintu gerbang.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 15, 'Kata mereka kepada perempuan itu: "Engkau mengigau." Akan tetapi ia tetap mengatakan, bahwa benar-benar demikian. Kata mereka: "Itu malaikatnya."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 16, 'Tetapi Petrus terus-menerus mengetuk dan ketika mereka membuka pintu dan melihat dia, mereka tercengang-cengang.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 17, 'Tetapi Petrus memberi isyarat dengan tangannya, supaya mereka diam, lalu ia menceriterakan bagaimana Tuhan menuntunnya ke luar dari penjara. Katanya: "Beritahukanlah hal ini kepada Yakobus dan saudara-saudara kita." Lalu ia keluar dan pergi ke tempat lain.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 18, 'Pada keesokan harinya gemparlah prajurit-prajurit itu. Mereka bertanya-tanya apakah yang telah terjadi dengan Petrus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 19, 'Herodes menyuruh mencari Petrus, tetapi ia tidak ditemukan. Lalu Herodes menyuruh memeriksa pengawal-pengawal itu dan membunuh mereka. Kemudian ia berangkat dari Yudea ke Kaisarea dan tinggal di situ.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 20, 'Herodes sangat marah terhadap orang Tirus dan Sidon. Atas persetujuan bersama mereka pergi menghadap dia. Mereka berhasil membujuk Blastus, pegawai istana raja, ke pihak mereka, lalu mereka memohonkan perdamaian, karena negeri mereka beroleh bahan makanan dari wilayah raja.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 21, 'Dan pada suatu hari yang ditentukan, Herodes mengenakan pakaian kerajaan, lalu duduk di atas takhta dan berpidato kepada mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 22, 'Dan rakyatnya bersorak membalasnya: "Ini suara allah dan bukan suara manusia!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 23, 'Dan seketika itu juga ia ditampar malaikat Tuhan karena ia tidak memberi hormat kepada Allah; ia mati dimakan cacing-cacing.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 24, 'Maka firman Tuhan makin tersebar dan makin banyak didengar orang.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 12, 25, 'Barnabas dan Saulus kembali dari Yerusalem, setelah mereka menyelesaikan tugas pelayanan mereka. Mereka membawa Yohanes, yang disebut juga Markus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 1, 'Pada waktu itu dalam jemaat di Antiokhia ada beberapa nabi dan pengajar, yaitu: Barnabas dan Simeon yang disebut Niger, dan Lukius orang Kirene, dan Menahem yang diasuh bersama dengan raja wilayah Herodes, dan Saulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 2, 'Pada suatu hari ketika mereka beribadah kepada Tuhan dan berpuasa, berkatalah Roh Kudus: "Khususkanlah Barnabas dan Saulus bagi-Ku untuk tugas yang telah Kutentukan bagi mereka."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 3, 'Maka berpuasa dan berdoalah mereka, dan setelah meletakkan tangan ke atas kedua orang itu, mereka membiarkan keduanya pergi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 4, 'Oleh karena disuruh Roh Kudus, Barnabas dan Saulus berangkat ke Seleukia, dan dari situ mereka berlayar ke Siprus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 5, 'Setiba di Salamis mereka memberitakan firman Allah di dalam rumah-rumah ibadat orang Yahudi. Dan Yohanes menyertai mereka sebagai pembantu mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 6, 'Mereka mengelilingi seluruh pulau itu sampai ke Pafos. Di situ mereka bertemu dengan seorang Yahudi bernama Baryesus. Ia seorang tukang sihir dan nabi palsu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 7, 'Ia adalah kawan gubernur pulau itu, Sergius Paulus, yang adalah orang cerdas. Gubernur itu memanggil Barnabas dan Saulus, karena ia ingin mendengar firman Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 8, 'Tetapi Elimas?demikianlah namanya dalam bahasa Yunani?,tukang sihir itu, menghalang-halangi mereka dan berusaha membelokkan gubernur itu dari imannya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 9, 'Tetapi Saulus, juga disebut Paulus, yang penuh dengan Roh Kudus, menatap dia,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 10, 'dan berkata: "Hai anak Iblis, engkau penuh dengan rupa-rupa tipu muslihat dan kejahatan, engkau musuh segala kebenaran, tidakkah engkau akan berhenti membelokkan Jalan Tuhan yang lurus itu?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 11, 'Sekarang, lihatlah, tangan Tuhan datang menimpa engkau, dan engkau menjadi buta, beberapa hari lamanya engkau tidak dapat melihat matahari." Dan seketika itu juga orang itu merasa diliputi kabut dan gelap, dan sambil meraba-raba ia harus mencari orang untuk menuntun dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 12, 'Melihat apa yang telah terjadi itu, percayalah gubernur itu; ia takjub oleh ajaran Tuhan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 13, 'Lalu Paulus dan kawan-kawannya meninggalkan Pafos dan berlayar ke Perga di Pamfilia; tetapi Yohanes meninggalkan mereka lalu kembali ke Yerusalem.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 14, 'Dari Perga mereka melanjutkan perjalanan mereka, lalu tiba di Antiokhia di Pisidia. Pada hari Sabat mereka pergi ke rumah ibadat, lalu duduk di situ.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 15, 'Setelah selesai pembacaan dari hukum Taurat dan kitab nabi-nabi, pejabat-pejabat rumah ibadat menyuruh bertanya kepada mereka: "Saudara-saudara, jikalau saudara-saudara ada pesan untuk membangun dan menghibur umat ini, silakanlah!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 16, 'Maka bangkitlah Paulus. Ia memberi isyarat dengan tangannya, lalu berkata: "Hai orang-orang Israel dan kamu yang takut akan Allah, dengarkanlah!', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 17, 'Allah umat Israel ini telah memilih nenek moyang kita dan membuat umat itu menjadi besar, ketika mereka tinggal di Mesir sebagai orang asing. Dengan tangan-Nya yang luhur Ia telah memimpin mereka keluar dari negeri itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 18, 'Empat puluh tahun lamanya Ia sabar terhadap tingkah laku mereka di padang gurun.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 19, 'Dan setelah membinasakan tujuh bangsa di tanah Kanaan, Ia membagi-bagikan tanah itu kepada mereka untuk menjadi warisan mereka', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 20, 'selama kira-kira empat ratus lima puluh tahun. Sesudah itu Ia memberikan mereka hakim-hakim sampai pada zaman nabi Samuel.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 21, 'Kemudian mereka meminta seorang raja dan Allah memberikan kepada mereka Saul bin Kish dari suku Benyamin, empat puluh tahun lamanya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 22, 'Setelah Saul disingkirkan, Allah mengangkat Daud menjadi raja mereka. Tentang Daud Allah telah menyatakan: Aku telah mendapat Daud bin Isai, seorang yang berkenan di hati-Ku dan yang melakukan segala kehendak-Ku.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 23, 'Dan dari keturunannyalah, sesuai dengan yang telah dijanjikan-Nya, Allah telah membangkitkan Juruselamat bagi orang Israel, yaitu Yesus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 24, 'Menjelang kedatangan-Nya Yohanes telah menyerukan kepada seluruh bangsa Israel supaya mereka bertobat dan memberi diri dibaptis.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 25, 'Dan ketika Yohanes hampir selesai menunaikan tugasnya, ia berkata: Aku bukanlah Dia yang kamu sangka, tetapi Ia akan datang kemudian dari padaku. Membuka kasut dari kaki-Nyapun aku tidak layak.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 26, 'Hai saudara-saudaraku, baik yang termasuk keturunan Abraham, maupun yang takut akan Allah, kabar keselamatan itu sudah disampaikan kepada kita.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 27, 'Sebab penduduk Yerusalem dan pemimpin-pemimpinnya tidak mengakui Yesus. Dengan menjatuhkan hukuman mati atas Dia, mereka menggenapi perkataan nabi-nabi yang dibacakan setiap hari Sabat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 28, 'Dan meskipun mereka tidak menemukan sesuatu yang dapat menjadi alasan untuk hukuman mati itu, namun mereka telah meminta kepada Pilatus supaya Ia dibunuh.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 29, 'Dan setelah mereka menggenapi segala sesuatu yang ada tertulis tentang Dia, mereka menurunkan Dia dari kayu salib, lalu membaringkan-Nya di dalam kubur.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 30, 'Tetapi Allah membangkitkan Dia dari antara orang mati.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 31, 'Dan selama beberapa waktu Ia menampakkan diri kepada mereka yang mengikuti Dia dari Galilea ke Yerusalem. Mereka itulah yang sekarang menjadi saksi-Nya bagi umat ini.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 32, 'Dan kami sekarang memberitakan kabar kesukaan kepada kamu, yaitu bahwa janji yang diberikan kepada nenek moyang kita,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 33, 'telah digenapi Allah kepada kita, keturunan mereka, dengan membangkitkan Yesus, seperti yang ada tertulis dalam mazmur kedua: Anak-Ku Engkau! Aku telah memperanakkan Engkau pada hari ini.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 34, 'Allah telah membangkitkan Dia dari antara orang mati dan Ia tidak akan diserahkan kembali kepada kebinasaan. Hal itu dinyatakan oleh Tuhan dalam firman ini: Aku akan menggenapi kepadamu janji-janji yang kudus yang dapat dipercayai, yang telah Kuberikan kepada Daud.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 35, 'Sebab itu Ia mengatakan dalam mazmur yang lain: Engkau tidak akan membiarkan Orang Kudus-Mu melihat kebinasaan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 36, 'Sebab Daud melakukan kehendak Allah pada zamannya, lalu ia mangkat dan dibaringkan di samping nenek moyangnya, dan ia memang diserahkan kepada kebinasaan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 37, 'Tetapi Yesus, yang dibangkitkan Allah, tidak demikian.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 38, 'Jadi ketahuilah, hai saudara-saudara, oleh karena Dialah maka diberitakan kepada kamu pengampunan dosa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 39, 'Dan di dalam Dialah setiap orang yang percaya memperoleh pembebasan dari segala dosa, yang tidak dapat kamu peroleh dari hukum Musa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 40, 'Karena itu, waspadalah, supaya jangan berlaku atas kamu apa yang telah dikatakan dalam kitab nabi-nabi:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 41, 'Ingatlah, hai kamu penghina-penghina, tercenganglah dan lenyaplah, sebab Aku melakukan suatu pekerjaan dalam zamanmu, suatu pekerjaan, yang tidak akan kamu percayai, jika diceriterakan kepadamu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 42, 'Ketika Paulus dan Barnabas keluar, mereka diminta untuk berbicara tentang pokok itu pula pada hari Sabat berikutnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 43, 'Setelah selesai ibadah, banyak orang Yahudi dan penganut-penganut agama Yahudi yang takut akan Allah, mengikuti Paulus dan Barnabas; kedua rasul itu mengajar mereka dan menasihati supaya mereka tetap hidup di dalam kasih karunia Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 44, 'Pada hari Sabat berikutnya datanglah hampir seluruh kota itu berkumpul untuk mendengar firman Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 45, 'Akan tetapi, ketika orang Yahudi melihat orang banyak itu, penuhlah mereka dengan iri hati dan sambil menghujat, mereka membantah apa yang dikatakan oleh Paulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 46, 'Tetapi dengan berani Paulus dan Barnabas berkata: "Memang kepada kamulah firman Allah harus diberitakan lebih dahulu, tetapi kamu menolaknya dan menganggap dirimu tidak layak untuk beroleh hidup yang kekal. Karena itu kami berpaling kepada bangsa-bangsa lain.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 47, 'Sebab inilah yang diperintahkan kepada kami: Aku telah menentukan engkau menjadi terang bagi bangsa-bangsa yang tidak mengenal Allah, supaya engkau membawa keselamatan sampai ke ujung bumi."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 48, 'Mendengar itu bergembiralah semua orang yang tidak mengenal Allah dan mereka memuliakan firman Tuhan; dan semua orang yang ditentukan Allah untuk hidup yang kekal, menjadi percaya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 49, 'Lalu firman Tuhan disiarkan di seluruh daerah itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 50, 'Orang-orang Yahudi menghasut perempuan-perempuan terkemuka yang takut akan Allah, dan pembesar-pembesar di kota itu, dan mereka menimbulkan penganiayaan atas Paulus dan Barnabas dan mengusir mereka dari daerah itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 51, 'Akan tetapi Paulus dan Barnabas mengebaskan debu kaki mereka sebagai peringatan bagi orang-orang itu, lalu pergi ke Ikonium.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 13, 52, 'Dan murid-murid di Antiokhia penuh dengan sukacita dan dengan Roh Kudus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 1, 'Di Ikoniumpun kedua rasul itu masuk ke rumah ibadat orang Yahudi, lalu mengajar sedemikian rupa, sehingga sejumlah besar orang Yahudi dan orang Yunani menjadi percaya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 2, 'Tetapi orang-orang Yahudi, yang menolak pemberitaan mereka, memanaskan hati orang-orang yang tidak mengenal Allah dan membuat mereka gusar terhadap saudara-saudara itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 3, 'Paulus dan Barnabas tinggal beberapa waktu lamanya di situ. Mereka mengajar dengan berani, karena mereka percaya kepada Tuhan. Dan Tuhan menguatkan berita tentang kasih karunia-Nya dengan mengaruniakan kepada mereka kuasa untuk mengadakan tanda-tanda dan mujizat-mujizat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 4, 'Tetapi orang banyak di kota itu terbelah menjadi dua: ada yang memihak kepada orang Yahudi, ada pula yang memihak kepada kedua rasul itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 5, 'Maka mulailah orang-orang yang tidak mengenal Allah dan orang-orang Yahudi bersama-sama dengan pemimpin-pemimpin mereka menimbulkan suatu gerakan untuk menyiksa dan melempari kedua rasul itu dengan batu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 6, 'Setelah rasul-rasul itu mengetahuinya, menyingkirlah mereka ke kota-kota di Likaonia, yaitu Listra dan Derbe dan daerah sekitarnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 7, 'Di situ mereka memberitakan Injil.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 8, 'Di Listra ada seorang yang duduk saja, karena lemah kakinya dan lumpuh sejak ia dilahirkan dan belum pernah dapat berjalan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 9, 'Ia duduk mendengarkan, ketika Paulus berbicara. Dan Paulus menatap dia dan melihat, bahwa ia beriman dan dapat disembuhkan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 10, 'Lalu kata Paulus dengan suara nyaring: "Berdirilah tegak di atas kakimu!" Dan orang itu melonjak berdiri, lalu berjalan kian ke mari.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 11, 'Ketika orang banyak melihat apa yang telah diperbuat Paulus, mereka itu berseru dalam bahasa Likaonia: "Dewa-dewa telah turun ke tengah-tengah kita dalam rupa manusia."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 12, 'Barnabas mereka sebut Zeus dan Paulus mereka sebut Hermes, karena ia yang berbicara.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 13, 'Maka datanglah imam dewa Zeus, yang kuilnya terletak di luar kota, membawa lembu-lembu jantan dan karangan-karangan bunga ke pintu gerbang kota untuk mempersembahkan korban bersama-sama dengan orang banyak kepada rasul-rasul itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 14, 'Mendengar itu Barnabas dan Paulus mengoyakkan pakaian mereka, lalu terjun ke tengah-tengah orang banyak itu sambil berseru:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 15, '"Hai kamu sekalian, mengapa kamu berbuat demikian? Kami ini adalah manusia biasa sama seperti kamu. Kami ada di sini untuk memberitakan Injil kepada kamu, supaya kamu meninggalkan perbuatan sia-sia ini dan berbalik kepada Allah yang hidup, yang telah menjadikan langit dan bumi, laut dan segala isinya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 16, 'Dalam zaman yang lampau Allah membiarkan semua bangsa menuruti jalannya masing-masing,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 17, 'namun Ia bukan tidak menyatakan diri-Nya dengan berbagai-bagai kebajikan, yaitu dengan menurunkan hujan dari langit dan dengan memberikan musim-musim subur bagi kamu. Ia memuaskan hatimu dengan makanan dan kegembiraan."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 18, 'Walaupun rasul-rasul itu berkata demikian, namun hampir-hampir tidak dapat mereka mencegah orang banyak mempersembahkan korban kepada mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 19, 'Tetapi datanglah orang-orang Yahudi dari Antiokhia dan Ikonium dan mereka membujuk orang banyak itu memihak mereka. Lalu mereka melempari Paulus dengan batu dan menyeretnya ke luar kota, karena mereka menyangka, bahwa ia telah mati.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 20, 'Akan tetapi ketika murid-murid itu berdiri mengelilingi dia, bangkitlah ia lalu masuk ke dalam kota. Keesokan harinya berangkatlah ia bersama-sama dengan Barnabas ke Derbe.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 21, 'Paulus dan Barnabas memberitakan Injil di kota itu dan memperoleh banyak murid. Lalu kembalilah mereka ke Listra, Ikonium dan Antiokhia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 22, 'Di tempat itu mereka menguatkan hati murid-murid itu dan menasihati mereka supaya mereka bertekun di dalam iman, dan mengatakan, bahwa untuk masuk ke dalam Kerajaan Allah kita harus mengalami banyak sengsara.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 23, 'Di tiap-tiap jemaat rasul-rasul itu menetapkan penatua-penatua bagi jemaat itu dan setelah berdoa dan berpuasa, mereka menyerahkan penatua-penatua itu kepada Tuhan, yang adalah sumber kepercayaan mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 24, 'Mereka menjelajah seluruh Pisidia dan tiba di Pamfilia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 25, 'Di situ mereka memberitakan firman di Perga, lalu pergi ke Atalia, di pantai.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 26, 'Dari situ berlayarlah mereka ke Antiokhia; di tempat itulah mereka dahulu diserahkan kepada kasih karunia Allah untuk memulai pekerjaan, yang telah mereka selesaikan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 27, 'Setibanya di situ mereka memanggil jemaat berkumpul, lalu mereka menceriterakan segala sesuatu yang Allah lakukan dengan perantaraan mereka, dan bahwa Ia telah membuka pintu bagi bangsa-bangsa lain kepada iman.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 14, 28, 'Di situ mereka lama tinggal bersama-sama dengan murid-murid itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 1, 'Beberapa orang datang dari Yudea ke Antiokhia dan mengajarkan kepada saudara-saudara di situ: "Jikalau kamu tidak disunat menurut adat istiadat yang diwariskan oleh Musa, kamu tidak dapat diselamatkan."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 2, 'Tetapi Paulus dan Barnabas dengan keras melawan dan membantah pendapat mereka itu. Akhirnya ditetapkan, supaya Paulus dan Barnabas serta beberapa orang lain dari jemaat itu pergi kepada rasul-rasul dan penatua-penatua di Yerusalem untuk membicarakan soal itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 3, 'Mereka diantarkan oleh jemaat sampai ke luar kota, lalu mereka berjalan melalui Fenisia dan Samaria, dan di tempat-tempat itu mereka menceriterakan tentang pertobatan orang-orang yang tidak mengenal Allah. Hal itu sangat menggembirakan hati saudara-saudara di situ.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 4, 'Setibanya di Yerusalem mereka disambut oleh jemaat dan oleh rasul-rasul dan penatua-penatua, lalu mereka menceriterakan segala sesuatu yang Allah lakukan dengan perantaraan mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 5, 'Tetapi beberapa orang dari golongan Farisi, yang telah menjadi percaya, datang dan berkata: "Orang-orang bukan Yahudi harus disunat dan diwajibkan untuk menuruti hukum Musa."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 6, 'Maka bersidanglah rasul-rasul dan penatua-penatua untuk membicarakan soal itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 7, 'Sesudah beberapa waktu lamanya berlangsung pertukaran pikiran mengenai soal itu, berdirilah Petrus dan berkata kepada mereka: "Hai saudara-saudara, kamu tahu, bahwa telah sejak semula Allah memilih aku dari antara kamu, supaya dengan perantaraan mulutku bangsa-bangsa lain mendengar berita Injil dan menjadi percaya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 8, 'Dan Allah, yang mengenal hati manusia, telah menyatakan kehendak-Nya untuk menerima mereka, sebab Ia mengaruniakan Roh Kudus juga kepada mereka sama seperti kepada kita,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 9, 'dan Ia sama sekali tidak mengadakan perbedaan antara kita dengan mereka, sesudah Ia menyucikan hati mereka oleh iman.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 10, 'Kalau demikian, mengapa kamu mau mencobai Allah dengan meletakkan pada tengkuk murid-murid itu suatu kuk, yang tidak dapat dipikul, baik oleh nenek moyang kita maupun oleh kita sendiri?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 11, 'Sebaliknya, kita percaya, bahwa oleh kasih karunia Tuhan Yesus Kristus kita akan beroleh keselamatan sama seperti mereka juga."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 12, 'Maka diamlah seluruh umat itu, lalu mereka mendengarkan Paulus dan Barnabas menceriterakan segala tanda dan mujizat yang dilakukan Allah dengan perantaraan mereka di tengah-tengah bangsa-bangsa lain.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 13, 'Setelah Paulus dan Barnabas selesai berbicara, berkatalah Yakobus: "Hai saudara-saudara, dengarkanlah aku:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 14, 'Simon telah menceriterakan, bahwa sejak semula Allah menunjukkan rahmat-Nya kepada bangsa-bangsa lain, yaitu dengan memilih suatu umat dari antara mereka bagi nama-Nya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 15, 'Hal itu sesuai dengan ucapan-ucapan para nabi seperti yang tertulis:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 16, 'Kemudian Aku akan kembali dan membangunkan kembali pondok Daud yang telah roboh, dan reruntuhannya akan Kubangun kembali dan akan Kuteguhkan,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 17, 'supaya semua orang lain mencari Tuhan dan segala bangsa yang tidak mengenal Allah, yang Kusebut milik-Ku demikianlah firman Tuhan yang melakukan semuanya ini,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 18, 'yang telah diketahui dari sejak semula.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 19, 'Sebab itu aku berpendapat, bahwa kita tidak boleh menimbulkan kesulitan bagi mereka dari bangsa-bangsa lain yang berbalik kepada Allah,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 20, 'tetapi kita harus menulis surat kepada mereka, supaya mereka menjauhkan diri dari makanan yang telah dicemarkan berhala-berhala, dari percabulan, dari daging binatang yang mati dicekik dan dari darah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 21, 'Sebab sejak zaman dahulu hukum Musa diberitakan di tiap-tiap kota, dan sampai sekarang hukum itu dibacakan tiap-tiap hari Sabat di rumah-rumah ibadat."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 22, 'Maka rasul-rasul dan penatua-penatua beserta seluruh jemaat itu mengambil keputusan untuk memilih dari antara mereka beberapa orang yang akan diutus ke Antiokhia bersama-sama dengan Paulus dan Barnabas, yaitu Yudas yang disebut Barsabas dan Silas. Keduanya adalah orang terpandang di antara saudara-saudara itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 23, 'Kepada mereka diserahkan surat yang bunyinya: "Salam dari rasul-rasul dan penatua-penatua, dari saudara-saudaramu kepada saudara-saudara di Antiokhia, Siria dan Kilikia yang berasal dari bangsa-bangsa lain.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 24, 'Kami telah mendengar, bahwa ada beberapa orang di antara kami, yang tiada mendapat pesan dari kami, telah menggelisahkan dan menggoyangkan hatimu dengan ajaran mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 25, 'Sebab itu dengan bulat hati kami telah memutuskan untuk memilih dan mengutus beberapa orang kepada kamu bersama-sama dengan Barnabas dan Paulus yang kami kasihi,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 26, 'yaitu dua orang yang telah mempertaruhkan nyawanya karena nama Tuhan kita Yesus Kristus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 27, 'Maka kami telah mengutus Yudas dan Silas, yang dengan lisan akan menyampaikan pesan yang tertulis ini juga kepada kamu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 28, 'Sebab adalah keputusan Roh Kudus dan keputusan kami, supaya kepada kamu jangan ditanggungkan lebih banyak beban dari pada yang perlu ini:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 29, 'kamu harus menjauhkan diri dari makanan yang dipersembahkan kepada berhala, dari darah, dari daging binatang yang mati dicekik dan dari percabulan. Jikalau kamu memelihara diri dari hal-hal ini, kamu berbuat baik. Sekianlah, selamat."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 30, 'Setelah berpamitan, Yudas dan Silas berangkat ke Antiokhia. Di situ mereka memanggil seluruh jemaat berkumpul, lalu menyerahkan surat itu kepada mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 31, 'Setelah membaca surat itu, jemaat bersukacita karena isinya yang menghiburkan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 32, 'Yudas dan Silas, yang adalah juga nabi, lama menasihati saudara-saudara itu dan menguatkan hati mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 33, 'Dan sesudah beberapa waktu keduanya tinggal di situ, saudara-saudara itu melepas mereka dalam damai untuk kembali kepada mereka yang mengutusnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 34, '(Tetapi Silas memutuskan untuk tinggal di situ.)', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 35, 'Paulus dan Barnabas tinggal beberapa lama di Antiokhia. Mereka bersama-sama dengan banyak orang lain mengajar dan memberitakan firman Tuhan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 36, 'Tetapi beberapa waktu kemudian berkatalah Paulus kepada Barnabas: "Baiklah kita kembali kepada saudara-saudara kita di setiap kota, di mana kita telah memberitakan firman Tuhan, untuk melihat, bagaimana keadaan mereka."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 37, 'Barnabas ingin membawa juga Yohanes yang disebut Markus;', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 38, 'tetapi Paulus dengan tegas berkata, bahwa tidak baik membawa serta orang yang telah meninggalkan mereka di Pamfilia dan tidak mau turut bekerja bersama-sama dengan mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 39, 'Hal itu menimbulkan perselisihan yang tajam, sehingga mereka berpisah dan Barnabas membawa Markus juga sertanya berlayar ke Siprus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 40, 'Tetapi Paulus memilih Silas, dan sesudah diserahkan oleh saudara-saudara itu kepada kasih karunia Tuhan', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 15, 41, 'berangkatlah ia mengelilingi Siria dan Kilikia sambil meneguhkan jemaat-jemaat di situ.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 1, 'Paulus datang juga ke Derbe dan ke Listra. Di situ ada seorang murid bernama Timotius; ibunya adalah seorang Yahudi dan telah menjadi percaya, sedangkan ayahnya seorang Yunani.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 2, 'Timotius ini dikenal baik oleh saudara-saudara di Listra dan di Ikonium,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 3, 'dan Paulus mau, supaya dia menyertainya dalam perjalanan. Paulus menyuruh menyunatkan dia karena orang-orang Yahudi di daerah itu, sebab setiap orang tahu bahwa bapanya adalah orang Yunani.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 4, 'Dalam perjalanan keliling dari kota ke kota Paulus dan Silas menyampaikan keputusan-keputusan yang diambil para rasul dan para penatua di Yerusalem dengan pesan, supaya jemaat-jemaat menurutinya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 5, 'Demikianlah jemaat-jemaat diteguhkan dalam iman dan makin lama makin bertambah besar jumlahnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 6, 'Mereka melintasi tanah Frigia dan tanah Galatia, karena Roh Kudus mencegah mereka untuk memberitakan Injil di Asia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 7, 'Dan setibanya di Misia mereka mencoba masuk ke daerah Bitinia, tetapi Roh Yesus tidak mengizinkan mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 8, 'Setelah melintasi Misia, mereka sampai di Troas.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 9, 'Pada malam harinya tampaklah oleh Paulus suatu penglihatan: ada seorang Makedonia berdiri di situ dan berseru kepadanya, katanya: "Menyeberanglah ke mari dan tolonglah kami!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 10, 'Setelah Paulus melihat penglihatan itu, segeralah kami mencari kesempatan untuk berangkat ke Makedonia, karena dari penglihatan itu kami menarik kesimpulan, bahwa Allah telah memanggil kami untuk memberitakan Injil kepada orang-orang di sana.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 11, 'Lalu kami bertolak dari Troas dan langsung berlayar ke Samotrake, dan keesokan harinya tibalah kami di Neapolis;', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 12, 'dari situ kami ke Filipi, kota pertama di bagian Makedonia ini, suatu kota perantauan orang Roma. Di kota itu kami tinggal beberapa hari.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 13, 'Pada hari Sabat kami ke luar pintu gerbang kota. Kami menyusur tepi sungai dan menemukan tempat sembahyang Yahudi, yang sudah kami duga ada di situ; setelah duduk, kami berbicara kepada perempuan-perempuan yang ada berkumpul di situ.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 14, 'Seorang dari perempuan-perempuan itu yang bernama Lidia turut mendengarkan. Ia seorang penjual kain ungu dari kota Tiatira, yang beribadah kepada Allah. Tuhan membuka hatinya, sehingga ia memperhatikan apa yang dikatakan oleh Paulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 15, 'Sesudah ia dibaptis bersama-sama dengan seisi rumahnya, ia mengajak kami, katanya: "Jika kamu berpendapat, bahwa aku sungguh-sungguh percaya kepada Tuhan, marilah menumpang di rumahku." Ia mendesak sampai kami menerimanya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 16, 'Pada suatu kali ketika kami pergi ke tempat sembahyang itu, kami bertemu dengan seorang hamba perempuan yang mempunyai roh tenung; dengan tenungan-tenungannya tuan-tuannya memperoleh penghasilan besar.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 17, 'Ia mengikuti Paulus dan kami dari belakang sambil berseru, katanya: "Orang-orang ini adalah hamba Allah Yang Mahatinggi. Mereka memberitakan kepadamu jalan kepada keselamatan."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 18, 'Hal itu dilakukannya beberapa hari lamanya. Tetapi ketika Paulus tidak tahan lagi akan gangguan itu, ia berpaling dan berkata kepada roh itu: "Demi nama Yesus Kristus aku menyuruh engkau keluar dari perempuan ini." Seketika itu juga keluarlah roh itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 19, 'Ketika tuan-tuan perempuan itu melihat, bahwa harapan mereka akan mendapat penghasilan lenyap, mereka menangkap Paulus dan Silas, lalu menyeret mereka ke pasar untuk menghadap penguasa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 20, 'Setelah mereka membawa keduanya menghadap pembesar-pembesar kota itu, berkatalah mereka, katanya: "Orang-orang ini mengacau kota kita ini, karena mereka orang Yahudi,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 21, 'dan mereka mengajarkan adat istiadat, yang kita sebagai orang Rum tidak boleh menerimanya atau menurutinya."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 22, 'Juga orang banyak bangkit menentang mereka. Lalu pembesar-pembesar kota itu menyuruh mengoyakkan pakaian dari tubuh mereka dan mendera mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 23, 'Setelah mereka berkali-kali didera, mereka dilemparkan ke dalam penjara. Kepala penjara diperintahkan untuk menjaga mereka dengan sungguh-sungguh.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 24, 'Sesuai dengan perintah itu, kepala penjara memasukkan mereka ke ruang penjara yang paling tengah dan membelenggu kaki mereka dalam pasungan yang kuat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 25, 'Tetapi kira-kira tengah malam Paulus dan Silas berdoa dan menyanyikan puji-pujian kepada Allah dan orang-orang hukuman lain mendengarkan mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 26, 'Akan tetapi terjadilah gempa bumi yang hebat, sehingga sendi-sendi penjara itu goyah; dan seketika itu juga terbukalah semua pintu dan terlepaslah belenggu mereka semua.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 27, 'Ketika kepala penjara itu terjaga dari tidurnya dan melihat pintu-pintu penjara terbuka, ia menghunus pedangnya hendak membunuh diri, karena ia menyangka, bahwa orang-orang hukuman itu telah melarikan diri.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 28, 'Tetapi Paulus berseru dengan suara nyaring, katanya: "Jangan celakakan dirimu, sebab kami semuanya masih ada di sini!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 29, 'Kepala penjara itu menyuruh membawa suluh, lalu berlari masuk dan dengan gemetar tersungkurlah ia di depan Paulus dan Silas.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 30, 'Ia mengantar mereka ke luar, sambil berkata: "Tuan-tuan, apakah yang harus aku perbuat, supaya aku selamat?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 31, 'Jawab mereka: "Percayalah kepada Tuhan Yesus Kristus dan engkau akan selamat, engkau dan seisi rumahmu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 32, 'Lalu mereka memberitakan firman Tuhan kepadanya dan kepada semua orang yang ada di rumahnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 33, 'Pada jam itu juga kepala penjara itu membawa mereka dan membasuh bilur mereka. Seketika itu juga ia dan keluarganya memberi diri dibaptis.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 34, 'Lalu ia membawa mereka ke rumahnya dan menghidangkan makanan kepada mereka. Dan ia sangat bergembira, bahwa ia dan seisi rumahnya telah menjadi percaya kepada Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 35, 'Setelah hari siang pembesar-pembesar kota menyuruh pejabat-pejabat kota pergi kepada kepala penjara dengan pesan: "Lepaskanlah kedua orang itu!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 36, 'Kepala penjara meneruskan pesan itu kepada Paulus, katanya: "Pembesar-pembesar kota telah menyuruh melepaskan kamu; jadi keluarlah kamu sekarang dan pergilah dengan selamat!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 37, 'Tetapi Paulus berkata kepada orang-orang itu: "Tanpa diadili mereka telah mendera kami, warganegara-warganegara Roma, di muka umum, lalu melemparkan kami ke dalam penjara. Sekarang mereka mau mengeluarkan kami dengan diam-diam? Tidak mungkin demikian! Biarlah mereka datang sendiri dan membawa kami ke luar."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 38, 'Pejabat-pejabat itu menyampaikan perkataan itu kepada pembesar-pembesar kota. Ketika mereka mendengar, bahwa Paulus dan Silas adalah orang Rum, maka takutlah mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 39, 'Mereka datang minta maaf lalu membawa kedua rasul itu ke luar dan memohon, supaya mereka meninggalkan kota itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 16, 40, 'Lalu mereka meninggalkan penjara itu dan pergi ke rumah Lidia; dan setelah bertemu dengan saudara-saudara di situ dan menghiburkan mereka, berangkatlah kedua rasul itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 1, 'Paulus dan Silas mengambil jalan melalui Amfipolis dan Apolonia dan tiba di Tesalonika. Di situ ada sebuah rumah ibadat orang Yahudi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 2, 'Seperti biasa Paulus masuk ke rumah ibadat itu. Tiga hari Sabat berturut-turut ia membicarakan dengan mereka bagian-bagian dari Kitab Suci.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 3, 'Ia menerangkannya kepada mereka dan menunjukkan, bahwa Mesias harus menderita dan bangkit dari antara orang mati, lalu ia berkata: "Inilah Mesias, yaitu Yesus, yang kuberitakan kepadamu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 4, 'Beberapa orang dari mereka menjadi yakin dan menggabungkan diri dengan Paulus dan Silas dan juga sejumlah besar orang Yunani yang takut kepada Allah, dan tidak sedikit perempuan-perempuan terkemuka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 5, 'Tetapi orang-orang Yahudi menjadi iri hati dan dengan dibantu oleh beberapa penjahat dari antara petualang-petualang di pasar, mereka mengadakan keributan dan mengacau kota itu. Mereka menyerbu rumah Yason dengan maksud untuk menghadapkan Paulus dan Silas kepada sidang rakyat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 6, 'Tetapi ketika mereka tidak menemukan keduanya, mereka menyeret Yason dan beberapa saudara ke hadapan pembesar-pembesar kota, sambil berteriak, katanya: "Orang-orang yang mengacaukan seluruh dunia telah datang juga ke mari,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 7, 'dan Yason menerima mereka menumpang di rumahnya. Mereka semua bertindak melawan ketetapan-ketetapan Kaisar dengan mengatakan, bahwa ada seorang raja lain, yaitu Yesus."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 8, 'Ketika orang banyak dan pembesar-pembesar kota mendengar semuanya itu, mereka menjadi gelisah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 9, 'Tetapi setelah mereka mendapat jaminan dari Yason dan dari saudara-saudara lain, merekapun dilepaskan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 10, 'Tetapi pada malam itu juga segera saudara-saudara di situ menyuruh Paulus dan Silas berangkat ke Berea. Setibanya di situ pergilah mereka ke rumah ibadat orang Yahudi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 11, 'Orang-orang Yahudi di kota itu lebih baik hatinya dari pada orang-orang Yahudi di Tesalonika, karena mereka menerima firman itu dengan segala kerelaan hati dan setiap hari mereka menyelidiki Kitab Suci untuk mengetahui, apakah semuanya itu benar demikian.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 12, 'Banyak di antara mereka yang menjadi percaya; juga tidak sedikit di antara perempuan-perempuan terkemuka dan laki-laki Yunani.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 13, 'Tetapi ketika orang-orang Yahudi dari Tesalonika tahu, bahwa juga di Berea telah diberitakan firman Allah oleh Paulus, datang jugalah mereka ke sana menghasut dan menggelisahkan hati orang banyak.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 14, 'Tetapi saudara-saudara menyuruh Paulus segera berangkat menuju ke pantai laut, tetapi Silas dan Timotius masih tinggal di Berea.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 15, 'Orang-orang yang mengiringi Paulus menemaninya sampai di Atena, lalu kembali dengan pesan kepada Silas dan Timotius, supaya mereka selekas mungkin datang kepadanya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 16, 'Sementara Paulus menantikan mereka di Atena, sangat sedih hatinya karena ia melihat, bahwa kota itu penuh dengan patung-patung berhala.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 17, 'Karena itu di rumah ibadat ia bertukar pikiran dengan orang-orang Yahudi dan orang-orang yang takut akan Allah, dan di pasar setiap hari dengan orang-orang yang dijumpainya di situ.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 18, 'Dan juga beberapa ahli pikir dari golongan Epikuros dan Stoa bersoal jawab dengan dia dan ada yang berkata: "Apakah yang hendak dikatakan si peleter ini?" Tetapi yang lain berkata: "Rupa-rupanya ia adalah pemberita ajaran dewa-dewa asing." Sebab ia memberitakan Injil tentang Yesus dan tentang kebangkitan-Nya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 19, 'Lalu mereka membawanya menghadap sidang Areopagus dan mengatakan: "Bolehkah kami tahu ajaran baru mana yang kauajarkan ini?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 20, 'Sebab engkau memperdengarkan kepada kami perkara-perkara yang aneh. Karena itu kami ingin tahu, apakah artinya semua itu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 21, 'Adapun orang-orang Atena dan orang-orang asing yang tinggal di situ tidak mempunyai waktu untuk sesuatu selain untuk mengatakan atau mendengar segala sesuatu yang baru.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 22, 'Paulus pergi berdiri di atas Areopagus dan berkata: "Hai orang-orang Atena, aku lihat, bahwa dalam segala hal kamu sangat beribadah kepada dewa-dewa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 23, 'Sebab ketika aku berjalan-jalan di kotamu dan melihat-lihat barang-barang pujaanmu, aku menjumpai juga sebuah mezbah dengan tulisan: Kepada Allah yang tidak dikenal. Apa yang kamu sembah tanpa mengenalnya, itulah yang kuberitakan kepada kamu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 24, 'Allah yang telah menjadikan bumi dan segala isinya, Ia, yang adalah Tuhan atas langit dan bumi, tidak diam dalam kuil-kuil buatan tangan manusia,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 25, 'dan juga tidak dilayani oleh tangan manusia, seolah-olah Ia kekurangan apa-apa, karena Dialah yang memberikan hidup dan nafas dan segala sesuatu kepada semua orang.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 26, 'Dari satu orang saja Ia telah menjadikan semua bangsa dan umat manusia untuk mendiami seluruh muka bumi dan Ia telah menentukan musim-musim bagi mereka dan batas-batas kediaman mereka,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 27, 'supaya mereka mencari Dia dan mudah-mudahan menjamah dan menemukan Dia, walaupun Ia tidak jauh dari kita masing-masing.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 28, 'Sebab di dalam Dia kita hidup, kita bergerak, kita ada, seperti yang telah juga dikatakan oleh pujangga-pujanggamu: Sebab kita ini dari keturunan Allah juga.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 29, 'Karena kita berasal dari keturunan Allah, kita tidak boleh berpikir, bahwa keadaan ilahi sama seperti emas atau perak atau batu, ciptaan kesenian dan keahlian manusia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 30, 'Dengan tidak memandang lagi zaman kebodohan, maka sekarang Allah memberitakan kepada manusia, bahwa di mana-mana semua mereka harus bertobat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 31, 'Karena Ia telah menetapkan suatu hari, pada waktu mana Ia dengan adil akan menghakimi dunia oleh seorang yang telah ditentukan-Nya, sesudah Ia memberikan kepada semua orang suatu bukti tentang hal itu dengan membangkitkan Dia dari antara orang mati."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 32, 'Ketika mereka mendengar tentang kebangkitan orang mati, maka ada yang mengejek, dan yang lain berkata: "Lain kali saja kami mendengar engkau berbicara tentang hal itu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 33, 'Lalu Paulus pergi meninggalkan mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 17, 34, 'Tetapi beberapa orang laki-laki menggabungkan diri dengan dia dan menjadi percaya, di antaranya juga Dionisius, anggota majelis Areopagus, dan seorang perempuan bernama Damaris, dan juga orang-orang lain bersama-sama dengan mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 1, 'Kemudian Paulus meninggalkan Atena, lalu pergi ke Korintus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 2, 'Di Korintus ia berjumpa dengan seorang Yahudi bernama Akwila, yang berasal dari Pontus. Ia baru datang dari Italia dengan Priskila, isterinya, karena kaisar Klaudius telah memerintahkan, supaya semua orang Yahudi meninggalkan Roma. Paulus singgah ke rumah mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 3, 'Dan karena mereka melakukan pekerjaan yang sama, ia tinggal bersama-sama dengan mereka. Mereka bekerja bersama-sama, karena mereka sama-sama tukang kemah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 4, 'Dan setiap hari Sabat Paulus berbicara dalam rumah ibadat dan berusaha meyakinkan orang-orang Yahudi dan orang-orang Yunani.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 5, 'Ketika Silas dan Timotius datang dari Makedonia, Paulus dengan sepenuhnya dapat memberitakan firman, di mana ia memberi kesaksian kepada orang-orang Yahudi, bahwa Yesus adalah Mesias.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 6, 'Tetapi ketika orang-orang itu memusuhi dia dan menghujat, ia mengebaskan debu dari pakaiannya dan berkata kepada mereka: "Biarlah darahmu tertumpah ke atas kepalamu sendiri; aku bersih, tidak bersalah. Mulai dari sekarang aku akan pergi kepada bangsa-bangsa lain."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 7, 'Maka keluarlah ia dari situ, lalu datang ke rumah seorang bernama Titius Yustus, yang beribadah kepada Allah, dan yang rumahnya berdampingan dengan rumah ibadat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 8, 'Tetapi Krispus, kepala rumah ibadat itu, menjadi percaya kepada Tuhan bersama-sama dengan seisi rumahnya, dan banyak dari orang-orang Korintus, yang mendengarkan pemberitaan Paulus, menjadi percaya dan memberi diri mereka dibaptis.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 9, 'Pada suatu malam berfirmanlah Tuhan kepada Paulus di dalam suatu penglihatan: "Jangan takut! Teruslah memberitakan firman dan jangan diam!', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 10, 'Sebab Aku menyertai engkau dan tidak ada seorangpun yang akan menjamah dan menganiaya engkau, sebab banyak umat-Ku di kota ini."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 11, 'Maka tinggallah Paulus di situ selama satu tahun enam bulan dan ia mengajarkan firman Allah di tengah-tengah mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 12, 'Akan tetapi setelah Galio menjadi gubernur di Akhaya, bangkitlah orang-orang Yahudi bersama-sama melawan Paulus, lalu membawa dia ke depan pengadilan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 13, 'Kata mereka: "Ia ini berusaha meyakinkan orang untuk beribadah kepada Allah dengan jalan yang bertentangan dengan hukum Taurat."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 14, 'Ketika Paulus hendak mulai berbicara, berkatalah Galio kepada orang-orang Yahudi itu: "Hai orang-orang Yahudi, jika sekiranya dakwaanmu mengenai suatu pelanggaran atau kejahatan, sudahlah sepatutnya aku menerima perkaramu,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 15, 'tetapi kalau hal itu adalah perselisihan tentang perkataan atau nama atau hukum yang berlaku di antara kamu, maka hendaklah kamu sendiri mengurusnya; aku tidak rela menjadi hakim atas perkara yang demikian."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 16, 'Lalu ia mengusir mereka dari ruang pengadilan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 17, 'Maka orang itu semua menyerbu Sostenes, kepala rumah ibadat, lalu memukulinya di depan pengadilan itu; tetapi Galio sama sekali tidak menghiraukan hal itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 18, 'Paulus tinggal beberapa hari lagi di Korintus. Lalu ia minta diri kepada saudara-saudara di situ, dan berlayar ke Siria, sesudah ia mencukur rambutnya di Kengkrea, karena ia telah bernazar. Priskila dan Akwila menyertai dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 19, 'Lalu sampailah mereka di Efesus. Paulus meninggalkan Priskila dan Akwila di situ. Ia sendiri masuk ke rumah ibadat dan berbicara dengan orang-orang Yahudi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 20, 'Mereka minta kepadanya untuk tinggal lebih lama di situ, tetapi ia tidak mengabulkannya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 21, 'Ia minta diri dan berkata: "Aku akan kembali kepada kamu, jika Allah menghendakinya." Lalu bertolaklah ia dari Efesus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 22, 'Ia sampai di Kaisarea dan setelah naik ke darat dan memberi salam kepada jemaat, ia berangkat ke Antiokhia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 23, 'Setelah beberapa hari lamanya ia tinggal di situ, ia berangkat pula, lalu menjelajahi seluruh tanah Galatia dan Frigia untuk meneguhkan hati semua murid.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 24, 'Sementara itu datanglah ke Efesus seorang Yahudi bernama Apolos, yang berasal dari Aleksandria. Ia seorang yang fasih berbicara dan sangat mahir dalam soal-soal Kitab Suci.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 25, 'Ia telah menerima pengajaran dalam Jalan Tuhan. Dengan bersemangat ia berbicara dan dengan teliti ia mengajar tentang Yesus, tetapi ia hanya mengetahui baptisan Yohanes.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 26, 'Ia mulai mengajar dengan berani di rumah ibadat. Tetapi setelah Priskila dan Akwila mendengarnya, mereka membawa dia ke rumah mereka dan dengan teliti menjelaskan kepadanya Jalan Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 27, 'Karena Apolos ingin menyeberang ke Akhaya, saudara-saudara di Efesus mengirim surat kepada murid-murid di situ, supaya mereka menyambut dia. Setibanya di Akhaya maka ia, oleh kasih karunia Allah, menjadi seorang yang sangat berguna bagi orang-orang yang percaya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 18, 28, 'Sebab dengan tak jemu-jemunya ia membantah orang-orang Yahudi di muka umum dan membuktikan dari Kitab Suci bahwa Yesus adalah Mesias.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 1, 'Ketika Apolos masih di Korintus, Paulus sudah menjelajah daerah-daerah pedalaman dan tiba di Efesus. Di situ didapatinya beberapa orang murid.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 2, 'Katanya kepada mereka: "Sudahkah kamu menerima Roh Kudus, ketika kamu menjadi percaya?" Akan tetapi mereka menjawab dia: "Belum, bahkan kami belum pernah mendengar, bahwa ada Roh Kudus."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 3, 'Lalu kata Paulus kepada mereka: "Kalau begitu dengan baptisan manakah kamu telah dibaptis?" Jawab mereka: "Dengan baptisan Yohanes."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 4, 'Kata Paulus: "Baptisan Yohanes adalah pembaptisan orang yang telah bertobat, dan ia berkata kepada orang banyak, bahwa mereka harus percaya kepada Dia yang datang kemudian dari padanya, yaitu Yesus."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 5, 'Ketika mereka mendengar hal itu, mereka memberi diri mereka dibaptis dalam nama Tuhan Yesus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 6, 'Dan ketika Paulus menumpangkan tangan di atas mereka, turunlah Roh Kudus ke atas mereka, dan mulailah mereka berkata-kata dalam bahasa roh dan bernubuat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 7, 'Jumlah mereka adalah kira-kira dua belas orang.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 8, 'Selama tiga bulan Paulus mengunjungi rumah ibadat di situ dan mengajar dengan berani. Oleh pemberitaannya ia berusaha meyakinkan mereka tentang Kerajaan Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 9, 'Tetapi ada beberapa orang yang tegar hatinya. Mereka tidak mau diyakinkan, malahan mengumpat Jalan Tuhan di depan orang banyak. Karena itu Paulus meninggalkan mereka dan memisahkan murid-muridnya dari mereka, dan setiap hari berbicara di ruang kuliah Tiranus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 10, 'Hal ini dilakukannya dua tahun lamanya, sehingga semua penduduk Asia mendengar firman Tuhan, baik orang Yahudi maupun orang Yunani.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 11, 'Oleh Paulus Allah mengadakan mujizat-mujizat yang luar biasa,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 12, 'bahkan orang membawa saputangan atau kain yang pernah dipakai oleh Paulus dan meletakkannya atas orang-orang sakit, maka lenyaplah penyakit mereka dan keluarlah roh-roh jahat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 13, 'Juga beberapa tukang jampi Yahudi, yang berjalan keliling di negeri itu, mencoba menyebut nama Tuhan Yesus atas mereka yang kerasukan roh jahat dengan berseru, katanya: "Aku menyumpahi kamu demi nama Yesus yang diberitakan oleh Paulus."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 14, 'Mereka yang melakukan hal itu ialah tujuh orang anak dari seorang imam kepala Yahudi yang bernama Skewa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 15, 'Tetapi roh jahat itu menjawab: "Yesus aku kenal, dan Paulus aku ketahui, tetapi kamu, siapakah kamu?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 16, 'Dan orang yang dirasuk roh jahat itu menerpa mereka dan menggagahi mereka semua dan mengalahkannya, sehingga mereka lari dari rumah orang itu dengan telanjang dan luka-luka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 17, 'Hal itu diketahui oleh seluruh penduduk Efesus, baik orang Yahudi maupun orang Yunani, maka ketakutanlah mereka semua dan makin masyhurlah nama Tuhan Yesus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 18, 'Banyak di antara mereka yang telah menjadi percaya, datang dan mengaku di muka umum, bahwa mereka pernah turut melakukan perbuatan-perbuata seperti itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 19, 'Banyak juga di antara mereka, yang pernah melakukan sihir, mengumpulkan kitab-kitabnya lalu membakarnya di depan mata semua orang. Nilai kitab-kitab itu ditaksir lima puluh ribu uang perak.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 20, 'Dengan jalan ini makin tersiarlah firman Tuhan dan makin berkuasa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 21, 'Kemudian dari pada semuanya itu Paulus bermaksud pergi ke Yerusalem melalui Makedonia dan Akhaya. Katanya: "Sesudah berkunjung ke situ aku harus melihat Roma juga."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 22, 'Lalu ia menyuruh dua orang pembantunya, yaitu Timotius dan Erastus, mendahuluinya ke Makedonia, tetapi ia sendiri tinggal beberapa lama lagi di Asia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 23, 'Kira-kira pada waktu itu timbul huru-hara besar mengenai Jalan Tuhan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 24, 'Sebab ada seorang bernama Demetrius, seorang tukang perak, yang membuat kuil-kuilan dewi Artemis dari perak. Usahanya itu mendatangkan penghasilan yang tidak sedikit bagi tukang-tukangnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 25, 'Ia mengumpulkan mereka bersama-sama dengan pekerja-pekerja lain dalam perusahaan itu dan berkata: "Saudara-saudara, kamu tahu, bahwa kemakmuran kita adalah hasil perusahaan ini!', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 26, 'Sekarang kamu sendiri melihat dan mendengar, bagaimana Paulus, bukan saja di Efesus, tetapi juga hampir di seluruh Asia telah membujuk dan menyesatkan banyak orang dengan mengatakan, bahwa apa yang dibuat oleh tangan manusia bukanlah dewa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 27, 'Dengan jalan demikian bukan saja perusahaan kita berada dalam bahaya untuk dihina orang, tetapi juga kuil Artemis, dewi besar itu, berada dalam bahaya akan kehilangan artinya. Dan Artemis sendiri, Artemis yang disembah oleh seluruh Asia dan seluruh dunia yang beradab, akan kehilangan kebesarannya."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 28, 'Mendengar itu meluaplah amarah mereka, lalu mereka berteriak-teriak, katanya: "Besarlah Artemis dewi orang Efesus!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 29, 'Seluruh kota menjadi kacau dan mereka ramai-ramai membanjiri gedung kesenian serta menyeret Gayus dan Aristarkhus, keduanya orang Makedonia dan teman seperjalanan Paulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 30, 'Paulus mau pergi ke tengah-tengah rakyat itu, tetapi murid-muridnya tidak mengizinkannya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 31, 'Bahkan beberapa pembesar yang berasal dari Asia yang bersahabat dengan Paulus, mengirim peringatan kepadanya, supaya ia jangan masuk ke gedung kesenian itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 32, 'Sementara itu orang yang berkumpul di dalam gedung itu berteriak-teriak; yang seorang mengatakan ini dan yang lain mengatakan itu, sebab kumpulan itu kacau-balau dan kebanyakan dari mereka tidak tahu untuk apa mereka berkumpul.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 33, 'Lalu seorang bernama Aleksander didorong ke depan oleh orang-orang Yahudi. Ia mendapat keterangan dari orang banyak tentang apa yang terjadi. Segera ia memberi isyarat dengan tangannya dan mau memberi penjelasan sebagai pembelaan di depan rakyat itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 34, 'Tetapi ketika mereka tahu, bahwa ia adalah orang Yahudi, berteriaklah mereka bersama-sama kira-kira dua jam lamanya: "Besarlah Artemis dewi orang Efesus!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 35, 'Akan tetapi panitera kota menenangkan orang banyak itu dan berkata: "Hai orang Efesus! Siapakah di dunia ini yang tidak tahu, bahwa kota Efesuslah yang memelihara baik kuil dewi Artemis, yang mahabesar, maupun patungnya yang turun dari langit?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 36, 'Hal itu tidak dapat dibantah, karena itu hendaklah kamu tenang dan janganlah terburu-buru bertindak.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 37, 'Sebab kamu telah membawa orang-orang ini ke sini, walaupun mereka tidak merampok kuil dewi kita dan tidak menghujat namanya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 38, 'Jadi jika Demetrius dan tukang-tukangnya ada pengaduannya terhadap seseorang, bukankah ada sidang-sidang pengadilan dan ada gubernur, jadi hendaklah kedua belah pihak mengajukan dakwaannya ke situ.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 39, 'Dan jika ada sesuatu yang lain yang kamu kehendaki, baiklah kehendakmu itu diselesaikan dalam sidang rakyat yang sah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 40, 'Sebab kita berada dalam bahaya akan dituduh, bahwa kita menimbulkan huru-hara pada hari ini, karena tidak ada alasan yang dapat kita kemukakan untuk membenarkan kumpulan yang kacau-balau ini."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 19, 41, '(19-40b) Dan dengan kata-kata itu ia membubarkan kumpulan rakyat itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 1, 'Setelah reda keributan itu, Paulus memanggil murid-murid dan menguatkan hati mereka. Dan sesudah minta diri, ia berangkat ke Makedonia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 2, 'Ia menjelajah daerah itu dan dengan banyak nasihat menguatkan hati saudara-saudara di situ. Lalu tibalah ia di tanah Yunani.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 3, 'Sesudah tiga bulan lamanya tinggal di situ ia hendak berlayar ke Siria. Tetapi pada waktu itu orang-orang Yahudi bermaksud membunuh dia. Karena itu ia memutuskan untuk kembali melalui Makedonia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 4, 'Ia disertai oleh Sopater anak Pirus, dari Berea, dan Aristarkhus dan Sekundus, keduanya dari Tesalonika, dan Gayus dari Derbe, dan Timotius dan dua orang dari Asia, yaitu Tikhikus dan Trofimus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 5, 'Mereka itu berangkat lebih dahulu dan menantikan kami di Troas.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 6, 'Tetapi sesudah hari raya Roti Tidak Beragi kami berlayar dari Filipi dan empat hari kemudian sampailah kami di Troas dan bertemu dengan mereka. Di situ kami tinggal tujuh hari lamanya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 7, 'Pada hari pertama dalam minggu itu, ketika kami berkumpul untuk memecah-mecahkan roti, Paulus berbicara dengan saudara-saudara di situ, karena ia bermaksud untuk berangkat pada keesokan harinya. Pembicaraan itu berlangsung sampai tengah malam.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 8, 'Di ruang atas, di mana kami berkumpul, dinyalakan banyak lampu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 9, 'Seorang muda bernama Eutikhus duduk di jendela. Karena Paulus amat lama berbicara, orang muda itu tidak dapat menahan kantuknya. Akhirnya ia tertidur lelap dan jatuh dari tingkat ketiga ke bawah. Ketika ia diangkat orang, ia sudah mati.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 10, 'Tetapi Paulus turun ke bawah. Ia merebahkan diri ke atas orang muda itu, mendekapnya, dan berkata: "Jangan ribut, sebab ia masih hidup."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 11, 'Setelah kembali di ruang atas, Paulus memecah-mecahkan roti lalu makan; habis makan masih lama lagi ia berbicara, sampai fajar menyingsing. Kemudian ia berangkat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 12, 'Sementara itu mereka mengantarkan orang muda itu hidup ke rumahnya, dan mereka semua merasa sangat terhibur.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 13, 'Kami berangkat lebih dahulu ke kapal dan berlayar ke Asos, dengan maksud untuk menjemput Paulus di situ sesuai dengan pesannya, sebab ia sendiri mau berjalan kaki melalui darat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 14, 'Ketika ia bertemu dengan kami di Asos, kami membawanya ke kapal, lalu melanjutkan pelayaran kami ke Metilene.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 15, 'Dari situ kami terus berlayar dan pada keesokan harinya kami berhadapan dengan pulau Khios. Pada hari berikutnya kami menuju Samos dan sehari kemudian tibalah kami di Miletus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 16, 'Paulus telah memutuskan untuk tidak singgah di Efesus, supaya jangan habis waktunya di Asia. Sebab ia buru-buru, agar jika mungkin, ia telah berada di Yerusalem pada hari raya Pentakosta.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 17, 'Karena itu ia menyuruh seorang dari Miletus ke Efesus dengan pesan supaya para penatua jemaat datang ke Miletus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 18, 'Sesudah mereka datang, berkatalah ia kepada mereka: "Kamu tahu, bagaimana aku hidup di antara kamu sejak hari pertama aku tiba di Asia ini:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 19, 'dengan segala rendah hati aku melayani Tuhan. Dalam pelayanan itu aku banyak mencucurkan air mata dan banyak mengalami pencobaan dari pihak orang Yahudi yang mau membunuh aku.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 20, 'Sungguhpun demikian aku tidak pernah melalaikan apa yang berguna bagi kamu. Semua kuberitakan dan kuajarkan kepada kamu, baik di muka umum maupun dalam perkumpulan-perkumpulan di rumah kamu;', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 21, 'aku senantiasa bersaksi kepada orang-orang Yahudi dan orang-orang Yunani, supaya mereka bertobat kepada Allah dan percaya kepada Tuhan kita, Yesus Kristus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 22, 'Tetapi sekarang sebagai tawanan Roh aku pergi ke Yerusalem dan aku tidak tahu apa yang akan terjadi atas diriku di situ', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 23, 'selain dari pada yang dinyatakan Roh Kudus dari kota ke kota kepadaku, bahwa penjara dan sengsara menunggu aku.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 24, 'Tetapi aku tidak menghiraukan nyawaku sedikitpun, asal saja aku dapat mencapai garis akhir dan menyelesaikan pelayanan yang ditugaskan oleh Tuhan Yesus kepadaku untuk memberi kesaksian tentang Injil kasih karunia Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 25, 'Dan sekarang aku tahu, bahwa kamu tidak akan melihat mukaku lagi, kamu sekalian yang telah kukunjungi untuk memberitakan Kerajaan Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 26, 'Sebab itu pada hari ini aku bersaksi kepadamu, bahwa aku bersih, tidak bersalah terhadap siapapun yang akan binasa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 27, 'Sebab aku tidak lalai memberitakan seluruh maksud Allah kepadamu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 28, 'Karena itu jagalah dirimu dan jagalah seluruh kawanan, karena kamulah yang ditetapkan Roh Kudus menjadi penilik untuk menggembalakan jemaat Allah yang diperoleh-Nya dengan darah Anak-Nya sendiri.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 29, 'Aku tahu, bahwa sesudah aku pergi, serigala-serigala yang ganas akan masuk ke tengah-tengah kamu dan tidak akan menyayangkan kawanan itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 30, 'Bahkan dari antara kamu sendiri akan muncul beberapa orang, yang dengan ajaran palsu mereka berusaha menarik murid-murid dari jalan yang benar dan supaya mengikut mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 31, 'Sebab itu berjaga-jagalah dan ingatlah, bahwa aku tiga tahun lamanya, siang malam, dengan tiada berhenti-hentinya menasihati kamu masing-masing dengan mencucurkan air mata.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 32, 'Dan sekarang aku menyerahkan kamu kepada Tuhan dan kepada firman kasih karunia-Nya, yang berkuasa membangun kamu dan menganugerahkan kepada kamu bagian yang ditentukan bagi semua orang yang telah dikuduskan-Nya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 33, 'Perak atau emas atau pakaian tidak pernah aku ingini dari siapapun juga.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 34, 'Kamu sendiri tahu, bahwa dengan tanganku sendiri aku telah bekerja untuk memenuhi keperluanku dan keperluan kawan-kawan seperjalananku.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 35, 'Dalam segala sesuatu telah kuberikan contoh kepada kamu, bahwa dengan bekerja demikian kita harus membantu orang-orang yang lemah dan harus mengingat perkataan Tuhan Yesus, sebab Ia sendiri telah mengatakan: Adalah lebih berbahagia memberi dari pada menerima."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 36, 'Sesudah mengucapkan kata-kata itu Paulus berlutut dan berdoa bersama-sama dengan mereka semua.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 37, 'Maka menangislah mereka semua tersedu-sedu dan sambil memeluk Paulus, mereka berulang-ulang mencium dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 20, 38, 'Mereka sangat berdukacita, terlebih-lebih karena ia katakan, bahwa mereka tidak akan melihat mukanya lagi. Lalu mereka mengantar dia ke kapal.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 1, 'Sesudah perpisahan yang berat itu bertolaklah kami dan langsung berlayar menuju Kos. Keesokan harinya sampailah kami di Rodos dan dari situ kami ke Patara.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 2, 'Di Patara kami mendapat kapal, yang hendak menyeberang ke Fenisia. Kami naik kapal itu, lalu bertolak.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 3, 'Kemudian tampak Siprus di sebelah kiri, tetapi kami melewatinya dan menuju ke Siria. Akhirnya tibalah kami di Tirus, sebab muatan kapal harus dibongkar di kota itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 4, 'Di situ kami mengunjungi murid-murid dan tinggal di situ tujuh hari lamanya. Oleh bisikan Roh murid-murid itu menasihati Paulus, supaya ia jangan pergi ke Yerusalem.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 5, 'Tetapi setelah lewat waktunya, kami berangkat meneruskan perjalanan kami. Murid-murid semua dengan isteri dan anak-anak mereka mengantar kami sampai ke luar kota; dan di tepi pantai kami berlutut dan berdoa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 6, 'Sesudah minta diri kami naik ke kapal, dan mereka pulang ke rumah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 7, 'Dari Tirus kami tiba di Ptolemais dan di situ berakhirlah pelayaran kami. Kami memberi salam kepada saudara-saudara dan tinggal satu hari di antara mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 8, 'Pada keesokan harinya kami berangkat dari situ dan tiba di Kaisarea. Kami masuk ke rumah Filipus, pemberita Injil itu, yaitu satu dari ketujuh orang yang dipilih di Yerusalem, dan kami tinggal di rumahnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 9, 'Filipus mempunyai empat anak dara yang beroleh karunia untuk bernubuat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 10, 'Setelah beberapa hari kami tinggal di situ, datanglah dari Yudea seorang nabi bernama Agabus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 11, 'Ia datang pada kami, lalu mengambil ikat pinggang Paulus. Sambil mengikat kaki dan tangannya sendiri ia berkata: "Demikianlah kata Roh Kudus: Beginilah orang yang empunya ikat pinggang ini akan diikat oleh orang-orang Yahudi di Yerusalem dan diserahkan ke dalam tangan bangsa-bangsa lain."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 12, 'Mendengar itu kami bersama-sama dengan murid-murid di tempat itu meminta, supaya Paulus jangan pergi ke Yerusalem.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 13, 'Tetapi Paulus menjawab: "Mengapa kamu menangis dan dengan jalan demikian mau menghancurkan hatiku? Sebab aku ini rela bukan saja untuk diikat, tetapi juga untuk mati di Yerusalem oleh karena nama Tuhan Yesus."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 14, 'Karena ia tidak mau menerima nasihat kami, kami menyerah dan berkata: "Jadilah kehendak Tuhan!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 15, 'Sesudah beberapa hari lamanya tinggal di Kaisarea, berkemaslah kami, lalu berangkat ke Yerusalem.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 16, 'Bersama-sama dengan kami turut juga beberapa murid dari Kaisarea. Mereka membawa kami ke rumah seorang yang bernama Manason. Ia dari Siprus dan sudah lama menjadi murid. Kami akan menumpang di rumahnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 17, 'Ketika kami tiba di Yerusalem, semua saudara menyambut kami dengan suka hati.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 18, 'Pada keesokan harinya pergilah Paulus bersama-sama dengan kami mengunjungi Yakobus; semua penatua telah hadir di situ.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 19, 'Paulus memberi salam kepada mereka, lalu menceriterakan dengan terperinci apa yang dilakukan Allah di antara bangsa-bangsa lain oleh pelayanannya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 20, 'Mendengar itu mereka memuliakan Allah. Lalu mereka berkata kepada Paulus: "Saudara, lihatlah, beribu-ribu orang Yahudi telah menjadi percaya dan mereka semua rajin memelihara hukum Taurat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 21, 'Tetapi mereka mendengar tentang engkau, bahwa engkau mengajar semua orang Yahudi yang tinggal di antara bangsa-bangsa lain untuk melepaskan hukum Musa, sebab engkau mengatakan, supaya mereka jangan menyunatkan anak-anaknya dan jangan hidup menurut adat istiadat kita.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 22, 'Jadi bagaimana sekarang? Tentu mereka akan mendengar, bahwa engkau telah datang ke mari.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 23, 'Sebab itu, lakukanlah apa yang kami katakan ini: Di antara kami ada empat orang yang bernazar.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 24, 'Bawalah mereka bersama-sama dengan engkau, lakukanlah pentahiran dirimu bersama-sama dengan mereka dan tanggunglah biaya mereka, sehingga mereka dapat mencukurkan rambutnya; maka semua orang akan tahu, bahwa segala kabar yang mereka dengar tentang engkau sama sekali tidak benar, melainkan bahwa engkau tetap memelihara hukum Taurat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 25, 'Tetapi mengenai bangsa-bangsa lain, yang telah menjadi percaya, sudah kami tuliskan keputusan-keputusan kami, yaitu mereka harus menjauhkan diri dari makanan yang dipersembahkan kepada berhala, dari darah, dari daging binatang yang mati dicekik dan dari percabulan."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 26, 'Pada hari berikutnya Paulus membawa orang-orang itu serta dengan dia, dan ia mentahirkan diri bersama-sama dengan mereka, lalu masuk ke Bait Allah untuk memberitahukan, bilamana pentahiran akan selesai dan persembahan akan dipersembahkan untuk mereka masing-masing.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 27, 'Ketika masa tujuh hari itu sudah hampir berakhir, orang-orang Yahudi yang datang dari Asia, melihat Paulus di dalam Bait Allah, lalu mereka menghasut rakyat dan menangkap dia,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 28, 'sambil berteriak: "Hai orang-orang Israel, tolong! Inilah orang yang di mana-mana mengajar semua orang untuk menentang bangsa kita dan menentang hukum Taurat dan tempat ini! Dan sekarang ia membawa orang-orang Yunani pula ke dalam Bait Allah dan menajiskan tempat suci ini!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 29, 'Sebab mereka telah melihat Trofimus dari Efesus sebelumnya bersama-sama dengan Paulus di kota, dan mereka menyangka, bahwa Paulus telah membawa dia ke dalam Bait Allah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 30, 'Maka gemparlah seluruh kota, dan rakyat datang berkerumun, lalu menangkap Paulus dan menyeretnya keluar dari Bait Allah dan seketika itu juga semua pintu gerbang Bait Allah itu ditutup.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 31, 'Sementara mereka merencanakan untuk membunuh dia, sampailah kabar kepada kepala pasukan, bahwa seluruh Yerusalem gempar.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 32, 'Kepala pasukan itu segera bergerak dengan prajurit-prajurit dan perwira-perwira dan maju mendapatkan orang banyak itu. Ketika mereka melihat dia dan prajurit-prajurit itu, berhentilah mereka memukul Paulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 33, 'Kepala pasukan itu mendekati Paulus, menangkapnya dan menyuruh mengikat dia dengan dua rantai, lalu bertanya siapakah dia dan apakah yang telah diperbuatnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 34, 'Tetapi dari antara orang banyak itu ada yang meneriakkan kepadanya ini, ada pula yang meneriakkan itu. Dan oleh karena keributan itu ia tidak dapat mengetahui apakah yang sebenarnya terjadi. Sebab itu ia menyuruh membawa Paulus ke markas.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 35, 'Ketika sampai ke tangga Paulus terpaksa didukung prajurit-prajurit karena berdesak-desaknya orang banyak,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 36, 'yang berbondong-bondong mengikuti dia, sambil berteriak: "Enyahkanlah dia!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 37, 'Ketika Paulus hendak dibawa masuk ke markas, ia berkata kepada kepala pasukan itu: "Bolehkah aku mengatakan sesuatu kepadamu?" Jawabnya: "Tahukah engkau bahasa Yunani?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 38, 'Jadi engkau bukan orang Mesir itu, yang baru-baru ini menimbulkan pemberontakan dan melarikan empat ribu orang pengacau bersenjata ke padang gurun?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 39, 'Paulus menjawab: "Aku adalah orang Yahudi, dari Tarsus, warga dari kota yang terkenal di Kilikia; aku minta, supaya aku diperbolehkan berbicara kepada orang banyak itu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 21, 40, 'Sesudah Paulus diperbolehkan oleh kepala pasukan, pergilah ia berdiri di tangga dan memberi isyarat dengan tangannya kepada rakyat itu; ketika suasana sudah tenang, mulailah ia berbicara kepada mereka dalam bahasa Ibrani, katanya:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 1, '"Hai saudara-saudara dan bapa-bapa, dengarkanlah, apa yang hendak kukatakan kepadamu sebagai pembelaan diri."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 2, 'Ketika orang banyak itu mendengar ia berbicara dalam bahasa Ibrani, makin tenanglah mereka. Ia berkata:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 3, '"Aku adalah orang Yahudi, lahir di Tarsus di tanah Kilikia, tetapi dibesarkan di kota ini; dididik dengan teliti di bawah pimpinan Gamaliel dalam hukum nenek moyang kita, sehingga aku menjadi seorang yang giat bekerja bagi Allah sama seperti kamu semua pada waktu ini.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 4, 'Dan aku telah menganiaya pengikut-pengikut Jalan Tuhan sampai mereka mati; laki-laki dan perempuan kutangkap dan kuserahkan ke dalam penjara.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 5, 'Tentang hal itu baik Imam Besar maupun Majelis Tua-Tua dapat memberi kesaksian. Dari mereka aku telah membawa surat-surat untuk saudara-saudara di Damsyik dan aku telah pergi ke sana untuk menangkap penganut-penganut Jalan Tuhan, yang terdapat juga di situ dan membawa mereka ke Yerusalem untuk dihukum.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 6, 'Tetapi dalam perjalananku ke sana, ketika aku sudah dekat Damsyik, yaitu waktu tengah hari, tiba-tiba memancarlah cahaya yang menyilaukan dari langit mengelilingi aku.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 7, 'Maka rebahlah aku ke tanah dan aku mendengar suatu suara yang berkata kepadaku: Saulus, Saulus, mengapakah engkau menganiaya Aku?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 8, 'Jawabku: Siapakah Engkau, Tuhan? Kata-Nya: Akulah Yesus, orang Nazaret, yang kauaniaya itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 9, 'Dan mereka yang menyertai aku, memang melihat cahaya itu, tetapi suara Dia, yang berkata kepadaku, tidak mereka dengar.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 10, 'Maka kataku: Tuhan, apakah yang harus kuperbuat? Kata Tuhan kepadaku: Bangkitlah dan pergilah ke Damsyik. Di sana akan diberitahukan kepadamu segala sesuatu yang ditugaskan kepadamu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 11, 'Dan karena aku tidak dapat melihat oleh karena cahaya yang menyilaukan mata itu, maka kawan-kawan seperjalananku memegang tanganku dan menuntun aku ke Damsyik.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 12, 'Di situ ada seorang bernama Ananias, seorang saleh yang menurut hukum Taurat dan terkenal baik di antara semua orang Yahudi yang ada di situ.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 13, 'Ia datang berdiri di dekatku dan berkata: Saulus, saudaraku, bukalah matamu dan melihatlah! Dan seketika itu juga aku melihat kembali dan menatap dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 14, 'Lalu katanya: Allah nenek moyang kita telah menetapkan engkau untuk mengetahui kehendak-Nya, untuk melihat Yang Benar dan untuk mendengar suara yang keluar dari mulut-Nya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 15, 'Sebab engkau harus menjadi saksi-Nya terhadap semua orang tentang apa yang kaulihat dan yang kaudengar.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 16, 'Dan sekarang, mengapa engkau masih ragu-ragu? Bangunlah, berilah dirimu dibaptis dan dosa-dosamu disucikan sambil berseru kepada nama Tuhan!', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 17, 'Sesudah aku kembali di Yerusalem dan ketika aku sedang berdoa di dalam Bait Allah, rohku diliputi oleh kuasa ilahi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 18, 'Aku melihat Dia, yang berkata kepadaku: Lekaslah, segeralah tinggalkan Yerusalem, sebab mereka tidak akan menerima kesaksianmu tentang Aku.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 19, 'Jawabku: Tuhan, mereka tahu, bahwa akulah yang pergi dari rumah ibadat yang satu ke rumah ibadat yang lain dan yang memasukkan mereka yang percaya kepada-Mu ke dalam penjara dan menyesah mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 20, 'Dan ketika darah Stefanus, saksi-Mu itu, ditumpahkan, aku ada di situ dan menyetujui perbuatan itu dan aku menjaga pakaian mereka yang membunuhnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 21, 'Tetapi kata Tuhan kepadaku: Pergilah, sebab Aku akan mengutus engkau jauh dari sini kepada bangsa-bangsa lain."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 22, 'Rakyat mendengarkan Paulus sampai kepada perkataan itu; tetapi sesudah itu, mereka mulai berteriak, katanya: "Enyahkan orang ini dari muka bumi! Ia tidak layak hidup!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 23, 'Mereka terus berteriak sambil melemparkan jubah mereka dan menghamburkan debu ke udara.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 24, 'Karena itu kepala pasukan memberi perintah untuk membawa Paulus ke markas dan menyuruh memeriksa dan menyesah dia, supaya dapat diketahui apa sebabnya orang banyak itu berteriak-teriak sedemikian terhadap dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 25, 'Tetapi ketika Paulus ditelentangkan untuk disesah, berkatalah ia kepada perwira yang bertugas: "Bolehkah kamu menyesah seorang warganegara Rum, apalagi tanpa diadili?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 26, 'Mendengar perkataan itu perwira itu melaporkannya kepada kepala pasukan, katanya: "Apakah yang hendak engkau perbuat? Orang itu warganegara Rum."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 27, 'Maka datanglah kepala pasukan itu kepada Paulus dan berkata: "Katakanlah, benarkah engkau warganegara Rum?" Jawab Paulus: "Benar."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 28, 'Lalu kata kepala pasukan itu: "Kewarganegaraan itu kubeli dengan harga yang mahal." Jawab Paulus: "Tetapi aku mempunyai hak itu karena kelahiranku."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 29, 'Maka mereka yang harus menyesah dia, segera mundur; dan kepala pasukan itu juga takut, setelah ia tahu, bahwa Paulus, yang ia suruh ikat itu, adalah orang Rum.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 22, 30, 'Namun kepala pasukan itu ingin mengetahui dengan teliti apa yang dituduhkan orang-orang Yahudi kepada Paulus. Karena itu pada keesokan harinya ia menyuruh mengambil Paulus dari penjara dan memerintahkan, supaya imam-imam kepala dan seluruh Mahkamah Agama berkumpul. Lalu ia membawa Paulus dari markas dan menghadapkannya kepada mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 1, 'Sambil menatap anggota-anggota Mahkamah Agama, Paulus berkata: "Hai saudara-saudaraku, sampai kepada hari ini aku tetap hidup dengan hati nurani yang murni di hadapan Allah."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 2, 'Tetapi Imam Besar Ananias menyuruh orang-orang yang berdiri dekat Paulus menampar mulut Paulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 3, 'Membalas itu Paulus berkata kepadanya: "Allah akan menampar engkau, hai tembok yang dikapur putih-putih! Engkau duduk di sini untuk menghakimi aku menurut hukum Taurat, namun engkau melanggar hukum Taurat oleh perintahmu untuk menampar aku."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 4, 'Dan orang-orang yang hadir di situ berkata: "Engkau mengejek Imam Besar Allah?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 5, 'Jawab Paulus: "Hai saudara-saudara, aku tidak tahu, bahwa ia adalah Imam Besar. Memang ada tertulis: Janganlah engkau berkata jahat tentang seorang pemimpin bangsamu!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 6, 'Dan karena ia tahu, bahwa sebagian dari mereka itu termasuk golongan orang Saduki dan sebagian termasuk golongan orang Farisi, ia berseru dalam Mahkamah Agama itu, katanya: "Hai saudara-saudaraku, aku adalah orang Farisi, keturunan orang Farisi; aku dihadapkan ke Mahkamah ini, karena aku mengharap akan kebangkitan orang mati."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 7, 'Ketika ia berkata demikian, timbullah perpecahan antara orang-orang Farisi dan orang-orang Saduki dan terbagi-bagilah orang banyak itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 8, 'Sebab orang-orang Saduki mengatakan, bahwa tidak ada kebangkitan dan tidak ada malaikat atau roh, tetapi orang-orang Farisi mengakui kedua-duanya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 9, 'Maka terjadilah keributan besar. Beberapa ahli Taurat dari golongan Farisi tampil ke depan dan membantah dengan keras, katanya: "Kami sama sekali tidak menemukan sesuatu yang salah pada orang ini! Barangkali ada roh atau malaikat yang telah berbicara kepadanya."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 10, 'Maka terjadilah perpecahan besar, sehingga kepala pasukan takut, kalau-kalau mereka akan mengoyak-ngoyak Paulus. Karena itu ia memerintahkan pasukan untuk turun ke bawah dan mengambil Paulus dari tengah-tengah mereka dan membawanya ke markas.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 11, 'Pada malam berikutnya Tuhan datang berdiri di sisinya dan berkata kepadanya: "Kuatkanlah hatimu, sebab sebagaimana engkau dengan berani telah bersaksi tentang Aku di Yerusalem, demikian jugalah hendaknya engkau pergi bersaksi di Roma."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 12, 'Dan setelah hari siang orang-orang Yahudi mengadakan komplotan dan bersumpah dengan mengutuk diri, bahwa mereka tidak akan makan atau minum, sebelum mereka membunuh Paulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 13, 'Jumlah mereka yang mengadakan komplotan itu lebih dari pada empat puluh orang.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 14, 'Mereka pergi kepada imam-imam kepala dan tua-tua bangsa Yahudi dan berkata: "Kami telah bersumpah dengan mengutuk diri, bahwa kami tidak akan makan atau minum, sebelum kami membunuh Paulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 15, 'Karena itu hendaklah kamu bersama-sama dengan Mahkamah Agama menganjurkan kepada kepala pasukan, supaya ia menghadapkan Paulus lagi kepada kamu, seolah-olah kamu hendak memeriksa perkaranya lebih teliti, dan sementara itu kami sudah siap sedia untuk membunuh dia sebelum ia sampai kepada kamu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 16, 'Akan tetapi kemenakan Paulus, anak saudaranya perempuan, mendengar tentang penghadangan itu. Ia datang ke markas dan setelah diizinkan masuk, ia memberitahukannya kepada Paulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 17, 'Lalu Paulus memanggil salah seorang perwira dan berkata kepadanya: "Bawalah anak ini kepada kepala pasukan, karena ada sesuatu yang perlu diberitahukannya kepadanya."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 18, 'Perwira itu membawanya kepada kepala pasukan dan berkata: "Paulus orang tahanan itu, memanggil aku dan meminta, supaya aku membawa anak muda ini kepadamu, sebab ada yang perlu diberitahukannya kepadamu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 19, 'Maka kepala pasukan itu memegang tangan anak muda itu, lalu membawanya ke samping dan bertanya: "Apakah yang perlu kauberitahukan kepadaku?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 20, 'Jawabnya: "Orang-orang Yahudi telah bersepakat untuk meminta kepadamu, supaya besok engkau menghadapkan Paulus lagi ke Mahkamah Agama, seolah-olah Mahkamah itu mau memperoleh keterangan yang lebih teliti dari padanya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 21, 'Akan tetapi janganlah engkau mendengarkan mereka, sebab lebih dari pada empat puluh orang dari mereka telah siap untuk menghadang dia. Mereka telah bersumpah dengan mengutuk diri, bahwa mereka tidak akan makan atau minum, sebelum mereka membunuh dia; sekarang mereka telah siap sedia dan hanya menantikan keputusanmu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 22, 'Lalu kepala pasukan menyuruh anak muda itu pulang dan memerintahkan kepadanya: "Jangan katakan kepada siapapun juga, bahwa engkau telah memberitahukan hal ini kepadaku."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 23, 'Kemudian kepala pasukan memanggil dua perwira dan berkata: "Siapkan dua ratus orang prajurit untuk berangkat ke Kaisarea beserta tujuh puluh orang berkuda dan dua ratus orang bersenjata lembing, kira-kira pada jam sembilan malam ini.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 24, 'Sediakan juga beberapa keledai tunggang untuk Paulus dan bawalah dia dengan selamat kepada wali negeri Feliks."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 25, 'Dan ia menulis surat, yang isinya sebagai berikut:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 26, '"Salam dari Klaudius Lisias kepada wali negeri Feliks yang mulia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 27, 'Orang ini ditangkap oleh orang-orang Yahudi dan ketika mereka hendak membunuhnya, aku datang dengan pasukan mencegahnya dan melepaskannya, karena aku dengar, bahwa ia adalah warganegara Roma.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 28, 'Untuk mengetahui apa alasannya mereka mendakwa dia, aku menghadapkannya ke Mahkamah Agama mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 29, 'Ternyatalah bagiku, bahwa ia didakwa karena soal-soal hukum Taurat mereka, tetapi tidak ada tuduhan, atas mana ia patut dihukum mati atau dipenjarakan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 30, 'Kepadaku telah diberitahukan, bahwa ada komplotan merencanakan membunuh dia. Karena itu aku segera menyuruh membawa dia kepadamu, sedang kepada para pendakwa telah kuberitahukan, bahwa mereka harus mengajukan perkara itu kepadamu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 31, 'Lalu prajurit-prajurit itu mengambil Paulus sesuai dengan yang diperintahkan kepada mereka dan membawanya pada waktu malam ke Antipatris.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 32, 'Pada keesokan harinya mereka membiarkan orang-orang berkuda dan Paulus meneruskan perjalanan, dan mereka sendiri pulang ke markas.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 33, 'Setibanya di Kaisarea orang-orang berkuda itu menyampaikan surat itu kepada wali negeri serta menyerahkan Paulus kepadanya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 34, 'Dan setelah membaca surat itu, wali negeri itu menanyakan Paulus dari propinsi manakah asalnya. Dan ketika ia mendengar, bahwa Paulus dari Kilikia,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 23, 35, 'ia berkata: "Aku akan memeriksa perkaramu, bila para pendakwamu juga telah tiba di sini." Lalu ia menyuruh menahan Paulus di istana Herodes.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 1, 'Lima hari kemudian datanglah Imam Besar Ananias bersama-sama dengan beberapa orang tua-tua dan seorang pengacara bernama Tertulus. Mereka menghadap wali negeri dan menyampaikan dakwaan mereka terhadap Paulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 2, 'Paulus dipanggil menghadap dan Tertulus mulai mendakwa dia, katanya: "Feliks yang mulia, oleh usahamu kami terus-menerus menikmati kesejahteraan, dan oleh kebijaksanaanmu banyak sekali perbaikan yang telah terlaksana untuk bangsa kami.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 3, 'Semuanya itu senantiasa dan di mana-mana kami sambut dengan sangat berterima kasih.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 4, 'Akan tetapi supaya jangan terlalu banyak menghabiskan waktumu, aku minta, supaya engkau mendengarkan kami sebentar dengan kemurahan hatimu yang terkenal itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 5, 'Telah nyata kepada kami, bahwa orang ini adalah penyakit sampar, seorang yang menimbulkan kekacauan di antara semua orang Yahudi di seluruh dunia yang beradab, dan bahwa ia adalah seorang tokoh dari sekte orang Nasrani.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 6, 'Malahan ia mencoba melanggar kekudusan Bait Allah. Oleh karena itu kami menangkap dia dan hendak menghakiminya menurut hukum Taurat kami.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 7, 'Tetapi kepala pasukan Lisias datang mencegahnya dan merebut dia dengan kekerasan dari tangan kami,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 8, 'lalu menyuruh para pendakwa datang menghadap engkau. Jika engkau sendiri memeriksa dia, dapatlah engkau mengetahui segala sesuatu yang kami tuduhkan kepadanya."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 9, 'Dan juga orang-orang Yahudi menyokong dakwaan itu dengan mengatakan, bahwa perkara itu sungguh demikian.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 10, 'Lalu wali negeri itu memberi isyarat kepada Paulus, bahwa ia boleh berbicara. Maka berkatalah Paulus: "Aku tahu, bahwa sudah bertahun-tahun lamanya engkau menjadi hakim atas bangsa ini. Karena itu tanpa ragu-ragu aku membela perkaraku ini di hadapanmu:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 11, 'Engkau dapat memastikan, bahwa tidak lebih dari dua belas hari yang lalu aku datang ke Yerusalem untuk beribadah.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 12, 'Dan tidak pernah orang mendapati aku sedang bertengkar dengan seseorang atau mengadakan huru-hara, baik di dalam Bait Allah, maupun di dalam rumah ibadat, atau di tempat lain di kota.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 13, 'Dan mereka tidak dapat membuktikan kepadamu apa yang sekarang dituduhkan mereka kepada diriku.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 14, 'Tetapi aku mengakui kepadamu, bahwa aku berbakti kepada Allah nenek moyang kami dengan menganut Jalan Tuhan, yaitu Jalan yang mereka sebut sekte. Aku percaya kepada segala sesuatu yang ada tertulis dalam hukum Taurat dan dalam kitab nabi-nabi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 15, 'Aku menaruh pengharapan kepada Allah, sama seperti mereka juga, bahwa akan ada kebangkitan semua orang mati, baik orang-orang yang benar maupun orang-orang yang tidak benar.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 16, 'Sebab itu aku senantiasa berusaha untuk hidup dengan hati nurani yang murni di hadapan Allah dan manusia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 17, 'Dan setelah beberapa tahun lamanya aku datang kembali ke Yerusalem untuk membawa pemberian bagi bangsaku dan untuk mempersembahkan persembahan-persembahan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 18, 'Sementara aku melakukan semuanya itu, beberapa orang Yahudi dari Asia mendapati aku di dalam Bait Allah, sesudah aku selesai mentahirkan diriku, tanpa orang banyak dan tanpa keributan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 19, 'Merekalah yang sebenarnya harus menghadap engkau di sini dan mengajukan dakwaan mereka, jika mereka mempunyai sesuatu terhadap aku.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 20, 'Namun biarlah orang-orang yang hadir di sini sekarang menyatakan kejahatan apakah yang mereka dapati, ketika aku dihadapkan di Mahkamah Agama.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 21, 'Atau mungkinkah karena satu-satunya perkataan yang aku serukan, ketika aku berdiri di tengah-tengah mereka, yakni: Karena hal kebangkitan orang-orang mati, aku hari ini dihadapkan kepada kamu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 22, 'Tetapi Feliks yang tahu benar-benar akan Jalan Tuhan, menangguhkan perkara mereka, katanya: "Setibanya kepala pasukan Lisias di sini, aku akan mengambil keputusan dalam perkaramu."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 23, 'Lalu ia menyuruh perwira itu tetap menahan Paulus, tetapi dengan tahanan ringan, dan tidak boleh mencegah sahabat-sahabatnya melayani dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 24, 'Dan setelah beberapa hari datanglah Feliks bersama-sama dengan isterinya Drusila, seorang Yahudi; ia menyuruh memanggil Paulus, lalu mendengar dari padanya tentang kepercayaan kepada Yesus Kristus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 25, 'Tetapi ketika Paulus berbicara tentang kebenaran, penguasaan diri dan penghakiman yang akan datang, Feliks menjadi takut dan berkata: "Cukuplah dahulu dan pergilah sekarang; apabila ada kesempatan baik, aku akan menyuruh memanggil engkau."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 26, 'Sementara itu ia berharap, bahwa Paulus akan memberikan uang kepadanya. Karena itu ia sering memanggilnya untuk bercakap-cakap dengan dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 24, 27, 'Tetapi sesudah genap dua tahun, Feliks digantikan oleh Perkius Festus, dan untuk mengambil hati orang Yahudi, ia membiarkan Paulus tetap dalam penjara.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 1, 'Tiga hari sesudah tiba di propinsi itu berangkatlah Festus dari Kaisarea ke Yerusalem.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 2, 'Di situ imam-imam kepala dan orang-orang Yahudi yang terkemuka datang menghadap dia dan menyampaikan dakwaan terhadap Paulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 3, 'Kepadanya mereka meminta suatu anugerah, yang merugikan Paulus, yaitu untuk menyuruh Paulus datang ke Yerusalem. Sebab mereka sedang membuat rencana untuk membunuh dia di tengah jalan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 4, 'Tetapi Festus menjawab, bahwa Paulus tetap ditahan di Kaisarea dan bahwa ia sendiri bermaksud untuk segera kembali ke sana.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 5, 'Katanya: "Karena itu baiklah orang-orang yang berwewenang di antara kamu turut ke sana bersama-sama dengan aku dan mengajukan dakwaan terhadap dia, jika ada kesalahannya."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 6, 'Festus tinggal tidak lebih dari pada delapan atau sepuluh hari di Yerusalem. Sesudah itu ia pulang ke Kaisarea. Pada keesokan harinya ia mengadakan sidang pengadilan, dan menyuruh menghadapkan Paulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 7, 'Sesudah Paulus tiba di situ, semua orang Yahudi yang datang dari Yerusalem berdiri mengelilinginya dan mereka mengemukakan banyak tuduhan berat terhadap dia yang tidak dapat mereka buktikan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 8, 'Sebaliknya Paulus membela diri, katanya: "Aku sedikitpun tidak bersalah, baik terhadap hukum Taurat orang Yahudi maupun terhadap Bait Allah atau terhadap Kaisar."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 9, 'Tetapi Festus yang hendak mengambil hati orang Yahudi, menjawab Paulus, katanya: "Apakah engkau bersedia pergi ke Yerusalem, supaya engkau dihakimi di sana di hadapanku tentang perkara ini?"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 10, 'Tetapi kata Paulus: "Aku sekarang berdiri di sini di hadapan pengadilan Kaisar dan di sinilah aku harus dihakimi. Seperti engkau sendiri tahu benar-benar, sedikitpun aku tidak berbuat salah terhadap orang Yahudi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 11, 'Jadi, jika aku benar-benar bersalah dan berbuat sesuatu kejahatan yang setimpal dengan hukuman mati, aku rela mati, tetapi, jika apa yang mereka tuduhkan itu terhadap aku ternyata tidak benar, tidak ada seorangpun yang berhak menyerahkan aku sebagai suatu anugerah kepada mereka. Aku naik banding kepada Kaisar!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 12, 'Setelah berunding dengan anggota-anggota pengadilan, Festus menjawab: "Engkau telah naik banding kepada Kaisar, jadi engkau harus pergi menghadap Kaisar."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 13, 'Beberapa hari kemudian datanglah raja Agripa dengan Bernike ke Kaisarea untuk mengadakan kunjungan kehormatan kepada Festus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 14, 'Karena mereka beberapa hari lamanya tinggal di situ, Festus memaparkan perkara Paulus kepada raja itu, katanya: "Di sini ada seorang tahanan yang ditinggalkan Feliks pada waktu ia pergi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 15, 'Ketika aku berada di Yerusalem, imam-imam kepala dan tua-tua orang Yahudi mengajukan dakwaan terhadap orang itu dan meminta supaya ia dihukum.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 16, 'Aku menjawab mereka, bahwa bukanlah kebiasaan pada orang-orang Roma untuk menyerahkan seorang terdakwa sebagai suatu anugerah sebelum ia dihadapkan dengan orang-orang yang menuduhnya dan diberi kesempatan untuk membela diri terhadap tuduhan itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 17, 'Karena itu mereka turut bersama-sama dengan aku ke mari. Pada keesokan harinya aku segera mengadakan sidang pengadilan dan menyuruh menghadapkan orang itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 18, 'Tetapi ketika para pendakwa berdiri di sekelilingnya, mereka tidak mengajukan suatu tuduhanpun tentang perbuatan jahat seperti yang telah aku duga.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 19, 'Tetapi mereka hanya berselisih paham dengan dia tentang soal-soal agama mereka, dan tentang seorang bernama Yesus, yang sudah mati, sedangkan Paulus katakan dengan pasti, bahwa Ia hidup.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 20, 'Karena aku ragu-ragu bagaimana aku harus memeriksa perkara-perkara seperti itu, aku menanyakan apakah ia mau pergi ke Yerusalem, supaya perkaranya dihakimi di situ.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 21, 'Tetapi Paulus naik banding. Ia minta, supaya ia tinggal dalam tahanan dan menunggu, sampai perkaranya diputuskan oleh Kaisar. Karena itu aku menyuruh menahan dia sampai aku dapat mengirim dia kepada Kaisar."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 22, 'Kata Agripa kepada Festus: "Aku ingin mendengar orang itu sendiri." Jawab Festus: "Besok engkau akan mendengar dia."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 23, 'Pada keesokan harinya datanglah Agripa dan Bernike dengan segala kebesaran dan sesudah mereka masuk ruang pengadilan bersama-sama dengan kepala-kepala pasukan dan orang-orang yang terkemuka dari kota itu, Festus memberi perintah, supaya Paulus dihadapkan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 24, 'Festus berkata: "Ya raja Agripa serta semua yang hadir di sini bersama-sama dengan kami. Lihatlah orang ini, yang dituduh oleh semua orang Yahudi, baik yang di Yerusalem, maupun yang di sini. Mereka telah datang kepadaku dan sambil berteriak-teriak mereka mengatakan, bahwa ia tidak boleh hidup lebih lama.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 25, 'Tetapi ternyata kepadaku, bahwa ia tidak berbuat sesuatupun yang setimpal dengan hukuman mati dan karena ia naik banding kepada Kaisar, aku memutuskan untuk mengirim dia menghadap Kaisar.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 26, 'Tetapi tidak ada apa-apa yang pasti yang harus kutulis kepada Kaisar tentang dia. Itulah sebabnya aku menghadapkan dia di sini kepada kamu semua, terutama kepadamu, raja Agripa, supaya, setelah diadakan pemeriksaan, aku dapat menuliskan sesuatu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 25, 27, 'Sebab pada hematku tidaklah wajar untuk mengirim seorang tahanan dengan tidak menyatakan tuduhan-tuduhan yang diajukan terhadap dia."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 1, 'Kata Agripa kepada Paulus: "Engkau diberi kesempatan untuk membela diri." Paulus memberi isyarat dengan tangannya, lalu memberi pembelaannya seperti berikut:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 2, '"Ya raja Agripa, aku merasa berbahagia, karena pada hari ini aku diperkenankan untuk memberi pertanggungan jawab di hadapanmu terhadap segala tuduhan yang diajukan orang-orang Yahudi terhadap diriku,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 3, 'terutama karena engkau tahu benar-benar adat istiadat dan persoalan orang Yahudi. Sebab itu aku minta kepadamu, supaya engkau mendengarkan aku dengan sabar.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 4, 'Semua orang Yahudi mengetahui jalan hidupku sejak masa mudaku, sebab dari semula aku hidup di tengah-tengah bangsaku di Yerusalem.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 5, 'Sudah lama mereka mengenal aku dan sekiranya mereka mau, mereka dapat memberi kesaksian, bahwa aku telah hidup sebagai seorang Farisi menurut mazhab yang paling keras dalam agama kita.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 6, 'Dan sekarang aku harus menghadap pengadilan oleh sebab aku mengharapkan kegenapan janji, yang diberikan Allah kepada nenek moyang kita,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 7, 'dan yang dinantikan oleh kedua belas suku kita, sementara mereka siang malam melakukan ibadahnya dengan tekun. Dan karena pengharapan itulah, ya raja Agripa, aku dituduh orang-orang Yahudi.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 8, 'Mengapa kamu menganggap mustahil, bahwa Allah membangkitkan orang mati?', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 9, 'Bagaimanapun juga, aku sendiri pernah menyangka, bahwa aku harus keras bertindak menentang nama Yesus dari Nazaret.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 10, 'Hal itu kulakukan juga di Yerusalem. Aku bukan saja telah memasukkan banyak orang kudus ke dalam penjara, setelah aku memperoleh kuasa dari imam-imam kepala, tetapi aku juga setuju, jika mereka dihukum mati.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 11, 'Dalam rumah-rumah ibadat aku sering menyiksa mereka dan memaksanya untuk menyangkal imannya dan dalam amarah yang meluap-luap aku mengejar mereka, bahkan sampai ke kota-kota asing."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 12, '"Dan dalam keadaan demikian, ketika aku dengan kuasa penuh dan tugas dari imam-imam kepala sedang dalam perjalanan ke Damsyik,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 13, 'tiba-tiba, ya raja Agripa, pada tengah hari bolong aku melihat di tengah jalan itu cahaya yang lebih terang dari pada cahaya matahari, turun dari langit meliputi aku dan teman-teman seperjalananku.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 14, 'Kami semua rebah ke tanah dan aku mendengar suatu suara yang mengatakan kepadaku dalam bahasa Ibrani: Saulus, Saulus, mengapa engkau menganiaya Aku? Sukar bagimu menendang ke galah rangsang.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 15, 'Tetapi aku menjawab: Siapa Engkau, Tuhan? Kata Tuhan: Akulah Yesus, yang kauaniaya itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 16, 'Tetapi sekarang, bangunlah dan berdirilah. Aku menampakkan diri kepadamu untuk menetapkan engkau menjadi pelayan dan saksi tentang segala sesuatu yang telah kaulihat dari pada-Ku dan tentang apa yang akan Kuperlihatkan kepadamu nanti.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 17, 'Aku akan mengasingkan engkau dari bangsa ini dan dari bangsa-bangsa lain. Dan Aku akan mengutus engkau kepada mereka,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 18, 'untuk membuka mata mereka, supaya mereka berbalik dari kegelapan kepada terang dan dari kuasa Iblis kepada Allah, supaya mereka oleh iman mereka kepada-Ku memperoleh pengampunan dosa dan mendapat bagian dalam apa yang ditentukan untuk orang-orang yang dikuduskan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 19, 'Sebab itu, ya raja Agripa, kepada penglihatan yang dari sorga itu tidak pernah aku tidak taat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 20, 'Tetapi mula-mula aku memberitakan kepada orang-orang Yahudi di Damsyik, di Yerusalem dan di seluruh tanah Yudea, dan juga kepada bangsa-bangsa lain, bahwa mereka harus bertobat dan berbalik kepada Allah serta melakukan pekerjaan-pekerjaan yang sesuai dengan pertobatan itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 21, 'Karena itulah orang-orang Yahudi menangkap aku di Bait Allah, dan mencoba membunuh aku.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 22, 'Tetapi oleh pertolongan Allah aku dapat hidup sampai sekarang dan memberi kesaksian kepada orang-orang kecil dan orang-orang besar. Dan apa yang kuberitakan itu tidak lain dari pada yang sebelumnya telah diberitahukan oleh para nabi dan juga oleh Musa,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 23, 'yaitu, bahwa Mesias harus menderita sengsara dan bahwa Ia adalah yang pertama yang akan bangkit dari antara orang mati, dan bahwa Ia akan memberitakan terang kepada bangsa ini dan kepada bangsa-bangsa lain."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 24, 'Sementara Paulus mengemukakan semuanya itu untuk mempertanggungjawabkan pekerjaannya, berkatalah Festus dengan suara keras: "Engkau gila, Paulus! Ilmumu yang banyak itu membuat engkau gila."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 25, 'Tetapi Paulus menjawab: "Aku tidak gila, Festus yang mulia! Aku mengatakan kebenaran dengan pikiran yang sehat!', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 26, 'Raja juga tahu tentang segala perkara ini, sebab itu aku berani berbicara terus terang kepadanya. Aku yakin, bahwa tidak ada sesuatupun dari semuanya ini yang belum didengarnya, karena perkara ini tidak terjadi di tempat yang terpencil.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 27, 'Percayakah engkau, raja Agripa, kepada para nabi? Aku tahu, bahwa engkau percaya kepada mereka."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 28, 'Jawab Agripa: "Hampir-hampir saja kauyakinkan aku menjadi orang Kristen!"', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 29, 'Kata Paulus: "Aku mau berdoa kepada Allah, supaya segera atau lama-kelamaan bukan hanya engkau saja, tetapi semua orang lain yang hadir di sini dan yang mendengarkan perkataanku menjadi sama seperti aku, kecuali belenggu-belenggu ini."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 30, 'Lalu bangkitlah raja dan wali negeri serta Bernike dan semua orang yang duduk bersama-sama mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 31, 'Sementara mereka keluar, mereka berkata seorang kepada yang lain: "Orang itu tidak melakukan sesuatu yang setimpal dengan hukuman mati atau hukuman penjara."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 26, 32, 'Kata Agripa kepada Festus: "Orang itu sebenarnya sudah dapat dibebaskan sekiranya ia tidak naik banding kepada Kaisar."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 1, 'Setelah diputuskan, bahwa kami akan berlayar ke Italia, maka Paulus dan beberapa orang tahanan lain diserahkan kepada seorang perwira yang bernama Yulius dari pasukan Kaisar.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 2, 'Kami naik ke sebuah kapal dari Adramitium yang akan berangkat ke pelabuhan-pelabuhan di sepanjang pantai Asia, lalu kami bertolak. Aristarkhus, seorang Makedonia dari Tesalonika, menyertai kami.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 3, 'Pada keesokan harinya kami singgah di Sidon. Yulius memperlakukan Paulus dengan ramah dan memperbolehkannya mengunjungi sahabat-sahabatnya, supaya mereka melengkapkan keperluannya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 4, 'Oleh karena angin sakal kami berlayar dari situ menyusur pantai Siprus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 5, 'Dan setelah mengarungi laut di depan Kilikia dan Pamfilia, sampailah kami di Mira, di daerah Likia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 6, 'Di situ perwira kami menemukan sebuah kapal dari Aleksandria yang hendak berlayar ke Italia. Ia memindahkan kami ke kapal itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 7, 'Selama beberapa hari berlayar, kami hampir-hampir tidak maju dan dengan susah payah kami mendekati Knidus. Karena angin tetap tidak baik, kami menyusur pantai Kreta melewati tanjung Salmone.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 8, 'Sesudah kami dengan susah payah melewati tanjung itu, sampailah kami di sebuah tempat bernama Pelabuhan Indah, dekat kota Lasea.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 9, 'Sementara itu sudah banyak waktu yang hilang. Waktu puasa sudah lampau dan sudah berbahaya untuk melanjutkan pelayaran. Sebab itu Paulus memperingatkan mereka, katanya:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 10, '"Saudara-saudara, aku lihat, bahwa pelayaran kita akan mendatangkan kesukaran-kesukaran dan kerugian besar, bukan saja bagi muatan dan kapal, tetapi juga bagi nyawa kita."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 11, 'Tetapi perwira itu lebih percaya kepada jurumudi dan nakhoda dari pada kepada perkataan Paulus.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 12, 'Karena pelabuhan itu tidak baik untuk tinggal di situ selama musim dingin, maka kebanyakan dari mereka lebih setuju untuk berlayar terus dan mencoba mencapai kota Feniks untuk tinggal di situ selama musim dingin. Kota Feniks adalah sebuah pelabuhan pulau Kreta, yang terbuka ke arah barat daya dan ke arah barat laut.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 13, 'Pada waktu itu angin sepoi-sepoi bertiup dari selatan. Mereka menyangka, bahwa maksud mereka sudah tentu akan tercapai. Mereka membongkar sauh, lalu berlayar dekat sekali menyusur pantai Kreta.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 14, 'Tetapi tidak berapa lama kemudian turunlah dari arah pulau itu angin badai, yang disebut angin "Timur Laut".', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 15, 'Kapal itu dilandanya dan tidak tahan menghadapi angin haluan. Karena itu kami menyerah saja dan membiarkan kapal kami terombang-ambing.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 16, 'Kemudian kami hanyut sampai ke pantai sebuah pulau kecil bernama Kauda, dan di situ dengan susah payah kami dapat menguasai sekoci kapal itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 17, 'Dan setelah sekoci itu dinaikkan ke atas kapal, mereka memasang alat-alat penolong dengan meliliti kapal itu dengan tali. Dan karena takut terdampar di beting Sirtis, mereka menurunkan layar dan membiarkan kapal itu terapung-apung saja.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 18, 'Karena kami sangat hebat diombang-ambingkan angin badai, maka pada keesokan harinya mereka mulai membuang muatan kapal ke laut.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 19, 'Dan pada hari yang ketiga mereka membuang alat-alat kapal dengan tangan mereka sendiri.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 20, 'Setelah beberapa hari lamanya baik matahari maupun bintang-bintang tidak kelihatan, dan angin badai yang dahsyat terus-menerus mengancam kami, akhirnya putuslah segala harapan kami untuk dapat menyelamatkan diri kami.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 21, 'Dan karena mereka beberapa lamanya tidak makan, berdirilah Paulus di tengah-tengah mereka dan berkata: "Saudara-saudara, jika sekiranya nasihatku dituruti, supaya kita jangan berlayar dari Kreta, kita pasti terpelihara dari kesukaran dan kerugian ini!', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 22, 'Tetapi sekarang, juga dalam kesukaran ini, aku menasihatkan kamu, supaya kamu tetap bertabah hati, sebab tidak seorangpun di antara kamu yang akan binasa, kecuali kapal ini.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 23, 'Karena tadi malam seorang malaikat dari Allah, yaitu dari Allah yang aku sembah sebagai milik-Nya, berdiri di sisiku,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 24, 'dan ia berkata: Jangan takut, Paulus! Engkau harus menghadap Kaisar; dan sesungguhnya oleh karunia Allah, maka semua orang yang ada bersama-sama dengan engkau di kapal ini akan selamat karena engkau.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 25, 'Sebab itu tabahkanlah hatimu, saudara-saudara! Karena aku percaya kepada Allah, bahwa semuanya pasti terjadi sama seperti yang dinyatakan kepadaku.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 26, 'Namun kita harus mendamparkan kapal ini di salah satu pulau."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 27, 'Malam yang keempat belas sudah tiba dan kami masih tetap terombang-ambing di laut Adria. Tetapi kira-kira tengah malam anak-anak kapal merasa, bahwa mereka telah dekat daratan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 28, 'Lalu mereka mengulurkan batu duga, dan ternyata air di situ dua puluh depa dalamnya. Setelah maju sedikit mereka menduga lagi dan ternyata lima belas depa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 29, 'Dan karena takut, bahwa kami akan terkandas di salah satu batu karang, mereka membuang empat sauh di buritan, dan kami sangat berharap mudah-mudahan hari lekas siang.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 30, 'Akan tetapi anak-anak kapal berusaha untuk melarikan diri dari kapal. Mereka menurunkan sekoci, dan berbuat seolah-olah mereka hendak melabuhkan beberapa sauh di haluan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 31, 'Karena itu Paulus berkata kepada perwira dan prajurit-prajuritnya: "Jika mereka tidak tinggal di kapal, kamu tidak mungkin selamat."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 32, 'Lalu prajurit-prajurit itu memotong tali sekoci dan membiarkannya hanyut.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 33, 'Ketika hari menjelang siang, Paulus mengajak semua orang untuk makan, katanya: "Sudah empat belas hari lamanya kamu menanti-nanti saja, menahan lapar dan tidak makan apa-apa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 34, 'Karena itu aku menasihati kamu, supaya kamu makan dahulu. Hal itu perlu untuk keselamatanmu. Tidak seorangpun di antara kamu akan kehilangan sehelaipun dari rambut kepalanya."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 35, 'Sesudah berkata demikian, ia mengambil roti, mengucap syukur kepada Allah di hadapan semua mereka, memecah-mecahkannya, lalu mulai makan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 36, 'Maka kuatlah hati semua orang itu, dan merekapun makan juga.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 37, 'Jumlah kami semua yang di kapal itu dua ratus tujuh puluh enam jiwa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 38, 'Setelah makan kenyang, mereka membuang muatan gandum ke laut untuk meringankan kapal itu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 39, 'Dan ketika hari mulai siang, mereka melihat suatu teluk yang rata pantainya. Walaupun mereka tidak mengenal daratan itu, mereka memutuskan untuk sedapat mungkin mendamparkan kapal itu ke situ.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 40, 'Mereka melepaskan tali-tali sauh, lalu meninggalkan sauh-sauh itu di dasar laut. Sementara itu mereka mengulurkan tali-tali kemudi, memasang layar topang, supaya angin meniup kapal itu menuju pantai.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 41, 'Tetapi mereka melanggar busung pasir, dan terkandaslah kapal itu. Haluannya terpancang dan tidak dapat bergerak dan buritannya hancur dipukul oleh gelombang yang hebat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 42, 'Pada waktu itu prajurit-prajurit bermaksud untuk membunuh tahanan-tahanan, supaya jangan ada seorangpun yang melarikan diri dengan berenang.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 43, 'Tetapi perwira itu ingin menyelamatkan Paulus. Karena itu ia menggagalkan maksud mereka, dan memerintahkan, supaya orang-orang yang pandai berenang lebih dahulu terjun ke laut dan naik ke darat,', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 27, 44, 'dan supaya orang-orang lain menyusul dengan mempergunakan papan atau pecahan-pecahan kapal. Demikianlah mereka semua selamat naik ke darat.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 1, 'Setelah kami tiba dengan selamat di pantai, barulah kami tahu, bahwa daratan itu adalah pulau Malta.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 2, 'Penduduk pulau itu sangat ramah terhadap kami. Mereka menyalakan api besar dan mengajak kami semua ke situ karena telah mulai hujan dan hawanya dingin.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 3, 'Ketika Paulus memungut seberkas ranting-ranting dan meletakkannya di atas api, keluarlah seekor ular beludak karena panasnya api itu, lalu menggigit tangannya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 4, 'Ketika orang-orang itu melihat ular itu terpaut pada tangan Paulus, mereka berkata seorang kepada yang lain: "Orang ini sudah pasti seorang pembunuh, sebab, meskipun ia telah luput dari laut, ia tidak dibiarkan hidup oleh Dewi Keadilan."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 5, 'Tetapi Paulus mengibaskan ular itu ke dalam api, dan ia sama sekali tidak menderita sesuatu.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 6, 'Namun mereka menyangka, bahwa ia akan bengkak atau akan mati rebah seketika itu juga. Tetapi sesudah lama menanti-nanti, mereka melihat, bahwa tidak ada apa-apa yang terjadi padanya, maka sebaliknya mereka berpendapat, bahwa ia seorang dewa.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 7, 'Tidak jauh dari tempat itu ada tanah milik gubernur pulau itu. Gubernur itu namanya Publius. Ia menyambut kami dan menjamu kami dengan ramahnya selama tiga hari.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 8, 'Ketika itu ayah Publius terbaring karena sakit demam dan disentri. Paulus masuk ke kamarnya; ia berdoa serta menumpangkan tangan ke atasnya dan menyembuhkan dia.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 9, 'Sesudah peristiwa itu datanglah juga orang-orang sakit lain dari pulau itu dan merekapun disembuhkan juga.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 10, 'Mereka sangat menghormati kami dan ketika kami bertolak, mereka menyediakan segala sesuatu yang kami perlukan.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 11, 'Tiga bulan kemudian kami berangkat dari situ naik sebuah kapal dari Aleksandria yang selama musim dingin berlabuh di pulau itu. Kapal itu memakai lambang Dioskuri.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 12, 'Kami singgah di Sirakusa dan tinggal di situ tiga hari lamanya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 13, 'Dari situ kami menyusur pantai, lalu sampai ke Regium. Sehari kemudian bertiuplah angin selatan dan pada hari kedua sampailah kami di Putioli.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 14, 'Di situ kami berjumpa dengan anggota-anggota jemaat, dan atas undangan mereka kami tinggal tujuh hari bersama-sama mereka. Sesudah itu kami berangkat ke Roma.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 15, 'Saudara-saudara yang di sana telah mendengar tentang hal ihwal kami dan mereka datang menjumpai kami sampai ke Forum Apius dan Tres Taberne. Ketika Paulus melihat mereka, ia mengucap syukur kepada Allah lalu kuatlah hatinya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 16, 'Setelah kami tiba di Roma, Paulus diperbolehkan tinggal dalam rumah sendiri bersama-sama seorang prajurit yang mengawalnya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 17, 'Tiga hari kemudian Paulus memanggil orang-orang terkemuka bangsa Yahudi dan setelah mereka berkumpul, Paulus berkata: "Saudara-saudara, meskipun aku tidak berbuat kesalahan terhadap bangsa kita atau terhadap adat istiadat nenek moyang kita, namun aku ditangkap di Yerusalem dan diserahkan kepada orang-orang Roma.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 18, 'Setelah aku diperiksa, mereka bermaksud melepaskan aku, karena tidak terdapat suatu kesalahanpun padaku yang setimpal dengan hukuman mati.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 19, 'Akan tetapi orang-orang Yahudi menentangnya dan karena itu terpaksalah aku naik banding kepada Kaisar, tetapi bukan dengan maksud untuk mengadukan bangsaku.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 20, 'Itulah sebabnya aku meminta, supaya aku melihat kamu dan berbicara dengan kamu, sebab justru karena pengharapan Israellah aku diikat dengan belenggu ini."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 21, 'Akan tetapi mereka berkata kepadanya: "Kami tidak menerima surat-surat dari Yudea tentang engkau dan juga tidak seorangpun dari saudara-saudara kita datang memberitakan apa-apa yang jahat mengenai engkau.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 22, 'Tetapi kami ingin mendengar dari engkau, bagaimana pikiranmu, sebab tentang mazhab ini kami tahu, bahwa di mana-manapun ia mendapat perlawanan."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 23, 'Lalu mereka menentukan suatu hari untuk Paulus. Pada hari yang ditentukan itu datanglah mereka dalam jumlah besar ke tempat tumpangannya. Ia menerangkan dan memberi kesaksian kepada mereka tentang Kerajaan Allah; dan berdasarkan hukum Musa dan kitab para nabi ia berusaha meyakinkan mereka tentang Yesus. Hal itu berlangsung dari pagi sampai sore.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 24, 'Ada yang dapat diyakinkan oleh perkataannya, ada yang tetap tidak percaya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 25, 'Maka bubarlah pertemuan itu dengan tidak ada kesesuaian di antara mereka. Tetapi Paulus masih mengatakan perkataan yang satu ini: "Tepatlah firman yang disampaikan Roh Kudus kepada nenek moyang kita dengan perantaraan nabi Yesaya:', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 26, 'Pergilah kepada bangsa ini, dan katakanlah: Kamu akan mendengar dan mendengar, namun tidak mengerti, kamu akan melihat dan melihat, namun tidak menanggap.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 27, 'Sebab hati bangsa ini telah menebal, dan telinganya berat mendengar, dan matanya melekat tertutup; supaya jangan mereka melihat dengan matanya dan mendengar dengan telinganya dan mengerti dengan hatinya, lalu berbalik sehingga Aku menyembuhkan mereka.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 28, 'Sebab itu kamu harus tahu, bahwa keselamatan yang dari pada Allah ini disampaikan kepada bangsa-bangsa lain dan mereka akan mendengarnya."', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 29, '(Dan setelah Paulus berkata demikian, pergilah orang-orang Yahudi itu dengan banyak perbedaan paham antara mereka.)', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 30, 'Dan Paulus tinggal dua tahun penuh di rumah yang disewanya sendiri itu; ia menerima semua orang yang datang kepadanya.', 'id', 'TB'),
  ('44', 'kis', 'Kisah Para Rasul', 28, 31, 'Dengan terus terang dan tanpa rintangan apa-apa ia memberitakan Kerajaan Allah dan mengajar tentang Tuhan Yesus Kristus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 1, 'Dari Paulus, hamba Kristus Yesus, yang dipanggil menjadi rasul dan dikuduskan untuk memberitakan Injil Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 2, 'Injil itu telah dijanjikan-Nya sebelumnya dengan perantaraan nabi-nabi-Nya dalam kitab-kitab suci,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 3, 'tentang Anak-Nya, yang menurut daging diperanakkan dari keturunan Daud,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 4, 'dan menurut Roh kekudusan dinyatakan oleh kebangkitan-Nya dari antara orang mati, bahwa Ia adalah Anak Allah yang berkuasa, Yesus Kristus Tuhan kita.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 5, 'Dengan perantaraan-Nya kami menerima kasih karunia dan jabatan rasul untuk menuntun semua bangsa, supaya mereka percaya dan taat kepada nama-Nya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 6, 'Kamu juga termasuk di antara mereka, kamu yang telah dipanggil menjadi milik Kristus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 7, 'Kepada kamu sekalian yang tinggal di Roma, yang dikasihi Allah, yang dipanggil dan dijadikan orang-orang kudus: Kasih karunia menyertai kamu dan damai sejahtera dari Allah, Bapa kita, dan dari Tuhan Yesus Kristus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 8, 'Pertama-tama aku mengucap syukur kepada Allahku oleh Yesus Kristus atas kamu sekalian, sebab telah tersiar kabar tentang imanmu di seluruh dunia.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 9, 'Karena Allah, yang kulayani dengan segenap hatiku dalam pemberitaan Injil Anak-Nya, adalah saksiku, bahwa dalam doaku aku selalu mengingat kamu:', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 10, 'Aku berdoa, semoga dengan kehendak Allah aku akhirnya beroleh kesempatan untuk mengunjungi kamu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 11, 'Sebab aku ingin melihat kamu untuk memberikan karunia rohani kepadamu guna menguatkan kamu,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 12, 'yaitu, supaya aku ada di antara kamu dan turut terhibur oleh iman kita bersama, baik oleh imanmu maupun oleh imanku.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 13, 'Saudara-saudara, aku mau, supaya kamu mengetahui, bahwa aku telah sering berniat untuk datang kepadamu?tetapi hingga kini selalu aku terhalang?agar di tengah-tengahmu aku menemukan buah, seperti juga di tengah-tengah bangsa bukan Yahudi yang lain.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 14, 'Aku berhutang baik kepada orang Yunani, maupun kepada orang bukan Yunani, baik kepada orang terpelajar, maupun kepada orang tidak terpelajar.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 15, 'Itulah sebabnya aku ingin untuk memberitakan Injil kepada kamu juga yang diam di Roma.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 16, 'Sebab aku mempunyai keyakinan yang kokoh dalam Injil, karena Injil adalah kekuatan Allah yang menyelamatkan setiap orang yang percaya, pertama-tama orang Yahudi, tetapi juga orang Yunani.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 17, 'Sebab di dalamnya nyata kebenaran Allah, yang bertolak dari iman dan memimpin kepada iman, seperti ada tertulis: "Orang benar akan hidup oleh iman."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 18, 'Sebab murka Allah nyata dari sorga atas segala kefasikan dan kelaliman manusia, yang menindas kebenaran dengan kelaliman.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 19, 'Karena apa yang dapat mereka ketahui tentang Allah nyata bagi mereka, sebab Allah telah menyatakannya kepada mereka.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 20, 'Sebab apa yang tidak nampak dari pada-Nya, yaitu kekuatan-Nya yang kekal dan keilahian-Nya, dapat nampak kepada pikiran dari karya-Nya sejak dunia diciptakan, sehingga mereka tidak dapat berdalih.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 21, 'Sebab sekalipun mereka mengenal Allah, mereka tidak memuliakan Dia sebagai Allah atau mengucap syukur kepada-Nya. Sebaliknya pikiran mereka menjadi sia-sia dan hati mereka yang bodoh menjadi gelap.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 22, 'Mereka berbuat seolah-olah mereka penuh hikmat, tetapi mereka telah menjadi bodoh.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 23, 'Mereka menggantikan kemuliaan Allah yang tidak fana dengan gambaran yang mirip dengan manusia yang fana, burung-burung, binatang-binatang yang berkaki empat atau binatang-binatang yang menjalar.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 24, 'Karena itu Allah menyerahkan mereka kepada keinginan hati mereka akan kecemaran, sehingga mereka saling mencemarkan tubuh mereka.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 25, 'Sebab mereka menggantikan kebenaran Allah dengan dusta dan memuja dan menyembah makhluk dengan melupakan Penciptanya yang harus dipuji selama-lamanya, amin.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 26, 'Karena itu Allah menyerahkan mereka kepada hawa nafsu yang memalukan, sebab isteri-isteri mereka menggantikan persetubuhan yang wajar dengan yang tak wajar.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 27, 'Demikian juga suami-suami meninggalkan persetubuhan yang wajar dengan isteri mereka dan menyala-nyala dalam berahi mereka seorang terhadap yang lain, sehingga mereka melakukan kemesuman, laki-laki dengan laki-laki, dan karena itu mereka menerima dalam diri mereka balasan yang setimpal untuk kesesatan mereka.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 28, 'Dan karena mereka tidak merasa perlu untuk mengakui Allah, maka Allah menyerahkan mereka kepada pikiran-pikiran yang terkutuk, sehingga mereka melakukan apa yang tidak pantas:', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 29, 'penuh dengan rupa-rupa kelaliman, kejahatan, keserakahan dan kebusukan, penuh dengan dengki, pembunuhan, perselisihan, tipu muslihat dan kefasikan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 30, 'Mereka adalah pengumpat, pemfitnah, pembenci Allah, kurang ajar, congkak, sombong, pandai dalam kejahatan, tidak taat kepada orang tua,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 31, 'tidak berakal, tidak setia, tidak penyayang, tidak mengenal belas kasihan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 1, 32, 'Sebab walaupun mereka mengetahui tuntutan-tuntutan hukum Allah, yaitu bahwa setiap orang yang melakukan hal-hal demikian, patut dihukum mati, mereka bukan saja melakukannya sendiri, tetapi mereka juga setuju dengan mereka yang melakukannya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 1, 'Karena itu, hai manusia, siapapun juga engkau, yang menghakimi orang lain, engkau sendiri tidak bebas dari salah. Sebab, dalam menghakimi orang lain, engkau menghakimi dirimu sendiri, karena engkau yang menghakimi orang lain, melakukan hal-hal yang sama.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 2, 'Tetapi kita tahu, bahwa hukuman Allah berlangsung secara jujur atas mereka yang berbuat demikian.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 3, 'Dan engkau, hai manusia, engkau yang menghakimi mereka yang berbuat demikian, sedangkan engkau sendiri melakukannya juga, adakah engkau sangka, bahwa engkau akan luput dari hukuman Allah?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 4, 'Maukah engkau menganggap sepi kekayaan kemurahan-Nya, kesabaran-Nya dan kelapangan hati-Nya? Tidakkah engkau tahu, bahwa maksud kemurahan Allah ialah menuntun engkau kepada pertobatan?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 5, 'Tetapi oleh kekerasan hatimu yang tidak mau bertobat, engkau menimbun murka atas dirimu sendiri pada hari waktu mana murka dan hukuman Allah yang adil akan dinyatakan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 6, 'Ia akan membalas setiap orang menurut perbuatannya,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 7, 'yaitu hidup kekal kepada mereka yang dengan tekun berbuat baik, mencari kemuliaan, kehormatan dan ketidakbinasaan,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 8, 'tetapi murka dan geram kepada mereka yang mencari kepentingan sendiri, yang tidak taat kepada kebenaran, melainkan taat kepada kelaliman.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 9, 'Penderitaan dan kesesakan akan menimpa setiap orang yang hidup yang berbuat jahat, pertama-tama orang Yahudi dan juga orang Yunani,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 10, 'tetapi kemuliaan, kehormatan dan damai sejahtera akan diperoleh semua orang yang berbuat baik, pertama-tama orang Yahudi, dan juga orang Yunani.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 11, 'Sebab Allah tidak memandang bulu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 12, 'Sebab semua orang yang berdosa tanpa hukum Taurat akan binasa tanpa hukum Taurat; dan semua orang yang berdosa di bawah hukum Taurat akan dihakimi oleh hukum Taurat.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 13, 'Karena bukanlah orang yang mendengar hukum Taurat yang benar di hadapan Allah, tetapi orang yang melakukan hukum Tauratlah yang akan dibenarkan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 14, 'Apabila bangsa-bangsa lain yang tidak memiliki hukum Taurat oleh dorongan diri sendiri melakukan apa yang dituntut hukum Taurat, maka, walaupun mereka tidak memiliki hukum Taurat, mereka menjadi hukum Taurat bagi diri mereka sendiri.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 15, 'Sebab dengan itu mereka menunjukkan, bahwa isi hukum Taurat ada tertulis di dalam hati mereka dan suara hati mereka turut bersaksi dan pikiran mereka saling menuduh atau saling membela.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 16, 'Hal itu akan nampak pada hari, bilamana Allah, sesuai dengan Injil yang kuberitakan, akan menghakimi segala sesuatu yang tersembunyi dalam hati manusia, oleh Kristus Yesus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 17, 'Tetapi, jika kamu menyebut dirimu orang Yahudi dan bersandar kepada hukum Taurat, bermegah dalam Allah,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 18, 'dan tahu akan kehendak-Nya, dan oleh karena diajar dalam hukum Taurat, dapat tahu mana yang baik dan mana yang tidak,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 19, 'dan yakin, bahwa engkau adalah penuntun orang buta dan terang bagi mereka yang di dalam kegelapan,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 20, 'pendidik orang bodoh, dan pengajar orang yang belum dewasa, karena dalam hukum Taurat engkau memiliki kegenapan segala kepandaian dan kebenaran.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 21, 'Jadi, bagaimanakah engkau yang mengajar orang lain, tidakkah engkau mengajar dirimu sendiri? Engkau yang mengajar: "Jangan mencuri," mengapa engkau sendiri mencuri?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 22, 'Engkau yang berkata: "Jangan berzinah," mengapa engkau sendiri berzinah? Engkau yang jijik akan segala berhala, mengapa engkau sendiri merampok rumah berhala?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 23, 'Engkau bermegah atas hukum Taurat, mengapa engkau sendiri menghina Allah dengan melanggar hukum Taurat itu?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 24, 'Seperti ada tertulis: "Sebab oleh karena kamulah nama Allah dihujat di antara bangsa-bangsa lain."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 25, 'Sunat memang ada gunanya, jika engkau mentaati hukum Taurat; tetapi jika engkau melanggar hukum Taurat, maka sunatmu tidak ada lagi gunanya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 26, 'Jadi jika orang yang tak bersunat memperhatikan tuntutan-tuntutan hukum Taurat, tidakkah ia dianggap sama dengan orang yang telah disunat?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 27, 'Jika demikian, maka orang yang tak bersunat, tetapi yang melakukan hukum Taurat, akan menghakimi kamu yang mempunyai hukum tertulis dan sunat, tetapi yang melanggar hukum Taurat.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 28, 'Sebab yang disebut Yahudi bukanlah orang yang lahiriah Yahudi, dan yang disebut sunat, bukanlah sunat yang dilangsungkan secara lahiriah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 2, 29, 'Tetapi orang Yahudi sejati ialah dia yang tidak nampak keyahudiannya dan sunat ialah sunat di dalam hati, secara rohani, bukan secara hurufiah. Maka pujian baginya datang bukan dari manusia, melainkan dari Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 1, 'Jika demikian, apakah kelebihan orang Yahudi dan apakah gunanya sunat?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 2, 'Banyak sekali, dan di dalam segala hal. Pertama-tama: sebab kepada merekalah dipercayakan firman Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 3, 'Jadi bagaimana, jika di antara mereka ada yang tidak setia, dapatkah ketidaksetiaan itu membatalkan kesetiaan Allah?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 4, 'Sekali-kali tidak! Sebaliknya: Allah adalah benar, dan semua manusia pembohong, seperti ada tertulis: "Supaya Engkau ternyata benar dalam segala firman-Mu, dan menang, jika Engkau dihakimi."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 5, 'Tetapi jika ketidakbenaran kita menunjukkan kebenaran Allah, apakah yang akan kita katakan? Tidak adilkah Allah?aku berkata sebagai manusia?jika Ia menampakkan murka-Nya?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 6, 'Sekali-kali tidak! Andaikata demikian, bagaimanakah Allah dapat menghakimi dunia?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 7, 'Tetapi jika kebenaran Allah oleh dustaku semakin melimpah bagi kemuliaan-Nya, mengapa aku masih dihakimi lagi sebagai orang berdosa?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 8, 'Bukankah tidak benar fitnahan orang yang mengatakan, bahwa kita berkata: "Marilah kita berbuat yang jahat, supaya yang baik timbul dari padanya." Orang semacam itu sudah selayaknya mendapat hukuman.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 9, 'Jadi bagaimana? Adakah kita mempunyai kelebihan dari pada orang lain? Sama sekali tidak. Sebab di atas telah kita tuduh baik orang Yahudi, maupun orang Yunani, bahwa mereka semua ada di bawah kuasa dosa,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 10, 'seperti ada tertulis: "Tidak ada yang benar, seorangpun tidak.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 11, 'Tidak ada seorangpun yang berakal budi, tidak ada seorangpun yang mencari Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 12, 'Semua orang telah menyeleweng, mereka semua tidak berguna, tidak ada yang berbuat baik, seorangpun tidak.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 13, 'Kerongkongan mereka seperti kubur yang ternganga, lidah mereka merayu-rayu, bibir mereka mengandung bisa.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 14, 'Mulut mereka penuh dengan sumpah serapah,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 15, 'kaki mereka cepat untuk menumpahkan darah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 16, 'Keruntuhan dan kebinasaan mereka tinggalkan di jalan mereka,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 17, 'dan jalan damai tidak mereka kenal;', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 18, 'rasa takut kepada Allah tidak ada pada orang itu."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 19, 'Tetapi kita tahu, bahwa segala sesuatu yang tercantum dalam Kitab Taurat ditujukan kepada mereka yang hidup di bawah hukum Taurat, supaya tersumbat setiap mulut dan seluruh dunia jatuh ke bawah hukuman Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 20, 'Sebab tidak seorangpun yang dapat dibenarkan di hadapan Allah oleh karena melakukan hukum Taurat, karena justru oleh hukum Taurat orang mengenal dosa.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 21, 'Tetapi sekarang, tanpa hukum Taurat kebenaran Allah telah dinyatakan, seperti yang disaksikan dalam Kitab Taurat dan Kitab-kitab para nabi,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 22, 'yaitu kebenaran Allah karena iman dalam Yesus Kristus bagi semua orang yang percaya. Sebab tidak ada perbedaan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 23, 'Karena semua orang telah berbuat dosa dan telah kehilangan kemuliaan Allah,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 24, 'dan oleh kasih karunia telah dibenarkan dengan cuma-cuma karena penebusan dalam Kristus Yesus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 25, 'Kristus Yesus telah ditentukan Allah menjadi jalan pendamaian karena iman, dalam darah-Nya. Hal ini dibuat-Nya untuk menunjukkan keadilan-Nya, karena Ia telah membiarkan dosa-dosa yang telah terjadi dahulu pada masa kesabaran-Nya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 26, 'Maksud-Nya ialah untuk menunjukkan keadilan-Nya pada masa ini, supaya nyata, bahwa Ia benar dan juga membenarkan orang yang percaya kepada Yesus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 27, 'Jika demikian, apakah dasarnya untuk bermegah? Tidak ada! Berdasarkan apa? Berdasarkan perbuatan? Tidak, melainkan berdasarkan iman!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 28, 'Karena kami yakin, bahwa manusia dibenarkan karena iman, dan bukan karena ia melakukan hukum Taurat.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 29, 'Atau adakah Allah hanya Allah orang Yahudi saja? Bukankah Ia juga adalah Allah bangsa-bangsa lain? Ya, benar. Ia juga adalah Allah bangsa-bangsa lain!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 30, 'Artinya, kalau ada satu Allah, yang akan membenarkan baik orang-orang bersunat karena iman, maupun orang-orang tak bersunat juga karena iman.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 3, 31, 'Jika demikian, adakah kami membatalkan hukum Taurat karena iman? Sama sekali tidak! Sebaliknya, kami meneguhkannya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 1, 'Jadi apakah akan kita katakan tentang Abraham, bapa leluhur jasmani kita?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 2, 'Sebab jikalau Abraham dibenarkan karena perbuatannya, maka ia beroleh dasar untuk bermegah, tetapi tidak di hadapan Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 3, 'Sebab apakah dikatakan nas Kitab Suci? "Lalu percayalah Abraham kepada Tuhan, dan Tuhan memperhitungkan hal itu kepadanya sebagai kebenaran."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 4, 'Kalau ada orang yang bekerja, upahnya tidak diperhitungkan sebagai hadiah, tetapi sebagai haknya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 5, 'Tetapi kalau ada orang yang tidak bekerja, namun percaya kepada Dia yang membenarkan orang durhaka, imannya diperhitungkan menjadi kebenaran.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 6, 'Seperti juga Daud menyebut berbahagia orang yang dibenarkan Allah bukan berdasarkan perbuatannya:', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 7, '"Berbahagialah orang yang diampuni pelanggaran-pelanggarannya, dan yang ditutupi dosa-dosanya;', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 8, 'berbahagialah manusia yang kesalahannya tidak diperhitungkan Tuhan kepadanya."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 9, 'Adakah ucapan bahagia ini hanya berlaku bagi orang bersunat saja atau juga bagi orang tak bersunat? Sebab telah kami katakan, bahwa kepada Abraham iman diperhitungkan sebagai kebenaran.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 10, 'Dalam keadaan manakah hal itu diperhitungkan? Sebelum atau sesudah ia disunat? Bukan sesudah disunat, tetapi sebelumnya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 11, 'Dan tanda sunat itu diterimanya sebagai meterai kebenaran berdasarkan iman yang ditunjukkannya, sebelum ia bersunat. Demikianlah ia dapat menjadi bapa semua orang percaya yang tak bersunat, supaya kebenaran diperhitungkan kepada mereka,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 12, 'dan juga menjadi bapa orang-orang bersunat, yaitu mereka yang bukan hanya bersunat, tetapi juga mengikuti jejak iman Abraham, bapa leluhur kita, pada masa ia belum disunat.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 13, 'Sebab bukan karena hukum Taurat telah diberikan janji kepada Abraham dan keturunannya, bahwa ia akan memiliki dunia, tetapi karena kebenaran, berdasarkan iman.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 14, 'Sebab jika mereka yang mengharapkannya dari hukum Taurat, menerima bagian yang dijanjikan Allah, maka sia-sialah iman dan batallah janji itu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 15, 'Karena hukum Taurat membangkitkan murka, tetapi di mana tidak ada hukum Taurat, di situ tidak ada juga pelanggaran.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 16, 'Karena itulah kebenaran berdasarkan iman supaya merupakan kasih karunia, sehingga janji itu berlaku bagi semua keturunan Abraham, bukan hanya bagi mereka yang hidup dari hukum Taurat, tetapi juga bagi mereka yang hidup dari iman Abraham. Sebab Abraham adalah bapa kita semua, ?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 17, 'seperti ada tertulis: "Engkau telah Kutetapkan menjadi bapa banyak bangsa" ?di hadapan Allah yang kepada-Nya ia percaya, yaitu Allah yang menghidupkan orang mati dan yang menjadikan dengan firman-Nya apa yang tidak ada menjadi ada.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 18, 'Sebab sekalipun tidak ada dasar untuk berharap, namun Abraham berharap juga dan percaya, bahwa ia akan menjadi bapa banyak bangsa, menurut yang telah difirmankan: "Demikianlah banyaknya nanti keturunanmu."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 19, 'Imannya tidak menjadi lemah, walaupun ia mengetahui, bahwa tubuhnya sudah sangat lemah, karena usianya telah kira-kira seratus tahun, dan bahwa rahim Sara telah tertutup.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 20, 'Tetapi terhadap janji Allah ia tidak bimbang karena ketidakpercayaan, malah ia diperkuat dalam imannya dan ia memuliakan Allah,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 21, 'dengan penuh keyakinan, bahwa Allah berkuasa untuk melaksanakan apa yang telah Ia janjikan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 22, 'Karena itu hal ini diperhitungkan kepadanya sebagai kebenaran.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 23, 'Kata-kata ini, yaitu "hal ini diperhitungkan kepadanya," tidak ditulis untuk Abraham saja,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 24, 'tetapi ditulis juga untuk kita; sebab kepada kitapun Allah memperhitungkannya, karena kita percaya kepada Dia, yang telah membangkitkan Yesus, Tuhan kita, dari antara orang mati,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 4, 25, 'yaitu Yesus, yang telah diserahkan karena pelanggaran kita dan dibangkitkan karena pembenaran kita.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 1, 'Sebab itu, kita yang dibenarkan karena iman, kita hidup dalam damai sejahtera dengan Allah oleh karena Tuhan kita, Yesus Kristus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 2, 'Oleh Dia kita juga beroleh jalan masuk oleh iman kepada kasih karunia ini. Di dalam kasih karunia ini kita berdiri dan kita bermegah dalam pengharapan akan menerima kemuliaan Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 3, 'Dan bukan hanya itu saja. Kita malah bermegah juga dalam kesengsaraan kita, karena kita tahu, bahwa kesengsaraan itu menimbulkan ketekunan,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 4, 'dan ketekunan menimbulkan tahan uji dan tahan uji menimbulkan pengharapan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 5, 'Dan pengharapan tidak mengecewakan, karena kasih Allah telah dicurahkan di dalam hati kita oleh Roh Kudus yang telah dikaruniakan kepada kita.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 6, 'Karena waktu kita masih lemah, Kristus telah mati untuk kita orang-orang durhaka pada waktu yang ditentukan oleh Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 7, 'Sebab tidak mudah seorang mau mati untuk orang yang benar?tetapi mungkin untuk orang yang baik ada orang yang berani mati?.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 8, 'Akan tetapi Allah menunjukkan kasih-Nya kepada kita, oleh karena Kristus telah mati untuk kita, ketika kita masih berdosa.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 9, 'Lebih-lebih, karena kita sekarang telah dibenarkan oleh darah-Nya, kita pasti akan diselamatkan dari murka Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 10, 'Sebab jikalau kita, ketika masih seteru, diperdamaikan dengan Allah oleh kematian Anak-Nya, lebih-lebih kita, yang sekarang telah diperdamaikan, pasti akan diselamatkan oleh hidup-Nya!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 11, 'Dan bukan hanya itu saja! Kita malah bermegah dalam Allah oleh Yesus Kristus, Tuhan kita, sebab oleh Dia kita telah menerima pendamaian itu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 12, 'Sebab itu, sama seperti dosa telah masuk ke dalam dunia oleh satu orang, dan oleh dosa itu juga maut, demikianlah maut itu telah menjalar kepada semua orang, karena semua orang telah berbuat dosa.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 13, 'Sebab sebelum hukum Taurat ada, telah ada dosa di dunia. Tetapi dosa itu tidak diperhitungkan kalau tidak ada hukum Taurat.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 14, 'Sungguhpun demikian maut telah berkuasa dari zaman Adam sampai kepada zaman Musa juga atas mereka, yang tidak berbuat dosa dengan cara yang sama seperti yang telah dibuat oleh Adam, yang adalah gambaran Dia yang akan datang.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 15, 'Tetapi karunia Allah tidaklah sama dengan pelanggaran Adam. Sebab, jika karena pelanggaran satu orang semua orang telah jatuh di dalam kuasa maut, jauh lebih besar lagi kasih karunia Allah dan karunia-Nya, yang dilimpahkan-Nya atas semua orang karena satu orang, yaitu Yesus Kristus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 16, 'Dan kasih karunia tidak berimbangan dengan dosa satu orang. Sebab penghakiman atas satu pelanggaran itu telah mengakibatkan penghukuman, tetapi penganugerahan karunia atas banyak pelanggaran itu mengakibatkan pembenaran.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 17, 'Sebab, jika oleh dosa satu orang, maut telah berkuasa oleh satu orang itu, maka lebih benar lagi mereka, yang telah menerima kelimpahan kasih karunia dan anugerah kebenaran, akan hidup dan berkuasa oleh karena satu orang itu, yaitu Yesus Kristus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 18, 'Sebab itu, sama seperti oleh satu pelanggaran semua orang beroleh penghukuman, demikian pula oleh satu perbuatan kebenaran semua orang beroleh pembenaran untuk hidup.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 19, 'Jadi sama seperti oleh ketidaktaatan satu orang semua orang telah menjadi orang berdosa, demikian pula oleh ketaatan satu orang semua orang menjadi orang benar.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 20, 'Tetapi hukum Taurat ditambahkan, supaya pelanggaran menjadi semakin banyak; dan di mana dosa bertambah banyak, di sana kasih karunia menjadi berlimpah-limpah,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 5, 21, 'supaya, sama seperti dosa berkuasa dalam alam maut, demikian kasih karunia akan berkuasa oleh kebenaran untuk hidup yang kekal, oleh Yesus Kristus, Tuhan kita.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 1, 'Jika demikian, apakah yang hendak kita katakan? Bolehkah kita bertekun dalam dosa, supaya semakin bertambah kasih karunia itu?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 2, 'Sekali-kali tidak! Bukankah kita telah mati bagi dosa, bagaimanakah kita masih dapat hidup di dalamnya?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 3, 'Atau tidak tahukah kamu, bahwa kita semua yang telah dibaptis dalam Kristus, telah dibaptis dalam kematian-Nya?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 4, 'Dengan demikian kita telah dikuburkan bersama-sama dengan Dia oleh baptisan dalam kematian, supaya, sama seperti Kristus telah dibangkitkan dari antara orang mati oleh kemuliaan Bapa, demikian juga kita akan hidup dalam hidup yang baru.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 5, 'Sebab jika kita telah menjadi satu dengan apa yang sama dengan kematian-Nya, kita juga akan menjadi satu dengan apa yang sama dengan kebangkitan-Nya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 6, 'Karena kita tahu, bahwa manusia lama kita telah turut disalibkan, supaya tubuh dosa kita hilang kuasanya, agar jangan kita menghambakan diri lagi kepada dosa.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 7, 'Sebab siapa yang telah mati, ia telah bebas dari dosa.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 8, 'Jadi jika kita telah mati dengan Kristus, kita percaya, bahwa kita akan hidup juga dengan Dia.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 9, 'Karena kita tahu, bahwa Kristus, sesudah Ia bangkit dari antara orang mati, tidak mati lagi: maut tidak berkuasa lagi atas Dia.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 10, 'Sebab kematian-Nya adalah kematian terhadap dosa, satu kali dan untuk selama-lamanya, dan kehidupan-Nya adalah kehidupan bagi Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 11, 'Demikianlah hendaknya kamu memandangnya: bahwa kamu telah mati bagi dosa, tetapi kamu hidup bagi Allah dalam Kristus Yesus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 12, 'Sebab itu hendaklah dosa jangan berkuasa lagi di dalam tubuhmu yang fana, supaya kamu jangan lagi menuruti keinginannya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 13, 'Dan janganlah kamu menyerahkan anggota-anggota tubuhmu kepada dosa untuk dipakai sebagai senjata kelaliman, tetapi serahkanlah dirimu kepada Allah sebagai orang-orang, yang dahulu mati, tetapi yang sekarang hidup. Dan serahkanlah anggota-anggota tubuhmu kepada Allah untuk menjadi senjata-senjata kebenaran.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 14, 'Sebab kamu tidak akan dikuasai lagi oleh dosa, karena kamu tidak berada di bawah hukum Taurat, tetapi di bawah kasih karunia.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 15, 'Jadi bagaimana? Apakah kita akan berbuat dosa, karena kita tidak berada di bawah hukum Taurat, tetapi di bawah kasih karunia? Sekali-kali tidak!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 16, 'Apakah kamu tidak tahu, bahwa apabila kamu menyerahkan dirimu kepada seseorang sebagai hamba untuk mentaatinya, kamu adalah hamba orang itu, yang harus kamu taati, baik dalam dosa yang memimpin kamu kepada kematian, maupun dalam ketaatan yang memimpin kamu kepada kebenaran?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 17, 'Tetapi syukurlah kepada Allah! Dahulu memang kamu hamba dosa, tetapi sekarang kamu dengan segenap hati telah mentaati pengajaran yang telah diteruskan kepadamu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 18, 'Kamu telah dimerdekakan dari dosa dan menjadi hamba kebenaran.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 19, 'Aku mengatakan hal ini secara manusia karena kelemahan kamu. Sebab sama seperti kamu telah menyerahkan anggota-anggota tubuhmu menjadi hamba kecemaran dan kedurhakaan yang membawa kamu kepada kedurhakaan, demikian hal kamu sekarang harus menyerahkan anggota-anggota tubuhmu menjadi hamba kebenaran yang membawa kamu kepada pengudusan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 20, 'Sebab waktu kamu hamba dosa, kamu bebas dari kebenaran.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 21, 'Dan buah apakah yang kamu petik dari padanya? Semuanya itu menyebabkan kamu merasa malu sekarang, karena kesudahan semuanya itu ialah kematian.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 22, 'Tetapi sekarang, setelah kamu dimerdekakan dari dosa dan setelah kamu menjadi hamba Allah, kamu beroleh buah yang membawa kamu kepada pengudusan dan sebagai kesudahannya ialah hidup yang kekal.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 6, 23, 'Sebab upah dosa ialah maut; tetapi karunia Allah ialah hidup yang kekal dalam Kristus Yesus, Tuhan kita.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 1, 'Apakah kamu tidak tahu, saudara-saudara, ?sebab aku berbicara kepada mereka yang mengetahui hukum?bahwa hukum berkuasa atas seseorang selama orang itu hidup?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 2, 'Sebab seorang isteri terikat oleh hukum kepada suaminya selama suaminya itu hidup. Akan tetapi apabila suaminya itu mati, bebaslah ia dari hukum yang mengikatnya kepada suaminya itu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 3, 'Jadi selama suaminya hidup ia dianggap berzinah, kalau ia menjadi isteri laki-laki lain; tetapi jika suaminya telah mati, ia bebas dari hukum, sehingga ia bukanlah berzinah, kalau ia menjadi isteri laki-laki lain.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 4, 'Sebab itu, saudara-saudaraku, kamu juga telah mati bagi hukum Taurat oleh tubuh Kristus, supaya kamu menjadi milik orang lain, yaitu milik Dia, yang telah dibangkitkan dari antara orang mati, agar kita berbuah bagi Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 5, 'Sebab waktu kita masih hidup di dalam daging, hawa nafsu dosa, yang dirangsang oleh hukum Taurat, bekerja dalam anggota-anggota tubuh kita, agar kita berbuah bagi maut.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 6, 'Tetapi sekarang kita telah dibebaskan dari hukum Taurat, sebab kita telah mati bagi dia, yang mengurung kita, sehingga kita sekarang melayani dalam keadaan baru menurut Roh dan bukan dalam keadaan lama menurut huruf hukum Taurat.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 7, 'Jika demikian, apakah yang hendak kita katakan? Apakah hukum Taurat itu dosa? Sekali-kali tidak! Sebaliknya, justru oleh hukum Taurat aku telah mengenal dosa. Karena aku juga tidak tahu apa itu keinginan, kalau hukum Taurat tidak mengatakan: "Jangan mengingini!"', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 8, 'Tetapi dalam perintah itu dosa mendapat kesempatan untuk membangkitkan di dalam diriku rupa-rupa keinginan; sebab tanpa hukum Taurat dosa mati.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 9, 'Dahulu aku hidup tanpa hukum Taurat. Akan tetapi sesudah datang perintah itu, dosa mulai hidup,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 10, 'sebaliknya aku mati. Dan perintah yang seharusnya membawa kepada hidup, ternyata bagiku justru membawa kepada kematian.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 11, 'Sebab dalam perintah itu, dosa mendapat kesempatan untuk menipu aku dan oleh perintah itu ia membunuh aku.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 12, 'Jadi hukum Taurat adalah kudus, dan perintah itu juga adalah kudus, benar dan baik.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 13, 'Jika demikian, adakah yang baik itu menjadi kematian bagiku? Sekali-kali tidak! Tetapi supaya nyata, bahwa ia adalah dosa, maka dosa mempergunakan yang baik untuk mendatangkan kematian bagiku, supaya oleh perintah itu dosa lebih nyata lagi keadaannya sebagai dosa.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 14, 'Sebab kita tahu, bahwa hukum Taurat adalah rohani, tetapi aku bersifat daging, terjual di bawah kuasa dosa.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 15, 'Sebab apa yang aku perbuat, aku tidak tahu. Karena bukan apa yang aku kehendaki yang aku perbuat, tetapi apa yang aku benci, itulah yang aku perbuat.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 16, 'Jadi jika aku perbuat apa yang tidak aku kehendaki, aku menyetujui, bahwa hukum Taurat itu baik.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 17, 'Kalau demikian bukan aku lagi yang memperbuatnya, tetapi dosa yang ada di dalam aku.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 18, 'Sebab aku tahu, bahwa di dalam aku, yaitu di dalam aku sebagai manusia, tidak ada sesuatu yang baik. Sebab kehendak memang ada di dalam aku, tetapi bukan hal berbuat apa yang baik.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 19, 'Sebab bukan apa yang aku kehendaki, yaitu yang baik, yang aku perbuat, melainkan apa yang tidak aku kehendaki, yaitu yang jahat, yang aku perbuat.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 20, 'Jadi jika aku berbuat apa yang tidak aku kehendaki, maka bukan lagi aku yang memperbuatnya, tetapi dosa yang diam di dalam aku.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 21, 'Demikianlah aku dapati hukum ini: jika aku menghendaki berbuat apa yang baik, yang jahat itu ada padaku.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 22, 'Sebab di dalam batinku aku suka akan hukum Allah,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 23, 'tetapi di dalam anggota-anggota tubuhku aku melihat hukum lain yang berjuang melawan hukum akal budiku dan membuat aku menjadi tawanan hukum dosa yang ada di dalam anggota-anggota tubuhku.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 24, 'Aku, manusia celaka! Siapakah yang akan melepaskan aku dari tubuh maut ini?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 7, 25, 'Syukur kepada Allah! oleh Yesus Kristus, Tuhan kita. (7-26) Jadi dengan akal budiku aku melayani hukum Allah, tetapi dengan tubuh insaniku aku melayani hukum dosa.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 1, 'Demikianlah sekarang tidak ada penghukuman bagi mereka yang ada di dalam Kristus Yesus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 2, 'Roh, yang memberi hidup telah memerdekakan kamu dalam Kristus dari hukum dosa dan hukum maut.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 3, 'Sebab apa yang tidak mungkin dilakukan hukum Taurat karena tak berdaya oleh daging, telah dilakukan oleh Allah. Dengan jalan mengutus Anak-Nya sendiri dalam daging, yang serupa dengan daging yang dikuasai dosa karena dosa, Ia telah menjatuhkan hukuman atas dosa di dalam daging,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 4, 'supaya tuntutan hukum Taurat digenapi di dalam kita, yang tidak hidup menurut daging, tetapi menurut Roh.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 5, 'Sebab mereka yang hidup menurut daging, memikirkan hal-hal yang dari daging; mereka yang hidup menurut Roh, memikirkan hal-hal yang dari Roh.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 6, 'Karena keinginan daging adalah maut, tetapi keinginan Roh adalah hidup dan damai sejahtera.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 7, 'Sebab keinginan daging adalah perseteruan terhadap Allah, karena ia tidak takluk kepada hukum Allah; hal ini memang tidak mungkin baginya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 8, 'Mereka yang hidup dalam daging, tidak mungkin berkenan kepada Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 9, 'Tetapi kamu tidak hidup dalam daging, melainkan dalam Roh, jika memang Roh Allah diam di dalam kamu. Tetapi jika orang tidak memiliki Roh Kristus, ia bukan milik Kristus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 10, 'Tetapi jika Kristus ada di dalam kamu, maka tubuh memang mati karena dosa, tetapi roh adalah kehidupan oleh karena kebenaran.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 11, 'Dan jika Roh Dia, yang telah membangkitkan Yesus dari antara orang mati, diam di dalam kamu, maka Ia, yang telah membangkitkan Kristus Yesus dari antara orang mati, akan menghidupkan juga tubuhmu yang fana itu oleh Roh-Nya, yang diam di dalam kamu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 12, 'Jadi, saudara-saudara, kita adalah orang berhutang, tetapi bukan kepada daging, supaya hidup menurut daging.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 13, 'Sebab, jika kamu hidup menurut daging, kamu akan mati; tetapi jika oleh Roh kamu mematikan perbuatan-perbuatan tubuhmu, kamu akan hidup.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 14, 'Semua orang, yang dipimpin Roh Allah, adalah anak Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 15, 'Sebab kamu tidak menerima roh perbudakan yang membuat kamu menjadi takut lagi, tetapi kamu telah menerima Roh yang menjadikan kamu anak Allah. Oleh Roh itu kita berseru: "ya Abba, ya Bapa!"', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 16, 'Roh itu bersaksi bersama-sama dengan roh kita, bahwa kita adalah anak-anak Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 17, 'Dan jika kita adalah anak, maka kita juga adalah ahli waris, maksudnya orang-orang yang berhak menerima janji-janji Allah, yang akan menerimanya bersama-sama dengan Kristus, yaitu jika kita menderita bersama-sama dengan Dia, supaya kita juga dipermuliakan bersama-sama dengan Dia.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 18, 'Sebab aku yakin, bahwa penderitaan zaman sekarang ini tidak dapat dibandingkan dengan kemuliaan yang akan dinyatakan kepada kita.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 19, 'Sebab dengan sangat rindu seluruh makhluk menantikan saat anak-anak Allah dinyatakan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 20, 'Karena seluruh makhluk telah ditaklukkan kepada kesia-siaan, bukan oleh kehendaknya sendiri, tetapi oleh kehendak Dia, yang telah menaklukkannya,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 21, 'tetapi dalam pengharapan, karena makhluk itu sendiri juga akan dimerdekakan dari perbudakan kebinasaan dan masuk ke dalam kemerdekaan kemuliaan anak-anak Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 22, 'Sebab kita tahu, bahwa sampai sekarang segala makhluk sama-sama mengeluh dan sama-sama merasa sakit bersalin.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 23, 'Dan bukan hanya mereka saja, tetapi kita yang telah menerima karunia sulung Roh, kita juga mengeluh dalam hati kita sambil menantikan pengangkatan sebagai anak, yaitu pembebasan tubuh kita.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 24, 'Sebab kita diselamatkan dalam pengharapan. Tetapi pengharapan yang dilihat, bukan pengharapan lagi; sebab bagaimana orang masih mengharapkan apa yang dilihatnya?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 25, 'Tetapi jika kita mengharapkan apa yang tidak kita lihat, kita menantikannya dengan tekun.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 26, 'Demikian juga Roh membantu kita dalam kelemahan kita; sebab kita tidak tahu, bagaimana sebenarnya harus berdoa; tetapi Roh sendiri berdoa untuk kita kepada Allah dengan keluhan-keluhan yang tidak terucapkan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 27, 'Dan Allah yang menyelidiki hati nurani, mengetahui maksud Roh itu, yaitu bahwa Ia, sesuai dengan kehendak Allah, berdoa untuk orang-orang kudus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 28, 'Kita tahu sekarang, bahwa Allah turut bekerja dalam segala sesuatu untuk mendatangkan kebaikan bagi mereka yang mengasihi Dia, yaitu bagi mereka yang terpanggil sesuai dengan rencana Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 29, 'Sebab semua orang yang dipilih-Nya dari semula, mereka juga ditentukan-Nya dari semula untuk menjadi serupa dengan gambaran Anak-Nya, supaya Ia, Anak-Nya itu, menjadi yang sulung di antara banyak saudara.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 30, 'Dan mereka yang ditentukan-Nya dari semula, mereka itu juga dipanggil-Nya. Dan mereka yang dipanggil-Nya, mereka itu juga dibenarkan-Nya. Dan mereka yang dibenarkan-Nya, mereka itu juga dimuliakan-Nya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 31, 'Sebab itu apakah yang akan kita katakan tentang semuanya itu? Jika Allah di pihak kita, siapakah yang akan melawan kita?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 32, 'Ia, yang tidak menyayangkan Anak-Nya sendiri, tetapi yang menyerahkan-Nya bagi kita semua, bagaimanakah mungkin Ia tidak mengaruniakan segala sesuatu kepada kita bersama-sama dengan Dia?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 33, 'Siapakah yang akan menggugat orang-orang pilihan Allah? Allah, yang membenarkan mereka? Siapakah yang akan menghukum mereka?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 34, 'Kristus Yesus, yang telah mati? Bahkan lebih lagi: yang telah bangkit, yang juga duduk di sebelah kanan Allah, yang malah menjadi Pembela bagi kita?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 35, 'Siapakah yang akan memisahkan kita dari kasih Kristus? Penindasan atau kesesakan atau penganiayaan, atau kelaparan atau ketelanjangan, atau bahaya, atau pedang?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 36, 'Seperti ada tertulis: "Oleh karena Engkau kami ada dalam bahaya maut sepanjang hari, kami telah dianggap sebagai domba-domba sembelihan."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 37, 'Tetapi dalam semuanya itu kita lebih dari pada orang-orang yang menang, oleh Dia yang telah mengasihi kita.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 38, 'Sebab aku yakin, bahwa baik maut, maupun hidup, baik malaikat-malaikat, maupun pemerintah-pemerintah, baik yang ada sekarang, maupun yang akan datang,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 8, 39, 'atau kuasa-kuasa, baik yang di atas, maupun yang di bawah, ataupun sesuatu makhluk lain, tidak akan dapat memisahkan kita dari kasih Allah, yang ada dalam Kristus Yesus, Tuhan kita.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 1, 'Aku mengatakan kebenaran dalam Kristus, aku tidak berdusta. Suara hatiku turut bersaksi dalam Roh Kudus,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 2, 'bahwa aku sangat berdukacita dan selalu bersedih hati.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 3, 'Bahkan, aku mau terkutuk dan terpisah dari Kristus demi saudara-saudaraku, kaum sebangsaku secara jasmani.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 4, 'Sebab mereka adalah orang Israel, mereka telah diangkat menjadi anak, dan mereka telah menerima kemuliaan, dan perjanjian-perjanjian, dan hukum Taurat, dan ibadah, dan janji-janji.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 5, 'Mereka adalah keturunan bapa-bapa leluhur, yang menurunkan Mesias dalam keadaan-Nya sebagai manusia, yang ada di atas segala sesuatu. Ia adalah Allah yang harus dipuji sampai selama-lamanya. Amin!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 6, 'Akan tetapi firman Allah tidak mungkin gagal. Sebab tidak semua orang yang berasal dari Israel adalah orang Israel,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 7, 'dan juga tidak semua yang terhitung keturunan Abraham adalah anak Abraham, tetapi: "Yang berasal dari Ishak yang akan disebut keturunanmu."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 8, 'Artinya: bukan anak-anak menurut daging adalah anak-anak Allah, tetapi anak-anak perjanjian yang disebut keturunan yang benar.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 9, 'Sebab firman ini mengandung janji: "Pada waktu seperti inilah Aku akan datang dan Sara akan mempunyai seorang anak laki-laki."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 10, 'Tetapi bukan hanya itu saja. Lebih terang lagi ialah Ribka yang mengandung dari satu orang, yaitu dari Ishak, bapa leluhur kita.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 11, 'Sebab waktu anak-anak itu belum dilahirkan dan belum melakukan yang baik atau yang jahat, ?supaya rencana Allah tentang pemilihan-Nya diteguhkan, bukan berdasarkan perbuatan, tetapi berdasarkan panggilan-Nya?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 12, 'dikatakan kepada Ribka: "Anak yang tua akan menjadi hamba anak yang muda,"', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 13, 'seperti ada tertulis: "Aku mengasihi Yakub, tetapi membenci Esau."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 14, 'Jika demikian, apakah yang hendak kita katakan? Apakah Allah tidak adil? Mustahil!', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 15, 'Sebab Ia berfirman kepada Musa: "Aku akan menaruh belas kasihan kepada siapa Aku mau menaruh belas kasihan dan Aku akan bermurah hati kepada siapa Aku mau bermurah hati."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 16, 'Jadi hal itu tidak tergantung pada kehendak orang atau usaha orang, tetapi kepada kemurahan hati Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 17, 'Sebab Kitab Suci berkata kepada Firaun: "Itulah sebabnya Aku membangkitkan engkau, yaitu supaya Aku memperlihatkan kuasa-Ku di dalam engkau, dan supaya nama-Ku dimasyhurkan di seluruh bumi."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 18, 'Jadi Ia menaruh belas kasihan kepada siapa yang dikehendaki-Nya dan Ia menegarkan hati siapa yang dikehendaki-Nya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 19, 'Sekarang kamu akan berkata kepadaku: "Jika demikian, apa lagi yang masih disalahkan-Nya? Sebab siapa yang menentang kehendak-Nya?"', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 20, 'Siapakah kamu, hai manusia, maka kamu membantah Allah? Dapatkah yang dibentuk berkata kepada yang membentuknya: "Mengapakah engkau membentuk aku demikian?"', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 21, 'Apakah tukang periuk tidak mempunyai hak atas tanah liatnya, untuk membuat dari gumpal yang sama suatu benda untuk dipakai guna tujuan yang mulia dan suatu benda lain untuk dipakai guna tujuan yang biasa?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 22, 'Jadi, kalau untuk menunjukkan murka-Nya dan menyatakan kuasa-Nya, Allah menaruh kesabaran yang besar terhadap benda-benda kemurkaan-Nya, yang telah disiapkan untuk kebinasaan?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 23, 'justru untuk menyatakan kekayaan kemuliaan-Nya atas benda-benda belas kasihan-Nya yang telah dipersiapkan-Nya untuk kemuliaan,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 24, 'yaitu kita, yang telah dipanggil-Nya bukan hanya dari antara orang Yahudi, tetapi juga dari antara bangsa-bangsa lain,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 25, 'seperti yang difirmankan-Nya juga dalam kitab nabi Hosea: "Yang bukan umat-Ku akan Kusebut: umat-Ku dan yang bukan kekasih: kekasih."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 26, 'Dan di tempat, di mana akan dikatakan kepada mereka: "Kamu ini bukanlah umat-Ku," di sana akan dikatakan kepada mereka: "Anak-anak Allah yang hidup."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 27, 'Dan Yesaya berseru tentang Israel: "Sekalipun jumlah anak Israel seperti pasir di laut, namun hanya sisanya akan diselamatkan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 28, 'Sebab apa yang telah difirmankan-Nya, akan dilakukan Tuhan di atas bumi, sempurna dan segera."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 29, 'Dan seperti yang dikatakan Yesaya sebelumnya: "Seandainya Tuhan semesta alam tidak meninggalkan pada kita keturunan, kita sudah menjadi seperti Sodom dan sama seperti Gomora."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 30, 'Jika demikian, apakah yang hendak kita katakan? Ini: bahwa bangsa-bangsa lain yang tidak mengejar kebenaran, telah beroleh kebenaran, yaitu kebenaran karena iman.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 31, 'Tetapi: bahwa Israel, sungguhpun mengejar hukum yang akan mendatangkan kebenaran, tidaklah sampai kepada hukum itu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 32, 'Mengapa tidak? Karena Israel mengejarnya bukan karena iman, tetapi karena perbuatan. Mereka tersandung pada batu sandungan,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 9, 33, 'seperti ada tertulis: "Sesungguhnya, Aku meletakkan di Sion sebuah batu sentuhan dan sebuah batu sandungan, dan siapa yang percaya kepada-Nya, tidak akan dipermalukan."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 1, 'Saudara-saudara, keinginan hatiku dan doaku kepada Tuhan ialah, supaya mereka diselamatkan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 2, 'Sebab aku dapat memberi kesaksian tentang mereka, bahwa mereka sungguh-sungguh giat untuk Allah, tetapi tanpa pengertian yang benar.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 3, 'Sebab, oleh karena mereka tidak mengenal kebenaran Allah dan oleh karena mereka berusaha untuk mendirikan kebenaran mereka sendiri, maka mereka tidak takluk kepada kebenaran Allah.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 4, 'Sebab Kristus adalah kegenapan hukum Taurat, sehingga kebenaran diperoleh tiap-tiap orang yang percaya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 5, 'Sebab Musa menulis tentang kebenaran karena hukum Taurat: "Orang yang melakukannya, akan hidup karenanya."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 6, 'Tetapi kebenaran karena iman berkata demikian: "Jangan katakan di dalam hatimu: Siapakah akan naik ke sorga?", yaitu: untuk membawa Yesus turun,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 7, 'atau: "Siapakah akan turun ke jurang maut?", yaitu: untuk membawa Kristus naik dari antara orang mati.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 8, 'Tetapi apakah katanya? Ini: "Firman itu dekat kepadamu, yakni di dalam mulutmu dan di dalam hatimu." Itulah firman iman, yang kami beritakan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 9, 'Sebab jika kamu mengaku dengan mulutmu, bahwa Yesus adalah Tuhan, dan percaya dalam hatimu, bahwa Allah telah membangkitkan Dia dari antara orang mati, maka kamu akan diselamatkan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 10, 'Karena dengan hati orang percaya dan dibenarkan, dan dengan mulut orang mengaku dan diselamatkan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 11, 'Karena Kitab Suci berkata: "Barangsiapa yang percaya kepada Dia, tidak akan dipermalukan."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 12, 'Sebab tidak ada perbedaan antara orang Yahudi dan orang Yunani. Karena, Allah yang satu itu adalah Tuhan dari semua orang, kaya bagi semua orang yang berseru kepada-Nya.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 13, 'Sebab, barangsiapa yang berseru kepada nama Tuhan, akan diselamatkan.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 14, 'Tetapi bagaimana mereka dapat berseru kepada-Nya, jika mereka tidak percaya kepada Dia? Bagaimana mereka dapat percaya kepada Dia, jika mereka tidak mendengar tentang Dia. Bagaimana mereka mendengar tentang Dia, jika tidak ada yang memberitakan-Nya?', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 15, 'Dan bagaimana mereka dapat memberitakan-Nya, jika mereka tidak diutus? Seperti ada tertulis: "Betapa indahnya kedatangan mereka yang membawa kabar baik!"', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 16, 'Tetapi tidak semua orang telah menerima kabar baik itu. Yesaya sendiri berkata: "Tuhan, siapakah yang percaya kepada pemberitaan kami?"', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 17, 'Jadi, iman timbul dari pendengaran, dan pendengaran oleh firman Kristus.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 18, 'Tetapi aku bertanya: Adakah mereka tidak mendengarnya? Memang mereka telah mendengarnya: "Suara mereka sampai ke seluruh dunia, dan perkataan mereka sampai ke ujung bumi."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 19, 'Tetapi aku bertanya: Adakah Israel menanggapnya? Pertama-tama Musa berkata: "Aku menjadikan kamu cemburu terhadap orang-orang yang bukan umat dan membangkitkan amarahmu terhadap bangsa yang bebal."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 20, 'Dan dengan berani Yesaya mengatakan: "Aku telah berkenan ditemukan mereka yang tidak mencari Aku, Aku telah menampakkan diri kepada mereka yang tidak menanyakan Aku."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 10, 21, 'Tetapi tentang Israel ia berkata: "Sepanjang hari Aku telah mengulurkan tangan-Ku kepada bangsa yang tidak taat dan yang membantah."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 1, 'Maka aku bertanya: Adakah Allah mungkin telah menolak umat-Nya? Sekali-kali tidak! Karena aku sendiripun orang Israel, dari keturunan Abraham, dari suku Benyamin.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 2, 'Allah tidak menolak umat-Nya yang dipilih-Nya. Ataukah kamu tidak tahu, apa yang dikatakan Kitab Suci tentang Elia, waktu ia mengadukan Israel kepada Allah:', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 3, '"Tuhan, nabi-nabi-Mu telah mereka bunuh, mezbah-mezbah-Mu telah mereka runtuhkan; hanya aku seorang dirilah yang masih hidup dan mereka ingin mencabut nyawaku."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 4, 'Tetapi bagaimanakah firman Allah kepadanya? "Aku masih meninggalkan tujuh ribu orang bagi-Ku, yang tidak pernah sujud menyembah Baal."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 5, 'Demikian juga pada waktu ini ada tinggal suatu sisa, menurut pilihan kasih karunia.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 6, 'Tetapi jika hal itu terjadi karena kasih karunia, maka bukan lagi karena perbuatan, sebab jika tidak demikian, maka kasih karunia itu bukan lagi kasih karunia.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 7, 'Jadi bagaimana? Israel tidak memperoleh apa yang dikejarnya, tetapi orang-orang yang terpilih telah memperolehnya. Dan orang-orang yang lain telah tegar hatinya,', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 8, 'seperti ada tertulis: "Allah membuat mereka tidur nyenyak, memberikan mata untuk tidak melihat dan telinga untuk tidak mendengar, sampai kepada hari sekarang ini."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 9, 'Dan Daud berkata: "Biarlah jamuan mereka menjadi jerat dan perangkap, penyesatan dan pembalasan bagi mereka.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 10, 'Dan biarlah mata mereka menjadi gelap, sehingga mereka tidak melihat, dan buatlah punggung mereka terus-menerus membungkuk."', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 11, 'Maka aku bertanya: Adakah mereka tersandung dan harus jatuh? Sekali-kali tidak! Tetapi oleh pelanggaran mereka, keselamatan telah sampai kepada bangsa-bangsa lain, supaya membuat mereka cemburu.', 'id', 'TB'),
  ('45', 'rm', 'Roma', 11, 12, 'Sebab jika pelanggaran mereka berarti kekayaan bagi dunia, dan kekurangan mereka kekayaan bagi bangsa-bangsa lain, terlebih-lebih lagi kesempurnaan mereka.', 'id', 'TB')
